window.OPERATORS = [{"id":"char_009_12fce","name":"12F","en":"12F","kind":"operator","region":"rhodes","origin":"不明","faction":"罗德岛","profession":"术师","aliases":[],"title":"12F的佣兵履历与任职","summary":"12F曾在多个势力之间活动，以佣兵或设施保全人员的身份参与冲突，部分记录得到核实。他与巨枭一同加入罗德岛，因作战经历被录用，现执行常规术师任务。档案评价其法术水平并不突出，但对技艺原理理解较深，能够依据经验提高作战中的生存机会。","focus":"其自报履历仅有部分得到核实，未公开经历不据此补全。","memories":[{"title":"一些选择","intro":"他的过去不是秘密，是一无所有。"}],"forms":[{"id":"char_009_12fce","name":"12F"}],"source":"https://prts.wiki/w/12F"},{"id":"char_225_haak","name":"阿","en":"Aak","kind":"operator","region":"lungmen","origin":"龙门","faction":"鲤氏侦探事务所","profession":"特种","aliases":[],"title":"龙门黑医生与装备研发任职","summary":"阿原在龙门灰色地带从事医疗工作，经老鲤推荐加入罗德岛。他具备丰富的医学理论和临床经验，但治疗时的言行及实验方式引起了管理方的担忧。凯尔希完成综合评估后，暂时将其推荐至医疗装备科和技术开发组，而非直接安排常规临床岗位。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"惊弓一夜","intro":"心中越慌，事情越乱。"}],"forms":[{"id":"char_225_haak","name":"阿"}],"source":"https://prts.wiki/w/%E9%98%BF"},{"id":"char_4178_alanna","name":"阿兰娜","en":"Alanna","kind":"operator","region":"rim","origin":"雷姆必拓","faction":"雷姆必拓","profession":"辅助","aliases":[],"title":"阿兰娜的矿区经历与工程任职","summary":"阿兰娜曾在雷姆必拓比格皮勒自治州驾驶运载车，掌握机械操控和维修技术。她早年为父母及其他工人办理矿难赔偿交涉，并在入职时主动说明相关经历。现任罗德岛工程部第三维修工坊成员，参与可露希尔主持的新设备研发和调试，承担与其技术经验相符的工作。","focus":"以入职资料中的工作经历为范围，不扩写矿难经过及其后续处理细节。","memories":[{"title":"再见一面","intro":"从地图上消失的小镇，没来得及说的那声“再见”。"}],"forms":[{"id":"char_4178_alanna","name":"阿兰娜"}],"source":"https://prts.wiki/w/%E9%98%BF%E5%85%B0%E5%A8%9C"},{"id":"char_446_aroma","name":"阿罗玛","en":"Aroma","kind":"operator","region":"siracusa","origin":"叙拉古","faction":"叙拉古","profession":"术师","aliases":[],"title":"阿罗玛的香氛与清洁工作","summary":"阿罗玛来自哥伦比亚经营净味香氛的家庭作坊，因矿石病到罗德岛治疗，并与后勤部建立合作。她负责本舰清洁，也为补给和灾害应对提供后勤支援。入职后，她因细致的工作成为清洁负责人，日常处理腐败垃圾、排水反味和室内污渍，并供应家庭作坊制作的香皂。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[{"title":"入职邀请","intro":"有些事情，只有人知道为什么需要去做。"}],"forms":[{"id":"char_446_aroma","name":"阿罗玛"}],"source":"https://prts.wiki/w/%E9%98%BF%E7%BD%97%E7%8E%9B"},{"id":"char_002_amiya","name":"阿米娅","en":"Amiya","kind":"operator","region":"rhodes","origin":"雷姆必拓","faction":"罗德岛","profession":"术师","aliases":[],"title":"阿米娅的罗德岛领导职责","summary":"阿米娅是罗德岛的公开领袖，在组织内部拥有最高执行权，现带领成员开展与感染者处境及矿石病相关的工作。档案记载，她虽然外表年轻，已经获得内部成员信任，并被视为合格的领导者。本阶段材料主要说明其组织职责，没有进一步展开具体履历。","focus":"所给第一档案为空，本条仅按公开职务与客观履历整理，不推定其他经历。","memories":[],"forms":[{"id":"char_002_amiya","name":"阿米娅"},{"id":"char_002_amiya","name":"阿米娅 · 近卫","patch":true},{"id":"char_002_amiya","name":"阿米娅 · 医疗","patch":true}],"source":"https://prts.wiki/w/%E9%98%BF%E7%B1%B3%E5%A8%85"},{"id":"char_4132_ascln","name":"阿斯卡纶","en":"Ascalon","kind":"operator","region":"rhodes","origin":"卡兹戴尔","faction":"S.W.E.E.P.","profession":"特种","aliases":[],"title":"阿斯卡纶的情报与反渗透职责","summary":"阿斯卡纶曾在巴别塔担任情报官，后成为罗德岛S.W.E.E.P.负责人，承担反渗透工作。多数普通干员对她并不熟悉，公开可查的档案也较为简略，对性格、能力和表现均采用普通评价。现有材料能够确认她的组织职务，但没有具体披露相关行动的内容与实施过程。","focus":"岗位信息与普通档案的评价范围不同，不据简略记录推定其全部能力。","memories":[{"title":"同行人","intro":"不知道为何而行，那么你要如何承担失去同行人的痛苦，阿斯卡纶？"}],"forms":[{"id":"char_4132_ascln","name":"阿斯卡纶"}],"source":"https://prts.wiki/w/%E9%98%BF%E6%96%AF%E5%8D%A1%E7%BA%B6"},{"id":"char_277_sqrrel","name":"阿消","en":"Shaw","kind":"operator","region":"lungmen","origin":"龙门","faction":"炎-龙门","profession":"特种","aliases":[],"title":"阿消的消防经历与特种任职","summary":"阿消原为龙门消防局消防员，现于罗德岛特种小组任职，兼为本舰提供消防安全服务。她把消防救灾技术用于战斗，为行动增加地形与设备方面的选择。日常交流中，她容易紧张，组织语言较为费力；进入工作状态后则投入而认真，发现可能引发火灾的行为会立即制止。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[{"title":"小心火烛","intro":"消防员从来都不怕火。她只是怕火令人们失去太多珍视的东西。"},{"title":"易燃品","intro":"没有消防员可以救下火场里的每个人，他们总会经历这种事。"}],"forms":[{"id":"char_277_sqrrel","name":"阿消"}],"source":"https://prts.wiki/w/%E9%98%BF%E6%B6%88"},{"id":"char_4218_aigis","name":"埃癸斯","en":"Aegis","kind":"operator","region":"other","origin":"未录入","faction":"S.E.E.S.","profession":"狙击","aliases":[],"title":"埃癸斯的类铳课程记录","summary":"联动档案记录，埃癸斯在类铳型武装课程中熟练使用多种装备，受到同学关注。课后，慑砂向她询问武器和持握方式，两人的讨论未能准确对应各自问题。博士随后介绍泰拉各地的类铳装备，她与慑砂一同听完了这次临时讲授。","focus":"本条采用联动档案的校园叙述框架，不据此补写其原世界的完整经历。","memories":[],"forms":[{"id":"char_4218_aigis","name":"埃癸斯"}],"source":"https://prts.wiki/w/%E5%9F%83%E7%99%B8%E6%96%AF"},{"id":"char_4043_erato","name":"埃拉托","en":"Erato","kind":"operator","region":"minos","origin":"米诺斯","faction":"米诺斯","profession":"狙击","aliases":[],"title":"埃拉托的游击经历与诗人身份","summary":"埃拉托来自米诺斯，是吟游诗人，也曾参加对抗萨尔贡殖民者的游击队。她来到罗德岛时首先询问帕拉斯的下落，相关人员因此核实了她的身份。她自称多次获得勇士大会射箭冠军，并具有竖琴演奏名声，但这些头衔未获证实，没有作为确定履历录入档案。","focus":"将可确认的游击经历与本人宣称的竞技、演奏头衔分别记录。","memories":[{"title":"英雄们的叙事诗","intro":"来自米诺斯的吟游诗人埃拉托，她知道英雄在何处。"}],"forms":[{"id":"char_4043_erato","name":"埃拉托"}],"source":"https://prts.wiki/w/%E5%9F%83%E6%8B%89%E6%89%98"},{"id":"char_4123_ela","name":"艾拉","en":"Ela","kind":"operator","region":"other","origin":"未知","faction":"彩虹小队","profession":"特种","aliases":[],"title":"艾拉的合作身份与战术专长","summary":"艾拉本名艾姿碧塔·博萨克，是彩虹小队成员及克里斯达尔事件亲历者，事件后登记为罗德岛合作人员。她独立、适应能力强，具有领导和短时决策能力，惯用雷鸣地雷干扰目标行动。她与队员保持临时合作关系，另有自身事务，并非罗德岛正式雇员。","focus":"本条限定联动事件后的合作记录，不将合作方计为本舰正式职工。","memories":[{"title":"“宛如初见”","intro":"这台光鲜亮丽而又磨牙吮血的机器她第一次见，也似乎早就不是第一次见了。"}],"forms":[{"id":"char_4123_ela","name":"艾拉"}],"source":"https://prts.wiki/w/%E8%89%BE%E6%8B%89"},{"id":"char_4009_irene","name":"艾丽妮","en":"Irene","kind":"operator","region":"iberia","origin":"伊比利亚","faction":"伊比利亚","profession":"近卫","aliases":[],"title":"愚人号事件后的信使任职","summary":"艾丽妮曾任伊比利亚审判官，是达里奥的学生。愚人号事件后，她辞职并经凯尔希推荐，以审判庭信使身份与罗德岛合作。她被安排参加伊比利亚特别行动工作，日常持续训练和阅读，遵守舰内制度，也会向求助者提供帮助、介绍故乡音乐。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"灯火微明","intro":"知行合一，何其困难。"}],"forms":[{"id":"char_4009_irene","name":"艾丽妮"}],"source":"https://prts.wiki/w/%E8%89%BE%E4%B8%BD%E5%A6%AE"},{"id":"char_127_estell","name":"艾丝黛尔","en":"Estelle","kind":"operator","region":"sargon","origin":"未公开","faction":"萨尔贡","profession":"近卫","aliases":[],"title":"艾丝黛尔的治疗与干员录用","summary":"艾丝黛尔因矿石病出现显性外貌变化，曾主动联系罗德岛寻求庇护和治疗。她在接受治疗、心理辅导及多项测试后，按照本人意愿获准加入作战队伍，现任近卫干员。日常观察记录显示，她对异变双角较为在意，经常紧张并回避社交，医疗人员建议继续提供支持。","focus":"依据档案中的行为观察叙述，不将外貌变化直接等同于整体心理状态。","memories":[{"title":"她的一小步","intro":"每个暂存于心的念头都会有绽放的一天。"}],"forms":[{"id":"char_127_estell","name":"艾丝黛尔"}],"source":"https://prts.wiki/w/%E8%89%BE%E4%B8%9D%E9%BB%9B%E5%B0%94"},{"id":"char_180_amgoat","name":"艾雅法拉","en":"Eyjafjalla","kind":"operator","region":"leithanien","origin":"莱塔尼亚","faction":"莱塔尼亚","profession":"术师","aliases":[],"title":"艾雅法拉的研究与医疗记录","summary":"艾雅法拉是莱塔尼亚火山学家及天灾信使，在源石技艺研究与高能法术运用方面具备专长。她在罗德岛治疗期间承担天灾研究、环境评估和危险地形航行保障。入职时，其听觉障碍等症状已被工作人员注意；研究者身份经正式通知确认，此前她已有高等学府中的学术经历。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[{"title":"学者之心","intro":"黑暗追着她，她追着光。"},{"title":"火山","intro":"经火烧过的是真理，亦是永恒。"}],"forms":[{"id":"char_180_amgoat","name":"艾雅法拉"},{"id":"char_1016_agoat2","name":"纯烬艾雅法拉"}],"source":"https://prts.wiki/w/%E8%89%BE%E9%9B%85%E6%B3%95%E6%8B%89"},{"id":"char_338_iris","name":"爱丽丝","en":"Iris","kind":"operator","region":"victoria","origin":"维多利亚","faction":"维多利亚","profession":"术师","aliases":[],"title":"归还寄存物与临时留舰","summary":"爱丽丝为归还一台旧收音机来到罗德岛，寻找的线索包括寄存人的真实姓名和外貌。财物归属及相关私人问题仍需处理，她因此申请长期留岛，并登记为临时干员。她使用能使人入眠并影响梦境的源石技艺，寄存物涉及的时间疑问尚未说明。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"糖果屋","intro":"在童话的世界里，说不出话的孩子，躲在远方的大人，无声无息的茶壶烛台，都可以被倾听。"}],"forms":[{"id":"char_338_iris","name":"爱丽丝"}],"source":"https://prts.wiki/w/%E7%88%B1%E4%B8%BD%E4%B8%9D"},{"id":"char_302_glaze","name":"安比尔","en":"Ambriel","kind":"operator","region":"laterano","origin":"拉特兰","faction":"拉特兰","profession":"狙击","aliases":[],"title":"安比尔的狙击任职与武器选择","summary":"安比尔是拉特兰公民，通过测试后加入罗德岛狙击小组，主要提供远程射击支援，并在伏击任务中表现良好。她使用经过改装的旧式长铳，说明此举是为避免近距离交战及搬运较重装备。尽管武器不符合部分常用战术标准，她的任务完成情况仍获得上级认可。","focus":"武器选择采用本人说明与工作记录，不进一步推定其训练态度。","memories":[{"title":"圣城晚照","intro":"夕阳总会平等地洒在圣城的每个角落，这堵围墙可拦不住它。"}],"forms":[{"id":"char_302_glaze","name":"安比尔"}],"source":"https://prts.wiki/w/%E5%AE%89%E6%AF%94%E5%B0%94"},{"id":"char_211_adnach","name":"安德切尔","en":"Adnachiel","kind":"operator","region":"rhodes","origin":"拉特兰","faction":"行动预备组A4","profession":"狙击","aliases":[],"title":"安德切尔的预备组任职","summary":"安德切尔是拉特兰公民，正式入职前为自由职业者。通过多项测试后，他加入罗德岛行动预备组A4，在反应、射击和支援任务中表现出潜力。档案记录他学习技术较快，观察细致，交流时多保持克制。有关先知的称呼来自同僚传言，本人并不认可这一说法。","focus":"学习能力与观察力有档案依据，先知称呼属于他人传言。","memories":[{"title":"预备“先知”","intro":"大家都知道安德切尔很聪明，但他总是能再一次超出大家的想象。"}],"forms":[{"id":"char_211_adnach","name":"安德切尔"}],"source":"https://prts.wiki/w/%E5%AE%89%E5%BE%B7%E5%88%87%E5%B0%94"},{"id":"char_291_aglina","name":"安洁莉娜","en":"Angelina","kind":"operator","region":"siracusa","origin":"叙拉古","faction":"叙拉古","profession":"辅助","aliases":[],"title":"信使经历与实习术师任职","summary":"安洁莉娜原名安心院安洁莉娜，曾在叙拉古递送情报和货物，档案据此将其职业推测为信使。加入罗德岛后，她以实习术师身份提供后勤、战场辅助和战术协同服务。相关记录还指出，她具有改变物体轻重的施术天赋，目前仍需要进一步引导和开发。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"没写收件人的包裹","intro":"信使很少有工作失误，因为补救起来真的很麻烦。 好的信使可以分享人与人之间的情感。"}],"forms":[{"id":"char_291_aglina","name":"安洁莉娜"},{"id":"char_1015_aglna2","name":"予愿安洁莉娜"}],"source":"https://prts.wiki/w/%E5%AE%89%E6%B4%81%E8%8E%89%E5%A8%9C"},{"id":"char_212_ansel","name":"安赛尔","en":"Ansel","kind":"operator","region":"rhodes","origin":"雷姆必拓","faction":"行动预备组A4","profession":"医疗","aliases":[],"title":"安赛尔的医疗训练与战地工作","summary":"安赛尔来自雷姆必拓，正式任职前是罗德岛实习员工，经过多项测试后调入医疗组，现为行动预备组A4成员。记录显示，他在复杂战况中仍优先安排医疗支援，按步骤救治伤员，也会提醒不遵守医疗要求的人员。其工作范围包括任务中的及时救护与相关照料。","focus":"本篇限于早期医疗任职记录，不以个别任务描述概括其所有能力。","memories":[{"title":"身为医者","intro":"和朋友们不同，他只能做到这些；他希望自己能为朋友做的不止这些。"}],"forms":[{"id":"char_212_ansel","name":"安赛尔"}],"source":"https://prts.wiki/w/%E5%AE%89%E8%B5%9B%E5%B0%94"},{"id":"char_218_cuttle","name":"安哲拉","en":"Andreana","kind":"operator","region":"aegir","origin":"伊比利亚","faction":"深海猎人","profession":"狙击","aliases":[],"title":"安哲拉的保镖经历与狙击任职","summary":"安哲拉出身伊比利亚，曾担任白炽的保镖，随后与白炽一同接受罗德岛雇佣。她原有良好的射击素养，接受专业训练后，以狙击干员身份参与多类任务。初到时，她因少言和表情变化不多被认为难以交流；长期相处后，同僚注意到她善于倾听，也会照顾他人。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[],"forms":[{"id":"char_218_cuttle","name":"安哲拉"}],"source":"https://prts.wiki/w/%E5%AE%89%E5%93%B2%E6%8B%89"},{"id":"char_236_rope","name":"暗索","en":"Rope","kind":"operator","region":"lungmen","origin":"雷姆必拓","faction":"炎-龙门","profession":"特种","aliases":[],"title":"龙门盗窃经历与侦察工作","summary":"暗索曾在龙门贫民窟盗窃，一次失手后被捕。龙门与罗德岛建立合作后，陈将她作为特殊人才推荐入职。她平时收集情报，作战使用绳索和钩爪。档案同时记录，她仍有下意识取走他人物品的习惯，但目前已经能够在事后归还。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"鲜花香水","intro":"异国人总会有一些神奇的幻想，不过很可惜，并非所有炎国人都能飞檐走壁。 真正的园艺爱好者比起开出的花和结出的果，更关注土壤。"}],"forms":[{"id":"char_236_rope","name":"暗索"}],"source":"https://prts.wiki/w/%E6%9A%97%E7%B4%A2"},{"id":"char_4131_odda","name":"奥达","en":"Odda","kind":"operator","region":"rhodes","origin":"卡兹戴尔","faction":"罗德岛","profession":"近卫","aliases":[],"title":"奥达往返卡兹戴尔的信使工作","summary":"奥达曾为巴别塔成员，现居卡兹戴尔，从事信使工作，定期向罗德岛运送信件和包裹，并偶尔承担当地外勤。他带来的家乡消息经常涉及死亡及其他困难，但萨卡兹干员仍会聚集听取。他也将罗德岛上的近况带回卡兹戴尔，向留在当地的亲属传递信息。","focus":"以信件传递的工作内容说明其作用，不增写未载明的具体送信事件。","memories":[],"forms":[{"id":"char_4131_odda","name":"奥达"}],"source":"https://prts.wiki/w/%E5%A5%A5%E8%BE%BE"},{"id":"char_4245_alga","name":"奥尔佳","en":"Ольга","kind":"operator","region":"ursus","origin":"乌萨斯","faction":"乌萨斯","profession":"近卫","aliases":[],"title":"奥尔佳的外交与联络工作","summary":"奥尔佳获得乌萨斯中央执行委员会豁免后进入外交部，经学生自治团成员推荐来到罗德岛，负责圣骏堡方面的联络。抵舰后，她拜访阿米娅、凯尔希和可露希尔，并参观各部门。约一周内，她掌握部门职能与工作状况，完成双方的信息同步，也将本舰见闻整理入笔记。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[],"forms":[{"id":"char_4245_alga","name":"奥尔佳"}],"source":"https://prts.wiki/w/%E5%A5%A5%E5%B0%94%E4%BD%B3"},{"id":"char_346_aosta","name":"奥斯塔","en":"Aosta","kind":"operator","region":"siracusa","origin":"叙拉古","faction":"贾维团伙","profession":"狙击","aliases":[],"title":"从叙拉古家族到游击岗位","summary":"奥斯塔原属叙拉古一座小城的家族，后来成为贾维团伙成员，并在一次事件后随贾维加入罗德岛，担任前线游击手。人事记录认为他安静、举止得体，处事可靠，考虑问题较为周全。部分措辞仍带有街头生活的习惯，与其组队的干员评价普遍良好。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"编织来日","intro":"或许这就是他想要的生活方式，或许自己可以尝试去抓住它。"}],"forms":[{"id":"char_346_aosta","name":"奥斯塔"}],"source":"https://prts.wiki/w/%E5%A5%A5%E6%96%AF%E5%A1%94"},{"id":"char_4186_tmoris","name":"八幡海铃","en":"Yahata Umiri","kind":"operator","region":"other","origin":"未知","faction":"Ave Mujica","profession":"特种","aliases":[],"title":"八幡海铃的乐队身份与协作","summary":"八幡海铃是Ave Mujica的贝斯手，经爱丽丝介绍加入罗德岛。乐队成员逐渐适应舰上生活后，她开始主动提供协助。相关观察记载，她能够较快学习并实践新知识，重视沟通和团队配合，在演奏及作战中均表现出专业态度。现有履历未详细交代其到来前的全部经历。","focus":"仅采用联动角色在罗德岛的档案，不以其他作品内容补足空白。","memories":[],"forms":[{"id":"char_4186_tmoris","name":"八幡海铃"}],"source":"https://prts.wiki/w/%E5%85%AB%E5%B9%A1%E6%B5%B7%E9%93%83"},{"id":"char_204_platnm","name":"白金","en":"Platinum","kind":"operator","region":"kazimierz","origin":"卡西米尔","faction":"卡西米尔","profession":"狙击","aliases":[],"title":"白金的无胄盟经历与受雇记录","summary":"白金来自卡西米尔无胄盟，曾从事刺客工作，在机动、歼灭与巷战中具备较高战术素养。她现于凯尔希指导下担任罗德岛狙击干员。档案提醒，自由填报的个人信息可信度有限，部分体检数据也未公开；核心资料则经过审核，其他履历仍有缺项。","focus":"公开自填资料与经审核记录须区分，缺失内容不视为已知事实。","memories":[{"title":"泡沫","intro":"“生活和梦境要是都能更有趣些就好了呢……”"}],"forms":[{"id":"char_204_platnm","name":"白金"}],"source":"https://prts.wiki/w/%E7%99%BD%E9%87%91"},{"id":"char_128_plosis","name":"白面鸮","en":"Ptilopsis","kind":"operator","region":"columbia","origin":"哥伦比亚","faction":"莱茵生命","profession":"医疗","aliases":[],"title":"白面鸮的医疗数据工作","summary":"白面鸮曾任莱茵生命数据维护专员，具备医疗技艺、数据维护和临床方案应用经验。来到罗德岛后，她参与赫默负责的医疗实验项目，承担资料记录、提取和分析，并协助伊芙利特的日常监护。她还维护部分公开数据，其对话记录具有检索界面的表达形式。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"深暗之梦","intro":"逝去的友人，奇特的源石装置，神秘的低语，这一切的秘密都被她埋藏在灵魂深处。"}],"forms":[{"id":"char_128_plosis","name":"白面鸮"}],"source":"https://prts.wiki/w/%E7%99%BD%E9%9D%A2%E9%B8%AE"},{"id":"char_4072_ironmn","name":"白铁","en":"Stainless","kind":"operator","region":"victoria","origin":"维多利亚","faction":"维多利亚","profession":"辅助","aliases":[],"title":"白铁的自救军与工程工作","summary":"白铁是机械工程师，曾任伦蒂尼姆市民自救军十一小队队长，在当地事件中与罗德岛协同作战。签订长期合作条款后，他作为工程干员和行动成员参与维多利亚地区任务。登舰后的日常记录还包括他主动认识同事、记忆姓名，以及制作小物件赠给情绪低落的同伴。","focus":"将军事合作、工程任职和日常交往分别记录，不以社交表现替代履历。","memories":[{"title":"啮合不良","intro":"齿轮总有自己该去的地方，但齿轮和人不一样。"}],"forms":[{"id":"char_4072_ironmn","name":"白铁"}],"source":"https://prts.wiki/w/%E7%99%BD%E9%93%81"},{"id":"char_118_yuki","name":"白雪","en":"ShiraYuki","kind":"operator","region":"higashi","origin":"东国","faction":"东","profession":"狙击","aliases":[],"title":"白雪的护卫经历与派遣记录","summary":"白雪原为文月的贴身护卫。龙门近卫局与罗德岛建立合作后，她被派来保护博士，使用大型手里剑，负责隐秘行动与情报收集。她平时少言，常不在公开场所露面，执行护卫任务时能及时到位。档案还记录她喜欢在海岬看雪，但没有解释这一习惯的具体缘由。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[{"title":"忍者之道","intro":"公主说过，愚忠不可取。"}],"forms":[{"id":"char_118_yuki","name":"白雪"}],"source":"https://prts.wiki/w/%E7%99%BD%E9%9B%AA"},{"id":"char_1026_gvial2","name":"百炼嘉维尔","en":"Gavial the Invincible","kind":"operator","region":"rhodes","origin":"萨尔贡","faction":"罗德岛","profession":"近卫","aliases":[],"title":"嘉维尔的新装备与双重岗位","summary":"嘉维尔在这一阶段仍属罗德岛医疗部，需要时也以战斧参加攻坚战斗。收到特米米关于故乡可能发生灾难的来信后，她申请更换装备，由森蚺赶制武器、护甲和配饰。档案明确否定了装备来自古老部族传承的流言，记载她选中了其中的大斧。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"以酒精之名！","intro":"要让醉醺醺的家伙们和酒说再见可不容易，哪怕是暂时的。"}],"forms":[{"id":"char_187_ccheal","name":"嘉维尔"},{"id":"char_1026_gvial2","name":"百炼嘉维尔"}],"source":"https://prts.wiki/w/%E7%99%BE%E7%82%BC%E5%98%89%E7%BB%B4%E5%B0%94"},{"id":"char_252_bibeak","name":"柏喙","en":"Bibeak","kind":"operator","region":"sami","origin":"萨米","faction":"萨米","profession":"近卫","aliases":[],"title":"柏喙的入职过程与服装制作","summary":"柏喙是雷神工业装备设计师之女，在工厂暴动中感染矿石病，以医疗救助对象身份来到罗德岛，后依本人意愿调入作战部门。她擅长剑术，也持续从事缝纫和服装设计。入舰后曾询问制作服装所需的场所与工具，并多次为同事量体、设计衣物，相关作品偏重装饰性。","focus":"本篇依据早期入职和手工活动记录，不扩写暴动背景及家庭关系。","memories":[{"title":"破壳","intro":"如果不靠自己啄开那层壳，羽兽就不算真正地来到这世上，看到真正的蓝天。"},{"title":"走出那条长长的走廊","intro":"柏喙收到两封信，一封来自她的父母，另一封来自那个伤害了她的人。"}],"forms":[{"id":"char_252_bibeak","name":"柏喙"}],"source":"https://prts.wiki/w/%E6%9F%8F%E5%96%99"},{"id":"char_4166_varkis","name":"摆渡人","en":"Varkáris","kind":"operator","region":"minos","origin":"米诺斯","faction":"米诺斯","profession":"近卫","aliases":[],"title":"摆渡人的渡口职务与就医记录","summary":"赞索斯曾任雅赛努斯特尔斐运河渡口管理者，在第一神殿文物交换仪式后辞职。经调香师介绍，他来到罗德岛治疗矿石病，以摆渡人为代号担任近卫。此前事件使人事与医疗部门在接待时保持警惕；实际就医过程中，他配合治疗，先前担心的冲突并未发生。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[],"forms":[{"id":"char_4166_varkis","name":"摆渡人"}],"source":"https://prts.wiki/w/%E6%91%86%E6%B8%A1%E4%BA%BA"},{"id":"char_325_bison","name":"拜松","en":"Bison","kind":"operator","region":"lungmen","origin":"龙门","faction":"炎-龙门","profession":"重装","aliases":[],"title":"拜松的物流接洽与交流经历","summary":"拜松是峯驰物流部门执行经理，负责与企鹅物流的合作接洽，并依合约协助罗德岛行动。他年龄较轻，但熟悉物流知识，拥有丰富工作经验，通常以沉稳方式确保交付。档案记录，企鹅物流的工作经历让他注意到自身不足，也重新考虑了对信使职业的理解。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"充实的假期","intro":"在学着怎么工作之前，最好先学会如何休假。"}],"forms":[{"id":"char_325_bison","name":"拜松"}],"source":"https://prts.wiki/w/%E6%8B%9C%E6%9D%BE"},{"id":"char_284_spot","name":"斑点","en":"Spot","kind":"operator","region":"rhodes","origin":"萨尔贡","faction":"行动预备组A6","profession":"重装","aliases":[],"title":"斑点的军旅背景与小队职责","summary":"斑点曾为萨尔贡士兵，主动向罗德岛求职，通过测试后被分配到预备行动组A6，担任防御人员。档案确认他具有守护方面的经验。日常记录则描述他较少说话，缺乏明显干劲，发言有时带有讽刺，与队伍其他成员的表现存在差异；现有资料未详细披露其早期服役经过。","focus":"工作履历与日常性格评价应分开理解，早期军旅情况仍有资料缺口。","memories":[{"title":"谁是英雄","intro":"或许，迎接真实的自己也是一种英雄的业绩？"}],"forms":[{"id":"char_284_spot","name":"斑点"}],"source":"https://prts.wiki/w/%E6%96%91%E7%82%B9"},{"id":"char_388_mint","name":"薄绿","en":"Mint","kind":"operator","region":"victoria","origin":"维多利亚","faction":"维多利亚","profession":"术师","aliases":[],"title":"薄绿的地质研究与入职经历","summary":"薄绿在维多利亚高等学府研究地质，参与多项实地项目。她选择升学留校，后来在关键考察中感染矿石病，经天火介绍到罗德岛治疗，同时从事源石理论与环境地质评测。档案将她描述为外表文静、实际好奇且活跃，并指出她较看重地质研究，而非单纯的术师身份。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[{"title":"昔日重现","intro":"你有没有问过自己，你的这份执着，究竟从何而来？"}],"forms":[{"id":"char_388_mint","name":"薄绿"}],"source":"https://prts.wiki/w/%E8%96%84%E7%BB%BF"},{"id":"char_230_savage","name":"暴行","en":"Savage","kind":"operator","region":"rim","origin":"雷姆必拓","faction":"雷姆必拓","profession":"近卫","aliases":[],"title":"矿业安保经历与爆破技艺","summary":"暴行曾在雷姆必拓矿业公司负责安保，执行过硬目标破坏和要员保护任务，后成为罗德岛近卫干员。她使用爆破锤配合源石技艺制造延时爆破。工程检查表明，锤体并无独立爆破装置，效果来自内部源石排列与她的施术，相关原理仍在研究。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"沉痛转机","intro":"一份责任，一个时机。"},{"title":"自有一“派”","intro":"为什么暴行对卡特斯这么友爱？呀，卡特斯人就是应该暖烘烘地凑在一起嘛！ 吃一块胡萝卜派，听听她的想法。"}],"forms":[{"id":"char_230_savage","name":"暴行"}],"source":"https://prts.wiki/w/%E6%9A%B4%E8%A1%8C"},{"id":"char_304_zebra","name":"暴雨","en":"Heavyrain","kind":"operator","region":"rhodes","origin":"萨尔贡","faction":"罗德岛","profession":"重装","aliases":[],"title":"暴雨离开萨尔贡军队之后","summary":"暴雨曾在萨尔贡一名王酋麾下服役，遭同僚背叛后离开军队，经过辗转加入罗德岛，现以重装干员身份参与任务。她在群体活动中较少发言，初见时常被认为阴沉。共同执行过任务的干员则评价她温和、细心，认为她主要是不擅长表达，而不是拒绝与人合作。","focus":"保留不同观察者的评价差异，不将初见印象写成确定的人格结论。","memories":[{"title":"不合时宜","intro":"士兵手中的长刀本应划开敌人的坚盾，可如今却要指向战友的后背。"}],"forms":[{"id":"char_304_zebra","name":"暴雨"}],"source":"https://prts.wiki/w/%E6%9A%B4%E9%9B%A8"},{"id":"char_4037_demetr","name":"贝洛内","en":"Bellone","kind":"operator","region":"siracusa","origin":"叙拉古","faction":"叙拉古","profession":"近卫","aliases":[],"title":"贝洛内家主的合作登记","summary":"贝洛内是叙拉古贝洛内家族在此阶段的家主，经伺夜介绍，与罗德岛开展情报交换和商品贸易。他初次来访时，人事部门发现旧档案曾把伺夜记作该家族最后一任领袖，因此需要重新处理身份记录。档案记述他常面带微笑，但在与人交往时仍会带来压迫感。","focus":"旧档案与现任职务属于不同时点，不宜将早期表述当作永久状态。","memories":[{"title":"一个没有家主的家族","intro":"他为背叛而愤怒，为失序而迷茫，这些对他而言都是很新奇的情绪，但他没有时间去细细体味。"}],"forms":[{"id":"char_4037_demetr","name":"贝洛内"}],"source":"https://prts.wiki/w/%E8%B4%9D%E6%B4%9B%E5%86%85"},{"id":"char_369_bena","name":"贝娜","en":"Bena","kind":"operator","region":"victoria","origin":"维多利亚","faction":"维多利亚","profession":"特种","aliases":[],"title":"贝娜的访舰调查与人偶技艺","summary":"贝娜为将爱丽丝带回维多利亚而来到罗德岛，最初怀疑对方的自由受到限制。约两个月调查后，她承认判断有误，随后仍选择陪同爱丽丝留岛，并登记为临时干员。她掌握操控人偶的特殊技艺，但考虑年龄和本人意愿，通常不被派往前线。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"简单的愿望","intro":"孩子的愿望总是很简单，就算产生变化，也仍是那么纯真且质朴。"}],"forms":[{"id":"char_369_bena","name":"贝娜"}],"source":"https://prts.wiki/w/%E8%B4%9D%E5%A8%9C"},{"id":"char_265_sophia","name":"鞭刃","en":"Whislash","kind":"operator","region":"kazimierz","origin":"卡西米尔","faction":"卡西米尔","profession":"近卫","aliases":[],"title":"鞭刃的竞技经历与教官任职","summary":"鞭刃本名佐菲娅，是临光与瑕光的姑母，曾作为竞技骑士进入卡西米尔特锦赛十六强。她原惯用左手，因伤改用右手，战斗状态不及巅峰时期。加入罗德岛后，她进入教官队伍，主要训练其他干员，必要时参加任务。档案强调其观察和指导能力，也记有较为强势的交往方式。","focus":"区分伤前竞技经历与目前教官岗位，不将受伤解释为完全退出行动。","memories":[{"title":"独家访谈","intro":"她包里总是装着很多东西，要找到那串钥匙，总是要费些功夫。"}],"forms":[{"id":"char_265_sophia","name":"鞭刃"}],"source":"https://prts.wiki/w/%E9%9E%AD%E5%88%83"},{"id":"char_4104_coldst","name":"冰酿","en":"Coldshot","kind":"operator","region":"columbia","origin":"哥伦比亚","faction":"哥伦比亚","profession":"狙击","aliases":[],"title":"冰酿的拓荒经验与办事处合作","summary":"海伦娜经杰西卡介绍成为罗德岛合作干员，帮助哥伦比亚拓荒地办事处。她熟悉烹饪、调酒、缝纫、狩猎、锻造与载具维修，相关技能主要来自长期拓荒生活。抵舰后，她会主动邀请同僚品尝食物、分享做法，也能模仿羽兽叫声，对野外生物习性保持观察。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[{"title":"一路顺风","intro":"只有那子弹和烈酒，能够温暖她。"}],"forms":[{"id":"char_4104_coldst","name":"冰酿"}],"source":"https://prts.wiki/w/%E5%86%B0%E9%85%BF"},{"id":"char_487_bobb","name":"波卜","en":"Bobbing","kind":"operator","region":"columbia","origin":"哥伦比亚","faction":"哥伦比亚","profession":"辅助","aliases":[],"title":"赤心医疗代表的交流任职","summary":"埃利西奥作为赤心医疗代表来到罗德岛交流，并申请使用波卜这一代号，参与谈判、救援和情绪安抚工作。人事部核查时注意到赤心医疗与梅兰德的组织关系，对其保持审慎态度。其夜间进入医疗部的记录出现后，相关人员决定与他直接讨论此事。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"谁与同行","intro":"他想知道，靠一个人的努力无法改变的事，与志同道合者一起努力，结果是否会有不同。"}],"forms":[{"id":"char_487_bobb","name":"波卜"}],"source":"https://prts.wiki/w/%E6%B3%A2%E5%8D%9C"},{"id":"char_258_podego","name":"波登可","en":"Podenco","kind":"operator","region":"rhodes","origin":"玻利瓦尔","faction":"罗德岛","profession":"辅助","aliases":[],"title":"波登可的种植经验与庭院工作","summary":"波登可出生于玻利瓦尔边境高原聚落，当地居民主要依靠躲避天灾与培育作物维持生活。她自幼接触植物，后来参加农作物培植，积累食用和观赏植物的照护经验。经普通招聘进入罗德岛后，她在调香师负责的庭院照看温室，也利用植物知识参与医疗支援和战场干扰。","focus":"依据种植与任职记录说明技术来源，不以庭院工作代替完整个人经历。","memories":[{"title":"花期","intro":"希望花香会让大家开心。"}],"forms":[{"id":"char_258_podego","name":"波登可"}],"source":"https://prts.wiki/w/%E6%B3%A2%E7%99%BB%E5%8F%AF"},{"id":"char_4223_botany","name":"伯塔尼","en":"Ботани","kind":"operator","region":"ursus","origin":"乌萨斯","faction":"乌萨斯","profession":"辅助","aliases":[],"title":"伯塔尼的学业与通讯研究","summary":"伯塔尼曾以季申娜·维克托罗夫娜·别利亚耶娃之名在圣骏堡帝国理工大学就读，肄业后经凛冬介绍加入罗德岛。她继续学习和研究源石通讯技术，并参加外勤。现有资料指出，该姓名并非她最早使用的名字；奖状、旧照片与处罚决定书共同记录了此前的部分经历。","focus":"姓名使用存在阶段变化，本条仅采用给定记录，不补造更早身份。","memories":[{"title":"发声","intro":"忠诚的帝国公民季申娜，你要做的，只是聆听。"}],"forms":[{"id":"char_4223_botany","name":"伯塔尼"}],"source":"https://prts.wiki/w/%E4%BC%AF%E5%A1%94%E5%B0%BC"},{"id":"char_4004_pudd","name":"布丁","en":"Pudding","kind":"operator","region":"columbia","origin":"哥伦比亚","faction":"哥伦比亚","profession":"术师","aliases":[],"title":"布丁的电气工程与系统维护","summary":"布丁原为哥伦比亚电气工程师，考察中感染矿石病后，到罗德岛求职并接受治疗。她经可露希尔选拔进入工程部，重新整理图纸，推进安全测试和电力系统优化。档案记载，其协助工作提高了能源转换效率，她也因首季度表现获得绩效奖励并申请休假。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"远方的雪","intro":"很长一段时间里，布丁对萨米的记忆就像一颗小小的雪景球，凝固如初。"}],"forms":[{"id":"char_4004_pudd","name":"布丁"}],"source":"https://prts.wiki/w/%E5%B8%83%E4%B8%81"},{"id":"char_356_broca","name":"布洛卡","en":"Broca","kind":"operator","region":"siracusa","origin":"叙拉古","faction":"贾维团伙","profession":"近卫","aliases":[],"title":"布洛卡从家族打手到攻坚手","summary":"布洛卡曾是叙拉古某城市的家族打手，后来加入贾维团伙，并随贾维来到罗德岛，现作为攻坚手参加前线任务。他平时寡言，表情严肃，初见时容易让人感到难以接近。进一步接触的同事则认为他性情厚道；档案说明，那副凶狠表情与过去雇主的要求有关。","focus":"早期职业习惯与目前的交往评价并列记录，不以面部表情判断动机。","memories":[{"title":"信任的第一步","intro":"想要让一个人信任你，最好的做法是用行动证明。"},{"title":"愤怒的布洛卡","intro":"贾维永远也无法理解，他为什么惹布洛卡生气。"}],"forms":[{"id":"char_356_broca","name":"布洛卡"}],"source":"https://prts.wiki/w/%E5%B8%83%E6%B4%9B%E5%8D%A1"},{"id":"char_4155_talr","name":"裁度","en":"Figurino","kind":"operator","region":"siracusa","origin":"叙拉古","faction":"叙拉古","profession":"特种","aliases":[],"title":"裁度的制衣业务与交流任职","summary":"裁度本名卢奇诺·德蒙塔诺，是叙拉古裁缝名店的现任主理人，经当地办事处推荐来舰交流，暂在后勤部工作。他与梓兰合作撰写服装文章、试做样衣，并邀请干员担任模特。相关活动影响了部分成员的日常着装，也让他在制衣本业之外参与罗德岛的支持工作。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[{"title":"体面的本分","intro":"他不再向往所谓的“大人物”和他们的体面。裁缝的剪刀，只为剪裁布料而开刃。"}],"forms":[{"id":"char_4155_talr","name":"裁度"}],"source":"https://prts.wiki/w/%E8%A3%81%E5%BA%A6"},{"id":"char_4106_bryota","name":"苍苔","en":"Bryophyta","kind":"operator","region":"siesta","origin":"汐斯塔","faction":"汐斯塔","profession":"近卫","aliases":[],"title":"苍苔的餐吧经历与后勤任职","summary":"苍苔原名埃尼斯·维瑟，与家人在汐斯塔风情街经营纯白火山餐吧。火山爆发后，经锡兰介绍来到罗德岛接受规范治疗，并加入后勤部。入职后，他参与设备维修、饮品制作及其他日常事务，逐渐成为干员们处理生活问题时经常联系的工作人员。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"风情街的日与夜","intro":"夏日短暂如歌，而时间总是公平的，他们会慢慢长大。"}],"forms":[{"id":"char_4106_bryota","name":"苍苔"}],"source":"https://prts.wiki/w/%E8%8B%8D%E8%8B%94"},{"id":"char_289_gyuki","name":"缠丸","en":"Matoimaru","kind":"operator","region":"higashi","origin":"东国","faction":"东","profession":"近卫","aliases":[],"title":"缠丸的武者经历与日常活动","summary":"缠丸来自东国，曾以流浪武者身份行动，后因偶然机会加入罗德岛。她擅长使用大型薙刀，战斗方式直接，但不以谋划见长。日常兴趣包括比武、踢球和插花，也会主动邀请同事参加活动。档案同时记有她容易相信新骗局的情况，具体早期游历经过并未完整公布。","focus":"本篇仅列明已知技能、兴趣与行为，不扩写东国流浪时期的遭遇。","memories":[{"title":"鬼的逮捕令","intro":"多年的游历告诉她一件事：绝不能相信“不劳而获”这四个字。"}],"forms":[{"id":"char_289_gyuki","name":"缠丸"}],"source":"https://prts.wiki/w/%E7%BC%A0%E4%B8%B8"},{"id":"char_4047_pianst","name":"车尔尼","en":"Czerny","kind":"operator","region":"leithanien","origin":"莱塔尼亚","faction":"莱塔尼亚","profession":"重装","aliases":[],"title":"车尔尼的音乐事业与合作任职","summary":"车尔尼是莱塔尼亚夕照区音乐家，兼具作曲与钢琴演奏能力，作品在当地生活场景中广泛传唱。他因矿石病较少外出，维谢海姆事件中又一度生命垂危。此后，他在当地罗德岛办事处兼职重装干员，并获得离开莱塔尼亚的机会，个人活动范围也随合作逐步扩大。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[{"title":"夕阳与朝日","intro":"他知道，总有一天，他也会走下山峰。"},{"title":"阳光洒落之前","intro":"他咬着牙扳开那道裂隙，光流汹涌而出。"}],"forms":[{"id":"char_4047_pianst","name":"车尔尼"}],"source":"https://prts.wiki/w/%E8%BD%A6%E5%B0%94%E5%B0%BC"},{"id":"char_010_chen","name":"陈","en":"Ch'en","kind":"operator","region":"lungmen","origin":"龙门","faction":"龙门近卫局","profession":"近卫","aliases":["陈晖洁"],"title":"陈的警务履历与施术测试","summary":"陈毕业于维多利亚皇家近卫学校，曾任龙门高级警司和特别督察组组长，参与多类执法行动，后以特别人员身份支援罗德岛。相关测试记录，她对源石技艺的控制仍不稳定，可能造成器械和环境损坏，并在施术后疲劳；评估认为适当媒介或有帮助。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"一鼓作气","intro":"一鼓作气，再而衰。"}],"forms":[{"id":"char_010_chen","name":"陈"},{"id":"char_1013_chen2","name":"假日威龙陈"},{"id":"char_1050_chen3","name":"赤刃明霄陈"}],"source":"https://prts.wiki/w/%E9%99%88"},{"id":"char_1027_greyy2","name":"承曦格雷伊","en":"Greyy the Lightningbearer","kind":"operator","region":"rhodes","origin":"玻利瓦尔","faction":"罗德岛","profession":"狙击","aliases":[],"title":"承曦格雷伊的工程任职与受教","summary":"通过工程师相关科目测试后，格雷伊在罗德岛工程部从事新技术研发和应用，也参与作战与技术实测。早期工作记录显示，他曾因过度投入检修等事务而消耗体力，医疗部为此收到反馈。后来Mechanist收他为学徒，对其学习与工作提供指导，此类过劳反馈随之减少。","focus":"按异格阶段记录工程成长与受教过程，不将过度工作描述为必要标准。","memories":[{"title":"撰写光明","intro":"他的笔记录下数据，也记录下想感谢的人。"}],"forms":[{"id":"char_253_greyy","name":"格雷伊"},{"id":"char_1027_greyy2","name":"承曦格雷伊"}],"source":"https://prts.wiki/w/%E6%89%BF%E6%9B%A6%E6%A0%BC%E9%9B%B7%E4%BC%8A"},{"id":"char_377_gdglow","name":"澄闪","en":"Goldenglow","kind":"operator","region":"victoria","origin":"维多利亚","faction":"维多利亚","profession":"术师","aliases":[],"title":"澄闪的求学工作与后勤任职","summary":"苏茜出生于维多利亚博森德尔，因家庭经济困难中断术师学业，父亲去世后做信差并意外感染矿石病。迁居卡拉顿后，她卷入当地议员阴谋，经夏栎等人举荐加入罗德岛。现以澄闪为代号在理发室工作，同时修习预备术师课程，学习控制自身能力。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[{"title":"纯属意外","intro":"人的一生中总会发生些让人不得安生的事，而有些人身上发生得更多些。"}],"forms":[{"id":"char_377_gdglow","name":"澄闪"}],"source":"https://prts.wiki/w/%E6%BE%84%E9%97%AA"},{"id":"char_445_wscoot","name":"骋风","en":"Windscoot","kind":"operator","region":"yan","origin":"炎","faction":"炎","profession":"近卫","aliases":[],"title":"骋风的运输合作与助学记录","summary":"骋风在尚蜀周边长期走镖，因病到罗德岛就医，随后签约提供药物运输和人才引荐。档案记载，他曾匿名资助一位因经济困难无法进修的练琴者。调查确认款项来源后，双方约定日后由罗德岛转交还款，骋风也接受了相关负责人对其处理方式的批评。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"只待天明","intro":"他还在担心自己给叔叔阿姨们带错了路，他们却已在背后推着他走。"}],"forms":[{"id":"char_445_wscoot","name":"骋风"}],"source":"https://prts.wiki/w/%E9%AA%8B%E9%A3%8E"},{"id":"char_4065_judge","name":"斥罪","en":"Penance","kind":"operator","region":"siracusa","origin":"叙拉古","faction":"叙拉古","profession":"重装","aliases":[],"title":"斥罪的法官经历与法律顾问工作","summary":"斥罪曾任叙拉古城邦法官，得到贝洛内家族支持，但也判处过该家族成员的罪行。经德克萨斯联系，她来到罗德岛担任法律顾问，并表示希望弥补过去违背法律正义的行为。后续观察记载，她能理解罗德岛部分业务的实际目的，也能与处理方式不同的同事合作。","focus":"保留其本人对旧工作的反省，不据此推定所有既往判决的性质。","memories":[{"title":"为你撑伞","intro":"在叙拉古，一个人能选择的未来并不多。"}],"forms":[{"id":"char_4065_judge","name":"斥罪"}],"source":"https://prts.wiki/w/%E6%96%A5%E7%BD%AA"},{"id":"char_475_akafyu","name":"赤冬","en":"Akafuyu","kind":"operator","region":"higashi","origin":"东国","faction":"东","profession":"近卫","aliases":[],"title":"赤冬的剑术与作战适应","summary":"赤冬来自东国，是信影流居合据物斩剑法传人，也掌握现代战斗技巧。她的视力低于常人，检查认为并非疾病所致，现有技术无法矫正；其他感官与训练使其战斗表现仍然优秀。来到罗德岛后，她需要磨合团队作战方式，生活中则偶有因视力产生的碰撞。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[{"title":"异乡剑士","intro":"远离战斗的生活是什么样的？"}],"forms":[{"id":"char_475_akafyu","name":"赤冬"}],"source":"https://prts.wiki/w/%E8%B5%A4%E5%86%AC"},{"id":"char_1050_chen3","name":"赤刃明霄陈","en":"Ch'en the Dawnstreak","kind":"operator","region":"yan","origin":"龙门","faction":"炎","profession":"近卫","aliases":[],"title":"陈辞职后的外派支援工作","summary":"这一阶段的陈已经辞去龙门高级警司及特别督察组组长职务，正式成为罗德岛成员。她依据个人意愿更多执行外派任务，为各地干员提供支援和现场指导，仍参与危机处置。同期档案另记述整合运动村落中的生产变化，但未在所给片段中展开完整行动过程。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[],"forms":[{"id":"char_010_chen","name":"陈"},{"id":"char_1013_chen2","name":"假日威龙陈"},{"id":"char_1050_chen3","name":"赤刃明霄陈"}],"source":"https://prts.wiki/w/%E8%B5%A4%E5%88%83%E6%98%8E%E9%9C%84%E9%99%88"},{"id":"char_4082_qiubai","name":"仇白","en":"Qiubai","kind":"operator","region":"yan","origin":"炎","faction":"炎","profession":"近卫","aliases":[],"title":"仇白的游历与炎国合作任务","summary":"仇白出生于炎国姜齐城附近水寨，因家庭变故离乡，长期游历，没有固定职业与住处。她曾与多名罗德岛干员在不同事件中接触，并介入勾吴城药材采购受阻的交涉。相关记录显示，商人随后解除限制药农的协议。之后她接受合作邀请，支持罗德岛在炎国的事务。","focus":"采购事件中的交谈内容未公开，不将推测写成明确的威胁或交换条件。","memories":[{"title":"如冰碎雪融","intro":"在那数千里长路上，她曾以为执剑是为了了断恩怨，也曾有人劝她收剑以避开恩怨。"}],"forms":[{"id":"char_4082_qiubai","name":"仇白"}],"source":"https://prts.wiki/w/%E4%BB%87%E7%99%BD"},{"id":"char_174_slbell","name":"初雪","en":"Pramanix","kind":"operator","region":"kjerag","origin":"谢拉格","faction":"谢拉格","profession":"辅助","aliases":["恩雅"],"title":"初雪的圣女职务与留舰记录","summary":"初雪出身谢拉格，担任喀兰圣女与宗教领袖，使用圣铃施展风雪相关技艺。她在当地享有宗教权首的礼仪地位，银灰在公开场合也须向她行礼。她后来经保密途径来到罗德岛，具体工作与停留时间未公开。档案同时指出，尊贵头衔并未消除其个人苦痛。","focus":"本条采用初雪早期档案，未将圣聆初雪阶段的职责并入。","memories":[{"title":"雪山外","intro":"她第一次离开谢拉格，但不是第一次向外看。"}],"forms":[{"id":"char_174_slbell","name":"初雪"},{"id":"char_1046_sbell2","name":"圣聆初雪"}],"source":"https://prts.wiki/w/%E5%88%9D%E9%9B%AA"},{"id":"char_1016_agoat2","name":"纯烬艾雅法拉","en":"Eyjafjalla the Hvít Aska","kind":"operator","region":"leithanien","origin":"莱塔尼亚","faction":"莱塔尼亚","profession":"医疗","aliases":[],"title":"艾雅法拉的研究与听力变化","summary":"艾雅法拉继续从事火山研究和天灾信使工作，参与纪录片拍摄及相关书籍编写，同时在罗德岛治疗。档案记录，她的听力继续恶化，主要结合助听器和唇语理解对话。她说明交流改善源于适应方法，而非病情好转，并提出希望得到正常的交流对待。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"夜色中的第一步","intro":"这个约定永远生效，不论何时，不论何地。"}],"forms":[{"id":"char_180_amgoat","name":"艾雅法拉"},{"id":"char_1016_agoat2","name":"纯烬艾雅法拉"}],"source":"https://prts.wiki/w/%E7%BA%AF%E7%83%AC%E8%89%BE%E9%9B%85%E6%B3%95%E6%8B%89"},{"id":"char_427_vigil","name":"伺夜","en":"Vigil","kind":"operator","region":"siracusa","origin":"叙拉古","faction":"叙拉古","profession":"先锋","aliases":[],"title":"伺夜的家族身份与新城合作","summary":"伺夜曾是叙拉古贝洛内家族最后一任领袖，后成为新沃尔西尼市长候补，经德克萨斯代表城市与罗德岛合作。他具有中距离作战经验和指挥能力。初次登舰时，部分干员因其背景保持谨慎，贾维主动与其交谈，双方没有发生预想中的冲突，并建立了较平和的交流。","focus":"按新沃尔西尼合作时期叙述，不把家族背景直接等同于当前政治立场。","memories":[{"title":"未来将至","intro":"时间将审判我。"},{"title":"双刃剑","intro":"回过头看，许多事，他在当时就已经明白了。"}],"forms":[{"id":"char_427_vigil","name":"伺夜"}],"source":"https://prts.wiki/w/%E4%BC%BA%E5%A4%9C"},{"id":"char_494_vendla","name":"刺玫","en":"Vendela","kind":"operator","region":"victoria","origin":"维多利亚","faction":"维多利亚","profession":"医疗","aliases":[],"title":"刺玫的幸存经历与家乡重建","summary":"玛格达尔在布伦特伍德血魔大君仪式中幸存，家传温室遭到毁坏。受洛洛与费斯特邀请，她加入伦蒂尼姆市民自救军承担后勤，之后来到罗德岛。认识到幸存居民仍面临健康问题后，她主动申请医疗相关工作。事件结束后，她返回维多利亚重建家乡，兼任办事处联络员。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[{"title":"新东西","intro":"对许多人来说，敌人已经离开，但痛苦将绵长地停留。药物是必须的，鲜花也是。"}],"forms":[{"id":"char_494_vendla","name":"刺玫"}],"source":"https://prts.wiki/w/%E5%88%BA%E7%8E%AB"},{"id":"char_1031_slent2","name":"淬羽赫默","en":"Silence the Paradigmatic","kind":"operator","region":"columbia","origin":"哥伦比亚","faction":"莱茵生命","profession":"辅助","aliases":[],"title":"科学伦理宣言后的合作调整","summary":"赫默发起特里蒙科学伦理联合宣言后，担任莱茵生命执行顾问，工作重心转向特里蒙，不再长期驻留本舰。她与医疗部交接后，仍希望继续医学协作。考虑到公共身份带来的立场问题，她提出以患者身份接受治疗，为与罗德岛维持个人联系保留空间。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[],"forms":[{"id":"char_108_silent","name":"赫默"},{"id":"char_1031_slent2","name":"淬羽赫默"}],"source":"https://prts.wiki/w/%E6%B7%AC%E7%BE%BD%E8%B5%AB%E9%BB%98"},{"id":"char_362_saga","name":"嵯峨","en":"Saga","kind":"operator","region":"higashi","origin":"东国","faction":"东","profession":"先锋","aliases":[],"title":"嵯峨的入职经过与设备学习","summary":"嵯峨是东国云游僧人，部分早期经历不明。她因迷路进入罗德岛办事处，表达求职意向后通过测试，成为先锋干员，擅长使用薙刀。她此前已认识炎熔。登舰后，她较快熟悉同事，也积极学习现代设备的使用，虽然初学时发生过失误，但随后能够熟练操作。","focus":"保留早期游历的资料空白，学习记录不代表其已掌握所有现代技术。","memories":[{"title":"未必空","intro":"问醒何曾醒，云空未必空。"}],"forms":[{"id":"char_362_saga","name":"嵯峨"}],"source":"https://prts.wiki/w/%E5%B5%AF%E5%B3%A8"},{"id":"char_157_dagda","name":"达格达","en":"Dagda","kind":"operator","region":"victoria","origin":"维多利亚","faction":"格拉斯哥帮","profession":"近卫","aliases":[],"title":"达格达的骑士经历与小队任务","summary":"达格达曾是伦蒂尼姆塔楼骑士，后来加入格拉斯哥帮，并随推进之王进入罗德岛。她作为小队成员执行攻坚任务，对战术指令适应较快，既能协同作战，也具有独立应变能力。任务之外，她与其他干员保持一定距离；档案没有据此否定其工作能力，而是分别记录两类表现。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[{"title":"脚步不停","intro":"她对荣耀、责任、爱国充满了不切实际的幻想。现实却一直拷打她：萨卡兹的入侵、老一辈的牺牲、自欺欺人。她该做个选择了。"}],"forms":[{"id":"char_157_dagda","name":"达格达"}],"source":"https://prts.wiki/w/%E8%BE%BE%E6%A0%BC%E8%BE%BE"},{"id":"char_4110_delphn","name":"戴菲恩","en":"Delphine","kind":"operator","region":"victoria","origin":"维多利亚","faction":"维多利亚","profession":"术师","aliases":[],"title":"戴菲恩的军事经历与旅行准备","summary":"戴菲恩曾在诺伯特区从事情报工作，后以典范军成员身份参与伦蒂尼姆周边战役。维多利亚事件后，她协助罗德岛当地办事处。档案确认她是温德米尔公爵之女，但目前未使用可继承的多项资源；驻舰时主要训练、搜集旅行资料，并关注混乱地区的情况。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[],"forms":[{"id":"char_4110_delphn","name":"戴菲恩"}],"source":"https://prts.wiki/w/%E6%88%B4%E8%8F%B2%E6%81%A9"},{"id":"char_4032_provs","name":"但书","en":"Proviso","kind":"operator","region":"kazimierz","origin":"卡西米尔","faction":"卡西米尔","profession":"辅助","aliases":[],"title":"但书离开长缰律所后的任职","summary":"但书本名黛丝特，曾在卡西米尔长缰律所从事诉讼与非诉业务，具有大量案件经验。罗德岛调查认可她的能力，也注意到旧案中部分手段和正义取向的问题。她说明既往事务已处理，并因关注罗德岛在特锦赛中的行动而选择求职，现担任法律顾问，继续审核相关文件。","focus":"旧案评价与入职后的工作分开记录，不因转职就判断此前问题已经消除。","memories":[{"title":"假定公正","intro":"任何一件事，都至少有两种解释方向。"}],"forms":[{"id":"char_4032_provs","name":"但书"}],"source":"https://prts.wiki/w/%E4%BD%86%E4%B9%A6"},{"id":"char_4126_fuze","name":"导火索","en":"Fuze","kind":"operator","region":"other","origin":"未知","faction":"彩虹小队","profession":"近卫","aliases":[],"title":"导火索的工程能力与合作记录","summary":"导火索本名舒赫拉特·柯西克巴耶夫，是彩虹小队工程专家，克里斯达尔事件后登记为罗德岛合作人员。他熟悉爆炸物运用，在硬目标爆破等测试中表现良好。主要装备能隔墙打击封闭空间，但不具备敌我识别，因此使用须受环境与战术条件限制。","focus":"本条依据联动后合作登记，不将特殊装备视为可无条件使用的能力。","memories":[{"title":"梦醒时分","intro":"为了逃避眼前的悲剧而深陷幻梦，却浑然不知活在梦中才是最大的悲剧。"}],"forms":[{"id":"char_4126_fuze","name":"导火索"}],"source":"https://prts.wiki/w/%E5%AF%BC%E7%81%AB%E7%B4%A2"},{"id":"char_393_toledo","name":"德·托莱多","en":"de Toledo","kind":"operator","region":"iberia","origin":"伊比利亚","faction":"伊比利亚","profession":"辅助","aliases":[],"title":"德托莱多的身份核查与任职","summary":"德·托莱多自称伊比利亚海军将领后裔和失落贵族，在当地拥有一批拥护者。人事核查发现，其口述与审判庭档案严重不符，因此将职业登记为自由职业。经艾丽妮推荐后，她加入罗德岛，以口才和对伊比利亚的了解协助办事处完成基础工作。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[],"forms":[{"id":"char_393_toledo","name":"德·托莱多"}],"source":"https://prts.wiki/w/%E5%BE%B7%C2%B7%E6%89%98%E8%8E%B1%E5%A4%9A"},{"id":"char_102_texas","name":"德克萨斯","en":"Texas","kind":"operator","region":"lungmen","origin":"哥伦比亚","faction":"企鹅物流","profession":"先锋","aliases":[],"title":"德克萨斯的物流与联络岗位","summary":"这份早期档案记载，德克萨斯是企鹅物流员工，具有突出的单兵作战能力。在合约期间，她担任企鹅物流驻罗德岛联络人员，并协助多项行动。日常观察显示她话少，常被认为喜欢独处，但实际多数时候与企鹅物流同事共同出现。资料未在此处详细说明她更早的人生经历。","focus":"采用基础形态的工作时点，不预先加入异格与叙拉古后续经历。","memories":[{"title":"使命必达","intro":"谁能想到会有给败者送货的一天呢？"}],"forms":[{"id":"char_102_texas","name":"德克萨斯"},{"id":"char_1028_texas2","name":"缄默德克萨斯"}],"source":"https://prts.wiki/w/%E5%BE%B7%E5%85%8B%E8%90%A8%E6%96%AF"},{"id":"char_183_skgoat","name":"地灵","en":"Earthspirit","kind":"operator","region":"leithanien","origin":"莱塔尼亚","faction":"莱塔尼亚","profession":"辅助","aliases":[],"title":"地灵的地质研究与辅助任务","summary":"地灵是地质学家，现任罗德岛辅助干员，承担环境评估、地形分析、地质勘探及天灾预警。她研究岩石时十分专注，相关成果为舰船与行动提供专业支持。档案也明确记述她保持准时下班的习惯，重视作息和个人生活，并未因研究投入而长期放弃工作之外的安排。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[{"title":"额外的工作","intro":"闲暇的时光，却总是被工作打断。"},{"title":"远方遗物","intro":"工作之外的事情，偶尔要比工作更复杂。"}],"forms":[{"id":"char_183_skgoat","name":"地灵"}],"source":"https://prts.wiki/w/%E5%9C%B0%E7%81%B5"},{"id":"char_1034_jesca2","name":"涤火杰西卡","en":"Jessica the Liberated","kind":"operator","region":"columbia","origin":"维多利亚","faction":"黑钢国际","profession":"重装","aliases":[],"title":"杰西卡离开黑钢后的治安工作","summary":"杰西卡与黑钢在行事方式上的分歧逐渐加深，最终离开基地及家族环境，前往拓荒地担任治安官。她组建驮兽队，与罗德岛合作向偏远地区运输药物，并为营地建设获得资金。档案指出，她仍未公开部分佣兵经历，但返舰后独自停留靶场的情况已经减少。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"徽章","intro":"她远比人们想象中坚强。"}],"forms":[{"id":"char_235_jesica","name":"杰西卡"},{"id":"char_1034_jesca2","name":"涤火杰西卡"}],"source":"https://prts.wiki/w/%E6%B6%A4%E7%81%AB%E6%9D%B0%E8%A5%BF%E5%8D%A1"},{"id":"char_4191_tippi","name":"蒂比","en":"Tippi","kind":"operator","region":"columbia","origin":"哥伦比亚","faction":"哥伦比亚","profession":"特种","aliases":[],"title":"蒂比的电影工作与医疗联络","summary":"蒂比在蓝卡坞从事场景喷绘，主动联系罗德岛，希望为当地感染者员工和演员建立医疗合作，同时提供特种作战服务。她参与过多部恐怖片制作，也常邀请朋友观看并分析影片。她说明，研究恐怖片的背景、声音、道具和表演，是为了学习如何共同形成影片所需的气氛。","focus":"记录本人陈述的学习目的与实际职业，不将娱乐兴趣扩写为全部创作经历。","memories":[{"title":"获奖感言","intro":"对于蓝卡坞来说，能成名的人太少，想成名的人太多。这件事再正常不过。"}],"forms":[{"id":"char_4191_tippi","name":"蒂比"}],"source":"https://prts.wiki/w/%E8%92%82%E6%AF%94"},{"id":"char_4195_radian","name":"电弧","en":"Raidian","kind":"operator","region":"rhodes","origin":"乌萨斯","faction":"罗德岛-精英干员","profession":"辅助","aliases":[],"title":"电弧的通讯支援与系统建设","summary":"电弧来自乌萨斯，是罗德岛精英干员，能够通过源石技艺感知电信号。她曾为巴别塔提供通讯支援，后来主导罗德岛早期通讯系统建设，建立相关工作所需的框架。现有输入主要记述她在组织内的技术职责，对个人成长、家庭及其他时期的行动没有提供完整资料。","focus":"本条以通讯职能为主，输入未充分记述的私人经历保持留白。","memories":[],"forms":[{"id":"char_4195_radian","name":"电弧"}],"source":"https://prts.wiki/w/%E7%94%B5%E5%BC%A7"},{"id":"char_181_flower","name":"调香师","en":"Perfumer","kind":"operator","region":"rhodes","origin":"米诺斯","faction":"罗德岛","profession":"医疗","aliases":[],"title":"调香师的嗅觉与疗养庭院工作","summary":"调香师莱娜出身米诺斯富裕家庭，具有敏锐嗅觉和香料调制天赋，经正常招聘进入罗德岛，管理疗养庭院。她能在复杂气味中分辨原料，也尝试把香薰与现代医疗结合。相关记录将其工作列为休养支援，尤其关注气味对情绪调节可能产生的作用。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"改建计划","intro":"花需要生长，庭院也需要扩张。"},{"title":"树犹如此","intro":"并非单纯的怀念，也并非单纯的怨恨。这种复杂的滋味，或许名为“乡愁”。"}],"forms":[{"id":"char_181_flower","name":"调香师"},{"id":"char_1022_flwr2","name":"撷英调香师"}],"source":"https://prts.wiki/w/%E8%B0%83%E9%A6%99%E5%B8%88"},{"id":"char_4208_wintim","name":"冬时","en":"Снегурочка","kind":"operator","region":"ursus","origin":"乌萨斯","faction":"乌萨斯","profession":"先锋","aliases":[],"title":"冬时的研究任职与入职评估","summary":"冬时原是乌萨斯远北中心矿区研究所研究员，来到罗德岛后继续部分既有研究。入职检查曾发现她的行李中有烈酒和镇定剂，医疗部随后开展评估与沟通。后续咨询记录显示，她担心真实状况影响录用，曾有意回避可能导致异常结果的回答，因此早期测试结果不能代表全部情况。","focus":"仅记录已披露的评估局限，不提供诊断，也不复述危险的具体使用方法。","memories":[{"title":"覆录","intro":"她曾以为每个瞬间都弥足珍贵，每步来时路都终将通往梦乡。"}],"forms":[{"id":"char_4208_wintim","name":"冬时"}],"source":"https://prts.wiki/w/%E5%86%AC%E6%97%B6"},{"id":"char_4244_tocka","name":"冻河","en":"Тоска","kind":"operator","region":"ursus","origin":"乌萨斯","faction":"乌萨斯","profession":"辅助","aliases":[],"title":"冻河的接诊经过与身份缺项","summary":"冻河公开履历仅列本名费奥多尔的一部分，其余记录缺失。乌萨斯南部流动医疗队曾收容持续发热的他，因无法控制矿石病症状或确认身份，向罗德岛总部求助。总部同意接收治疗，没有因履历不明拒诊。相关材料从接诊过程切入，尚不足以重建他的完整身世。","focus":"身份缺失属于档案现状，本条不据受限信息推测其真实来历。","memories":[],"forms":[{"id":"char_4244_tocka","name":"冻河"}],"source":"https://prts.wiki/w/%E5%86%BB%E6%B2%B3"},{"id":"char_452_bstalk","name":"豆苗","en":"Beanstalk","kind":"operator","region":"columbia","origin":"哥伦比亚","faction":"哥伦比亚","profession":"先锋","aliases":[],"title":"磐蟹饲养员的入职与侦察工作","summary":"豆苗来自哥伦比亚农场主家庭，多次递交创业计划未果后，经介绍到罗德岛工作。入职当天，她驾驶货车运来磐蟹，并展示了训练成果，证书和实际表现均支持其专业饲养员身份。通过专项测试后，她开始承担后勤和特殊侦察作战服务。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"呼唤荒野","intro":"总有些人需要被教会如何敬畏，小瞧小磐蟹的人都会为他们的浅薄付出代价。"}],"forms":[{"id":"char_452_bstalk","name":"豆苗"}],"source":"https://prts.wiki/w/%E8%B1%86%E8%8B%97"},{"id":"char_130_doberm","name":"杜宾","en":"Dobermann","kind":"operator","region":"rhodes","origin":"玻利瓦尔","faction":"罗德岛","profession":"近卫","aliases":[],"title":"杜宾的军事经历与新人培训","summary":"杜宾曾在玻利瓦尔军队服役，加入罗德岛后担任教官，主要负责基层与新晋干员培训，必要时也承担俘虏审讯。她熟悉不同规模的军事行动，并作为近卫干员参加前线任务。档案记载，新入职人员无论先前履历如何，均需接受她的训练，以适应罗德岛队伍的工作要求。","focus":"本篇以现有培训和作战职责为限，不扩写其在玻利瓦尔的具体服役事件。","memories":[{"title":"在玻利瓦尔以外","intro":"离开吧，你要找的玻利瓦尔不在这里。"}],"forms":[{"id":"char_130_doberm","name":"杜宾"}],"source":"https://prts.wiki/w/%E6%9D%9C%E5%AE%BE"},{"id":"char_501_durin","name":"杜林","en":"Durin","kind":"operator","region":"rhodes","origin":"未公开","faction":"行动组A4","profession":"术师","aliases":[],"title":"杜林的行动组职务与作息","summary":"杜林属于罗德岛A4行动组，具有较强法术天赋，但受体质与性格影响，未能完全发挥。她极易入睡，睡眠时间显著高于干员平均，工作却很少出现缺漏。战斗中，她利用身高和隐蔽位置施术；非工作时通常寻找适合休息的地方。档案将作息与任务表现分开记录。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[{"title":"午休时间","intro":"只要不耽误工作，悠悠闲闲地睡久一点也没什么不好嘛。"}],"forms":[{"id":"char_501_durin","name":"杜林"}],"source":"https://prts.wiki/w/%E6%9D%9C%E6%9E%97"},{"id":"char_4147_mitm","name":"渡桥","en":"Mitm","kind":"operator","region":"rhodes","origin":"卡兹戴尔","faction":"罗德岛","profession":"先锋","aliases":[],"title":"渡桥的街区管理与情报联络","summary":"渡桥原名珀耳，曾在卡兹戴尔以顾问身份参与街区秩序管理，经妮芙推荐后负责当地情报联络。他的自述称自己只是无薪监督员，但外部材料显示，他还维护走私者和孤儿参与的情报网络。人事部认为其表述存在保留，对入职动机和任务风险仍需评估。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"白纸黑字","intro":"他不是没有理想，他只是把那些不好意思说出口的东西藏在伪装下面。"},{"title":"有始有终","intro":"一份报纸本身并不重要，一座城市能生产报纸，城中的人会买报读报，这才重要。"}],"forms":[{"id":"char_4147_mitm","name":"渡桥"}],"source":"https://prts.wiki/w/%E6%B8%A1%E6%A1%A5"},{"id":"char_294_ayer","name":"断崖","en":"Ayerscarpe","kind":"operator","region":"rim","origin":"雷姆必拓","faction":"雷姆必拓","profession":"近卫","aliases":[],"title":"断崖的信使护卫与行动经验","summary":"断崖曾担任天灾信使莱恩哈特的护卫，负责调查期间的安全，也协助搬运仪器等日常工作。两人共同加入罗德岛后，他提供护卫、侦察、渗透与游击方面的经验。他使用从雷姆必拓黑市购入的非制式武器，倾向通过主动攻击排除威胁，以保护任务中的重要目标。","focus":"明确区分日常随行与遭遇危险时的行动方式，不推定未记载的雇佣经过。","memories":[{"title":"黄沙觅迹","intro":"莱恩哈特……他是我的雇主。"}],"forms":[{"id":"char_294_ayer","name":"断崖"}],"source":"https://prts.wiki/w/%E6%96%AD%E5%B4%96"},{"id":"char_159_peacok","name":"断罪者","en":"Conviction","kind":"operator","region":"minos","origin":"米诺斯","faction":"米诺斯","profession":"近卫","aliases":[],"title":"断罪者称号的传说记录","summary":"断罪者又被称为定罪者或艺术拳法家，出现在与古国阿加门及米诺斯周边相关的童话、史书和传说中。不同记录所述种族与外形并不一致，现有材料认为该称呼可能不止指向一个人。其履历因此以传说汇集的形式呈现，不能整理成已经获得实证的单一生平。","focus":"输入包含传说及推断，本条不把多种记载合并为确定的人物历史。","memories":[],"forms":[{"id":"char_159_peacok","name":"断罪者"}],"source":"https://prts.wiki/w/%E6%96%AD%E7%BD%AA%E8%80%85"},{"id":"char_4048_doroth","name":"多萝西","en":"Dorothy","kind":"operator","region":"columbia","origin":"哥伦比亚","faction":"莱茵生命","profession":"特种","aliases":[],"title":"多萝西的研究合作与实验背景","summary":"多萝西是莱茵生命源石技艺应用科主任，以合作项目负责人身份加入罗德岛，使用本名为代号。她在特里蒙骚乱及斐尔迪南被通缉后不久到访，推动双方高等级合作。档案同时指出，她主导的研究产出曾造成危险后果，相关经历属于评估合作时必须考虑的背景。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"何处是我朋友的家","intro":"多萝西·弗兰克斯，我奉劝你最好配合我们的调查工作。"}],"forms":[{"id":"char_4048_doroth","name":"多萝西"}],"source":"https://prts.wiki/w/%E5%A4%9A%E8%90%9D%E8%A5%BF"},{"id":"char_4083_chimes","name":"铎铃","en":"Wind Chimes","kind":"operator","region":"yan","origin":"炎","faction":"炎","profession":"近卫","aliases":[],"title":"铎铃的返乡任职与山村邮路","summary":"铎铃出生于炎国西北山村，曾考入移动城市的学校，后来放弃深造回乡担任信使。她探查便利通行的山道，改善相邻村庄的信息往来，也曾尝试建立村庄与城市间的农产品商贸通道，但计划未成。因矿石病来到罗德岛治疗后，她继续以兼职形式提供信使服务。","focus":"商贸计划受阻的原因并未完整披露，不只用运输成本解释结果。","memories":[{"title":"落叶何归","intro":"只要家还在，人们就还会写下一封又一封家书。"}],"forms":[{"id":"char_4083_chimes","name":"铎铃"}],"source":"https://prts.wiki/w/%E9%93%8E%E9%93%83"},{"id":"char_271_spikes","name":"芳汀","en":"Arene","kind":"operator","region":"laterano","origin":"拉特兰","faction":"拉特兰","profession":"近卫","aliases":[],"title":"芳汀的离境求学与治疗经历","summary":"芳汀是拉特兰出生的萨科塔人，因数年前涉及遗产铳的事件感染矿石病，随后离开拉特兰，前往莱塔尼亚求学。通过专业测试后，他在罗德岛接受治疗并担任近卫。档案解释，拉特兰感染者虽保留公民权利，通常不能在境内长期居留，芳汀的经历应放在这一规定下理解。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[{"title":"亲爱的兰道尔","intro":"意料之外的来信，不该招惹的人。"}],"forms":[{"id":"char_271_spikes","name":"芳汀"}],"source":"https://prts.wiki/w/%E8%8A%B3%E6%B1%80"},{"id":"char_4148_philae","name":"菲莱","en":"Philae","kind":"operator","region":"sargon","origin":"萨尔贡","faction":"萨尔贡","profession":"重装","aliases":[],"title":"菲莱的神庙经历与救灾合作","summary":"菲莱来自萨尔贡，曾任神庙守卫，信奉生命之河，现以虔修者身份游历。她在旅途中与罗德岛办事处建立长期合作，提供安保和救灾援助，兼任外勤重装干员。驻舰时她仍保持静坐习惯，并主动请旁人留出距离，以避免修习中的法术意外伤人。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"新生","intro":"有时候，夺走生命是赋予生机的唯一方式。"}],"forms":[{"id":"char_4148_philae","name":"菲莱"}],"source":"https://prts.wiki/w/%E8%8F%B2%E8%8E%B1"},{"id":"char_300_phenxi","name":"菲亚梅塔","en":"Fiammetta","kind":"operator","region":"laterano","origin":"拉特兰","faction":"拉特兰","profession":"狙击","aliases":[],"title":"菲亚梅塔的公证所合作职责","summary":"菲亚梅塔是拉特兰公证所高级特派员，依罗德岛与教廷的协议获得补给并提供服务。她经常随莫斯提马行动，自称负责监管，正式外交交涉却由莫斯提马单独参加。观察记录认为这一安排与其同伴的特殊身份有关；涉及职权与核心秘密的进一步问题，她没有作出回答。","focus":"监管安排的完整依据未公开，不以观察者推测替代明确的职务说明。","memories":[{"title":"乐园","intro":"故乡，在离开之后才被赋予意涵。"},{"title":"在干净明亮的夜晚","intro":"在告别的时候，我们希望那是一个干净明亮的夜晚。为了过去曾经存在，为了过去不再需要被证明。"}],"forms":[{"id":"char_300_phenxi","name":"菲亚梅塔"}],"source":"https://prts.wiki/w/%E8%8F%B2%E4%BA%9A%E6%A2%85%E5%A1%94"},{"id":"char_123_fang","name":"芬","en":"Fang","kind":"operator","region":"rhodes","origin":"卡西米尔","faction":"行动预备组A1","profession":"先锋","aliases":[],"title":"芬的警备经历与预备队任职","summary":"芬曾在警备队实习，后来与米格鲁、克洛丝一同进入罗德岛行动预备组A1，并担任队长。她具备较好的作战能力，能够较快适应岗位，使用轻便短枪配合机动抢占地形。队友评价她行动急切，有时尚未听完说明就开始执行；三人仍在训练中争取成为独当一面的干员。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[{"title":"二次冲锋","intro":"实力增强之后，便也要承担更大的责任。一直作为小队队长来培养的芬也想证明，自己被寄予期望是值得的。"}],"forms":[{"id":"char_123_fang","name":"芬"},{"id":"char_1036_fang2","name":"历阵锐枪芬"}],"source":"https://prts.wiki/w/%E8%8A%AC"},{"id":"char_4182_oblvns","name":"丰川祥子","en":"Togawa Sakiko","kind":"operator","region":"other","origin":"未知","faction":"Ave Mujica","profession":"近卫","aliases":[],"title":"丰川祥子的暂居与舰内工作","summary":"丰川祥子是乐队键盘手，与伙伴经爱丽丝担保暂居罗德岛。档案记录，她的音乐能力与礼仪显示出良好教育背景，来自名门家庭。罗德岛原希望年轻来客休息，她却明确要求安排工作，不愿无偿留宿，并在停留期间积极参加舰上各项事务。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[],"forms":[{"id":"char_4182_oblvns","name":"丰川祥子"}],"source":"https://prts.wiki/w/%E4%B8%B0%E5%B7%9D%E7%A5%A5%E5%AD%90"},{"id":"char_222_bpipe","name":"风笛","en":"Bagpipe","kind":"operator","region":"victoria","origin":"维多利亚","faction":"维多利亚","profession":"先锋","aliases":[],"title":"风笛退役后的罗德岛任职","summary":"风笛毕业于维多利亚皇家近卫学校，服役三年后退役，经同校好友陈介绍加入罗德岛。通过磨合后，她在多类任务中表现出系统训练形成的战术与战斗素养。日常记录则描述她待人主动、较快与同事熟悉，生活上不拘细节。其军事岗位表现与平常交往方式并不相同。","focus":"将日常观察与职业训练分别记录，不以随和态度推定军事纪律水平。","memories":[{"title":"难行长路","intro":"认定的路，她一定会走下去。"}],"forms":[{"id":"char_222_bpipe","name":"风笛"}],"source":"https://prts.wiki/w/%E9%A3%8E%E7%AC%9B"},{"id":"char_4016_kazema","name":"风丸","en":"Kazemaru","kind":"operator","region":"higashi","origin":"东国","faction":"东","profession":"特种","aliases":[],"title":"风丸的离职转任与情报工作","summary":"风丸曾任东国忍者。旧家主去世后，她在新家主的公司工作半年余，因个人意愿与商业目标不合，经协调转到罗德岛。她现为驻维多利亚情报人员。档案将她对平静办公环境的不适应记为职业转变原因之一，相关忍者经验则继续用于新的情报与外勤任务。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[{"title":"应为必为","intro":"她已不是一个忍者，不需再为谁效忠，但她早已为现在的工作献上自己的忠诚。"},{"title":"在人群之中","intro":"还好，在人群之中、她的背后，她之前付出的努力早已生根发芽。"}],"forms":[{"id":"char_4016_kazema","name":"风丸"}],"source":"https://prts.wiki/w/%E9%A3%8E%E4%B8%B8"},{"id":"char_4222_taraxa","name":"风絮","en":"Taraxacum","kind":"operator","region":"yan","origin":"萨尔贡","faction":"炎","profession":"医疗","aliases":[],"title":"风絮的医学游学与临时任职","summary":"风絮来自萨尔贡，是游历各地的医学学徒，也有丰富驮兽车驾驶经验。他师从一位炎国医师，经年事先介绍到罗德岛交流，作为临时干员提供日常医疗服务。初次见面时，同事注意到他熟悉炎国语言、茶叶产地和古法食品做法，之后很快与当地出身干员熟悉。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[],"forms":[{"id":"char_4222_taraxa","name":"风絮"}],"source":"https://prts.wiki/w/%E9%A3%8E%E7%B5%AE"},{"id":"char_106_franka","name":"芙兰卡","en":"Franka","kind":"operator","region":"columbia","origin":"哥伦比亚","faction":"黑钢国际","profession":"近卫","aliases":[],"title":"芙兰卡的黑钢任职与安保合作","summary":"芙兰卡是黑钢国际生化防护部门的安全保障人员，具有护卫、突击及战术协同经验。她在罗德岛接受矿石病治疗，同时依据合同提供安保服务。档案描述其作风较激进，常以言语戏弄他人，但入职材料、行动协助合同与治疗协议均按程序提交，成为合作判断的依据之一。","focus":"记录其行为特点和手续情况，不将合同完备扩大为所有行动均无风险。","memories":[{"title":"往日的象征","intro":"当她在意的时候，周围的一草一木都是往日的象征；当她不在意的时候，它们什么都不是。"},{"title":"驻足","intro":"目标，是她最讨厌的词。"}],"forms":[{"id":"char_106_franka","name":"芙兰卡"}],"source":"https://prts.wiki/w/%E8%8A%99%E5%85%B0%E5%8D%A1"},{"id":"char_120_hibisc","name":"芙蓉","en":"Hibiscus","kind":"operator","region":"rhodes","origin":"维多利亚","faction":"行动预备组A1","profession":"医疗","aliases":[],"title":"芙蓉的治疗经历与医师养成","summary":"芙蓉出生于伦蒂尼姆，是炎熔的孪生姐姐。感染矿石病后，她来到罗德岛治疗，并在受照顾的过程中希望参与助人工作，经过努力成为医师。档案记述她自幼体贴、勤快，善于照料他人；她也理解妹妹较少表达情感，并未将表面的冷淡视作姐妹关系已经疏远。","focus":"本条采用早期医师档案，不将濯尘芙蓉阶段的主治职务提前。","memories":[{"title":"良方","intro":"她的力量有限，但她会努力坚持得久一点。"}],"forms":[{"id":"char_120_hibisc","name":"芙蓉"},{"id":"char_1024_hbisc2","name":"濯尘芙蓉"}],"source":"https://prts.wiki/w/%E8%8A%99%E8%93%89"},{"id":"char_4031_liesel","name":"复奏","en":"Ripresa","kind":"operator","region":"siracusa","origin":"莱塔尼亚","faction":"叙拉古","profession":"术师","aliases":[],"title":"复奏的乐团经营与钢琴学习","summary":"复奏是新沃尔西尼乐团经理人，观察到当地权力人物与罗德岛的联系后，主动申请商业合作，希望扩大乐团知名度，也按意愿参加部分外勤。她在车尔尼的钢琴课上积极练习，课后递交的录音逐渐从个人习作扩展到不同乐器及整个乐组的演奏。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"春日序曲","intro":"“马赛拉小姐，你喜欢什么颜色？你喜欢吃什么呢？你要不要来我们乐团工作啊？”"}],"forms":[{"id":"char_4031_liesel","name":"复奏"}],"source":"https://prts.wiki/w/%E5%A4%8D%E5%A5%8F"},{"id":"char_474_glady","name":"歌蕾蒂娅","en":"Gladiia","kind":"operator","region":"aegir","origin":"阿戈尔","faction":"深海猎人","profession":"特种","aliases":[],"title":"歌蕾蒂娅的阿戈尔职务与合作","summary":"歌蕾蒂娅是阿戈尔技术执政官、荣誉军团长，也是深海猎人战争设计者之一。她以合作身份协助罗德岛，同时保留阿戈尔职务，并负责相关事务。记录确认其具有突出的多类型作战能力，但登陆时间与地点不明，普通干员与她接触较少，对其个人情况的了解有限。","focus":"阿戈尔官方职务与普通干员传闻分开处理，不将夸张战斗描述全部采信。","memories":[{"title":"失水症","intro":"歌蕾蒂娅不得不适应缺水状态下的一切。"}],"forms":[{"id":"char_474_glady","name":"歌蕾蒂娅"}],"source":"https://prts.wiki/w/%E6%AD%8C%E8%95%BE%E8%92%82%E5%A8%85"},{"id":"char_220_grani","name":"格拉尼","en":"Grani","kind":"operator","region":"victoria","origin":"维多利亚","faction":"维多利亚","profession":"先锋","aliases":[],"title":"格拉尼的骑警经历与合约任务","summary":"格拉尼是维多利亚骑警，在高速机动与突袭作战方面具有天赋。她以合约干员身份支援罗德岛各行动组，主动承担周边巡逻和防卫协助。其家庭保留早期移民带来的朴素传统，她佩戴朋友赠送的卡西米尔语袖标，对骑士文化保持兴趣；现有工作仍以警务和行动支援为主。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[{"title":"穷途不返","intro":"“首先是骑警队，然后是战友、同伴……你会失去，你所保卫与珍爱的一切。”"}],"forms":[{"id":"char_220_grani","name":"格拉尼"}],"source":"https://prts.wiki/w/%E6%A0%BC%E6%8B%89%E5%B0%BC"},{"id":"char_326_glacus","name":"格劳克斯","en":"Glaucus","kind":"operator","region":"iberia","origin":"阿戈尔地区","faction":"伊比利亚","profession":"辅助","aliases":[],"title":"格劳克斯的武器测评与对空任务","summary":"格劳克斯早年离开阿戈尔地区流浪，后加入罗德岛，担任雷神工业先进武器测评工作，研究并调整装备，也执行对空任务。行动记录认为她处理无人机十分有效，但武器可能影响周边设备。相关同伴曾提醒她注意附带损坏，以免长期承担队伍的检修费用。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"以我双腿","intro":"无需他人认可，在格劳克斯的心中，科技自有其形状。"}],"forms":[{"id":"char_326_glacus","name":"格劳克斯"}],"source":"https://prts.wiki/w/%E6%A0%BC%E5%8A%B3%E5%85%8B%E6%96%AF"},{"id":"char_253_greyy","name":"格雷伊","en":"Greyy","kind":"operator","region":"bolivar","origin":"玻利瓦尔","faction":"玻利瓦尔","profession":"术师","aliases":[],"title":"格雷伊的家庭背景与基础任职","summary":"格雷伊来自玻利瓦尔，父亲为工人，母亲曾在福利院工作，家庭收入有限。他继承了一定法术天赋，也有身体较弱的情况。感染矿石病后，原有生活安排发生改变。通过测试进入罗德岛后，他作为术师参加小队行动，并提供基地电力设施维护等服务。","focus":"此篇采用基础形态的早期档案，不提前加入后续工程学徒阶段。","memories":[{"title":"过滤星星","intro":"他学着自己的母亲，努力照亮了一方夜空。"}],"forms":[{"id":"char_253_greyy","name":"格雷伊"},{"id":"char_1027_greyy2","name":"承曦格雷伊"}],"source":"https://prts.wiki/w/%E6%A0%BC%E9%9B%B7%E4%BC%8A"},{"id":"char_196_sunbr","name":"古米","en":"Гум","kind":"operator","region":"ursus","origin":"乌萨斯","faction":"乌萨斯学生自治团","profession":"重装","aliases":[],"title":"古米的学生经历与后勤工作","summary":"古米曾在切尔诺伯格中学就读，并获乌萨斯童子军活动青少年组亚军。来到罗德岛后，她凭体能表现获准担任实习重装干员，同时负责后勤与战地烹饪。她积极参与舰上生活，擅长乌萨斯式料理，但没有职业厨师经验，也未表示要以主厨为职业目标。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[{"title":"缺失的陪伴","intro":"对于孩子来说，没什么能比得上亲人的陪伴。"},{"title":"成长","intro":"为了保护身边的伙伴，古米什么都能做得到。"}],"forms":[{"id":"char_196_sunbr","name":"古米"}],"source":"https://prts.wiki/w/%E5%8F%A4%E7%B1%B3"},{"id":"char_1023_ghost2","name":"归溟幽灵鲨","en":"Specter the Unchained","kind":"operator","region":"aegir","origin":"阿戈尔","faction":"深海猎人","profession":"特种","aliases":[],"title":"幽灵鲨记忆恢复后的状态记录","summary":"幽灵鲨原名劳伦缇娜，是深海猎人成员。愚人号事件后，她的记忆恢复，精神与情绪总体趋稳，也能够谈论失忆时期的经历。医疗部仍观察到激战或情绪强烈时行为方式改变，尚不能确定属于状态复发还是有意模仿，因此建议继续关注而非作出单一结论。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"自我","intro":"记忆回来了，幽灵鲨想要重新确认一下自我的样貌。"}],"forms":[{"id":"char_143_ghost","name":"幽灵鲨"},{"id":"char_1023_ghost2","name":"归溟幽灵鲨"}],"source":"https://prts.wiki/w/%E5%BD%92%E6%BA%9F%E5%B9%BD%E7%81%B5%E9%B2%A8"},{"id":"char_4163_rosesa","name":"瑰盐","en":"Rose Salt","kind":"operator","region":"iberia","origin":"伊比利亚","faction":"伊比利亚","profession":"医疗","aliases":[],"title":"瑰盐的草药医疗与情报协助","summary":"瑰盐原在伊比利亚流动行医，熟悉草药，也与当地不同阶层保持联系，现协助罗德岛开展情报收集与前期调研。登舰后，她主动询问身体不适者并尝试提供帮助，较快取得部分干员好感。但记录也载有她顺走同事手链的行为，提示其日常表现并非只有最初呈现的一面。","focus":"并列已有帮助行为与具体过失，不据其中一项作整体道德判断。","memories":[{"title":"梦想中的好生活","intro":"“你说怎么会有人不想过好日子呢？”"}],"forms":[{"id":"char_4163_rosesa","name":"瑰盐"}],"source":"https://prts.wiki/w/%E7%91%B0%E7%9B%90"},{"id":"char_4246_dminon","name":"国度","en":"Территория","kind":"operator","region":"ursus","origin":"乌萨斯","faction":"乌萨斯","profession":"特种","aliases":[],"title":"国度的收容经过与行为观察","summary":"国度是以乌萨斯皇帝内卫形态现身的坍缩体，已确认不受相关官方机构或通常的乌萨斯意志支配。圣骏堡事变后，它主动来到当地罗德岛办事处，经考察后被收容于本部。友好状态下，它能学习浇花、雕刻和简单乐器；攻击行为则由有权限人员另行记录和评估。","focus":"本条区分已确认的控制关系与观察中的行为，不直接推定完整意识状态。","memories":[{"title":"无名尸","intro":"国度记得最早的事，是看见一具埋在雪里的尸体，某个他不认识的人。"}],"forms":[{"id":"char_4246_dminon","name":"国度"}],"source":"https://prts.wiki/w/%E5%9B%BD%E5%BA%A6"},{"id":"char_394_hadiya","name":"哈蒂娅","en":"Hadiya","kind":"operator","region":"sargon","origin":"哥伦比亚","faction":"萨尔贡","profession":"近卫","aliases":[],"title":"哈蒂娅的战斗训练与荒野适应","summary":"哈蒂娅是萨尔贡裔哥伦比亚人，出自剑角部族后代，为学习战斗主动加入萨尔贡办事处。她使用在哥伦比亚定制的组合机械武器，较擅长有障碍物的近战。对于开阔荒野作战，她承认经验不足，持续向其他萨尔贡干员求教，并在受训同时参加外勤。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"去荒野的路","intro":"总有一天她会离开熟悉的家园，但何处才是她的下一站？"},{"title":"被抗拒者","intro":"既然拒绝与歧视是无法逃避的命题，那唯一的解就不是等待问题消失，而是必须挺身向前。"}],"forms":[{"id":"char_394_hadiya","name":"哈蒂娅"}],"source":"https://prts.wiki/w/%E5%93%88%E8%92%82%E5%A8%85"},{"id":"char_4114_harold","name":"哈洛德","en":"Harold","kind":"operator","region":"victoria","origin":"维多利亚","faction":"维多利亚","profession":"医疗","aliases":[],"title":"哈洛德的军旅与医疗任职","summary":"哈洛德是维多利亚子爵，出自开斯特家族旁支，长期率征召军作战，并在此期间积累临床医疗经验。他公开贵族与军事背景后，坚持以个人身份加入罗德岛，主要担任医疗干员。日常资料还记载其饲养与介绍幼年驮兽的情况，与正式场合的礼仪表现形成明显差异。","focus":"记录其公开身份及目前岗位，不以贵族背景概括所有合作动机。","memories":[{"title":"老兵的义肢","intro":"老哈洛德打心眼儿里喜欢谢拉格，只是，有些事啊，总是难以尽如人意。"}],"forms":[{"id":"char_4114_harold","name":"哈洛德"}],"source":"https://prts.wiki/w/%E5%93%88%E6%B4%9B%E5%BE%B7"},{"id":"char_4045_heidi","name":"海蒂","en":"Heidi","kind":"operator","region":"victoria","origin":"维多利亚","faction":"维多利亚","profession":"辅助","aliases":[],"title":"海蒂的信使工作与自救军经历","summary":"海蒂以小说家的公开身份在维多利亚活动，并长期担任凯尔希的私人信使。她参与伦蒂尼姆市民自救军后遭萨卡兹军抓捕，在罗德岛入城时获救，随后正式成为干员。她并非职业战士，具备一定行动手段及从老师处学习的战术规划知识，其工作与守护家园的行动相连。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[{"title":"第一封信","intro":"她明白对方没有说出的九十九句话，也明白眼前的战争如何让她们无话可说。"}],"forms":[{"id":"char_4045_heidi","name":"海蒂"}],"source":"https://prts.wiki/w/%E6%B5%B7%E8%92%82"},{"id":"char_4066_highmo","name":"海沫","en":"Highmore","kind":"operator","region":"iberia","origin":"伊比利亚","faction":"伊比利亚","profession":"近卫","aliases":[],"title":"海沫的伤后救治与外勤考察","summary":"海沫在伊比利亚行动中受到波及，被送到罗德岛救治。接收时，人员对其特殊状态与其他成员安全有所疑虑，阿米娅进行了担保，医疗部随后处理伤口和增生组织。水月提出给予她重新进入人群的机会，经考察及测试后，她获准在伊比利亚周边参加外勤。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[],"forms":[{"id":"char_4066_highmo","name":"海沫"}],"source":"https://prts.wiki/w/%E6%B5%B7%E6%B2%AB"},{"id":"char_4079_haini","name":"海霓","en":"Lucilla","kind":"operator","region":"aegir","origin":"阿戈尔","faction":"阿戈尔","profession":"辅助","aliases":[],"title":"海霓的穹顶管理与文化交流","summary":"海霓本名卢契拉，隶属阿戈尔技术院设施管理所，担任穹顶管理员和洋流测绘员。海陆建立联系后，她以个人身份与罗德岛合作，不定期参加文化交流。舰上谈话记录显示，她常询问他人故乡的城市风貌与生活记忆，也介绍自己在穹顶投映和洋流喷泉方面的工作。","focus":"仅用已记载的交流内容说明其活动，不由个别谈话推断私人感情。","memories":[{"title":"怀有希望之人","intro":"卢契拉发现，失望和希望往往都来自感性认知。"}],"forms":[{"id":"char_4079_haini","name":"海霓"}],"source":"https://prts.wiki/w/%E6%B5%B7%E9%9C%93"},{"id":"char_1021_kroos2","name":"寒芒克洛丝","en":"Kroos the Keen Glint","kind":"operator","region":"rhodes","origin":"雷姆必拓","faction":"罗德岛","profession":"狙击","aliases":[],"title":"寒芒克洛丝的晋升与外勤工作","summary":"经过长期训练和任务磨炼，克洛丝晋升为正式干员，主要承担外勤，在射击与隐匿行动方面形成自己的经验。档案记述她身高、发式与着装均有变化，爱玩、爱笑等习惯仍保留。她看似困倦时也未必放松警戒，判断这一阶段表现，需要区分日常姿态与实际的工作状态。","focus":"本条采用正式干员阶段的履历记录，与预备组时期分别叙述。","memories":[{"title":"蒙眬","intro":"“贪念我当然是有的。只不过我的贪念，并不是金钱能够满足的罢了。”"}],"forms":[{"id":"char_124_kroos","name":"克洛丝"},{"id":"char_1021_kroos2","name":"寒芒克洛丝"}],"source":"https://prts.wiki/w/%E5%AF%92%E8%8A%92%E5%85%8B%E6%B4%9B%E4%B8%9D"},{"id":"char_341_sntlla","name":"寒檀","en":"Santalla","kind":"operator","region":"sami","origin":"萨米","faction":"萨米","profession":"术师","aliases":[],"title":"寒檀的萨米向导与患者护送","summary":"寒檀原为萨米部族萨满，因故自我流放，在病情延缓后加入罗德岛。她主要在萨米执行任务，为初来者担任向导，护送当地患者求医，并熟练操控风雪。驻舰时，她参加课程、学习外部知识，对使用其他语言保持谨慎，日常仍更习惯木石与自然环境。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"吹起未来的雪花","intro":"在萨米眼中，她从未被罢黜。"}],"forms":[{"id":"char_341_sntlla","name":"寒檀"}],"source":"https://prts.wiki/w/%E5%AF%92%E6%AA%80"},{"id":"char_4039_horn","name":"号角","en":"Horn","kind":"operator","region":"victoria","origin":"维多利亚","faction":"维多利亚","profession":"重装","aliases":[],"title":"号角的军官职务与伦蒂尼姆合作","summary":"号角毕业于维多利亚皇家近卫学校，现任风暴突击队第二分队指挥官。她在伦蒂尼姆事件中与罗德岛协同作战，经Misery介绍签订战略合作条款。她使用带击发机构的特殊盾牌，兼具防护与射击用途；罗德岛工程人员曾为她及部队整修装备，并研究其复杂机械结构。","focus":"按这份合作阶段的资料记录职务，不把武器性能当作完整战斗评价。","memories":[{"title":"独奏曲","intro":"就算战场上只剩下她一个人，就算这场战斗看不到尽头，就算她能做的只是拼尽全力地站着而已。"}],"forms":[{"id":"char_4039_horn","name":"号角"}],"source":"https://prts.wiki/w/%E5%8F%B7%E8%A7%92"},{"id":"char_297_hamoni","name":"和弦","en":"Harmonie","kind":"operator","region":"victoria","origin":"维多利亚","faction":"塔拉","profession":"术师","aliases":[],"title":"和弦的情报履历与外交驻留","summary":"和弦曾为维多利亚军方情报人员，现为深池高级军官，以威灵顿公爵外交使臣身份驻留罗德岛，协助部分当地事务。出于安全考虑，其法杖经过检查，未发现额外摄像或发信功能。测试确认她擅长类似水浪的法术，并能使目标产生呼吸不畅的感受。","focus":"任职与驻留以本阶段为准，合作身份不表示双方政治立场完全一致。","memories":[{"title":"孤独的舞者","intro":"是从哪一天开始的呢？她习惯了观看他人钻营、密谋、忙忙碌碌。"}],"forms":[{"id":"char_297_hamoni","name":"和弦"}],"source":"https://prts.wiki/w/%E5%92%8C%E5%BC%A6"},{"id":"char_4041_chnut","name":"褐果","en":"Chestnut","kind":"operator","region":"rhodes","origin":"未公开","faction":"罗德岛","profession":"医疗","aliases":[],"title":"褐果从地质勘探转向医疗","summary":"褐果在地下聚居地从事地质勘探，自幼学习矿物知识，曾参与城市扩建前的环境调查。到地面后，他选择成为医生，使用矿物进行疗愈。档案记述其老师与朋友虽然不完全理解这一转向，仍支持他的决定；他保存着初次采矿后亲手制成的小灯。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"黑色石头","intro":"只有经受住考验，才能成为真正的“宝石”吗？"}],"forms":[{"id":"char_4041_chnut","name":"褐果"}],"source":"https://prts.wiki/w/%E8%A4%90%E6%9E%9C"},{"id":"char_4088_hodrer","name":"赫德雷","en":"Hoederer","kind":"operator","region":"kazdel","origin":"卡兹戴尔","faction":"巴别塔","profession":"近卫","aliases":[],"title":"赫德雷的佣兵履历与重新合作","summary":"赫德雷曾率萨卡兹佣兵，参加巴别塔转移，之后离开并以整合运动雇佣兵身份出现在切尔诺伯格。后来他进入伦蒂尼姆军事委员会，取得重要情报后离开，与罗德岛重新联系。经阿米娅沟通，他再次签订合作条款。其早期经历仍不完整，不能据几次身份转换确定全部立场。","focus":"依可确认的履历顺序叙述，对各阶段尚未公开的动机保留空白。","memories":[],"forms":[{"id":"char_4088_hodrer","name":"赫德雷"}],"source":"https://prts.wiki/w/%E8%B5%AB%E5%BE%B7%E9%9B%B7"},{"id":"char_188_helage","name":"赫拉格","en":"Hellagur","kind":"operator","region":"ursus","origin":"乌萨斯","faction":"乌萨斯","profession":"近卫","aliases":[],"title":"赫拉格的军旅履历与诊所职责","summary":"赫拉格曾在乌萨斯帝国近卫军服役，后来管理切尔诺伯格感染者地下诊所阿撒兹勒。依合作协议，他长期驻留罗德岛，提供战术指挥支援，军事实务与战斗经验较为成熟。同僚常称他为将军，感染者社群也有相关传闻；他本人更强调使诊所持续运作，而非发展医疗技术。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[{"title":"命途","intro":"骑士与将军，战争与傲慢，国家与感染者。"}],"forms":[{"id":"char_188_helage","name":"赫拉格"}],"source":"https://prts.wiki/w/%E8%B5%AB%E6%8B%89%E6%A0%BC"},{"id":"char_108_silent","name":"赫默","en":"Silence","kind":"operator","region":"columbia","origin":"哥伦比亚","faction":"莱茵生命","profession":"医疗","aliases":[],"title":"赫默的研究履历与医疗工作","summary":"赫默曾任莱茵生命源石项目研究员，主持应用研究和临床试验，后在罗德岛提供战场医疗。她在实验工作中严谨、执行力强，团队节奏也较紧凑。日常大型社交场合中，她通常沉默，但面对科研交流能够耐心倾听、讨论问题，并向研究人员提供建议。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"职场新人","intro":"前路艰辛曲折，但作为一个新人，她已经做得够好了。"}],"forms":[{"id":"char_108_silent","name":"赫默"},{"id":"char_1031_slent2","name":"淬羽赫默"}],"source":"https://prts.wiki/w/%E8%B5%AB%E9%BB%98"},{"id":"char_340_shwaz","name":"黑","en":"Schwarz","kind":"operator","region":"siesta","origin":"雷姆必拓","faction":"汐斯塔","profession":"狙击","aliases":[],"title":"黑的汐斯塔经历与护卫工作","summary":"黑曾任汐斯塔市长护卫及城市治安局局长，后来随锡兰加入罗德岛。她擅长隐秘行动、侦察与反侦察、野外求生和使用弩，现承担博士护卫及部分基层训练。日常观察记载，她话少，常在锡兰附近活动，也偶尔与佣兵、赏金猎人出身的干员共同前往酒吧。","focus":"本篇采用基础任职记录，不以寡言态度推定其全部人际关系。","memories":[{"title":"离乡之日","intro":"为何而生活，这是一个问题。"},{"title":"普通的一天","intro":"对黑来说，她现在要关心的事情，比以前多了一点。"}],"forms":[{"id":"char_340_shwaz","name":"黑"}],"source":"https://prts.wiki/w/%E9%BB%91"},{"id":"char_4046_ebnhlz","name":"黑键","en":"Ebenholz","kind":"operator","region":"leithanien","origin":"莱塔尼亚","faction":"莱塔尼亚","profession":"术师","aliases":[],"title":"黑键的就医与外勤录用","summary":"黑键在维谢海姆事件中感染矿石病，经芙蓉介绍到罗德岛治疗，凭源石技艺表现通过考核，成为外勤干员。日常交流时，他会礼貌回答必要问题，却较少继续闲谈。博士和少数同僚能够与他进行更深入的交流，此时他也会表达不常向他人公开的意见。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[{"title":"孤灯","intro":"夜色深沉，冷雨寂静无声。那盏孤灯竭力闪烁，希望隐没的太阳不要在夜里冻僵。"}],"forms":[{"id":"char_4046_ebnhlz","name":"黑键"}],"source":"https://prts.wiki/w/%E9%BB%91%E9%94%AE"},{"id":"char_500_noirc","name":"黑角","en":"Noir Corne","kind":"operator","region":"rhodes","origin":"东国","faction":"行动组A4","profession":"重装","aliases":[],"title":"黑角的前线保护与后勤职责","summary":"黑角是罗德岛老牌基础干员，前线承担保护队友的任务，返舰后从事后勤工作。他戴面具，初见时容易给人难以交流的印象。档案记录，实际交往中他不以年龄或资历要求特殊对待，能够与年轻干员正常说笑，并持续承担各类日常事务。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"甲板另一侧","intro":"下班之后，才是生活。"}],"forms":[{"id":"char_500_noirc","name":"黑角"},{"id":"char_1030_noirc2","name":"火龙S黑角"}],"source":"https://prts.wiki/w/%E9%BB%91%E8%A7%92"},{"id":"char_4140_lasher","name":"衡沙","en":"Sand Reckoner","kind":"operator","region":"sargon","origin":"萨尔贡","faction":"萨尔贡","profession":"辅助","aliases":[],"title":"衡沙的宝石监管与地区支援","summary":"衡沙曾是米纳特哈玛仪宝石交易所监管人。交易所不面向公众零售，主要负责珍稀宝石估价、商铺准入和大宗交易中转，具有当地行业规则维护职能。经莎草介绍，他与罗德岛建立合作，以资金和人脉支持萨尔贡东部活动。档案未详细列出每项合作的具体内容。","focus":"将制度背景与个人已知任职分开，不把历代监管人的事迹全部归于他。","memories":[{"title":"遗失之物","intro":"作为监管人，他尽力保证每次都能完美收场……但难免会遇到一些意外。"}],"forms":[{"id":"char_4140_lasher","name":"衡沙"}],"source":"https://prts.wiki/w/%E8%A1%A1%E6%B2%99"},{"id":"char_226_hmau","name":"吽","en":"Hung","kind":"operator","region":"lungmen","origin":"龙门","faction":"鲤氏侦探事务所","profession":"重装","aliases":[],"title":"吽的事务所经历与重装任职","summary":"吽由龙门鲤氏侦探事务所所长老鲤推荐来到罗德岛，现以重装干员身份为前线队友提供保护。他身材高大，体能较强。档案对其日常表现的记录则集中在敦厚、和蔼与愿意为他人考虑，同僚普遍认为他容易相处。现有输入主要涵盖任职和性格，未展开完整的早年经历。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[{"title":"南墙","intro":"良心哭的声音太小，吵不过金银落在饭碗里的那一阵叮当作响。"},{"title":"阴谋","intro":"吽不是不知道这世上有那么多无可挽回的事，但他依旧相信，只要人和人能够好好沟通、相互理解，那就总会有办法，总会有结果。"}],"forms":[{"id":"char_226_hmau","name":"吽"}],"source":"https://prts.wiki/w/%E5%90%BD"},{"id":"char_144_red","name":"红","en":"Projekt Red","kind":"operator","region":"rhodes","origin":"未公开","faction":"S.W.E.E.P.","profession":"特种","aliases":[],"title":"红的特别作战与日常接触记录","summary":"红的身份和履历尚不完整，由凯尔希接收、监护并担保，擅长机动、特种与隐秘作战。部分同伴对其精准而非常规的战斗方式感到畏惧，她平时也较少露面。随着接触增加，记录中出现了较天真幼稚的日常表现，与少数干员的联系也在逐渐增多。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[],"forms":[{"id":"char_144_red","name":"红"}],"source":"https://prts.wiki/w/%E7%BA%A2"},{"id":"char_290_vigna","name":"红豆","en":"Vigna","kind":"operator","region":"columbia","origin":"卡兹戴尔","faction":"哥伦比亚","profession":"先锋","aliases":[],"title":"红豆的迁居经历与先锋任职","summary":"红豆出生于卡兹戴尔，幼年随父母在哥伦比亚城市生活，住处多次迁移。她见过同族遭受歧视，也曾为保护他们与人冲突，同时受到部分友善人士支持。经测试加入罗德岛后，她担任先锋干员，在遭遇、突击及战术协同中显示潜力，并参与战场开辟等工作。","focus":"将已记载的成长环境与当前岗位并列，不以同族经历概括所有萨卡兹。","memories":[{"title":"该做的事","intro":"摇滚可以是爱好的一切，但未必是生活的一切。"}],"forms":[{"id":"char_290_vigna","name":"红豆"}],"source":"https://prts.wiki/w/%E7%BA%A2%E8%B1%86"},{"id":"char_4023_rfalcn","name":"红隼","en":"Kestrel","kind":"operator","region":"sargon","origin":"萨尔贡","faction":"萨尔贡","profession":"先锋","aliases":[],"title":"红隼的逃离救援与办事处任职","summary":"红隼曾是萨尔贡舒巴特—阿尔萨兰地区部落战士，与兄弟姐妹一同遭王酋军奴役。逃离并遇到罗德岛后，她重返矿场救出工友，主动申请加入。她现于萨尔贡办事处治疗并参与外勤，常在训练室与其他战斗人员切磋，借此逐渐结识本舰同僚。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[{"title":"未来的痕迹","intro":"她对过往的思念，和她想象中的未来，透过“齿痕”紧紧连接在一起。"},{"title":"第一道伤疤","intro":"一场大火过后，她终于有了可以作为纪念的伤疤。"}],"forms":[{"id":"char_4023_rfalcn","name":"红隼"}],"source":"https://prts.wiki/w/%E7%BA%A2%E9%9A%BC"},{"id":"char_190_clour","name":"红云","en":"Vermeil","kind":"operator","region":"siracusa","origin":"不明","faction":"叙拉古","profession":"狙击","aliases":[],"title":"红云的荒野狩猎与狙击任职","summary":"红云具体出生地不明，长期在叙拉古荒野活动，以狩猎、收集废弃资源和聚落交易维持生活，也接受不违反当地规则的有偿工作。她加入罗德岛狙击小组后承担射击援护。随身披风来自Vermeil聚落的手工制作，可遮挡风沙，也是当地交易和赠送的物品。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"安身之处","intro":"离开荒野的野孩子，该在何处安身？"}],"forms":[{"id":"char_190_clour","name":"红云"}],"source":"https://prts.wiki/w/%E7%BA%A2%E4%BA%91"},{"id":"char_4055_bgsnow","name":"鸿雪","en":"Позёмка","kind":"operator","region":"rhodes","origin":"乌萨斯","faction":"罗德岛","profession":"狙击","aliases":[],"title":"鸿雪的迁居与际崖城代表经历","summary":"鸿雪本名阿芙朵嘉，曾出身乌萨斯贵族家庭，家人在政治事件中死亡后逃入际崖城。她在当地居住多年，成为文学代表，并参与劝说居民前往阿卡胡拉避难。后经商业代表介绍来到罗德岛考察，以狙击干员身份参加外勤。她未公开真实姓氏，对部分早期经历也未补充细节。","focus":"尊重本人未公开的姓名和事件细节，不将档案空白转写成确定情节。","memories":[{"title":"墨迹已落","intro":"她想逃离自己黑色的过去，但那也是她开口所能诉说的一切。"}],"forms":[{"id":"char_4055_bgsnow","name":"鸿雪"}],"source":"https://prts.wiki/w/%E9%B8%BF%E9%9B%AA"},{"id":"char_4220_kormr","name":"虎狼丸","en":"Koromaru","kind":"operator","region":"other","origin":"未录入","faction":"S.E.E.S.","profession":"近卫","aliases":[],"title":"虎狼丸在拉特兰校园的记录","summary":"虎狼丸的出身与客观履历在输入中尚未完整录入，已有材料主要记述它在校园中的活动。不同班级曾争取它更多的在校时间，天田乾所在小学部以最初入学关系提出主张，即使它并未完成正式登记。有关争论被写入班级记录，可据此确认其与学生群体的相处，其他来历仍未说明。","focus":"输入缺少客观履历，本条仅采用现有校园记录，不补写原世界经历。","memories":[],"forms":[{"id":"char_4220_kormr","name":"虎狼丸"}],"source":"https://prts.wiki/w/%E8%99%8E%E7%8B%BC%E4%B8%B8"},{"id":"char_171_bldsk","name":"华法琳","en":"Warfarin","kind":"operator","region":"rhodes","origin":"卡兹戴尔","faction":"罗德岛","profession":"医疗","aliases":[],"title":"华法琳的血库管理与医疗资历","summary":"华法琳是罗德岛元老，曾与凯尔希共同建立医疗体系，负责血库建设和管理，在医学与治疗技艺方面经验深厚。她此前的经历尚不明确，外貌与实际资历也不相称。日常中，她并不要求同伴按前辈方式对待自己，但治疗时要求患者服从医嘱。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"怪物","intro":"“怪物”也有处世之道。"},{"title":"难得认真","intro":"她毕竟活了几百年。"}],"forms":[{"id":"char_171_bldsk","name":"华法琳"}],"source":"https://prts.wiki/w/%E5%8D%8E%E6%B3%95%E7%90%B3"},{"id":"char_243_waaifu","name":"槐琥","en":"Waai Fu","kind":"operator","region":"lungmen","origin":"炎","faction":"鲤氏侦探事务所","profession":"特种","aliases":[],"title":"槐琥的在校身份与录用测试","summary":"槐琥是龙门在校大学生，经当地事务所推荐，参加龙门与罗德岛商业交流协议下的人员录用。她平稳通过心理测试，在实战测试中也迅速击倒负责考核的干员，显示出与学生身份之外相关的作战经验。罗德岛因此继续关注其潜力，背景调查在这份档案的时点仍未结束。","focus":"测试结果能确认部分能力，不能据此补全尚在调查的个人背景。","memories":[{"title":"武为何物","intro":"行侠仗义离不开一身武功，但不是所有问题都能靠拳头解决。"}],"forms":[{"id":"char_243_waaifu","name":"槐琥"}],"source":"https://prts.wiki/w/%E6%A7%90%E7%90%A5"},{"id":"char_1038_whitw2","name":"荒芜拉普兰德","en":"Lappland the Decadenza","kind":"operator","region":"siracusa","origin":"叙拉古","faction":"叙拉古","profession":"术师","aliases":[],"title":"荒芜拉普兰德的脱离与合作","summary":"拉普兰德在这一阶段已脱离萨卢佐家族，公开履历记为无业，擅长单兵行动，经常协助罗德岛完成攻坚与肃清。她返舰前未通知人事部，抵达时携带武器，并穿着叙拉古礼服。相关记录确认其身份及行动阶段发生变化，但没有因此断言她与旧有关系的所有问题已经结束。","focus":"本条采用荒芜形态档案，与早期近卫阶段的任职记录分开。","memories":[{"title":"气味游戏","intro":"拉普兰德羞辱了她的狼群，但这并非她的乐趣。"}],"forms":[{"id":"char_140_whitew","name":"拉普兰德"},{"id":"char_1038_whitw2","name":"荒芜拉普兰德"}],"source":"https://prts.wiki/w/%E8%8D%92%E8%8A%9C%E6%8B%89%E6%99%AE%E5%85%B0%E5%BE%B7"},{"id":"char_017_huang","name":"煌","en":"Blaze","kind":"operator","region":"rhodes","origin":"维多利亚","faction":"罗德岛-精英干员","profession":"近卫","aliases":[],"title":"煌的精英作战与热气流运用","summary":"煌作为罗德岛精英干员承担攻坚任务，擅长机动、突袭与歼灭作战。她的技艺主要加热一定范围内的气体，存在温度、距离和目标限制。经过反复测试训练，她能够利用热流缓冲、膨胀推力及局部爆破配合作战，也能以血液增强效果。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"你愿意吗","intro":"曾有多少人亦走过、或将要走上这条路。"}],"forms":[{"id":"char_017_huang","name":"煌"},{"id":"char_1040_blaze2","name":"烛煌"}],"source":"https://prts.wiki/w/%E7%85%8C"},{"id":"char_431_ashlok","name":"灰毫","en":"Ashlock","kind":"operator","region":"kazimierz","origin":"卡西米尔","faction":"红松骑士团","profession":"重装","aliases":[],"title":"灰毫离开竞技场后的任职调整","summary":"灰毫本名格蕾纳蒂，是红松骑士团成员，特锦赛结束后随同伴加入罗德岛。她使用火炮与盾牌承担远程杀伤及阵线防守。档案记载，她此前先以家族、后以竞赛冠军为目标，来到罗德岛后需要适应与旧骑士规则不同的工作。她仍会在任务需要时参加保护同伴的行动。","focus":"按入职后的调整阶段叙述，不将目标变化解释为已完成的身份转型。","memories":[{"title":"决斗","intro":"今天，卡西米尔竞技场将上演“骑士之死”。"}],"forms":[{"id":"char_431_ashlok","name":"灰毫"}],"source":"https://prts.wiki/w/%E7%81%B0%E6%AF%AB"},{"id":"char_367_swllow","name":"灰喉","en":"GreyThroat","kind":"operator","region":"rhodes","origin":"未公开","faction":"罗德岛","profession":"狙击","aliases":[],"title":"灰喉的寄居经历与行动队考核","summary":"灰喉的父母曾研究矿石病，与部分罗德岛医疗人员有学术联系。父亲失去消息后，母亲将她留在本舰，随后亦下落不明。她在罗德岛生活多年，取得灰喉代号的时间远晚于到舰时间。后来她通过考核加入行动队；档案没有充分确认双亲此后的经历或结局。","focus":"双亲失踪仅按资料记录处理，不将未获消息等同已确认死亡。","memories":[{"title":"殊途","intro":"她在害怕，她的手微微颤抖，但她知道，生命本无差等。"}],"forms":[{"id":"char_367_swllow","name":"灰喉"}],"source":"https://prts.wiki/w/%E7%81%B0%E5%96%89"},{"id":"char_456_ash","name":"灰烬","en":"Ash","kind":"operator","region":"other","origin":"未知","faction":"彩虹小队","profession":"狙击","aliases":[],"title":"灰烬的战术指挥与临时合作","summary":"灰烬暂任彩虹小队队长，负责行动方针，擅长快速突入和精确爆破，可利用发射器破障或攻击重装目标。她经历瞭望塔事件后登记为罗德岛合作人员。档案认为其战斗和指挥技术值得交流，同时明确双方没有正式长期雇佣关系，小队仍有独立事务。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"旅伴","intro":"梦想与谎言，一枚硬币的两面。"}],"forms":[{"id":"char_456_ash","name":"灰烬"}],"source":"https://prts.wiki/w/%E7%81%B0%E7%83%AC"},{"id":"char_1030_noirc2","name":"火龙S黑角","en":"Rathalos S Noir Corne","kind":"operator","region":"rhodes","origin":"东国","faction":"行动组A4","profession":"近卫","aliases":[],"title":"黑角返航后的装备与战斗训练","summary":"黑角完成东国任务后，换用艾露猫制造的盔甲和太刀，不再持原有盾牌。他反复保养和练习新装备，相关日常引起同事注意。任务记录则显示，他仍保持在前线承受攻击、保护队友的习惯，且较快提高武器控制水平。他说明持续携带装备是为加速学习新的用法。","focus":"采用火龙S形态的返航后档案，与基础黑角阶段分别记录。","memories":[],"forms":[{"id":"char_500_noirc","name":"黑角"},{"id":"char_1030_noirc2","name":"火龙S黑角"}],"source":"https://prts.wiki/w/%E7%81%AB%E9%BE%99S%E9%BB%91%E8%A7%92"},{"id":"char_493_firwhl","name":"火哨","en":"Firewhistle","kind":"operator","region":"rim","origin":"雷姆必拓","faction":"雷姆必拓","profession":"重装","aliases":[],"title":"火哨的安保经营与合作任职","summary":"火哨在雷姆必拓经营小型私人安保公司，代表公司与罗德岛签订协议，也以干员身份提供服务。她性格开朗，常到本舰为公司介绍业务，因此有时被误认为联络员或仅名义上的负责人。她通常不介意这些称呼，现有材料确认其同时承担企业负责人及合作干员两种身份。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[{"title":"独行之人","intro":"她离开那条光明的坦途，试图与荆棘中的人同路，荆棘中的人却说，她和他们不是一路人。"}],"forms":[{"id":"char_493_firwhl","name":"火哨"}],"source":"https://prts.wiki/w/%E7%81%AB%E5%93%A8"},{"id":"char_163_hpsts","name":"火神","en":"Vulcan","kind":"operator","region":"minos","origin":"米诺斯","faction":"米诺斯","profession":"重装","aliases":[],"title":"火神的铁匠工作与武器维护","summary":"火神来自米诺斯，感染矿石病后到罗德岛求医，并通过协议成为成员。她日常主要负责武器打造与维护，必要时亲自执行任务。专属铁匠铺同时是她的居所，除外勤外很少主动离开。她通常不热衷谈话，涉及武器时会更愿意回应，但仍保持寡言。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"锻造","intro":"修补的不仅仅是武器，还有武器对于使用者的意义。"}],"forms":[{"id":"char_163_hpsts","name":"火神"}],"source":"https://prts.wiki/w/%E7%81%AB%E7%A5%9E"},{"id":"char_4027_heyak","name":"霍尔海雅","en":"Ho'olheyak","kind":"operator","region":"columbia","origin":"哥伦比亚","faction":"哥伦比亚","profession":"术师","aliases":[],"title":"霍尔海雅的特工背景与合作","summary":"霍尔海雅曾为梅兰德基金会特工，经凯尔希与博士引荐加入罗德岛，提供隐秘行动及极端环境任务支持。她程序上已离开旧组织，但常申请独立行动，其背景与接触情报的能力仍使部分人员担忧。她也分享过旧组织的工作方式；档案对其完整立场没有给出统一结论。","focus":"明确专业能力与信任评价的区别，不用工作成果替代尚未公开的政治立场。","memories":[],"forms":[{"id":"char_4027_heyak","name":"霍尔海雅"}],"source":"https://prts.wiki/w/%E9%9C%8D%E5%B0%94%E6%B5%B7%E9%9B%85"},{"id":"char_4230_mcnist","name":"机械师","en":"Mechanist","kind":"operator","region":"rhodes","origin":"哥伦比亚","faction":"罗德岛-精英干员","profession":"重装","aliases":[],"title":"机械师的工程研发与维护职责","summary":"机械师出身哥伦比亚，是罗德岛精英干员，主持武器装备、工程设施和实验器材的研发、制造及维护，为各部门提供硬件支持。档案记述他几乎总穿工作服，连用餐时也少有例外，同僚曾推测这与随时进入工作状态有关。相关行为的原因仍应与他实际承担的职责分别理解。","focus":"日常着装的原因包含同僚推测，本条不将推测提升为本人确认。","memories":[],"forms":[{"id":"char_4230_mcnist","name":"机械师"}],"source":"https://prts.wiki/w/%E6%9C%BA%E6%A2%B0%E5%B8%88"},{"id":"char_4203_kichi","name":"吉星","en":"Kichisei","kind":"operator","region":"higashi","origin":"东国","faction":"东","profession":"狙击","aliases":[],"title":"吉星的店铺经历与求医入职","summary":"吉星曾在东国锻冶町担任珠宝鉴定师，并经营同名杂货铺。金石会事件后，她失去店铺与住处，经介绍来到罗德岛治疗矿石病，随后以狙击干员身份任职。第一份档案另记录她在牌桌旁与熟人谈话的片段，但没有进一步交代此前事件的完整经过。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"好运相伴","intro":"人人都喜欢无忧无虑的你。"}],"forms":[{"id":"char_4203_kichi","name":"吉星"}],"source":"https://prts.wiki/w/%E5%90%89%E6%98%9F"},{"id":"char_422_aurora","name":"极光","en":"Aurora","kind":"operator","region":"kjerag","origin":"谢拉格","faction":"谢拉格","profession":"重装","aliases":[],"title":"极光的防御工程学习与任职","summary":"极光来自谢拉格，中学毕业后接受希瓦艾什家资助，到哥伦比亚学习雪地极端环境防御工程。感染矿石病使学业中断，她转赴罗德岛治疗，通过考核后兼任工程与行动人员。她使用自己设计制造的特殊武器，在舰内外任务中提供服务。现有材料未公布其全部求学及患病经过。","focus":"以明确的学习领域与当前岗位为范围，不扩写学业中断的具体细节。","memories":[{"title":"她所见","intro":"极光抬头望向天空，天空并没有出现五彩极光。极光低头看向脚下，她正站在原地保护着她和她身后的伙伴。"}],"forms":[{"id":"char_422_aurora","name":"极光"}],"source":"https://prts.wiki/w/%E6%9E%81%E5%85%89"},{"id":"char_401_elysm","name":"极境","en":"Elysium","kind":"operator","region":"rhodes","origin":"伊比利亚","faction":"罗德岛","profession":"先锋","aliases":[],"title":"极境的游历与战场通讯工作","summary":"极境出身伊比利亚，曾独自游历多个地区，后来在罗德岛特殊行动小队三队任队长副手，负责通讯与秘密行动支援。他掌握声讯相关源石技艺，日常态度活跃。人事记录还记下他试图在履历中加入外貌自夸但被阻止一事；正式职能仍以小队支援和通讯保障为主。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[{"title":"漫长旅途","intro":"在离开家乡后，你是否已经如愿看过那些不一样的风景？"}],"forms":[{"id":"char_401_elysm","name":"极境"}],"source":"https://prts.wiki/w/%E6%9E%81%E5%A2%83"},{"id":"char_293_thorns","name":"棘刺","en":"Thorns","kind":"operator","region":"iberia","origin":"伊比利亚","faction":"伊比利亚","profession":"近卫","aliases":[],"title":"棘刺的离乡履历与药剂研究","summary":"棘刺精通剑术和药剂制作，自述因伊比利亚宗教局势动荡离乡，受邀加入罗德岛；这部分来路尚未完全核实。驻舰期间，他持续研究配方和萃取技术，常因专注而忽略衣着。长期接触的同伴认为，他言行直接、不重外界评价，与初见时的冷酷印象有所不同。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"纪念日","intro":"遵循自己的心意做事，不问出身。"}],"forms":[{"id":"char_293_thorns","name":"棘刺"},{"id":"char_1039_thorn2","name":"引星棘刺"}],"source":"https://prts.wiki/w/%E6%A3%98%E5%88%BA"},{"id":"char_187_ccheal","name":"嘉维尔","en":"Gavial","kind":"operator","region":"rhodes","origin":"未公开","faction":"罗德岛","profession":"医疗","aliases":[],"title":"嘉维尔的治疗与医疗岗位选择","summary":"嘉维尔原为自由佣兵，感染矿石病后离开故乡，经过辗转加入罗德岛。她具有较强体能、破坏力与战斗技巧，但按照本人意愿担任医疗干员。日常观察描述其性格直爽，初见时容易让患者担心，进一步接触则可见其工作认真。密录入口还记录了她离乡后的学医主题。","focus":"本篇限于基础医疗形态，不把后来的百炼阶段提前写入当前岗位。","memories":[{"title":"学医之路","intro":"离开雨林之后，嘉维尔才知道，在雨林中理所当然的事情，在外面却并非如此。"}],"forms":[{"id":"char_187_ccheal","name":"嘉维尔"},{"id":"char_1026_gvial2","name":"百炼嘉维尔"}],"source":"https://prts.wiki/w/%E5%98%89%E7%BB%B4%E5%B0%94"},{"id":"char_4237_jcinta","name":"嘉辛塔","en":"Jacinta","kind":"operator","region":"rim","origin":"雷姆必拓","faction":"雷姆必拓","profession":"先锋","aliases":[],"title":"嘉辛塔的治疗与先锋录用","summary":"嘉辛塔是雷姆必拓矿业大亨坎贝尔夫妇的女儿，因矿石病到罗德岛接受治疗，根据本人意愿成为先锋干员。初期同僚多以文静、温和与衣着整洁描述她，相处也较为礼貌谨慎。现有输入重点涵盖家世、接诊与录用经过，并未完整展开她在此前事件中的所有行动。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[{"title":"破土而出","intro":"与其在懵懂中腐烂，不如随风飞舞吧。"}],"forms":[{"id":"char_4237_jcinta","name":"嘉辛塔"}],"source":"https://prts.wiki/w/%E5%98%89%E8%BE%9B%E5%A1%94"},{"id":"char_349_chiave","name":"贾维","en":"Chiave","kind":"operator","region":"siracusa","origin":"叙拉古","faction":"贾维团伙","profession":"先锋","aliases":[],"title":"贾维的团伙经历与前线任职","summary":"贾维曾在叙拉古小城修车厂工作，后来成为小团伙首领，并在一次事件后带两名成员加入罗德岛，现任前线突击手。档案记录，他通常态度爽朗，想到事情便立即行动，也因不顾礼节的言行惹过麻烦。其个人吸引力使伙伴常愿意参加这些临时行动。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"代表作","intro":"贾维一口咬定自己的代表作永远是下一作，不过他的两个朋友还是认为“她”标志着他修车生涯的巅峰。"}],"forms":[{"id":"char_349_chiave","name":"贾维"}],"source":"https://prts.wiki/w/%E8%B4%BE%E7%BB%B4"},{"id":"char_1013_chen2","name":"假日威龙陈","en":"Ch'en the Holungday","kind":"operator","region":"rhodes","origin":"龙门","faction":"罗德岛","profession":"狙击","aliases":[],"title":"陈离职后的外派与射击训练","summary":"陈辞去龙门近卫局职务后，正式成为罗德岛成员，主要接受外派支援和现场指导任务。多索雷斯度假归来后，她使用特制铳参加狙击训练，并经一周左右的调试确定近距离霰弹与中远距离轰炸方案。她原有剑术仍在，新的武器训练属于探索其他作战方式的尝试。","focus":"明确该形态发生在离职与度假之后，不以新武器取代原有经历。","memories":[{"title":"归属","intro":"在真正了解某件事之前，不要轻率地评价它。"},{"title":"道路","intro":"不要麻痹，放弃惯性，忍受不安，保持痛苦。"}],"forms":[{"id":"char_010_chen","name":"陈"},{"id":"char_1013_chen2","name":"假日威龙陈"},{"id":"char_1050_chen3","name":"赤刃明霄陈"}],"source":"https://prts.wiki/w/%E5%81%87%E6%97%A5%E5%A8%81%E9%BE%99%E9%99%88"},{"id":"char_260_durnar","name":"坚雷","en":"Dur-nar","kind":"operator","region":"rhodes","origin":"哥伦比亚","faction":"罗德岛","profession":"重装","aliases":[],"title":"坚雷的退伍与教官任职","summary":"坚雷曾任哥伦比亚正规军中士，退伍原因未公开，后来经常规录用加入罗德岛，兼任教官与重装干员。她负责中级标准课程及重装入门课程，具有丰富战场经验，使用特制盾牌防护并以电刃攻击。档案记述她待人正直率真，任务之外喜欢尝试不同食品。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[{"title":"额外训练","intro":"训练就是要怕什么来什么。"},{"title":"杯中旧事","intro":"九点之后喝杯酒，消愁愁更愁。"}],"forms":[{"id":"char_260_durnar","name":"坚雷"}],"source":"https://prts.wiki/w/%E5%9D%9A%E9%9B%B7"},{"id":"char_1028_texas2","name":"缄默德克萨斯","en":"Texas the Omertosa","kind":"operator","region":"lungmen","origin":"哥伦比亚","faction":"企鹅物流","profession":"特种","aliases":[],"title":"德克萨斯重返叙拉古后的来访","summary":"这一阶段的德克萨斯仍是企鹅物流员工，也是最后的德克萨斯家族成员，具有出色的单兵能力。她带伺夜与斥罪来到罗德岛时，衣着明显带有叙拉古特征，令熟人意识到她已重返故地。企鹅物流其他成员随后同行到访，档案以此记录她旧身份与当前伙伴关系的并存。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[],"forms":[{"id":"char_102_texas","name":"德克萨斯"},{"id":"char_1028_texas2","name":"缄默德克萨斯"}],"source":"https://prts.wiki/w/%E7%BC%84%E9%BB%98%E5%BE%B7%E5%85%8B%E8%90%A8%E6%96%AF"},{"id":"char_4116_blkkgt","name":"锏","en":"Degenbrecher","kind":"operator","region":"kjerag","origin":"莱塔尼亚","faction":"喀兰贸易","profession":"近卫","aliases":[],"title":"锏的竞技经历与喀兰护卫工作","summary":"锏曾三次获得卡西米尔骑士竞赛冠军，第三次获胜违背商业联合会的安排，离领奖台后遭遇刺杀。她离开城市时未能带走奖杯，后来成为喀兰贸易总裁恩希欧迪斯的贴身保镖。依据博士与总裁签订的合同，她长期以近卫干员身份加入罗德岛，在多类任务中承担前线作战。","focus":"竞技与离城过程采用档案转述，不进一步推定所有刺杀行动的实施细节。","memories":[{"title":"骑士的旅程","intro":"为打败过去的阴影，骑士踏入了雪山。"}],"forms":[{"id":"char_4116_blkkgt","name":"锏"}],"source":"https://prts.wiki/w/%E9%94%8F"},{"id":"char_4036_forcer","name":"见行者","en":"Enforcer","kind":"operator","region":"laterano","origin":"拉特兰","faction":"拉特兰","profession":"特种","aliases":["艾泽尔"],"title":"见行者的公证所与合作任职","summary":"见行者本名艾泽尔·帕斯托莱，是拉特兰公民，刚通过公证所实训。万国峰会期间，他被卷入异端团体引发的骚乱；事后经送葬人引荐，依罗德岛与公证所协议提供特种支援。档案记录其性格温和、乐于助人，并以他与送葬人的差异说明，同机构执行者的处事方式并不一致。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[{"title":"出行计划","intro":"一个对卡兹戴尔足够了解的萨卡兹，他对萨科塔能有什么好脸色？"}],"forms":[{"id":"char_4036_forcer","name":"见行者"}],"source":"https://prts.wiki/w/%E8%A7%81%E8%A1%8C%E8%80%85"},{"id":"char_199_yak","name":"角峰","en":"Matterhorn","kind":"operator","region":"kjerag","origin":"谢拉格","faction":"喀兰贸易","profession":"重装","aliases":[],"title":"角峰的侍卫训练与外派工作","summary":"角峰出身谢拉格，父亲与祖父均为银灰家的近卫，他也从小按家族侍卫方向受训。不同于上一代只接受军事训练，他获得学习其他技能的机会，并选择厨艺。后来，他作为喀兰贸易成员，依据公司与罗德岛的合作协定外派，参与罗德岛相关任务。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"一天","intro":"一碗汤，角峰炖了一天。"}],"forms":[{"id":"char_199_yak","name":"角峰"}],"source":"https://prts.wiki/w/%E8%A7%92%E5%B3%B0"},{"id":"char_272_strong","name":"孑","en":"Jaye","kind":"operator","region":"lungmen","origin":"龙门","faction":"炎-龙门","profession":"特种","aliases":[],"title":"孑的水产生意与干员录用","summary":"孑在龙门经营水产生意，经星熊介绍，接受并通过测试后加入罗德岛，现作为特种干员参加任务，主要技能是熟练刀工。他初到舰上时因长相凶恶，引起同事对其背景的猜测。后续接触记录认为他待人友善，确认原有身份确为水产小贩，没有支持那些传闻的额外材料。","focus":"依据已确认职业和交往记录叙述，不把外貌误认扩写为隐藏身份。","memories":[{"title":"将错就错","intro":"孑凶恶的外表经常给他带来不必要的麻烦，但是偶尔，孑也能利用这点做一些好事。"},{"title":"关键人物","intro":"时代会变，曾经最熟悉的人也会变，普普通通的水产小贩因此成了“关键人物”。这一路遗落了什么，未来将要守护什么，他心里都有数。"}],"forms":[{"id":"char_272_strong","name":"孑"}],"source":"https://prts.wiki/w/%E5%AD%91"},{"id":"char_347_jaksel","name":"杰克","en":"Jackie","kind":"operator","region":"columbia","origin":"哥伦比亚","faction":"哥伦比亚","profession":"近卫","aliases":[],"title":"杰克的辅警经历与近卫录用","summary":"杰克原为哥伦比亚辅警，因故感染矿石病后前往罗德岛治疗。经父亲同意，她参加测试并成为干员，在近身格斗方面表现出较强天赋，参与多类任务。她日常活跃友善，喜欢讲述父亲的事迹，受到不少同僚喜爱。现有材料未完整交代感染事件及其此前警务经历。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[{"title":"无价的勋章","intro":"在危机发生的那一刻，杰克只有一个想法：决不能见死不救。"}],"forms":[{"id":"char_347_jaksel","name":"杰克"}],"source":"https://prts.wiki/w/%E6%9D%B0%E5%85%8B"},{"id":"char_235_jesica","name":"杰西卡","en":"Jessica","kind":"operator","region":"columbia","origin":"维多利亚","faction":"黑钢国际","profession":"狙击","aliases":[],"title":"杰西卡的黑钢派遣学习记录","summary":"杰西卡是黑钢正式干员，作为双方交流项目的一部分驻扎罗德岛学习。人事档案认为，她的实战能力已经可以信赖，但性格缺乏自信，经常表现慌张，因此容易被旁人低估。所给材料主要记录这一阶段的驻派状态，尚未涉及她之后与黑钢关系的变化。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"缓步前行","intro":"她走得不快，也没有选择人们眼中最好走的路。"}],"forms":[{"id":"char_235_jesica","name":"杰西卡"},{"id":"char_1034_jesca2","name":"涤火杰西卡"}],"source":"https://prts.wiki/w/%E6%9D%B0%E8%A5%BF%E5%8D%A1"},{"id":"char_4217_makoto","name":"结城理","en":"Makoto Yuki","kind":"operator","region":"other","origin":"未录入","faction":"S.E.E.S.","profession":"特种","aliases":[],"title":"结城理的拉特兰校园记录","summary":"结城理在现有校园记录中是一名低调、寡言的学生，最初曾有人担心他能否适应拉特兰的学校生活，后来的表现消除了部分顾虑。校庆当天，埃癸斯因找不到他而向阿米娅求助，两人开始寻人。该条目没有提供完整客观履历，也未交代此次寻人的全部结果及更早经历。","focus":"严格采用联动校园片段，不以外部作品的设定补全履历空白。","memories":[],"forms":[{"id":"char_4217_makoto","name":"结城理"}],"source":"https://prts.wiki/w/%E7%BB%93%E5%9F%8E%E7%90%86"},{"id":"char_4078_bdhkgt","name":"截云","en":"Jieyun","kind":"operator","region":"yan","origin":"炎","faction":"炎","profession":"狙击","aliases":[],"title":"截云的荒野生活与外勤登记","summary":"截云是生活在炎国西北沙漠中的阿纳萨少女，经槐琥介绍到罗德岛当地办事处接受治疗，同时担任外勤干员。她随身携带多个袋子，装有求生用具，也保存小石子、花叶与动物毛发。别人询问时，她能说明这些物件的取得地点，收藏习惯与其荒野生活记录相连。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[{"title":"最后的比武","intro":"该留不住的都是留不住的。但今天的比武，很尽兴。"}],"forms":[{"id":"char_4078_bdhkgt","name":"截云"}],"source":"https://prts.wiki/w/%E6%88%AA%E4%BA%91"},{"id":"char_306_leizi","name":"惊蛰","en":"Leizi","kind":"operator","region":"yan","origin":"炎","faction":"炎","profession":"术师","aliases":[],"title":"惊蛰的大理寺身份与雷法传承","summary":"惊蛰以炎国大理寺官员身份与罗德岛签订搜查协议，暂时驻舰，具备成熟战斗技巧与特殊技艺。她使用的雷法有严格传承要求，并兼具执法和权力象征。档案认可其作战表现，同时因官方身份与不明动机建议谨慎交流；关于雷法的神秘传说并未全部得到研究确认。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"司雷霆者","intro":"执炎律者，若有律不依，那立炎律何用？！"}],"forms":[{"id":"char_306_leizi","name":"惊蛰"},{"id":"char_1043_leizi2","name":"司霆惊蛰"}],"source":"https://prts.wiki/w/%E6%83%8A%E8%9B%B0"},{"id":"char_4169_caledo","name":"镜匠","en":"Caleido","kind":"operator","region":"rhodes","origin":"卡兹戴尔","faction":"罗德岛","profession":"重装","aliases":[],"title":"镜匠卡莱朵的供应与锻造合作","summary":"卡莱朵在卡兹戴尔从事镜子制作与销售，当地需求有限，生意规模不大。她主动向罗德岛当地办事处推销随身镜，经干员推荐后建立合作。现负责罗德岛宿舍镜子的翻新和供应，并在返回卡兹戴尔前协助锻造。档案记录其产品有装饰背板，镜面保持清洁，但未列出全部交易情况。","focus":"以手艺、销售和具体合作职责为范围，不推定未披露的商业安排。","memories":[],"forms":[{"id":"char_4169_caledo","name":"镜匠"}],"source":"https://prts.wiki/w/%E9%95%9C%E5%8C%A0"},{"id":"char_4019_ncdeer","name":"九色鹿","en":"Nine-Colored Deer","kind":"operator","region":"yan","origin":"炎","faction":"炎","profession":"辅助","aliases":[],"title":"九色鹿的药草知识与访学记录","summary":"九色鹿自称来自炎国山林，未告知具体位置。她熟悉药草采集与制作，具备一定作战能力，经其他干员介绍来到罗德岛交流学习，近期随舰同行。虽然未接受正规训练，她在战场判断、伤口应急处理和伤员搬运方面已有经验；这些经验的具体来源，输入并未说明。","focus":"出身信息包含本人自述，既有救护经验不能用于反推完整经历。","memories":[{"title":"大慈恻隐","intro":"善良如果被利用，其中心情应该如何平复？"}],"forms":[{"id":"char_4019_ncdeer","name":"九色鹿"}],"source":"https://prts.wiki/w/%E4%B9%9D%E8%89%B2%E9%B9%BF"},{"id":"char_1042_phatm2","name":"酒神","en":"Tragodia","kind":"operator","region":"victoria","origin":"维多利亚","faction":"维多利亚","profession":"辅助","aliases":[],"title":"蓝卡坞拍摄后的合作调整","summary":"傀影结束蓝卡坞拍摄后，已经实现最初到罗德岛的目的，与博士协商后决定保留合作。此后，他以辅助干员身份游历泰拉，为落脚地附近的办事处提供支援。此前他多独立执行刺客任务，少与本舰成员见面，出演电影的消息使更多干员开始了解其现状。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[],"forms":[{"id":"char_250_phatom","name":"傀影"},{"id":"char_1042_phatm2","name":"酒神"}],"source":"https://prts.wiki/w/%E9%85%92%E7%A5%9E"},{"id":"char_4221_ju","name":"矩","en":"Ju","kind":"operator","region":"yan","origin":"炎","faction":"炎","profession":"狙击","aliases":[],"title":"矩的身体检查与工程顾问工作","summary":"矩长期在炎国乡野游历，具有广泛经历，后受博士邀请，以工程技术顾问身份暂驻罗德岛。检查发现其身体可拆卸，但运行原理尚不能完全解释。多起记录涉及他取下头部讲解构造、遗留手指或手臂零件，以及由此引发的误会。他目前协助日常建设，也接受相关研究。","focus":"把观察现象与未明原理分开，不将地方机关人传闻直接视为完整历史。","memories":[{"title":"奇石","intro":"这场纷争的解法，当真只有“离去”一种？"}],"forms":[{"id":"char_4221_ju","name":"矩"}],"source":"https://prts.wiki/w/%E7%9F%A9"},{"id":"char_328_cammou","name":"卡达","en":"Click","kind":"operator","region":"rhodes","origin":"未公开","faction":"罗德岛","profession":"术师","aliases":[],"title":"卡达的视频创作与记录工作","summary":"卡达是独立视频制作者，经过多种题材尝试，主要拍摄自然风光与野外求生，在网络上具有一定知名度。她依本人意愿加入罗德岛，担任术师，负责后方支援及战场记录摄制。其职业与便携摄影设备、城际网络的发展相关，现有履历主要涵盖创作方向和入职后的职责。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[{"title":"无人工房","intro":"簌、簌、簌，是谁在敲门？欢迎来到，无人厂房——"}],"forms":[{"id":"char_328_cammou","name":"卡达"}],"source":"https://prts.wiki/w/%E5%8D%A1%E8%BE%BE"},{"id":"char_214_kafka","name":"卡夫卡","en":"Kafka","kind":"operator","region":"columbia","origin":"哥伦比亚","faction":"哥伦比亚","profession":"特种","aliases":[],"title":"卡夫卡的园艺经历与隐秘任务","summary":"卡夫卡原在哥伦比亚某城从事园艺，经赫默引荐加入罗德岛，因身手和思维敏捷而常参与隐秘任务。档案记载，她日常常带笑容，刻意表现乖巧，且明知旁人能够识破也不打算改变。她不太在意因此产生的评价，但对因身高被当作孩子的情况会直接表示不满。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"许以秘密","intro":"卡夫卡有很多秘密，但她只会告诉一个人。"}],"forms":[{"id":"char_214_kafka","name":"卡夫卡"}],"source":"https://prts.wiki/w/%E5%8D%A1%E5%A4%AB%E5%8D%A1"},{"id":"char_426_billro","name":"卡涅利安","en":"Carnelian","kind":"operator","region":"leithanien","origin":"萨尔贡","faction":"莱塔尼亚","profession":"术师","aliases":[],"title":"卡涅利安的游学与伯爵侍从工作","summary":"卡涅利安来自萨尔贡不受王酋管辖的部族，成年后依传统外出游学。到莱塔尼亚时，她发现少年伯爵隐瞒的感染者身份，最初遭到扣留，后来双方关系发生改变。她继续以侍从身份停留，并为伯爵秘密寻求治疗，因此与罗德岛合作，协助处理莱塔尼亚境内的相关事务。","focus":"按档案记录的关系变化叙述，不以最初扣留或后来的合作单独概括全程。","memories":[{"title":"保护者的本性","intro":"姐姐有姐姐的行事手段，妹妹也有妹妹的应对方法。"}],"forms":[{"id":"char_426_billro","name":"卡涅利安"}],"source":"https://prts.wiki/w/%E5%8D%A1%E6%B6%85%E5%88%A9%E5%AE%89"},{"id":"char_209_ardign","name":"卡缇","en":"Cardigan","kind":"operator","region":"rhodes","origin":"莱塔尼亚","faction":"行动预备组A4","profession":"重装","aliases":[],"title":"卡缇的巡逻经历与预备组工作","summary":"卡缇是莱塔尼亚公民，正式任职前参加雪橇巡逻队，通过多项测试后加入罗德岛行动预备组A4。档案将她描述为积极、自信，面对任务和日常生活均保持较高活力，对小组成员也较热情。输入主要提供巡逻背景、录用经过与相处表现，没有完整列出更早的家庭和训练经历。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[{"title":"绝对能行！","intro":"卡缇喜欢奔跑。卡缇擅长奔跑。卡缇此刻，必须奔跑！"}],"forms":[{"id":"char_209_ardign","name":"卡缇"}],"source":"https://prts.wiki/w/%E5%8D%A1%E7%BC%87"},{"id":"char_003_kalts","name":"凯尔希","en":"Kal'tsit","kind":"operator","region":"rhodes","origin":"罗德岛","faction":"罗德岛","profession":"医疗","aliases":[],"title":"凯尔希的医疗与管理职责","summary":"凯尔希是罗德岛高层管理人员和医疗项目负责人，学识涉及工业、社会、历史及多门自然学科。在行动中，她提供医学理论与应急医疗支持，也参与战略指挥和多个项目。所给第一档案只有少量历史对话，不能由此确认其全部个人经历或具体的历史行动。","focus":"第一档案仅有片段对话，本条不据此补足凯尔希的完整历史与行动。","memories":[{"title":"长路至此","intro":"为什么偏偏是医生，凯尔希？"}],"forms":[{"id":"char_003_kalts","name":"凯尔希"},{"id":"char_1052_kalts2","name":"凯尔希·思衡托"}],"source":"https://prts.wiki/w/%E5%87%AF%E5%B0%94%E5%B8%8C"},{"id":"char_1052_kalts2","name":"凯尔希·思衡托","en":"Kal'tsit·Esperanta","kind":"operator","region":"rhodes","origin":"罗德岛","faction":"罗德岛","profession":"医疗","aliases":[],"title":"思衡托阶段的医疗与研发职责","summary":"该后续阶段档案将凯尔希记为罗德岛创立者之一及医疗负责人，主要以医学专家身份参与矿石病药物研发。资料提及一次意外及凯尔希的“死亡”，相关损失未立即向全部干员公开。部分离舰人员返回新基地时，只注意到环境、人员和凯尔希外观的变化，具体情况仍未在此完整说明。","focus":"保留该形态独立时点及记录中的引号，不将其与基础阶段状态混为一谈。","memories":[],"forms":[{"id":"char_003_kalts","name":"凯尔希"},{"id":"char_1052_kalts2","name":"凯尔希·思衡托"}],"source":"https://prts.wiki/w/%E5%87%AF%E5%B0%94%E5%B8%8C%C2%B7%E6%80%9D%E8%A1%A1%E6%89%98"},{"id":"char_4162_cathy","name":"凯瑟琳","en":"Catherine","kind":"operator","region":"victoria","origin":"维多利亚","faction":"维多利亚","profession":"辅助","aliases":[],"title":"凯瑟琳的工人代表与合作职责","summary":"凯瑟琳出身伦蒂尼姆海布里区，是产业工人与工人代表，长期参与劳动者和工厂管理方的谈判。伦蒂尼姆事件中，她参加市民自救军抵抗，与罗德岛协同行动。之后，她协调多家工厂及工人团体建立合作，重点处理源石污染善后、矿石病预防和医疗救治事务。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[{"title":"日色温柔","intro":"伦蒂尼姆的太阳还会升起，海布里区的清晨总会到来。战争结束了，希望我们都能交好运。"}],"forms":[{"id":"char_4162_cathy","name":"凯瑟琳"}],"source":"https://prts.wiki/w/%E5%87%AF%E7%91%9F%E7%90%B3"},{"id":"char_4228_closur","name":"可露希尔","en":"Closure","kind":"operator","region":"rhodes","origin":"卡兹戴尔","faction":"罗德岛","profession":"先锋","aliases":[],"title":"可露希尔的部门职责与档案锁定","summary":"可露希尔担任罗德岛总工程师、采购负责人，并兼管多个部门。她将自己的档案设置为付费内容，但实际付款或当面询问后均会开放正文；若有人绕过锁定，她会追查方法并修补漏洞。人事部也掌握若干访问方式，相关记录同时描述了她添加桌面宠物的技术玩笑。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"分身有术","intro":"确定自己继承了她意志的方式，不只有过劳一种……"}],"forms":[{"id":"char_4228_closur","name":"可露希尔"}],"source":"https://prts.wiki/w/%E5%8F%AF%E9%9C%B2%E5%B8%8C%E5%B0%94"},{"id":"char_201_moeshd","name":"可颂","en":"Croissant","kind":"operator","region":"lungmen","origin":"米诺斯","faction":"企鹅物流","profession":"重装","aliases":[],"title":"可颂的物流派驻与日常经营","summary":"可颂是企鹅物流员工，在合同期间担任派驻罗德岛的外勤干员。她擅长防守，可以牵制多个敌人，也能使用巨锤进行攻击。日常记录显示，她以改善生活和消费为工作目标，经常寻找额外收入机会，并在基地摆摊。档案同时说明，她并非只关注积累金钱，但时有支出超过收入的情况。","focus":"可确认的任职和消费习惯分别记录，不据摆摊行为推定其全部价值取向。","memories":[{"title":"生意场","intro":"买进卖出，过手皆为烟云。"}],"forms":[{"id":"char_201_moeshd","name":"可颂"}],"source":"https://prts.wiki/w/%E5%8F%AF%E9%A2%82"},{"id":"char_4231_clemnt","name":"克莱门莎","en":"Clementia","kind":"operator","region":"aegir","origin":"阿戈尔","faction":"阿戈尔","profession":"近卫","aliases":[],"title":"克莱门莎的陆上项目与合作","summary":"克莱门莎拥有阿戈尔荣誉军团长、执政官及总战争设计师等职衔，负责阿戈尔已开展或计划开展的陆上项目。她协助罗德岛在伊比利亚与阿戈尔工作，并希望通过合作接触更多陆上政治实体。档案另留有她对武器设计部门的试用反馈，涉及舰载工具小型化的技术工作。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[],"forms":[{"id":"char_4231_clemnt","name":"克莱门莎"}],"source":"https://prts.wiki/w/%E5%85%8B%E8%8E%B1%E9%97%A8%E8%8E%8E"},{"id":"char_124_kroos","name":"克洛丝","en":"Kroos","kind":"operator","region":"rhodes","origin":"雷姆必拓","faction":"行动预备组A1","profession":"狙击","aliases":[],"title":"克洛丝的警备训练与弩射击","summary":"克洛丝来自雷姆必拓，曾与芬、米格鲁一起在哥伦比亚警备队受训，后进入罗德岛行动预备组。她日常较慢、温和，常带笑容，也偶有尖锐言语。档案记载，她为减少战场移动而选择现代弩，并经过练习获得精准射击能力，能与其他干员配合实施后方援护。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"苹果","intro":"偶发的怠惰会引起不可知的连锁反应。"}],"forms":[{"id":"char_124_kroos","name":"克洛丝"},{"id":"char_1021_kroos2","name":"寒芒克洛丝"}],"source":"https://prts.wiki/w/%E5%85%8B%E6%B4%9B%E4%B8%9D"},{"id":"char_301_cutter","name":"刻刀","en":"Cutter","kind":"operator","region":"columbia","origin":"哥伦比亚","faction":"哥伦比亚","profession":"近卫","aliases":[],"title":"刻刀的雇佣兵经历与护送工作","summary":"刻刀出身哥伦比亚西南乡镇，当地因天灾、贫瘠和管理薄弱而缺乏稳定生计。她长期在边缘地区从事雇佣工作，并为行动设定个人规则。因矿石病来到罗德岛后，她在任务中显示出近距离作战能力，现任近卫小队成员，多次参与重要人员护送。规则的完整内容未在此列明。","focus":"记录已知职业背景与自我约束，不从地区混乱推断她曾参与的具体案件。","memories":[{"title":"速食食品","intro":"雇佣兵就像速食食品，雇佣兵往往只能吃到速食食品。"}],"forms":[{"id":"char_301_cutter","name":"刻刀"}],"source":"https://prts.wiki/w/%E5%88%BB%E5%88%80"},{"id":"char_2013_cerber","name":"刻俄柏","en":"Ceobe","kind":"operator","region":"rhodes","origin":"玻利瓦尔","faction":"罗德岛","profession":"术师","aliases":[],"title":"刻俄柏的流浪经历与获救经过","summary":"刻俄柏自幼持续流浪，在野外感染矿石病，长期未获正规治疗。她在莱塔尼亚因饥饿袭击执行任务的罗德岛预备小队，遭制服后被送往当地分部，随后获得救助。通过干员测试后，她正式加入本舰；现有履历将其求生直觉与意志记为支撑漫游的重要因素。","focus":"本条采用客观履历与初遇记录，不将流浪地域误作出生地。","memories":[{"title":"特大号烤饼","intro":"荒野之子会将自然的准则应用在文明社会中。"}],"forms":[{"id":"char_2013_cerber","name":"刻俄柏"}],"source":"https://prts.wiki/w/%E5%88%BB%E4%BF%84%E6%9F%8F"},{"id":"char_101_sora","name":"空","en":"Sora","kind":"operator","region":"lungmen","origin":"因经纪公司要求不公开","faction":"企鹅物流","profession":"辅助","aliases":[],"title":"空的偶像工作与声音支援","summary":"空仍从事偶像工作，因故暂居企鹅物流，在双方与罗德岛建立合作后参加相关行动。她能够非主动地施展声音相关技艺，以歌声提供战场支援。所给档案记录她活泼、富有朝气，同时尚未完全掌握偶像工作与干员岗位之间的安排，目前仍在尝试协调两方面事务。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"距离","intro":"偶像是为人带来希望的角色，不仅仅是在舞台上。"},{"title":"向舞台前进","intro":"空想要的很简单，那就是——在舞台上自由地歌唱。"}],"forms":[{"id":"char_101_sora","name":"空"}],"source":"https://prts.wiki/w/%E7%A9%BA"},{"id":"char_282_catap","name":"空爆","en":"Catapult","kind":"operator","region":"rhodes","origin":"卡西米尔","faction":"行动预备组A6","profession":"狙击","aliases":[],"title":"空爆的患者身份与A6任职","summary":"空爆先以患者身份进入罗德岛，因能力受到注意，在征求本人意见后接受并通过测试，被分配到预备行动组A6。她曾是士兵，日常表现较为散漫，喜欢加入热闹，有时明知可能出问题仍参与其中，因此经常受到梓兰批评。该材料没有说明她此前服役的完整经过。","focus":"将已记录的日常违纪与职业背景分开，不把单一表现扩成全部经历。","memories":[{"title":"挣脱","intro":"当你无法忍受现有的生活方式，那就打破它，重新再选一种。"},{"title":"改变","intro":"时间到底能改变多少？"}],"forms":[{"id":"char_282_catap","name":"空爆"},{"id":"char_1049_catap2","name":"雷狼龙S空爆"}],"source":"https://prts.wiki/w/%E7%A9%BA%E7%88%86"},{"id":"char_4015_spuria","name":"空构","en":"Spuria","kind":"operator","region":"laterano","origin":"拉特兰","faction":"拉特兰","profession":"特种","aliases":[],"title":"空构的教皇厅任职与访学","summary":"空构本名斯普莉雅，是拉特兰公民，就职于教皇厅第六厅。安布罗修事件后，她随执行者里凯莱外派罗德岛，以访学人员身份协助工程部。她精通铳械辅助技术，熟悉通讯与机械工程，射击及移动目标跟随测试表现较好；记录同时指出，她有意避免完全依赖铳械作战。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[{"title":"铳声回响","intro":"一把铳能决定的生死太多，能改变的事情又太少。"}],"forms":[{"id":"char_4015_spuria","name":"空构"}],"source":"https://prts.wiki/w/%E7%A9%BA%E6%9E%84"},{"id":"char_332_archet","name":"空弦","en":"Archetto","kind":"operator","region":"laterano","origin":"拉特兰","faction":"拉特兰","profession":"狙击","aliases":[],"title":"空弦的修道院商业合作任务","summary":"空弦原名席德佳，来自兰登修道院，辗转龙门、叙拉古与萨尔贡寻找发展机会后，选择联系罗德岛。她携带修道院宣传材料，主动提出合作条款，并依据个人申请担任狙击干员。档案确认其作战能力优异，也记录她在各项工作中持续关注商业机会。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"偶像宣传","intro":"商业宣传总是需要一个形象代言人，而为了维持形象，代言人总是身不由己。"}],"forms":[{"id":"char_332_archet","name":"空弦"}],"source":"https://prts.wiki/w/%E7%A9%BA%E5%BC%A6"},{"id":"char_405_absin","name":"苦艾","en":"Absinthe","kind":"operator","region":"ursus","origin":"乌萨斯","faction":"乌萨斯学生自治团","profession":"术师","aliases":[],"title":"苦艾的切城经历与术师任职","summary":"苦艾是切尔诺伯格本地警察的女儿，曾与一队警察在城市失序后共同求生。局势和天灾使原有疏散行动难以继续，她最后独自倒在废墟中，被罗德岛救援队找到。登舰后，她主动申请加入，通过培训与测试成为术师干员，同时参与舰内巡逻。现有记录未详述同行警察的全部结局。","focus":"依据本人陈述与救援记录叙述，不补写缺失人员的具体遭遇。","memories":[{"title":"向死寻生","intro":"死还是活？这根本不是问句。"}],"forms":[{"id":"char_405_absin","name":"苦艾"}],"source":"https://prts.wiki/w/%E8%8B%A6%E8%89%BE"},{"id":"char_250_phatom","name":"傀影","en":"Phantom","kind":"operator","region":"victoria","origin":"维多利亚","faction":"维多利亚","profession":"特种","aliases":[],"title":"傀影的特种任职与履历边界","summary":"傀影此前独自在维多利亚及周边活动，过去的行踪与背景尚未完全查实，后成为罗德岛特种干员。初到本舰时，他未被工作人员察觉便进入身后位置，引起后勤人员惊慌，舰船随后加强监测与防控。档案认可其作战能力，也要求对未明部分持续保持审慎。","focus":"本条限定已记录的潜行表现与录用情况，不补造背景缺项。","memories":[{"title":"合作","intro":"人与人之间总会产生种种交集，谁也不会是例外。"}],"forms":[{"id":"char_250_phatom","name":"傀影"},{"id":"char_1042_phatm2","name":"酒神"}],"source":"https://prts.wiki/w/%E5%82%80%E5%BD%B1"},{"id":"char_140_whitew","name":"拉普兰德","en":"Lappland","kind":"operator","region":"siracusa","origin":"叙拉古","faction":"叙拉古","profession":"近卫","aliases":[],"title":"拉普兰德的行动能力与履历核查","summary":"这一阶段的拉普兰德身份和履历仍有缺失，作为近卫执行特别行动，在攻坚与肃清任务中有很强的歼灭能力。日常中她能礼貌交谈，也会观察他人对黑色笑话的反应。医疗组监控其较严重的感染情况；关于危险家族出身的传闻，调查未找到证据，后因风险停止。","focus":"身世传闻尚未核实，履历核查停止不等于已经确认或否认家族联系。","memories":[],"forms":[{"id":"char_140_whitew","name":"拉普兰德"},{"id":"char_1038_whitw2","name":"荒芜拉普兰德"}],"source":"https://prts.wiki/w/%E6%8B%89%E6%99%AE%E5%85%B0%E5%BE%B7"},{"id":"char_373_lionhd","name":"莱恩哈特","en":"Leonhardt","kind":"operator","region":"rim","origin":"雷姆必拓","faction":"雷姆必拓","profession":"术师","aliases":[],"title":"莱恩哈特的矿队顾问与预警工作","summary":"莱恩哈特是雷姆必拓天灾信使，曾多次作为顾问随尤立卡自治州矿队行动，熟悉地形、地质调查及灾后现场作业。他具有野外应对、与护卫协同以及回避次生灾害的经验。现以术师干员身份在罗德岛任职，并提供天灾区域调查与预警服务，也参加需要破坏硬目标的任务。","focus":"从职业经验与现有岗位说明能力，不扩写未给出的具体矿区行动。","memories":[{"title":"暗境求生","intro":"我们一定会平安再相见的。"}],"forms":[{"id":"char_373_lionhd","name":"莱恩哈特"}],"source":"https://prts.wiki/w/%E8%8E%B1%E6%81%A9%E5%93%88%E7%89%B9"},{"id":"char_4142_laios","name":"莱欧斯","en":"Laios","kind":"operator","region":"other","origin":"北方大陆（自称）","faction":"莱欧斯小队","profession":"近卫","aliases":[],"title":"莱欧斯的探索经验与小队合作","summary":"莱欧斯是其冒险小队的队长，声称来自北方大陆，具有丰富的迷宫探索经验。他与伙伴提及的多个地点未见于罗德岛资料，具体来历尚难确认。执行野外任务时，小队能提供实际作战帮助，因此其贡献得到认可。输入保留了对身份的多种推测，未形成确定的来源结论。","focus":"出身地为本人自述，输入中的猜测不作为世界地理事实。","memories":[],"forms":[{"id":"char_4142_laios","name":"莱欧斯"}],"source":"https://prts.wiki/w/%E8%8E%B1%E6%AC%A7%E6%96%AF"},{"id":"char_4117_ray","name":"莱伊","en":"Ray","kind":"operator","region":"rim","origin":"雷姆必拓","faction":"雷姆必拓","profession":"狙击","aliases":[],"title":"莱伊的探井工作与入职测试","summary":"莱伊长期在雷姆必拓担任探井人，检查未知矿井并承担安保工作，没有稳定职业。遇到故地重游的阿米娅、博士和暴行后，她主动申请入职。暴行随后进行测试，确认其素质已足以担任现代大型矿场的安保；此前，她并未考虑过这种职业选择，入职后开始参加安保、战斗和勘探任务。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"夜晚荒漠上的鳞群","intro":"沙地兽，你看到了吗？原来“夜晚荒漠上的鳞群”这个传说是真的，还和你我有关。"},{"title":"月下舞者","intro":"她所追寻的光，不在终点，而在每一步前行的路上。"}],"forms":[{"id":"char_4117_ray","name":"莱伊"}],"source":"https://prts.wiki/w/%E8%8E%B1%E4%BC%8A"},{"id":"char_129_bluep","name":"蓝毒","en":"Blue Poison","kind":"operator","region":"iberia","origin":"未公开","faction":"伊比利亚","profession":"狙击","aliases":[],"title":"蓝毒的毒剂作战与毒理协助","summary":"蓝毒的身份与早期履历在档案中缺失，现任罗德岛狙击干员，使用小型手弩和自行配制的含毒箭矢。她也定期协助医疗组开展毒理研究，并在完成前线任务后照顾中毒人员。相关能力一度妨碍她与部分同事交往，但共同工作者也记录了她待人平和的一面。","focus":"能力危险性与人际评价采用不同证据，不由其中一项推定另一项。","memories":[{"title":"触不可及","intro":"最远的距离，是从传说到现实的距离。"}],"forms":[{"id":"char_129_bluep","name":"蓝毒"}],"source":"https://prts.wiki/w/%E8%93%9D%E6%AF%92"},{"id":"char_322_lmlee","name":"老鲤","en":"Lee","kind":"operator","region":"lungmen","origin":"炎","faction":"鲤氏侦探事务所","profession":"特种","aliases":[],"title":"老鲤的事务所经营与咨询合作","summary":"老鲤是龙门私家侦探，创办鲤氏侦探事务所，在罗德岛发展当地业务时与其相识，后来提供本地信息咨询并引荐人才。他熟悉跟踪、伪装、交涉和推理，日常也常做菜泡茶，并不长期驻舰。有时他借面谈工作到访，同时探望已在本舰工作的事务所成员。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[{"title":"三餐一日","intro":"每到一个新地方，就去当地的菜市场看看吧。"}],"forms":[{"id":"char_322_lmlee","name":"老鲤"}],"source":"https://prts.wiki/w/%E8%80%81%E9%B2%A4"},{"id":"char_1049_catap2","name":"雷狼龙S空爆","en":"Zinogre S Catapult","kind":"operator","region":"rhodes","origin":"卡西米尔","faction":"行动预备组A6","profession":"近卫","aliases":[],"title":"空爆的近卫转岗与泡影国报告","summary":"空爆按个人意愿变更为近卫干员，除A6日常任务外，也独自参加险地外勤。泡影国归来时，她提交的报告以狩猎、环境和怪物食材为主，没有完整说明行动过程。梓兰提供了另一份较详细的事件报告，两份材料相互补充，也反映她在当地收集了系统的生态信息。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[],"forms":[{"id":"char_282_catap","name":"空爆"},{"id":"char_1049_catap2","name":"雷狼龙S空爆"}],"source":"https://prts.wiki/w/%E9%9B%B7%E7%8B%BC%E9%BE%99S%E7%A9%BA%E7%88%86"},{"id":"char_107_liskam","name":"雷蛇","en":"Liskarm","kind":"operator","region":"columbia","origin":"瓦伊凡","faction":"黑钢国际","profession":"重装","aliases":[],"title":"雷蛇的安保合同与战术协同","summary":"雷蛇受雇于黑钢国际，曾在冲突地区为企业、政府部门及其他组织提供防卫服务，现依安保条约协助罗德岛。她在作战中重视推进、观察、沟通和战术确认。作为芙兰卡的搭档，她会反复提醒正确流程，制止可能的冒进。档案将这种处理方式与她优先保障生命安全的态度相联系。","focus":"仅据行动观察说明作战习惯，不将严谨流程推定为任何环境下的唯一方案。","memories":[{"title":"苹果派对准备中！","intro":"一本正经的样子？在这儿可行不通。"},{"title":"尚待","intro":"离开家乡的树叶，渴望着庇护那枯木再生。"}],"forms":[{"id":"char_107_liskam","name":"雷蛇"}],"source":"https://prts.wiki/w/%E9%9B%B7%E8%9B%87"},{"id":"char_4193_lemuen","name":"蕾缪安","en":"Lemuen","kind":"operator","region":"laterano","origin":"拉特兰","faction":"拉特兰","profession":"狙击","aliases":[],"title":"蕾缪安的枢机任职与正式访问","summary":"蕾缪安是拉特兰教皇厅第七厅枢机，任职后重排办公空间、职能区域和文件传送系统。她将到访罗德岛称为探望家属，但程序上仍属于拉特兰代表正式访问，期间依协议提供协助。档案同时记录其行政改革与来访身份，私人称呼不能替代正式合作安排。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[],"forms":[{"id":"char_4193_lemuen","name":"蕾缪安"}],"source":"https://prts.wiki/w/%E8%95%BE%E7%BC%AA%E5%AE%89"},{"id":"char_1036_fang2","name":"历阵锐枪芬","en":"Fang the Fire-sharpened","kind":"operator","region":"rhodes","origin":"卡西米尔","faction":"罗德岛","profession":"先锋","aliases":[],"title":"芬的正式考核与小队指挥工作","summary":"芬经过长期训练和多次外勤后通过正式考核，担任外勤小队组长，掌握战场指挥与一线沟通技巧。经历诀别和悲剧后，她比预备干员时期更加内敛、稳重，装备选择也偏向实用。档案同时记录，她仍仔细观察队员特点、关心成员，并继续积累经验。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[],"forms":[{"id":"char_123_fang","name":"芬"},{"id":"char_1036_fang2","name":"历阵锐枪芬"}],"source":"https://prts.wiki/w/%E5%8E%86%E9%98%B5%E9%94%90%E6%9E%AA%E8%8A%AC"},{"id":"char_237_gravel","name":"砾","en":"Gravel","kind":"operator","region":"kazimierz","origin":"卡西米尔","faction":"卡西米尔","profession":"特种","aliases":[],"title":"砾的骑士身份与博士护卫工作","summary":"砾是卡西米尔四阶骑士，因未在此说明的原因逗留罗德岛，擅长隐秘行动与暗杀，并自愿担任博士近卫之一。日常材料记有她对博士较为直接的言语和情绪激动时容易脸红的表现。除这些情况外，档案没有确认其他越界行为，也未完整公开她来到罗德岛前的履历。","focus":"保留来由和动机未明的边界，不用个别发言作心理状态结论。","memories":[{"title":"梦中过往","intro":"父母与家乡，是每一位孩子永远找寻的原点。"}],"forms":[{"id":"char_237_gravel","name":"砾"}],"source":"https://prts.wiki/w/%E7%A0%BE"},{"id":"char_194_leto","name":"烈夏","en":"Лето","kind":"operator","region":"ursus","origin":"乌萨斯","faction":"乌萨斯学生自治团","profession":"近卫","aliases":[],"title":"烈夏的学生经历与外勤任务","summary":"烈夏本名罗莎琳·塔季扬诺夫娜·拉里娜，切尔诺伯格事变前在当地中学就读，与凛冬同为学生中的领军人物。加入罗德岛后，她主要承担中长线外勤任务。档案比较自治团成员对灾难的反应，指出她较少回避谈及经历；这一表现应与其他成员的状态分别记录。","focus":"本条记录资料中呈现的差异，不据外在表现自行作心理诊断。","memories":[{"title":"捉迷藏","intro":"烈夏长这么大，只在那一天哭过。"}],"forms":[{"id":"char_194_leto","name":"烈夏"}],"source":"https://prts.wiki/w/%E7%83%88%E5%A4%8F"},{"id":"char_137_brownb","name":"猎蜂","en":"Beehunter","kind":"operator","region":"ursus","origin":"乌萨斯","faction":"乌萨斯","profession":"近卫","aliases":[],"title":"猎蜂的地下搏击经历与前线任职","summary":"猎蜂曾是乌萨斯地下搏击手，原所属组织分裂后加入罗德岛，现担任近卫，在前线发挥近身破坏力。第一档案主要记录她的日常状态，认为其生活要求简单，较为自在，尤其喜欢鱼干和蜂蜜。所给材料没有继续展开原组织分裂的原因或此前比赛经历。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"终场铃声","intro":"擂台终局敲响的钟声，不过是在宣告下一场比赛的来临。"}],"forms":[{"id":"char_137_brownb","name":"猎蜂"}],"source":"https://prts.wiki/w/%E7%8C%8E%E8%9C%82"},{"id":"char_4225_tanya","name":"裂响","en":"Crackborne","kind":"operator","region":"ursus","origin":"乌萨斯","faction":"乌萨斯","profession":"重装","aliases":[],"title":"裂响的工人背景与救助任职","summary":"裂响本名瑭雅，出身乌萨斯泽尔格勒的工人家庭，母亲从事建筑，父亲是消防员。她年幼时负责照顾弟妹，后来在当地以整合运动名号发起反抗。经弑君者介绍，她来到罗德岛接受治疗，并以正式干员身份参加外勤。现有资料没有列出反抗行动的详细过程与全部结果。","focus":"以已知出身和任职顺序为限，不把组织名号等同于所有其他行动的立场。","memories":[{"title":"昨日已死","intro":"过往的幽灵如影随形，今日之路该如何走下去？"}],"forms":[{"id":"char_4225_tanya","name":"裂响"}],"source":"https://prts.wiki/w/%E8%A3%82%E5%93%8D"},{"id":"char_4080_lin","name":"林","en":"Lin","kind":"operator","region":"lungmen","origin":"龙门","faction":"炎-龙门","profession":"术师","aliases":[],"title":"林雨霞的公开职务与合作","summary":"林本名林雨霞，来自龙门，公开履历包括青年创业者协会会长、客座讲师与行政顾问等职务，本职工作仍未充分说明。玉门事件后，她主动正式与罗德岛合作，为当地感染者收治提供帮助。本人申报资料有限且部分存疑，因此公开职衔、实际工作与未明信息需要区分。","focus":"公开职务可以核对，但不足以完整说明本职与其他未公开活动。","memories":[{"title":"新潮旧浪","intro":"贫民窟的规矩只有一条，那就是让这里的人过上好日子。"}],"forms":[{"id":"char_4080_lin","name":"林"}],"source":"https://prts.wiki/w/%E6%9E%97"},{"id":"char_148_nearl","name":"临光","en":"Nearl","kind":"operator","region":"kazdel","origin":"卡西米尔","faction":"使徒","profession":"重装","aliases":["玛嘉烈·临光"],"title":"临光的重装任职与治疗技艺","summary":"临光曾任卡西米尔耀骑士，作为感染者援助团体使徒成员来到罗德岛，担任重装并提供现场指挥。她擅长掩护、机动与开阔地带作战，使用兼具法杖功能的战锤施展发光技艺，能够治疗并鼓舞同伴。评估人员推测其能力还有复杂形式，但尚未证实。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[],"forms":[{"id":"char_148_nearl","name":"临光"},{"id":"char_1014_nearl2","name":"耀骑士临光"}],"source":"https://prts.wiki/w/%E4%B8%B4%E5%85%89"},{"id":"char_1033_swire2","name":"琳琅诗怀雅","en":"Swire the Elegant Wit","kind":"operator","region":"lungmen","origin":"龙门","faction":"炎-龙门","profession":"特种","aliases":[],"title":"诗怀雅升任局长后的合作方式","summary":"诗怀雅升任龙门近卫局局长后，来罗德岛的频率和停留时间均减少，并谨慎回避部分龙门公务话题。汐斯塔度假归来后，她仅以私人身份视情况提供协助，也谈及与拜松合办的物流公司和水上乐园。档案另记有她与星熊因称谓、避嫌安排产生的日常争执，但未认定两人关系破裂。","focus":"按局长阶段区分公职与私人合作，不采信由出场减少推测的人事隔阂。","memories":[],"forms":[{"id":"char_308_swire","name":"诗怀雅"},{"id":"char_1033_swire2","name":"琳琅诗怀雅"}],"source":"https://prts.wiki/w/%E7%90%B3%E7%90%85%E8%AF%97%E6%80%80%E9%9B%85"},{"id":"char_115_headbr","name":"凛冬","en":"Зима","kind":"operator","region":"ursus","origin":"乌萨斯","faction":"乌萨斯学生自治团","profession":"先锋","aliases":[],"title":"凛冬的学生背景与小队指挥","summary":"凛冬曾在切尔诺伯格中学就读，早年已热衷战斗与突击。通过罗德岛测试后，她作为先锋担任小队队长。档案指出，她讲话直接，但会判断言行是否可行，并非完全不考虑影响；伙伴受到委屈时，她也会迅速作出反应。现有材料将个人作风与带队职责一并记录。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[{"title":"强中自有强中手","intro":"不要想太多，开心地玩一场吧。"},{"title":"在冬夜里燃烧","intro":"如果没有这场火……不，并没有什么如果。"}],"forms":[{"id":"char_115_headbr","name":"凛冬"},{"id":"char_1051_headb2","name":"怒潮凛冬"}],"source":"https://prts.wiki/w/%E5%87%9B%E5%86%AC"},{"id":"char_4102_threye","name":"凛视","en":"Valarqvin","kind":"operator","region":"sami","origin":"萨米","faction":"萨米","profession":"辅助","aliases":[],"title":"凛视的族群背景与北地合作","summary":"凛视来自萨米北部冬牙群山的独眼巨人族群，主动为某种预见的未来寻求合作，现协助罗德岛处理萨米及北方冰原事务。该族群长期未出现在多数公开记录中，其接触使部分知情干员感到忧虑。档案只记述合作与相关历史背景，没有公布所预见未来的完整内容。","focus":"预见内容没有在所给材料中公开，不应将族群传说直接写成确定结局。","memories":[],"forms":[{"id":"char_4102_threye","name":"凛视"}],"source":"https://prts.wiki/w/%E5%87%9B%E8%A7%86"},{"id":"char_1045_svash2","name":"凛御银灰","en":"SilverAsh the Reignfrost","kind":"operator","region":"kjerag","origin":"谢拉格","faction":"谢拉格","profession":"先锋","aliases":[],"title":"银灰辞任喀兰贸易董事长之后","summary":"该后续阶段记录中，恩希欧迪斯仍任希瓦艾什族长，但已辞去喀兰贸易董事长职务，由诺希斯接任。资料将此事放在1101年谢拉格经历观测站计划、天灾及外部军事压力的背景中。交接后公司继续运作，他则减少公开露面。合作档案认为身份与局势特殊，建议谨慎选择接洽方式。","focus":"以凛御形态的后续时点为准，不将辞职扩大解释为退出所有公共事务。","memories":[],"forms":[{"id":"char_172_svrash","name":"银灰"},{"id":"char_1045_svash2","name":"凛御银灰"}],"source":"https://prts.wiki/w/%E5%87%9B%E5%BE%A1%E9%93%B6%E7%81%B0"},{"id":"char_206_gnosis","name":"灵知","en":"Gnosis","kind":"operator","region":"kjerag","origin":"谢拉格","faction":"喀兰贸易","profession":"辅助","aliases":[],"title":"灵知的技术研发与研究室任职","summary":"灵知曾任喀兰贸易首席技术执行官，主持核心技术开发及工业设施设计，并长期研究源石。通过双方特别协议，他加入罗德岛，成为主要研究室成员，持续从事科研。档案记述其洞察力和求知欲较强，交流时常显得冷峻刻薄；这些相处评价与其专业成果同时存在。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[{"title":"起点","intro":"在一开始，诺希斯并不喜欢恩希欧迪斯这个人。"}],"forms":[{"id":"char_206_gnosis","name":"灵知"}],"source":"https://prts.wiki/w/%E7%81%B5%E7%9F%A5"},{"id":"char_358_lisa","name":"铃兰","en":"Suzuran","kind":"operator","region":"siracusa","origin":"东国","faction":"叙拉古","profession":"辅助","aliases":[],"title":"铃兰的治疗学习与低难度任务","summary":"铃兰本名丽萨，姓氏按监护人要求隐去，年纪尚小，在罗德岛治疗并接受凯尔希指导。她拥有优秀施术天赋，主动申请后获准在其他干员陪同下参加低难度任务。照护记录认为，她礼貌而坚强，但对感染者处境缺少基础认识，因此还需相关教育和说明。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[],"forms":[{"id":"char_358_lisa","name":"铃兰"}],"source":"https://prts.wiki/w/%E9%93%83%E5%85%B0"},{"id":"char_192_falco","name":"翎羽","en":"Plume","kind":"operator","region":"laterano","origin":"拉特兰","faction":"拉特兰","profession":"先锋","aliases":[],"title":"翎羽的斧枪训练与安保任职","summary":"翎羽来自拉特兰，曾任戍卫队成员。早期使用制式斧枪时，她因力量不足而训练受挫，后来在同僚指导下转向速度、移动和操作技巧，逐步形成有效流程。离开拉特兰来到罗德岛后，她担任安保人员，负责基地巡查、重要物资看护等工作，也能承担稳定的进攻与防守任务。","focus":"记录训练方法的调整，不把力量限制写成对全部作战能力的否定。","memories":[{"title":"远大理想","intro":"她会背着那柄旧斧枪往前走。"}],"forms":[{"id":"char_192_falco","name":"翎羽"}],"source":"https://prts.wiki/w/%E7%BF%8E%E7%BE%BD"},{"id":"char_4187_graceb","name":"聆音","en":"Gracebearer","kind":"operator","region":"bolivar","origin":"玻利瓦尔","faction":"玻利瓦尔","profession":"近卫","aliases":[],"title":"聆音的修女身份与返乡任职","summary":"聆音来自玻利瓦尔，经信仰搅拌机推荐加入罗德岛，后来返回家乡，在当地办事处担任近卫。档案以其修女身份和日常行为描述虔诚：较少参与闲谈，遵守自身行为规范，愿意不计报酬帮助有需要者。现有输入重点涵盖推荐、返乡与任职，未完整交代此前人生经历。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[{"title":"砸碎一抹微笑","intro":"一位说谎的虔信者告诉我，有一片和我脚下的土地截然不同的地方。我杀了她，去看看。"}],"forms":[{"id":"char_4187_graceb","name":"聆音"}],"source":"https://prts.wiki/w/%E8%81%86%E9%9F%B3"},{"id":"char_2023_ling","name":"令","en":"Ling","kind":"operator","region":"yan","origin":"炎","faction":"炎-岁","profession":"辅助","aliases":[],"title":"令的访客登记与舰内诗歌记录","summary":"令寓居尚蜀，与炎国部分政府部门有联系，尚蜀事件后通过审核，以访客身份留舰。她日常饮酒，不强求他人陪同，醉后有唱歌并在墙上书写的行为。干员收集了相关诗词，认为其中包含古文体、地名和特殊描述，但解释成本较高，内容真伪仍不能一概确定。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"醒时梦长","intro":"从江南到塞北，再到这尚蜀山巅的无名古亭，千载时间，百样世情，不过一场酣梦而已。"}],"forms":[{"id":"char_2023_ling","name":"令"}],"source":"https://prts.wiki/w/%E4%BB%A4"},{"id":"char_4042_lumen","name":"流明","en":"Lumen","kind":"operator","region":"iberia","origin":"伊比利亚","faction":"伊比利亚","profession":"医疗","aliases":["乔迪"],"title":"流明的地方救护与三方会议工作","summary":"流明本名乔迪，来自伊比利亚格兰法洛，长期担任礼拜堂护工。经极境和凯尔希引荐，他成为罗德岛驻伊比利亚干员，协助当地感染者医疗救护。他也列席罗德岛、阿戈尔及审判庭的会议，提供个人视角的意见。日常记录强调他会关注他人需求，并在能力范围内提供帮助或陪伴。","focus":"列席会议不代表拥有各方决策权，个人医疗工作与外交参与分别记录。","memories":[{"title":"直到灯火明亮","intro":"阿戈尔人，你为什么还没有离开格兰法洛？"}],"forms":[{"id":"char_4042_lumen","name":"流明"}],"source":"https://prts.wiki/w/%E6%B5%81%E6%98%8E"},{"id":"char_126_shotst","name":"流星","en":"Meteor","kind":"operator","region":"kazimierz","origin":"卡西米尔","faction":"卡西米尔","profession":"狙击","aliases":[],"title":"流星的守林经历与离乡治疗","summary":"流星原为卡西米尔守林人，曾与伙伴共同守护森林，掌握弓术、追踪及荒野生存技巧。感染矿石病后，她被迫离乡，辗转加入罗德岛，在治疗期间担任前线狙击干员。档案记述她待人温和、善于体谅同伴，喜欢集体活动，也会主动组织，因此日常相处中受到信赖。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[{"title":"滚烫旧忆","intro":"往日的回忆是身后穷追的野兽。"},{"title":"两难","intro":"月亮不总是圆满，世上多的是缺憾。"}],"forms":[{"id":"char_126_shotst","name":"流星"}],"source":"https://prts.wiki/w/%E6%B5%81%E6%98%9F"},{"id":"char_486_takila","name":"龙舌兰","en":"Tequila","kind":"operator","region":"bolivar","origin":"玻利瓦尔","faction":"玻利瓦尔","profession":"近卫","aliases":[],"title":"龙舌兰的免职与沟通事务","summary":"龙舌兰原名埃内斯托，曾任多索雷斯国际贸易管理部门副职，暴乱后被革职，经陈引荐通过测试加入罗德岛。他很快适应新工作，擅长交流和争端调解。记录指出，他几乎始终保持友善表情，少有负面情绪外露，部分同伴因此仍对其实际情绪状态保持关切。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"尖刺的滋味","intro":"青年的志向已有决断，尽管浪涛依旧在拍击海岸。"}],"forms":[{"id":"char_486_takila","name":"龙舌兰"}],"source":"https://prts.wiki/w/%E9%BE%99%E8%88%8C%E5%85%B0"},{"id":"char_4196_reckpr","name":"录武官","en":"Record Keeper","kind":"operator","region":"yan","origin":"炎","faction":"炎","profession":"医疗","aliases":[],"title":"录武官云青萍的文职与外勤评估","summary":"云青萍曾在炎国记录将士武功、编撰相关书籍，经左乐介绍暂驻罗德岛，协助司岁台观察岁兽代理人并承担后勤工作。旧伤限制其体能，但长期锻炼形成了良好平衡、吐纳和动态观察能力。综合评估后，他获准在不频繁且力所能及的条件下参加部分外勤，而非无限制参与任务。","focus":"区分医疗限制、专项能力与获准范围，不把有限许可描述为完全康复。","memories":[{"title":"何须剑","intro":"武道至极，无剑胜有剑。"}],"forms":[{"id":"char_4196_reckpr","name":"录武官"}],"source":"https://prts.wiki/w/%E5%BD%95%E6%AD%A6%E5%AE%98"},{"id":"char_4130_luton","name":"露托","en":"Lutonada","kind":"operator","region":"bolivar","origin":"玻利瓦尔","faction":"玻利瓦尔","profession":"重装","aliases":[],"title":"露托的战场谋生与后勤合作","summary":"露托曾在玻利瓦尔各处交战区活动，不隶属当地组织，以战场打扫维生。来到罗德岛接受治疗后，她与后勤部签订合作协议，偶尔担任外勤战场环境顾问。身体初步恢复时，她常独处，与人相处较疏离，也会用过去的工作习惯解释同僚注意到的异常举动。","focus":"本条仅记录适应与工作经历，不将旧有谋生习惯推定为完整性格。","memories":[{"title":"阳光映照之下","intro":"露托觉得自己也会在以后的日子里回忆起这个带着阳光、花香和烤肉香气的下午。"}],"forms":[{"id":"char_4130_luton","name":"露托"}],"source":"https://prts.wiki/w/%E9%9C%B2%E6%89%98"},{"id":"char_4232_hbound","name":"旅骨","en":"Homebound","kind":"operator","region":"iberia","origin":"伊比利亚","faction":"伊比利亚","profession":"特种","aliases":[],"title":"旅骨的水文工作与设备改造","summary":"旅骨原名纳乔，熟悉水文测绘和地理建模，港都打捞结束后经克莱门莎引荐，常驻伊比利亚协助沿海观测。到本舰后，他因多次收到遗失物提示，请工程部改造探测设备，使其能扫描建筑空间。此后，他也作为失物招领志愿者，使用专业装置协助寻找物品。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[],"forms":[{"id":"char_4232_hbound","name":"旅骨"}],"source":"https://prts.wiki/w/%E6%97%85%E9%AA%A8"},{"id":"char_433_windft","name":"掠风","en":"Windflit","kind":"operator","region":"columbia","origin":"哥伦比亚","faction":"哥伦比亚","profession":"辅助","aliases":[],"title":"掠风的工程教育与机械支援","summary":"掠风来自哥伦比亚工人家庭，曾帮助父母从事流水线劳动，并表现出学习和改进机械的能力。他通过求学获得工学及源石工学双学位，毕业后加入罗德岛工程部，主要设计制造机械并提供作战支援。初入职时，档案也记录了他的自轻倾向及与富裕同事交往方面的困难。","focus":"教育与任职能够确认，心理变化的后续进展未在该段资料中展开。","memories":[{"title":"老工厂里的一支舞","intro":"“今天的工厂灯火通明，像昨天傍晚我说爱你时的夕阳 。”\n——工人们最常唱的一首歌"}],"forms":[{"id":"char_433_windft","name":"掠风"}],"source":"https://prts.wiki/w/%E6%8E%A0%E9%A3%8E"},{"id":"char_484_robrta","name":"罗比菈塔","en":"Roberta","kind":"operator","region":"columbia","origin":"哥伦比亚","faction":"哥伦比亚","profession":"辅助","aliases":[],"title":"罗比菈塔的化妆与工程任职","summary":"罗比菈塔是哥伦比亚知名化妆师，曾在电影化妆及发型设计领域获得业界认可。她来到罗德岛后，坚持参加工程部门考核，表现出自动化机械的专业素养，经可露希尔同意成为驻舰干员。现有记录明确她同时具备两类职业能力，并未说明她必须因此终止原有化妆业务。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[{"title":"挽歌","intro":"挽歌的演奏者自吟自赏。"}],"forms":[{"id":"char_484_robrta","name":"罗比菈塔"}],"source":"https://prts.wiki/w/%E7%BD%97%E6%AF%94%E8%8F%88%E5%A1%94"},{"id":"char_451_robin","name":"罗宾","en":"Robin","kind":"operator","region":"columbia","origin":"哥伦比亚","faction":"哥伦比亚","profession":"特种","aliases":[],"title":"罗宾的保镖经历与特种任职","summary":"罗宾曾在哥伦比亚担任保镖，经赫默推荐后通过考核，使用自制陷阱配合远程攻击，参加罗德岛各类任务。档案描述她较为沉默，常给人心事重重的印象。本人解释，这是长期维持家计、需要考虑许多事务形成的习惯；进一步交流也能看到她与同龄人相近的爱好。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"冷暖自知","intro":"罗德岛很好，她也很好。"}],"forms":[{"id":"char_451_robin","name":"罗宾"}],"source":"https://prts.wiki/w/%E7%BD%97%E5%AE%BE"},{"id":"char_4215_buddy","name":"罗德岛隐秘队","en":"Rhodes Island Recon","kind":"operator","region":"rhodes","origin":"未知","faction":"罗德岛","profession":"先锋","aliases":[],"title":"隐秘队的成员构成与调查职责","summary":"罗德岛隐秘队由艾露猫政宗和牙猎犬义经组成，名字沿用故乡的随从编制。两者受过情报调查与素材收集训练，也在泡影国积累经验，加入后很快承担相关任务。他们仍寻找回乡道路，同时参与泰拉冒险，并逐渐与舰上成员熟悉。政宗还曾向A6介绍故乡猎人的工作与训练要求。","focus":"本篇限于联动条目的成员和行动记录，不将故乡规则套用为泰拉通则。","memories":[],"forms":[{"id":"char_4215_buddy","name":"罗德岛隐秘队"}],"source":"https://prts.wiki/w/%E7%BD%97%E5%BE%B7%E5%B2%9B%E9%9A%90%E7%A7%98%E9%98%9F"},{"id":"char_4067_lolxh","name":"罗小黑","en":"Luo Xiaohei","kind":"operator","region":"yan","origin":"未知","faction":"炎","profession":"近卫","aliases":[],"title":"罗小黑的推荐入职与同行记录","summary":"罗小黑经老鲤推荐来到罗德岛，通过考核后正式成为近卫。虽然年幼，他的作战能力显著高于同龄水平。朋友小白、阿根及比丢也一同到来；初到陌生环境时，他们对自身经历有所保留。档案认可小黑的善良与勇敢，同时没有把尚未公开的来历整理成确定结论。","focus":"同行者的部分经历仍属保留信息，本条不依据零散透露补全其来历。","memories":[{"title":"夜游船","intro":"有些夜里，睡意不能如约而至，所以思念代替了它的位置。"}],"forms":[{"id":"char_4067_lolxh","name":"罗小黑"}],"source":"https://prts.wiki/w/%E7%BD%97%E5%B0%8F%E9%BB%91"},{"id":"char_4133_logos","name":"逻各斯","en":"Logos","kind":"operator","region":"rhodes","origin":"卡兹戴尔","faction":"罗德岛-精英干员","profession":"术师","aliases":[],"title":"逻各斯的测试标准与精英职责","summary":"逻各斯曾是巴别塔核心成员，参与卡兹戴尔内战，后成为罗德岛首批精英干员，制定施术潜能评估标准。现阶段，他继续担任外勤指挥，参与术师测试选拔及敏感情报处理。第一档案另记录，他曾设计以自身外貌辨认种族的测试，多数参与者未能正确作答。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[],"forms":[{"id":"char_4133_logos","name":"逻各斯"}],"source":"https://prts.wiki/w/%E9%80%BB%E5%90%84%E6%96%AF"},{"id":"char_4040_rockr","name":"洛洛","en":"Rockrock","kind":"operator","region":"victoria","origin":"维多利亚","faction":"维多利亚","profession":"术师","aliases":[],"title":"洛洛的自救军经历与行动指挥","summary":"洛洛是伦蒂尼姆自救军早期成员，使用费斯特改造的无人机进行侦察和远程攻击。父亲死于萨卡兹佣兵之手，使她曾反对含有萨卡兹成员的罗德岛加入行动。之后的战局促使她处理更复杂的取舍，记录中也有她在队长牺牲后接过指挥的表现。现与当地办事处保持合作。","focus":"依据已记录的立场变化与行动叙述，不假定她已消除所有既有分歧。","memories":[{"title":"六百镑","intro":"这场雪从天明下到天黑，又从天黑下到天明。"}],"forms":[{"id":"char_4040_rockr","name":"洛洛"}],"source":"https://prts.wiki/w/%E6%B4%9B%E6%B4%9B"},{"id":"char_4064_mlynar","name":"玛恩纳","en":"Młynar","kind":"operator","region":"kazimierz","origin":"卡西米尔","faction":"卡西米尔","profession":"近卫","aliases":[],"title":"玛恩纳的家族身份与地区合作","summary":"玛恩纳是临光家前家主，也是临光与瑕光的叔叔，履历未记其取得正式骑士封号。特锦赛结束约两个月后，他接受罗德岛邀请，协助卡西米尔地区事务。虽未正式加入征战骑士，他的战斗技巧具有典型骑士风格；有空时，也会在训练场向其他干员提供指点。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[],"forms":[{"id":"char_4064_mlynar","name":"玛恩纳"}],"source":"https://prts.wiki/w/%E7%8E%9B%E6%81%A9%E7%BA%B3"},{"id":"char_4141_marcil","name":"玛露西尔","en":"Marcille","kind":"operator","region":"other","origin":"北方大陆（自称）","faction":"莱欧斯小队","profession":"术师","aliases":[],"title":"玛露西尔的联动来历与法术支援","summary":"玛露西尔属于莱欧斯小队，自述在迷宫救援法琳时意外来到泰拉，目前在罗德岛寻找返回方法，并提供医疗和法术协助。测试中她体能较弱，长途行动容易疲劳，但熟练掌握多类魔法，能完成攻击、治愈、结界及其他支援工作。外部来历仍以本人陈述为界。","focus":"原所在地及穿越经过来自本人陈述，本条不额外引入其他世界设定。","memories":[],"forms":[{"id":"char_4141_marcil","name":"玛露西尔"}],"source":"https://prts.wiki/w/%E7%8E%9B%E9%9C%B2%E8%A5%BF%E5%B0%94"},{"id":"char_248_mgllan","name":"麦哲伦","en":"Magallan","kind":"operator","region":"columbia","origin":"哥伦比亚","faction":"莱茵生命","profession":"辅助","aliases":[],"title":"麦哲伦的外勤探索与无人机装备","summary":"麦哲伦是莱茵生命实验室外勤专员，依合作协议暂以罗德岛为据点开展探索。她使用多功能测绘仪与模块化无人机，根据环境和任务装配不同设备，执行调查、攻击或友军支援。档案列出制冷、开采及武装等模块，也保留部分功能的保密状态，没有公布所有探索活动的详细经过。","focus":"以可公开装备与任务范围为限，不从保密模块名称推定实际能力。","memories":[{"title":"生生不息","intro":"唱着歌的老人埋下的种子，麦哲伦把它们种成大片的花。"}],"forms":[{"id":"char_248_mgllan","name":"麦哲伦"}],"source":"https://prts.wiki/w/%E9%BA%A6%E5%93%B2%E4%BC%A6"},{"id":"char_4006_melnte","name":"玫拉","en":"Melanite","kind":"operator","region":"columbia","origin":"哥伦比亚","faction":"哥伦比亚","profession":"狙击","aliases":[],"title":"玫拉的测试员经历与外勤录用","summary":"玫拉原受雇于哥伦比亚武器测试公司，担任资深测试员。感染矿石病后，她与原公司解约，来到罗德岛寻求治疗，并签约成为外勤干员。医疗检查告一段落后，她主动递交简历，言语简短，留意面试人员举动。输入主要记述职业转换与应聘经过，没有完整披露旧公司的工作项目。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[{"title":"失去的时光","intro":"她被自己一度以为已经丢弃的时间找回。"}],"forms":[{"id":"char_4006_melnte","name":"玫拉"}],"source":"https://prts.wiki/w/%E7%8E%AB%E6%8B%89"},{"id":"char_208_melan","name":"玫兰莎","en":"Melantha","kind":"operator","region":"rhodes","origin":"维多利亚","faction":"行动预备组A4","profession":"近卫","aliases":[],"title":"玫兰莎的家庭背景与预备组任职","summary":"玫兰莎出生于伦蒂尼姆，父母从事香料贸易、加工与品牌经营，她自幼接触相关知识，也参与过香薰产品开发。感染后，她以此前没有职业的普通患者身份接受罗德岛测试，成绩优异并获准入职，担任行动预备组A4组长，所给材料主要涵盖家庭背景与初期任职。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"小队长","intro":"你看别人有多好，别人看你就也一样。"}],"forms":[{"id":"char_208_melan","name":"玫兰莎"}],"source":"https://prts.wiki/w/%E7%8E%AB%E5%85%B0%E8%8E%8E"},{"id":"char_133_mm","name":"梅","en":"May","kind":"operator","region":"victoria","origin":"维多利亚","faction":"维多利亚","profession":"狙击","aliases":[],"title":"梅的侦查训练与狙击岗位","summary":"梅自称维多利亚皇家侦探，并宣称曾破获多起案件、受到上司赏识，但这些履历在记录中仍按本人陈述处理。能够确认的是，她接受过侦查、追踪、反追踪和线索分析训练，现以狙击干员身份协助罗德岛。日常虽有失误，观察者也记有她在关键时刻表现可靠的情况。","focus":"明确区分自称头衔与可确认训练，不将未核实的案件成绩写成事实。","memories":[{"title":"大侦探探案集·卷一","intro":"维多利亚探案界的闪亮新星！大侦探梅缇丝·杰拉尔丁值得纪念的第一案！"}],"forms":[{"id":"char_133_mm","name":"梅"}],"source":"https://prts.wiki/w/%E6%A2%85"},{"id":"char_242_otter","name":"梅尔","en":"Mayer","kind":"operator","region":"columbia","origin":"哥伦比亚","faction":"莱茵生命","profession":"辅助","aliases":[],"title":"梅尔的机械设计与研究合作","summary":"梅尔出身哥伦比亚，属于莱茵生命研究室，是线控机械咪波的创造者，也经营个人工作室鲁特拉。她与罗德岛合作，在建筑、设计和开发方面提供帮助。此前在跨部门项目中，她曾为赫默筹备、安装和调试实验设备，项目后来中止；她对项目的了解与核心内容并不完全一致。","focus":"本条区分设备工作与项目全貌，不将有限参与视为掌握全部研究信息。","memories":[{"title":"满满的日程表","intro":"每天都要连轴转，烦在其中，乐在其中。"},{"title":"造物之心","intro":"从莱茵生命到罗德岛，它们一路同行。"}],"forms":[{"id":"char_242_otter","name":"梅尔"}],"source":"https://prts.wiki/w/%E6%A2%85%E5%B0%94"},{"id":"char_391_rosmon","name":"迷迭香","en":"Rosmontis","kind":"operator","region":"rhodes","origin":"哥伦比亚","faction":"罗德岛-精英干员","profession":"狙击","aliases":[],"title":"迷迭香的精英任职与能力测试","summary":"迷迭香是罗德岛精英干员，掌握稀有技艺，擅长对抗大型目标、设施制动和多类攻坚任务，由凯尔希指派担任歼灭战核心人员之一。档案说明其外貌为年幼菲林，能力测试已停止在室内进行。其他个人资料移入高权限库，因此所给信息主要是职务和战术评估。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[],"forms":[{"id":"char_391_rosmon","name":"迷迭香"}],"source":"https://prts.wiki/w/%E8%BF%B7%E8%BF%AD%E9%A6%99"},{"id":"char_4017_puzzle","name":"谜图","en":"Puzzle","kind":"operator","region":"victoria","origin":"维多利亚","faction":"维多利亚","profession":"先锋","aliases":[],"title":"谜图的情报任职与治疗限制","summary":"谜图是维多利亚军方情报人员，携开斯特公爵署名信函，以感染者身份来罗德岛寻求治疗并建立合作。他通过入职测试，具备隐蔽行动及烟雾技艺经验，但早期因频繁透支技艺，外勤一度被暂停。医疗人员要求他调整作战方式，以免影响抑制疗程及增加病情变化的风险。","focus":"将录用资格与医疗限制分开，不把暂停任务解释为能力或忠诚问题。","memories":[{"title":"旧日歌谣","intro":"他在又一个新的身份中，再次许下了无法兑现的承诺。"}],"forms":[{"id":"char_4017_puzzle","name":"谜图"}],"source":"https://prts.wiki/w/%E8%B0%9C%E5%9B%BE"},{"id":"char_122_beagle","name":"米格鲁","en":"Beagle","kind":"operator","region":"rhodes","origin":"玻利瓦尔","faction":"行动预备组A1","profession":"重装","aliases":[],"title":"米格鲁的预备队经历与防御工作","summary":"米格鲁来自玻利瓦尔，与芬及克洛丝一同加入罗德岛，担任行动预备组A1前卫。她主要依靠耐力和基本防御保护身后队友，没有复杂的法术或花哨技巧。档案指出，她起初仍显不成熟，但经过坚持训练，逐渐表现出专业态度、不认输的作风及较好的成长潜力。","focus":"本条采用行动预备组时期档案，不将后续剧情状态提前并入。","memories":[{"title":"小队的盾牌","intro":"当她们聚在一起，所有的负面情绪都会消失不见——看吧，今天也是个适合见面的好天气。"}],"forms":[{"id":"char_122_beagle","name":"米格鲁"}],"source":"https://prts.wiki/w/%E7%B1%B3%E6%A0%BC%E9%B2%81"},{"id":"char_344_beewax","name":"蜜蜡","en":"Beeswax","kind":"operator","region":"sargon","origin":"萨尔贡","faction":"萨尔贡","profession":"术师","aliases":[],"title":"蜜蜡的寻亲来访与游学入职","summary":"蜜蜡来自萨尔贡沙漠深处的部族，首次外出游历时主动联系罗德岛，希望寻找先行离乡的血亲。核查确认对方已是干员，但正执行秘密任务，短期不会回舰。她随后申请加入并随行等待，通过测试取得术师身份，把罗德岛作为游学试炼的第一站。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"黄沙归途","intro":"为生命寻找归途，亦是为自己寻找去处。"}],"forms":[{"id":"char_344_beewax","name":"蜜蜡"}],"source":"https://prts.wiki/w/%E8%9C%9C%E8%9C%A1"},{"id":"char_449_glider","name":"蜜莓","en":"Honeyberry","kind":"operator","region":"rim","origin":"雷姆必拓","faction":"雷姆必拓","profession":"医疗","aliases":[],"title":"蜜莓的草药经验与心理支持","summary":"蜜莓来自雷姆必拓，入职前与母亲居住在西部森林地带，熟悉植物药用、树屋建造和果实辨认等知识。她兼修心理学，加入罗德岛医疗部后，既运用草药治疗身体疾病，也关注干员的情绪与心理需求。日常观察记载她活泼、耐心，喜欢与朋友相处，但未列出全部专业训练经过。","focus":"按已知知识与岗位范围叙述，不将情绪观察等同于完整的心理诊疗资质。","memories":[{"title":"苦涩的根茎","intro":"偏见与隔阂看似不可撼动，但总得有人，也总会有人做些什么。"}],"forms":[{"id":"char_449_glider","name":"蜜莓"}],"source":"https://prts.wiki/w/%E8%9C%9C%E8%8E%93"},{"id":"char_4071_peper","name":"明椒","en":"Paprika","kind":"operator","region":"rhodes","origin":"哥伦比亚","faction":"罗德岛","profession":"医疗","aliases":[],"title":"明椒的佣兵经历与医疗支援","summary":"明椒曾在哥伦比亚从事萨卡兹佣兵工作，被曼弗雷德召至伦蒂尼姆。因理念不合，她带领小队脱离原阵营，遇袭后获救，随后接受罗德岛雇佣，为作战小组提供医疗支援。档案记述她性格直爽，做事利落，也指出双方接触过程中存在其他相关萨卡兹人员的引导。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[{"title":"少年雇佣兵","intro":"太天真的萨卡兹不会有未来，臭丫头，希望你的运气足够好，尽量比我活得久一点。"}],"forms":[{"id":"char_4071_peper","name":"明椒"}],"source":"https://prts.wiki/w/%E6%98%8E%E6%A4%92"},{"id":"char_4229_aphris","name":"谬因","en":"Aphrissa","kind":"operator","region":"columbia","origin":"哥伦比亚","faction":"哥伦比亚","profession":"术师","aliases":[],"title":"谬因的学术履历与辞职任职","summary":"谬因是常居玻利瓦尔的哥伦比亚人，曾任卢米内斯大学分校副教授，研究应用源石学与计算科学。大行军事件后，她辞去教职并成为罗德岛术师。人事核验确认了其十二岁入学、四年后获博士并留校任教的记录，所给材料没有展开辞职决定的全部原因。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[],"forms":[{"id":"char_4229_aphris","name":"谬因"}],"source":"https://prts.wiki/w/%E8%B0%AC%E5%9B%A0"},{"id":"char_154_morgan","name":"摩根","en":"Morgan","kind":"operator","region":"victoria","origin":"维多利亚","faction":"格拉斯哥帮","profession":"近卫","aliases":[],"title":"摩根的格拉斯哥帮事务职责","summary":"摩根是格拉斯哥帮成员，推进之王曾以帮派“大脑”称呼她。在罗德岛期间，她协助推进之王处理与格拉斯哥帮有关的事务，也兼职承担维多利亚办事处的部分工作。现有档案对她的日常装束留下片段描述，但没有提供更多可核实的早年履历，也未具体列明所有经办事项。","focus":"头衔为同伴的戏称，正文主要采用明确工作职责，不作超出资料的推断。","memories":[{"title":"巨轮之下","intro":"“摩根回忆录”撕掉的那页上写着美好的畅想，而未来要补上什么内容，她会找到答案。"}],"forms":[{"id":"char_154_morgan","name":"摩根"}],"source":"https://prts.wiki/w/%E6%91%A9%E6%A0%B9"},{"id":"char_4134_cetsyr","name":"魔王","en":"Civilight Eterna","kind":"operator","region":"rhodes","origin":"卡兹戴尔","faction":"罗德岛","profession":"辅助","aliases":[],"title":"魔王档案中的封存履历","summary":"魔王条目的客观履历使用特蕾西娅的封存人事资料，记述她建立卡兹戴尔移动城市、参与创立军事委员会和创办巴别塔。执政期间，她推进医疗、教育与基础建设，并参与抵抗入侵及外交工作，后来在战争中身亡。该资料的保存性质明确，不能仅由可用单位名称推断本人复生。","focus":"本条依据封存履历整理，历史人物与后续记忆程序需要分别说明。","memories":[{"title":"你与时间同长","intro":"“我知道你在长大，这没关系，这很好。”"}],"forms":[{"id":"char_4134_cetsyr","name":"魔王"}],"source":"https://prts.wiki/w/%E9%AD%94%E7%8E%8B"},{"id":"char_117_myrrh","name":"末药","en":"Myrrh","kind":"operator","region":"rhodes","origin":"未公开","faction":"罗德岛","profession":"医疗","aliases":[],"title":"末药的制药职责与原料研究","summary":"末药出身地未公开，以药师身份加入罗德岛医疗小组，承担制药工作，并表现出药物研发潜力。档案记载，她经常早出晚归，重视药品质量，喜欢在自然环境寻找更有效的原料。人际交往方面，她除少数好友外较难维持长期关系，但始终认真执行医疗职责。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"护身符","intro":"有些事，人们明知道是假的，却仍愿意相信它是真的。"}],"forms":[{"id":"char_117_myrrh","name":"末药"}],"source":"https://prts.wiki/w/%E6%9C%AB%E8%8D%AF"},{"id":"char_213_mostma","name":"莫斯提马","en":"Mostima","kind":"operator","region":"laterano","origin":"拉特兰","faction":"拉特兰","profession":"术师","aliases":[],"title":"莫斯提马的信使工作与出行记录","summary":"莫斯提马是企鹅物流员工，通常单独行动，加入前的履历在此并未详细说明。日常资料记录她了解多个国家的风土和地方信息，能够与不同人员友好交往，但经常不在固定地点，其他干员难以确认她的行踪。观察者也提到她与人保持距离，相关行为没有在该段给出完整原因。","focus":"本篇保留早期基础档案的认识范围，不以距离感补写确定的秘密任务。","memories":[{"title":"高楼之上","intro":"并不是一切愿望都会有结果。"},{"title":"旅途的注脚","intro":"我们或许永远只能顾及目所能及之处。"}],"forms":[{"id":"char_213_mostma","name":"莫斯提马"}],"source":"https://prts.wiki/w/%E8%8E%AB%E6%96%AF%E6%8F%90%E9%A9%AC"},{"id":"char_249_mlyss","name":"缪尔赛思","en":"Muelsyse","kind":"operator","region":"columbia","origin":"未公开","faction":"莱茵生命","profession":"先锋","aliases":[],"title":"缪尔赛思的科研职位与合作","summary":"缪尔赛思担任莱茵生命生态科主任，是哥伦比亚生命及环境科学领域研究者，也在多所大学任客座讲师。特里蒙事件后，她与罗德岛签订长期合作，参与生物工程研究室的联合项目，并作为先锋执行相关任务。现有记录同时确认其原有科研职位与跨机构合作关系。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[{"title":"无根之雨","intro":"让所有脆弱的生命能在此栖居……包括她自己。"}],"forms":[{"id":"char_249_mlyss","name":"缪尔赛思"}],"source":"https://prts.wiki/w/%E7%BC%AA%E5%B0%94%E8%B5%9B%E6%80%9D"},{"id":"char_4171_wulfen","name":"钼铅","en":"Wulfenite","kind":"operator","region":"sargon","origin":"萨尔贡","faction":"萨尔贡","profession":"特种","aliases":[],"title":"钼铅的地质考察与学术交流","summary":"钼铅兼任探险家、矿石收藏者和视频创作者，考察中感染后到罗德岛治疗，转为特种干员支援野外探索。她从具体矿物积累大量地质知识，部分内容尚未系统归纳。参加研究交流时，她还带动同伴分享考察经历，使会议内容由理论讨论扩展到个人经验与实地见闻。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"最后一次探险","intro":"穆丽儿无法说出安慰的话、鼓励的话，她知道这一切都没有办法。但是穆丽儿还是想再试试，试着再拉当时的自己一把。"}],"forms":[{"id":"char_4171_wulfen","name":"钼铅"}],"source":"https://prts.wiki/w/%E9%92%BC%E9%93%85"},{"id":"char_185_frncat","name":"慕斯","en":"Mousse","kind":"operator","region":"victoria","origin":"维多利亚","faction":"维多利亚","profession":"近卫","aliases":[],"title":"慕斯的甜点实习与后勤任职","summary":"慕斯出身维多利亚伦蒂尼姆富裕家庭，曾在瓦莱丽蛋糕店担任实习甜点师，在职期间感染矿石病，由父母送至罗德岛。接受治疗、心理辅导和测试后，她按本人意愿获准加入，主要承担常规后勤及战场辅助。档案也记载她不适应家族社交生活，但父母仍提供成长所需的照顾。","focus":"依据已知家庭与任职情况记录，不将兴趣差异推定为亲属关系破裂。","memories":[{"title":"小点心","intro":"对一份新款的面包而言，心意和情意是它的最佳配料。"}],"forms":[{"id":"char_185_frncat","name":"慕斯"}],"source":"https://prts.wiki/w/%E6%85%95%E6%96%AF"},{"id":"char_4025_aprot2","name":"暮落","en":"Shalem","kind":"operator","region":"victoria","origin":"维多利亚","faction":"维多利亚","profession":"重装","aliases":[],"title":"暮落的本舰工作与履历缺项","summary":"暮落是罗德岛本舰雇员，主要负责外勤和后勤筹备，以重装干员身份参加任务，具有较强战斗能力。档案记录他逐渐成为部分同僚熟悉的顾问，但人们常难准确回想最初相识的情形。背景资料仍有数项未核实，日常熟悉程度不能替代对其过去经历的正式确认。","focus":"人物的熟悉感与履历核实程度不同，未明条目保持原有边界。","memories":[{"title":"那一场戏","intro":"噩梦从未离开。"}],"forms":[{"id":"char_4025_aprot2","name":"暮落"}],"source":"https://prts.wiki/w/%E6%9A%AE%E8%90%BD"},{"id":"char_4138_narant","name":"娜仁图亚","en":"Narantuya","kind":"operator","region":"sargon","origin":"萨尔贡","faction":"萨尔贡","profession":"狙击","aliases":[],"title":"娜仁图亚的沙盗经历与护送预警","summary":"娜仁图亚曾在萨尔贡多地当沙盗，现以自然知识和生存技能参加罗德岛外勤。最初接触运输队时，她在绿洲与干员交谈并共享食物，临行提醒警惕东南方向沙暴。队伍随后遭沙盗埋伏，因已有防备顺利应对；再次会面时，她承认预判也来自熟悉同行的行动方式。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"何处寻宝藏","intro":"萨尔贡荒漠上有种说法，真正的宝藏只会让它中意的人找到。"}],"forms":[{"id":"char_4138_narant","name":"娜仁图亚"}],"source":"https://prts.wiki/w/%E5%A8%9C%E4%BB%81%E5%9B%BE%E4%BA%9A"},{"id":"char_4212_nasti","name":"娜斯提","en":"Nasti","kind":"operator","region":"columbia","origin":"卡兹戴尔","faction":"莱茵生命","profession":"辅助","aliases":[],"title":"娜斯提的工程主任与顾问合作","summary":"娜斯提任莱茵生命工程科主任，具有工程科学及应用语言学专长。经塞雷娅介绍，她接受罗德岛长期合作邀约，作为工程部特聘顾问支持多个项目。签约人员的回忆记载，合同在一处地下检修设施办理，现场有大量戴安全帽的巨蚁活动；她当时正在处理工程检修，未另设仪式。","focus":"现场经过采用来访者记录，不推定巨蚁的生物机制或全部研究用途。","memories":[],"forms":[{"id":"char_4212_nasti","name":"娜斯提"}],"source":"https://prts.wiki/w/%E5%A8%9C%E6%96%AF%E6%8F%90"},{"id":"char_103_angel","name":"能天使","en":"Exusiai","kind":"operator","region":"lungmen","origin":"拉特兰","faction":"企鹅物流","profession":"狙击","aliases":[],"title":"能天使的物流工作与联络任务","summary":"能天使是拉特兰公民及企鹅物流成员，从事秘密联络、武装押运等非公开业务。合约期间，她担任企鹅物流驻罗德岛联络人员，并支援多项行动。档案评价她乐观、善于活跃气氛，熟悉娱乐方式，待人慷慨；这些消费和交往习惯也使她较难积存金钱。","focus":"本条采用企鹅物流早期合作记录，不提前并入新约阶段的创业身份。","memories":[{"title":"来信","intro":"别太担心拉特兰人，他们在哪儿都能过得很好。"},{"title":"改变中的不变","intro":"活在当下，乐在其中。"}],"forms":[{"id":"char_103_angel","name":"能天使"},{"id":"char_1041_angel2","name":"新约能天使"}],"source":"https://prts.wiki/w/%E8%83%BD%E5%A4%A9%E4%BD%BF"},{"id":"char_4146_nymph","name":"妮芙","en":"Nymph","kind":"operator","region":"rhodes","origin":"卡兹戴尔","faction":"罗德岛","profession":"术师","aliases":[],"title":"妮芙的心灵技艺与卡兹戴尔见闻","summary":"妮芙经卡兹戴尔办事处加入外勤部门，结合心灵技艺与笞心魔天赋执行工作。她长期感知城市中的怨恨和哀痛，第一档案还记述了当地的生活变化：军人返回、商人采购粮食和消费品、工厂转向日用品生产。她对居民开始处理生计事务而非相互争抢的现象表示高兴。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"跃动的微光","intro":"当初飘落在她手心的那一点微光，如今已能为许多人驱散黑暗。"},{"title":"心火","intro":"仇恨与幸福从来不是某个族群、某些人的专属。"}],"forms":[{"id":"char_4146_nymph","name":"妮芙"}],"source":"https://prts.wiki/w/%E5%A6%AE%E8%8A%99"},{"id":"char_311_mudrok","name":"泥岩","en":"Mudrock","kind":"operator","region":"rhodes","origin":"卡兹戴尔","faction":"罗德岛","profession":"重装","aliases":[],"title":"泥岩的队伍迁徙与入舰经过","summary":"泥岩曾率萨卡兹佣兵加入整合运动，因分歧离开乌萨斯，没有参加切尔诺伯格及龙门行动。她在莱塔尼亚接纳当地感染者，被推为队伍领袖，之后因反复冲突转往卡兹戴尔，并经Logos接触来到罗德岛。盔甲使用技艺填充，外观和声音曾使包括部分队员在内的人误判其体型与性别。","focus":"明确组织经历与未参加的具体事件，不将队伍迁徙写成单纯的个人转职。","memories":[{"title":"在卡兹戴尔","intro":"一条长路终将到尽头，但她将行的路远不止这一条。"}],"forms":[{"id":"char_311_mudrok","name":"泥岩"}],"source":"https://prts.wiki/w/%E6%B3%A5%E5%B2%A9"},{"id":"char_2014_nian","name":"年","en":"Nian","kind":"operator","region":"yan","origin":"炎","faction":"炎-岁","profession":"重装","aliases":[],"title":"年的访客身份与工艺活动","summary":"年以访客身份停留罗德岛，自报无业，但熟悉金属加工，具有较广的冶金知识，偶尔为工程项目提出意见。她声称擅长音像娱乐制作，也向干员提供相关作品。多数人不清楚她何时到舰，凯尔希允许其停留，阿米娅则与她保持友好来往；公开记录仍未完整说明其身份。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[{"title":"千年一叹","intro":"年的电影故事看起来离奇古怪，但是偶尔，她也会在其中加一点认真的东西。"}],"forms":[{"id":"char_2014_nian","name":"年"}],"source":"https://prts.wiki/w/%E5%B9%B4"},{"id":"char_1051_headb2","name":"怒潮凛冬","en":"Zima the Raging Tide","kind":"operator","region":"ursus","origin":"乌萨斯","faction":"乌萨斯学生自治团","profession":"近卫","aliases":[],"title":"凛冬的近卫任职与办事处协助","summary":"凛冬继续担任乌萨斯学生自治团团长，长期带领作战小队，在训练和高频战斗中形成成熟的近卫风格。近期她协助罗德岛在圣骏堡建立办事处，并参与乌萨斯行动。第一档案回溯自治团离舰旅程，记载路线比预定曲折，最先抵达的雪地位于谢拉格，而非乌萨斯。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"循环","intro":"真正属于乌萨斯未来的道路，一定是从乌萨斯自己的土地上生长出来的。"}],"forms":[{"id":"char_115_headbr","name":"凛冬"},{"id":"char_1051_headb2","name":"怒潮凛冬"}],"source":"https://prts.wiki/w/%E6%80%92%E6%BD%AE%E5%87%9B%E5%86%AC"},{"id":"char_4173_nowell","name":"诺威尔","en":"Nowell","kind":"operator","region":"victoria","origin":"维多利亚","faction":"维多利亚","profession":"医疗","aliases":[],"title":"诺威尔的配镜生计与寻人行程","summary":"诺威尔是维多利亚配镜师，曾在泰拉多地游历寻人，以提供配镜服务维持生计，后来与九领导的新整合运动短暂同行。伦蒂尼姆事件结束后，他与一名旧顾客重逢，经介绍开始接触罗德岛。他已不记得出生地的确切位置，档案仅由受高卢语影响的口音提出地域推测。","focus":"口音推测不等于正式籍贯记录，现有资料未交代所寻之人的全部情况。","memories":[{"title":"当我们人生开始时","intro":"一双苍老的手，推开通往最初的门。"}],"forms":[{"id":"char_4173_nowell","name":"诺威尔"}],"source":"https://prts.wiki/w/%E8%AF%BA%E5%A8%81%E5%B0%94"},{"id":"char_485_pallas","name":"帕拉斯","en":"Pallas","kind":"operator","region":"minos","origin":"米诺斯","faction":"米诺斯","profession":"近卫","aliases":[],"title":"帕拉斯的祭司经历与秘密治疗","summary":"帕拉斯曾任米诺斯祭司，离开雅赛努斯赴阿克罗蒂村任职，带领居民反抗周边部落侵扰，并推动旅游与文化产业。矿石病加重后，她到罗德岛秘密治疗，起初信息受到保密，还有萨卡兹护卫陪同。治疗期间，她逐渐对罗德岛产生兴趣，相关接触在此后继续发展。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[],"forms":[{"id":"char_485_pallas","name":"帕拉斯"}],"source":"https://prts.wiki/w/%E5%B8%95%E6%8B%89%E6%96%AF"},{"id":"char_381_bubble","name":"泡泡","en":"Bubble","kind":"operator","region":"sargon","origin":"萨尔贡","faction":"萨尔贡","profession":"重装","aliases":[],"title":"泡泡的感染救治与预备干员训练","summary":"泡泡是萨尔贡部族勇士的女儿，野外直接接触源石后未及时清理伤口，造成感染。父亲为避免她难堪，以特训为名送她到罗德岛治疗，并登记预备干员。她通过测试，但对社交规则和巨盾实战运用仍不熟练，需要教官进一步训练以避免任务中的差错。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"勇者的试炼","intro":"在大片大片部落图腾中，一个小小的塞拉托女孩背着沉沉的盾，向前冲去。"}],"forms":[{"id":"char_381_bubble","name":"泡泡"}],"source":"https://prts.wiki/w/%E6%B3%A1%E6%B3%A1"},{"id":"char_281_popka","name":"泡普卡","en":"Popukar","kind":"operator","region":"rhodes","origin":"雷姆必拓","faction":"行动预备组A6","profession":"近卫","aliases":[],"title":"泡普卡的医疗接收与小队录用","summary":"泡普卡先以患者身份被罗德岛接收，经本人同意后接受测试，被分配到预备行动组A6，主要担任攻坚人员。矿石病带来的力量使她具备较强破坏能力，但尚不足以承担复杂工作。日常资料记有她无意闯祸的情况，也记载她态度诚恳，队友通常愿意原谅并继续照看她。","focus":"技能、工作限制与日常照护需要分别记录，不以其中一项代替全部评价。","memories":[{"title":"玩乐之间","intro":"把小干员们放在游戏室里最安全了，怎么会出事呢？"},{"title":"茧房","intro":"为了隔绝可能的伤害，为了尝试保护微小的梦与摇摇欲坠的未来，大家构筑了一座茧房。"}],"forms":[{"id":"char_281_popka","name":"泡普卡"}],"source":"https://prts.wiki/w/%E6%B3%A1%E6%99%AE%E5%8D%A1"},{"id":"char_4234_pedro","name":"佩德洛","en":"Pedro","kind":"operator","region":"bolivar","origin":"玻利瓦尔","faction":"玻利瓦尔","profession":"辅助","aliases":[],"title":"佩德洛的征召经历与情报合作","summary":"佩德洛来自玻利瓦尔，曾被多支真正玻利瓦尔人部队征召，主要担任游击队员或情报人员。大行军事件后，他离开部队，与罗德岛合作处理部分情报。档案将其经历放在当地少年兵问题中讨论，并指出外部干预受到政治与实际条件限制，未把征召经过概括为完全自主选择。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[],"forms":[{"id":"char_4234_pedro","name":"佩德洛"}],"source":"https://prts.wiki/w/%E4%BD%A9%E5%BE%B7%E6%B4%9B"},{"id":"char_4058_pepe","name":"佩佩","en":"Pepe","kind":"operator","region":"sargon","origin":"萨尔贡","faction":"萨尔贡","profession":"近卫","aliases":[],"title":"佩佩的学者身份与正式到访","summary":"佩佩是萨尔贡历史学者，也是一位帕夏的长女，现协助罗德岛当地考古勘察。正式访舰时，她带来车队、侍从、珍宝和古老文本，以隆重仪仗进入会客区域。旁观干员未能看清其面貌，只觉得声音熟悉；所给记录主要描述此次公开接待，并未展开具体研究项目。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[],"forms":[{"id":"char_4058_pepe","name":"佩佩"}],"source":"https://prts.wiki/w/%E4%BD%A9%E4%BD%A9"},{"id":"char_145_prove","name":"普罗旺斯","en":"Provence","kind":"operator","region":"siracusa","origin":"叙拉古","faction":"叙拉古","profession":"狙击","aliases":[],"title":"普罗旺斯的天灾调查与预警","summary":"普罗旺斯是天灾信使，在荒野观察自然变化，对潜在灾害作判断，并记录和预警已经发生的天灾。她具备野外生存、团队协作和精准射击经验，加入罗德岛后继续承担灾区调查及狙击任务。档案指出她清楚该职业的精神负担，仍以珍视生命为由持续工作，保持相对稳定的行动状态。","focus":"对职业动机采用档案说明，不将稳定表现推定为从未受到灾难影响。","memories":[{"title":"同事们","intro":"生命当然是宝贵的，你我同样贵重。"},{"title":"崎路前行","intro":"天灾和人祸，当这二者交织，她应该如何做？"}],"forms":[{"id":"char_145_prove","name":"普罗旺斯"}],"source":"https://prts.wiki/w/%E6%99%AE%E7%BD%97%E6%97%BA%E6%96%AF"},{"id":"char_4144_chilc","name":"齐尔查克","en":"Chilchuck","kind":"operator","region":"other","origin":"东方大陆（自称）","faction":"莱欧斯小队","profession":"先锋","aliases":[],"title":"齐尔查克的探查职责与合作","summary":"齐尔查克在莱欧斯小队中负责发现陷阱、开锁与规划路线，凭敏锐五感提高迷宫探索效率并保障队员安全。来到罗德岛后，他寻找返回原所在地的方法，同时提供地形侦察和隐患探查支援。其声称的出身地尚未得到本舰资料确认，但现有外勤合作已能体现专业能力。","focus":"出身信息按自述保留，本条不将原世界地名直接确定为泰拉区域。","memories":[],"forms":[{"id":"char_4144_chilc","name":"齐尔查克"}],"source":"https://prts.wiki/w/%E9%BD%90%E5%B0%94%E6%9F%A5%E5%85%8B"},{"id":"char_1029_yato2","name":"麒麟R夜刀","en":"Kirin R Yato","kind":"operator","region":"rhodes","origin":"东国","faction":"行动组A4","profession":"特种","aliases":[],"title":"夜刀归舰后的新装备测试","summary":"夜刀完成露华村任务并短期治疗后，返回A4组长岗位，换用艾露猫制作的新装备，承担更高难度攻坚。测试确认装备可增强机能、抵御部分冲击，作用与特殊材料有关，机制尚未完全解释。工程部也专门验证并否定了可从任意高度坠落而不受伤的传言。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[],"forms":[{"id":"char_502_nblade","name":"夜刀"},{"id":"char_1029_yato2","name":"麒麟R夜刀"}],"source":"https://prts.wiki/w/%E9%BA%92%E9%BA%9FR%E5%A4%9C%E5%88%80"},{"id":"char_478_kirara","name":"绮良","en":"Kirara","kind":"operator","region":"higashi","origin":"东国","faction":"东","profession":"特种","aliases":[],"title":"绮良的离乡求医与设备协助","summary":"绮良原是东国南部一座沿海移动城市的学生，家乡商贸较发达，远离主要冲突线。感染矿石病后，她离开故乡，向老同学寄信求助，并依宴的回信指引来到罗德岛治疗。她对电子设备较熟悉，现为范围通讯和设备检修提供帮助。材料未说明她已完成正式专业教育或全部学业。","focus":"以已知技能和求医过程为限，不把电子爱好扩大为未确认的技术资格。","memories":[{"title":"隐藏结局","intro":"“中间没有任何波折。一切顺利。”"},{"title":"无伤通关","intro":"“一切都在计划之中！”"}],"forms":[{"id":"char_478_kirara","name":"绮良"}],"source":"https://prts.wiki/w/%E7%BB%AE%E8%89%AF"},{"id":"char_4062_totter","name":"铅踝","en":"Totter","kind":"operator","region":"sargon","origin":"萨尔贡","faction":"萨尔贡","profession":"狙击","aliases":[],"title":"铅踝的佣兵经历与偶发外勤","summary":"铅踝本名托特尔，原为住在维多利亚边境深林的半隐退佣兵。为偿还人情，他离开山林前往伦蒂尼姆战场，事件后选择偶尔参加罗德岛狙击外勤。他每年驻舰时间很少，通常只为汇报和检查到访，其余时间留在林中木屋或执行任务；同行人员对其判断与经验多有认可。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[{"title":"计划","intro":"就算是一片荒芜的废墟，也会得到夕阳温情的注目。"},{"title":"归乡","intro":"没人能真正看淡世事。"}],"forms":[{"id":"char_4062_totter","name":"铅踝"}],"source":"https://prts.wiki/w/%E9%93%85%E8%B8%9D"},{"id":"char_479_sleach","name":"琴柳","en":"Saileach","kind":"operator","region":"victoria","origin":"维多利亚","faction":"维多利亚","profession":"先锋","aliases":[],"title":"琴柳的仪仗经历与高强度训练","summary":"琴柳曾在小丘郡地方部队担任仪仗执旗手，战乱后经办事处介绍成为合作干员，具备军训基础和支援能力。驻舰时她参加烹饪活动、分享日常经验，同时将大量时间用于训练。教官曾认为强度偏高，经结合本人意愿和医疗评估后计划仍继续，测试显示能力快速提升。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"一双羽兽","intro":"随着旗帜升高的，还有放飞的希望与期盼。"},{"title":"鬓旁的花","intro":"她想与大家一起等待春天，但大家却想跟随她去寻找春天。"}],"forms":[{"id":"char_479_sleach","name":"琴柳"}],"source":"https://prts.wiki/w/%E7%90%B4%E6%9F%B3"},{"id":"char_488_buildr","name":"青枳","en":"Poncirus","kind":"operator","region":"siesta","origin":"汐斯塔","faction":"汐斯塔","profession":"先锋","aliases":[],"title":"青枳的土木经历与舰内改建工作","summary":"青枳主修土木工程，曾在哥伦比亚和汐斯塔从事建筑、修缮及拆迁，经锡兰推荐在罗德岛治疗，同时兼职参与舰内改建。初来时，她误入药剂研讨现场，被当作试用志愿者，对强烈酸味表现出特别适应。她从小在哥伦比亚生活，但明确将自己认作汐斯塔人。","focus":"地域认同采用本人强调的说法，药剂插曲不替代其专业履历。","memories":[{"title":"复还的羽兽","intro":"“汐斯塔”……它是一颗未成熟的橙子。"}],"forms":[{"id":"char_488_buildr","name":"青枳"}],"source":"https://prts.wiki/w/%E9%9D%92%E6%9E%B3"},{"id":"char_149_scave","name":"清道夫","en":"Scavenger","kind":"operator","region":"rhodes","origin":"未公开","faction":"S.W.E.E.P.","profession":"先锋","aliases":[],"title":"清道夫的放逐经历与佣兵转职","summary":"清道夫感染后被原群落驱逐，独自求生，曾受委托人暗算，后来成为处理隐秘事务的地下佣兵。经中间人介绍，她放弃不稳定的佣兵工作，加入罗德岛。档案将她的独行与戒备同既往经历及源石影响联系起来，也指出当前交流仍较困难，适应本舰生活的情况需要继续观察。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[{"title":"硬币的意志","intro":"她熟悉生存的规则，除此之外的事情，她习惯闭上眼睛交给硬币去判断。"}],"forms":[{"id":"char_149_scave","name":"清道夫"}],"source":"https://prts.wiki/w/%E6%B8%85%E9%81%93%E5%A4%AB"},{"id":"char_385_finlpp","name":"清流","en":"Purestream","kind":"operator","region":"yan","origin":"炎","faction":"炎","profession":"医疗","aliases":[],"title":"清流的河道清理与污水处理","summary":"清流长期从事河道清理，具有丰富净水经验，主动联系后经评审与罗德岛签约。入职初期，部分干员未理解其环保工作的意义。她随后清理停驻地区的水道，并承担舰船排放污水的二次处理，相关工作使同事开始重新评估她在环境维护方面的专业能力。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"涓滴亦江流","intro":"若无每一滴水，便无不息的江流。"}],"forms":[{"id":"char_385_finlpp","name":"清流"}],"source":"https://prts.wiki/w/%E6%B8%85%E6%B5%81"},{"id":"char_4026_vulpis","name":"忍冬","en":"Vulpisfoglia","kind":"operator","region":"siracusa","origin":"叙拉古","faction":"叙拉古","profession":"先锋","aliases":[],"title":"忍冬的家族经历与留舰申请","summary":"忍冬本名英格丽，是铃兰的母亲，曾为叙拉古威尼斯家族核心成员，多次承担暗杀、突袭与歼灭行动，后离开家族。此前探望女儿时，她主要询问舰上防卫和外勤风险。独自提出留舰申请后，罗德岛补充调查其履历，确认她在叙拉古留下多份案件记录及尚未失效的悬赏。","focus":"母亲身份与既往行动均按资料保留，不以照顾家人取消对旧履历的记录。","memories":[],"forms":[{"id":"char_4026_vulpis","name":"忍冬"}],"source":"https://prts.wiki/w/%E5%BF%8D%E5%86%AC"},{"id":"char_363_toddi","name":"熔泉","en":"Toddifons","kind":"operator","region":"victoria","origin":"维多利亚","faction":"维多利亚","profession":"狙击","aliases":[],"title":"熔泉的学院训练与工匠任职","summary":"熔泉曾在维多利亚西尔军事学院学习，肄业且未正式服役，但接受系统训练，擅长攻城战术与相关武器制造。她加入罗德岛后兼任狙击干员和初级工匠，主要执行远程工事破坏与火力压制。初次到舰由亲属陪同，医疗接待与随行物品也被记录，但不能据此代替完整职业履历。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[{"title":"装甲与重弩","intro":"出任务也要选个合适的队友。"}],"forms":[{"id":"char_363_toddi","name":"熔泉"}],"source":"https://prts.wiki/w/%E7%86%94%E6%B3%89"},{"id":"char_4183_mortis","name":"若叶睦","en":"Wakaba Mutsumi","kind":"operator","region":"other","origin":"未知","faction":"Ave Mujica","profession":"特种","aliases":[],"title":"若叶睦的暂居工作与果蔬栽培","summary":"若叶睦是乐队吉他手，在罗德岛暂居期间主要承担简单工作，也在疗养庭院取得一小块土地栽培果蔬。她出自知名演员家庭，自幼受到关注，并从小与丰川祥子相识。档案形容她不善言辞，同时记录了她对祥子的长期支持，未进一步展开原所在地的完整经历。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[],"forms":[{"id":"char_4183_mortis","name":"若叶睦"}],"source":"https://prts.wiki/w/%E8%8B%A5%E5%8F%B6%E7%9D%A6"},{"id":"char_202_demkni","name":"塞雷娅","en":"Saria","kind":"operator","region":"columbia","origin":"哥伦比亚","faction":"莱茵生命","profession":"重装","aliases":[],"title":"塞雷娅的科研合作与技艺运用","summary":"塞雷娅曾任莱茵生命防卫科主任，具有生命科学、微生物学和源石技艺方面的研究经验，现与罗德岛在科研等领域合作。她能操作一定区域内的钙及其化合物，并结合医学知识进行防护、削弱敌人及队友协同。相关任务还包括要员保全、异常事态处置和歼灭行动。","focus":"能力范围按该档案的公开说明记录，不推导未展示的物质操控效果。","memories":[{"title":"沃土","intro":"塞雷娅会为莱茵带来新时代吗？这是悬在所有人心中的疑问。"}],"forms":[{"id":"char_202_demkni","name":"塞雷娅"}],"source":"https://prts.wiki/w/%E5%A1%9E%E9%9B%B7%E5%A8%85"},{"id":"char_4184_dolris","name":"三角初华","en":"Misumi Uika","kind":"operator","region":"other","origin":"未知","faction":"Ave Mujica","profession":"辅助","aliases":[],"title":"三角初华的乐队身份与留舰","summary":"三角初华是Ave Mujica主唱兼吉他手，也是偶像组合sumimi成员，爱好观星，常在谈话中提及祥子。来到罗德岛后，她以友善态度与干员相处，耐心学习舰上事务，并与乐队同伴共同获得信赖。现有输入主要描述公开演艺身份和适应情况，没有完整展开原有世界中的私人经历。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[],"forms":[{"id":"char_4184_dolris","name":"三角初华"}],"source":"https://prts.wiki/w/%E4%B8%89%E8%A7%92%E5%88%9D%E5%8D%8E"},{"id":"char_473_mberry","name":"桑葚","en":"Mulberry","kind":"operator","region":"yan","origin":"炎","faction":"炎","profession":"医疗","aliases":[],"title":"桑葚的救援履历与交换学习","summary":"桑葚属于炎国灾害救援组织春乾，主要在寒冷且天灾多发地区开展救援。交换项目设立后，她以笔试第一的成绩通过选拔，前往罗德岛学习紧急矿石病防护和初期治疗。她在学习之外也以临时干员身份协助医疗部，是双方这一交流计划的首位派遣人员。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"平安祈愿","intro":"她曾经觉得这份祈愿困住了自己，所以不敢回头看；但现在，她想将这份祝福与希望送给更多的人。"}],"forms":[{"id":"char_473_mberry","name":"桑葚"}],"source":"https://prts.wiki/w/%E6%A1%91%E8%91%9A"},{"id":"char_416_zumama","name":"森蚺","en":"Eunectes","kind":"operator","region":"sargon","origin":"萨尔贡","faction":"萨尔贡","profession":"重装","aliases":["祖玛玛"],"title":"森蚺的部族身份与机械作战","summary":"森蚺原名祖玛玛，是萨尔贡阿卡胡拉某部族族长，通过测试后加入罗德岛并接受治疗。她起初以本名登记，后来在同行机械被重新命名为暴躁铁皮后，改用部族名称作为代号。她对机械有浓厚兴趣，现与该机械共同执行任务；档案没有把幼年与嘉维尔的打斗计入正式战斗经验。","focus":"分别记录本名、代号及经验统计标准，不将爱好或童年打斗等同正式履历。","memories":[{"title":"密林狂想","intro":"她在纸上画出的狂野梦想究竟是什么形状，没人猜得到。"}],"forms":[{"id":"char_416_zumama","name":"森蚺"}],"source":"https://prts.wiki/w/%E6%A3%AE%E8%9A%BA"},{"id":"char_4143_sensi","name":"森西","en":"Senshi","kind":"operator","region":"other","origin":"伊兹甘达（自称）","faction":"莱欧斯小队","profession":"重装","aliases":[],"title":"森西的厨师职责与野外经验","summary":"森西属于莱欧斯小队，自称来自伊兹甘达，在队内担任厨师，具有丰富的野外生存经验。他重视饮食，负责准备健康伙食，随身携带由特殊材料制作的锅具和刀具。罗德岛尚不熟悉其所称地名，但认可其专业表现；有关迷宫冒险者的身份也暂按小队提供的信息记录。","focus":"所在地与部分身份来自本人陈述，本条不据此扩写泰拉地理。","memories":[],"forms":[{"id":"char_4143_sensi","name":"森西"}],"source":"https://prts.wiki/w/%E6%A3%AE%E8%A5%BF"},{"id":"char_4139_papyrs","name":"莎草","en":"Papyrus","kind":"operator","region":"sargon","origin":"萨尔贡","faction":"萨尔贡","profession":"医疗","aliases":[],"title":"莎草的博物馆经历与历史研究","summary":"莎草原名阿娜特，曾代理管理萨尔贡法尔贾万达巴德博物馆，变故后开始游历大地。她现与当地罗德岛办事处合作，以外勤身份为历史研究提供理论支持。驻处记录显示，她每天较早到岗，并严格按下班时间离开，作息的稳定性给同事留下了明显印象。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"玻璃窗外","intro":"空调车开不到的地方，书籍与铭文不曾记载的故事。"}],"forms":[{"id":"char_4139_papyrs","name":"莎草"}],"source":"https://prts.wiki/w/%E8%8E%8E%E8%8D%89"},{"id":"char_264_f12yin","name":"山","en":"Mountain","kind":"operator","region":"columbia","origin":"哥伦比亚","faction":"哥伦比亚","profession":"近卫","aliases":[],"title":"山的入狱背景与近卫任职","summary":"山是哥伦比亚一家大型建筑企业负责人的儿子，家庭遭竞争对手陷害而入狱，离开监狱后加入罗德岛，现任近卫干员，参与前线任务。他体格高大，日常待人礼貌，入舰初期因这种差异受到关注。档案还记载他熟悉上层社会事务，承认富裕出身，但较少主动以此谈论或自夸。","focus":"采用已经公开的家庭与任职资料，不扩写陷害事件的完整证据和后续处理。","memories":[{"title":"意外的烦恼","intro":"有时候，烦恼往往来自一些细微的角落。"},{"title":"赴罪","intro":"虽感彷徨，仍要握紧双拳，面对漫漫长路。"}],"forms":[{"id":"char_264_f12yin","name":"山"}],"source":"https://prts.wiki/w/%E5%B1%B1"},{"id":"char_4235_thumpy","name":"珊比","en":"Thumpy","kind":"operator","region":"rim","origin":"雷姆必拓","faction":"雷姆必拓","profession":"重装","aliases":[],"title":"珊比的治疗经过与重装任职","summary":"珊比来自雷姆必拓大涌泉镇，为治疗矿石病来到罗德岛，经安洁莉娜推荐并依本人意愿，加入外勤部担任重装。入职体检中，她显示出突出的听觉能力，能够辨认很轻的语声，在方向及频率分辨上也受到注意。现有材料主要涵盖来舰、推荐和测评，未完整说明更早生活。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[],"forms":[{"id":"char_4235_thumpy","name":"珊比"}],"source":"https://prts.wiki/w/%E7%8F%8A%E6%AF%94"},{"id":"char_457_blitz","name":"闪击","en":"Blitz","kind":"operator","region":"other","origin":"未知","faction":"彩虹小队","profession":"重装","aliases":[],"title":"闪击的近战评估与语言适应","summary":"闪击是彩虹小队成员，瞭望塔事件后登记为罗德岛合作人员，擅长室内及街巷近战，使用手枪和闪光护盾。多次模拟测试得到较高评分，他也在短期内掌握当地交流所需的语言细节。罗德岛未追查小队缺失的旧记录，双方没有长期合同，任务邀请须考虑合作性质。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"团队坚盾","intro":"他偶尔也会在冲刺时把队友甩得很远。"}],"forms":[{"id":"char_457_blitz","name":"闪击"}],"source":"https://prts.wiki/w/%E9%97%AA%E5%87%BB"},{"id":"char_147_shining","name":"闪灵","en":"Shining","kind":"operator","region":"kazdel","origin":"卡兹戴尔","faction":"使徒","profession":"医疗","aliases":[],"title":"闪灵的医疗组织经历与理论贡献","summary":"闪灵是萨卡兹医师，曾属于赦罪师，后成为感染者援助团体使徒的一员。她为罗德岛提供医疗源石技艺理论，也参加战地救护。她说明相关方法源于与同僚缓解感染者病痛的研究。报告记录这些技艺既能治疗伤害，也可形成一定防护，但具体原理仍有待进一步研究。","focus":"区分已观察到的效果与尚未明确的机制，不将防护能力写成无限庇护。","memories":[{"title":"雨夜","intro":"暴雨将停，天也该亮了。"}],"forms":[{"id":"char_147_shining","name":"闪灵"}],"source":"https://prts.wiki/w/%E9%97%AA%E7%81%B5"},{"id":"char_150_snakek","name":"蛇屠箱","en":"Cuora","kind":"operator","region":"columbia","origin":"未公开","faction":"哥伦比亚","profession":"重装","aliases":[],"title":"蛇屠箱的任职登记与防守能力","summary":"蛇屠箱身份与出身不明，部分记忆及履历缺失。成为罗德岛干员时，她学习正确书写代号，认真签署任职合同；在强对抗测试中展现出较高防守能力，现以重装身份参与行动。档案描述她性格天真开朗，患矿石病后仍保持这一表现，但未据此补全遗失的过去。","focus":"失忆与履历缺项按当前记录处理，不由性格或代号推断身世。","memories":[{"title":"夺包奇遇","intro":"都怪我，只是因为踩到了我的背包，我就和她发了脾气……"}],"forms":[{"id":"char_150_snakek","name":"蛇屠箱"}],"source":"https://prts.wiki/w/%E8%9B%87%E5%B1%A0%E7%AE%B1"},{"id":"char_379_sesa","name":"慑砂","en":"Sesa","kind":"operator","region":"sargon","origin":"萨尔贡","faction":"萨尔贡","profession":"狙击","aliases":[],"title":"慑砂的武器调整与求职记录","summary":"慑砂来自萨尔贡，曾替非法武器交易所调整装备，工作接触中得知罗德岛，随后主动求职。他提交的履历较含糊，常以玄妙词语解释技术。工程检查确认，他对发射器进行了精密改装，使施术能力较弱者也能发挥主要威力，相关工程才能得到明确认可。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"致命诱惑","intro":"这一次，或许是慑砂找寻真相的难得机会，抑或是一个精心设置的陷阱。"}],"forms":[{"id":"char_379_sesa","name":"慑砂"}],"source":"https://prts.wiki/w/%E6%85%91%E7%A0%82"},{"id":"char_469_indigo","name":"深靛","en":"Indigo","kind":"operator","region":"iberia","origin":"伊比利亚","faction":"伊比利亚","profession":"术师","aliases":[],"title":"深靛的灯塔经历与法杖研究","summary":"深靛曾是伊比利亚海滨灯塔的见习看守，游历中认识蓝毒与格劳克斯，后经蓝毒介绍加入罗德岛。研究发现其光类技艺具有特殊波形，法杖顶端单元也有较高供能潜力。她本人仅知道法杖由离乡时的老师交付，并不掌握完整来历；现有研究因此尚未得到全部所需信息。","focus":"分别呈现仪器结果、研究者推测和本人所知，不把未知部分写成定论。","memories":[{"title":"硬核饮品","intro":"把它一饮而尽需要的不是酒量，而是一颗为朋友着想的心。"}],"forms":[{"id":"char_469_indigo","name":"深靛"}],"source":"https://prts.wiki/w/%E6%B7%B1%E9%9D%9B"},{"id":"char_110_deepcl","name":"深海色","en":"Deepcolor","kind":"operator","region":"aegir","origin":"未公开","faction":"阿戈尔","profession":"辅助","aliases":[],"title":"深海色的任职与背景记录","summary":"深海色的客观履历标注出身不明、资料缺失，确认她在源石技艺、法术支援与协同方面具有能力，现任罗德岛特种行动干员。局部档案另述艺术家庭、父亲任教和学习绘画的经历。两类记录并未在输入中得到完整核实，应保留其信息层次，不能直接视为已确定的家庭史。","focus":"总体履历与局部背景叙述存在张力，本条不选择一方作为最终结论。","memories":[{"title":"幽蓝怀想","intro":"那是她自己的蓝色。"},{"title":"蓝调","intro":"顺着河流一直走，一直走，到溪流的尽头。"}],"forms":[{"id":"char_110_deepcl","name":"深海色"}],"source":"https://prts.wiki/w/%E6%B7%B1%E6%B5%B7%E8%89%B2"},{"id":"char_4109_baslin","name":"深律","en":"Bassline","kind":"operator","region":"leithanien","origin":"莱塔尼亚","faction":"莱塔尼亚","profession":"重装","aliases":[],"title":"深律的宫廷礼仪官与联络工作","summary":"深律于一一〇〇年秋担任莱塔尼亚双塔宫廷礼仪官，与罗德岛签约，负责双方沟通。来访时，他带着低音号及正式公函。人事评测认为他平日安静，交谈礼貌、知识广博，面对不熟悉的问题愿意请教；同时，他仍表现出一定警惕，个人资料需与公共任职区分阅读。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"晚霞下的演奏","intro":"曲意逢迎的号声，不如孤注一掷的坦诚。"}],"forms":[{"id":"char_4109_baslin","name":"深律"}],"source":"https://prts.wiki/w/%E6%B7%B1%E5%BE%8B"},{"id":"char_4137_udflow","name":"深巡","en":"Underflow","kind":"operator","region":"aegir","origin":"阿戈尔","faction":"阿戈尔","profession":"重装","aliases":[],"title":"深巡的研究履历与对陆接洽职责","summary":"深巡本名西昆妲，曾任深海猎人计划研究员，后进入阿戈尔军团系统，担任海巡队指挥官。阿戈尔向陆上诸国发出合作邀请后，她以对陆接洽代表身份与罗德岛签订协议，并以罗德岛为渠道开展诸国交流。该档案只提供有限的公务接触片段，没有具体列出所有谈判内容和结果。","focus":"以公开职务和合作安排为范围，不从有限会谈片段推导整体外交政策。","memories":[{"title":"X103号模块","intro":"连她自己都没有意识到，她可能只是想再听一遍那首歌。"}],"forms":[{"id":"char_4137_udflow","name":"深巡"}],"source":"https://prts.wiki/w/%E6%B7%B1%E5%B7%A1"},{"id":"char_1046_sbell2","name":"圣聆初雪","en":"Pramanix the Prerita","kind":"operator","region":"kjerag","origin":"谢拉格","faction":"谢拉格","profession":"术师","aliases":[],"title":"圣聆初雪的教育与圣女职责","summary":"初雪在此阶段继续担任喀兰圣女及谢拉格宗教领袖，参与当地发展与变革，并着手建设境内基础教育系统。部分情报报告称，她曾在谢拉格驱散一场即将降临的天灾。输入以现任职责和相关报告为主，未提供整套教育制度的实施细节，也未逐项确认该事件的全部过程。","focus":"本条采用异格时点，天灾事项按部分报告记述，不提升为完整核实结论。","memories":[],"forms":[{"id":"char_174_slbell","name":"初雪"},{"id":"char_1046_sbell2","name":"圣聆初雪"}],"source":"https://prts.wiki/w/%E5%9C%A3%E8%81%86%E5%88%9D%E9%9B%AA"},{"id":"char_1032_excu2","name":"圣约送葬人","en":"Executor the Ex Foedere","kind":"operator","region":"laterano","origin":"拉特兰","faction":"拉特兰","profession":"近卫","aliases":[],"title":"送葬人受封后的公证所职责","summary":"送葬人获教宗亲授圣徒称号后，仍隶属拉特兰公证所，继续接受任务派遣，执行公民权益相关事务，并依合约服务罗德岛。官方没有限制双方接触，合作逐渐密切。所给档案指出，外观已有明显变化，但新增头衔尚未对其常规工作造成根本影响。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"蓝色","intro":"天空倒映在他的眼中。"}],"forms":[{"id":"char_279_excu","name":"送葬人"},{"id":"char_1032_excu2","name":"圣约送葬人"}],"source":"https://prts.wiki/w/%E5%9C%A3%E7%BA%A6%E9%80%81%E8%91%AC%E4%BA%BA"},{"id":"char_308_swire","name":"诗怀雅","en":"Swire","kind":"operator","region":"lungmen","origin":"龙门","faction":"龙门近卫局","profession":"近卫","aliases":[],"title":"诗怀雅的高级警司与指挥职责","summary":"该早期阶段的诗怀雅任龙门近卫局高级警司，作为特别合作人员协助罗德岛，并提供现场战术指挥。她的源石技艺运用有限，主要能远程操作无人机。记录举例说明，在无人机上安装扩音器后，她可将指令传达给龙门警员。此处未涉及后续局长职务或其他时期的合作方式。","focus":"明确采用高级警司时点，不将后续升迁提前加入基础形态的任职说明。","memories":[{"title":"就任前夕","intro":"家庭是人类永恒的母题。幼童总会以为家庭就是人生的全部，但决定他们人生的一切，若是砸向这片大地，或许也只能激起微不足道的涟漪。"}],"forms":[{"id":"char_308_swire","name":"诗怀雅"},{"id":"char_1033_swire2","name":"琳琅诗怀雅"}],"source":"https://prts.wiki/w/%E8%AF%97%E6%80%80%E9%9B%85"},{"id":"char_215_mantic","name":"狮蝎","en":"Manticore","kind":"operator","region":"sargon","origin":"萨尔贡","faction":"萨尔贡","profession":"特种","aliases":[],"title":"狮蝎的特殊行动与交流记录","summary":"狮蝎过往大部分履历缺失，已知曾从事指定目标清除，档案据此推测她有杀手背景。她在潜伏、侵扰及突袭中技巧熟练，现为罗德岛提供特别行动服务。日常相处时，她温柔腼腆，说话常有停顿和试探，与他人交流仍显生硬；这些表现应与其战斗能力分别记录。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[{"title":"缄默","intro":"她战战兢兢，甚至害怕自己说话的声音。"}],"forms":[{"id":"char_215_mantic","name":"狮蝎"}],"source":"https://prts.wiki/w/%E7%8B%AE%E8%9D%8E"},{"id":"char_378_asbest","name":"石棉","en":"Asbestos","kind":"operator","region":"rim","origin":"雷姆必拓","faction":"雷姆必拓","profession":"重装","aliases":[],"title":"石棉的探险合作与改装盾牌","summary":"石棉原是雷姆必拓探险家，经麦哲伦介绍到罗德岛治疗，与组织协商后签约。她接受专业训练，使用亲手改造的大盾在前线保护同伴，多数时间仍在外探险。档案认为她言语和态度不友善，但实际成熟、有能力，驻舰期间较少出现在公共场合。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"奇景","intro":"阿达克利斯人喜欢外乡人！"}],"forms":[{"id":"char_378_asbest","name":"石棉"}],"source":"https://prts.wiki/w/%E7%9F%B3%E6%A3%89"},{"id":"char_4063_quartz","name":"石英","en":"Quartz","kind":"operator","region":"columbia","origin":"哥伦比亚","faction":"哥伦比亚","profession":"近卫","aliases":[],"title":"石英的佣兵工作与巨剑测试","summary":"石英是哥伦比亚佣兵，通过罗德岛测试时，巨剑操作尚不熟练，也曾险些误击裁判。她为此道歉，但拒绝改练其他武器。评估认为，她能在复杂战场灵活调整方案，仍可成为可靠队员。观察者推测大型武器可能有减少冲突的威慑用途，但这并不是经本人确认的唯一选择原因。","focus":"区分实际测试表现与评估者推测，不把佣兵职业普遍化为传奇或犯罪。","memories":[{"title":"无需遗憾","intro":" 对不起……我别无选择。"}],"forms":[{"id":"char_4063_quartz","name":"石英"}],"source":"https://prts.wiki/w/%E7%9F%B3%E8%8B%B1"},{"id":"char_4236_tmslot","name":"时隙","en":"Timeslot","kind":"operator","region":"rim","origin":"雷姆必拓","faction":"雷姆必拓","profession":"术师","aliases":[],"title":"时隙的通讯研究与工程部任职","summary":"时隙是通讯技术工程师，其研究已用于雷姆必拓远程系统。加入罗德岛后，她为基地远程通讯提供技术支持。初入工程部时，她较为拘谨，常询问是否需要为领导准备咖啡或整理文件，得知不必后仍不安心。档案将这一适应过程与既有专业成果分别记述，并未否定其技术能力。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[{"title":"嗝尽所能","intro":"领教一下平时很软弱的人爆发时的厉害吧！"}],"forms":[{"id":"char_4236_tmslot","name":"时隙"}],"source":"https://prts.wiki/w/%E6%97%B6%E9%9A%99"},{"id":"char_489_serum","name":"蚀清","en":"Corroserum","kind":"operator","region":"columbia","origin":"哥伦比亚","faction":"哥伦比亚","profession":"术师","aliases":[],"title":"蚀清的研发辅助与产品外派","summary":"蚀清在雷神工业实验原型工程部担任项目经理助理，主要参与研发流程和技术辅助，后申请外派到罗德岛测试产品。他能快速完成指标，通常不会主动扩展职责，完成后便休息。记录明确指出，工作量并不少，他的休息状态不应被误认为任务未完成或能力不足。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"蚀清的工牌","intro":"梦想、激情、理想、意志都是不耐腐蚀的材料，所以请各位在工作中注意自身的防护，谢谢。"}],"forms":[{"id":"char_489_serum","name":"蚀清"}],"source":"https://prts.wiki/w/%E8%9A%80%E6%B8%85"},{"id":"char_241_panda","name":"食铁兽","en":"FEater","kind":"operator","region":"lungmen","origin":"炎","faction":"炎-龙门","profession":"特种","aliases":[],"title":"食铁兽的武术训练与演艺中断","summary":"食铁兽曾是炎国武打电影演员，在进入演艺行业前已接受多年武术训练，传承铁意六合拳，熟悉相关招式。矿石病迫使她停止电影拍摄，来到罗德岛后曾经历目标调整。档案确认她后来形成新的方向，但本段未详细说明这一过程，也未完整列出此前参与的影片及训练经历。","focus":"把已知职业转折与未展开的后续分开，不以概述替代具体活动剧情。","memories":[{"title":"一落千丈","intro":"再坚韧的劲竹，只要长在悬崖旁，也会恐惧风的无常。"}],"forms":[{"id":"char_241_panda","name":"食铁兽"}],"source":"https://prts.wiki/w/%E9%A3%9F%E9%93%81%E5%85%BD"},{"id":"char_210_stward","name":"史都华德","en":"Steward","kind":"operator","region":"rhodes","origin":"谢拉格","faction":"行动预备组A4","profession":"术师","aliases":[],"title":"史都华德的早年学习与入职","summary":"史都华德出生于谢拉格南部，幼年表现沉稳，并显露源石法术天赋。当地环境和学习费用限制了早期发展。后来他通过罗德岛多项测试，加入行动预备组A4，在法术支援、路线确认等项目中表现出潜力。现有材料主要涵盖成长条件和预备组任职，未展开完整后续生涯。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[],"forms":[{"id":"char_210_stward","name":"史都华德"}],"source":"https://prts.wiki/w/%E5%8F%B2%E9%83%BD%E5%8D%8E%E5%BE%B7"},{"id":"char_350_surtr","name":"史尔特尔","en":"Surtr","kind":"operator","region":"rhodes","origin":"不明","faction":"罗德岛","profession":"近卫","aliases":[],"title":"史尔特尔的接收经过与治疗","summary":"史尔特尔在乌萨斯附近灾后小镇被勘探队发现，当时独自在损坏房屋休息。队伍担心后续灾害将她带回，后来确认她只是途经当地落脚。她在罗德岛接受缺失性记忆问题的治疗，并因测试中表现出的强大战斗能力成为干员，病因和能力来由尚不明确。","focus":"发现地点只代表当次相遇，不能作为出生地、失忆原因或能力来源的证据。","memories":[],"forms":[{"id":"char_350_surtr","name":"史尔特尔"}],"source":"https://prts.wiki/w/%E5%8F%B2%E5%B0%94%E7%89%B9%E5%B0%94"},{"id":"char_1502_crosly","name":"弑君者","en":"Crownslayer","kind":"operator","region":"rhodes","origin":"乌萨斯","faction":"罗德岛","profession":"特种","aliases":[],"title":"弑君者的脱离组织与监督治疗","summary":"弑君者本名柳德米拉，曾为整合运动干部，擅长潜伏、暗杀及突袭。龙门事件后她离开组织，于1100年末主动接触罗德岛，现接受监督治疗。抵达时，她与精神状态异常的红一同出现，起初被制服；后续检查判断红的异常并非由她造成，并认为她曾对红提供援助。","focus":"既往敌对与到舰时的新情况分别核实，不因任一方面预设全部结论。","memories":[{"title":"欲摘其冠","intro":"柳德米拉，你打算回去干什么？"}],"forms":[{"id":"char_1502_crosly","name":"弑君者"}],"source":"https://prts.wiki/w/%E5%BC%91%E5%90%9B%E8%80%85"},{"id":"char_158_milu","name":"守林人","en":"Firewatch","kind":"operator","region":"rhodes","origin":"未公开","faction":"罗德岛","profession":"狙击","aliases":[],"title":"守林人的边境作战与狙击职责","summary":"守林人出身不明，曾在卡西米尔与乌萨斯边境作战多年，档案推测其有游击队背景。她熟悉伏击、狙击及流动作战，现于罗德岛狙击小组提供火力援护。记录描述她稳定、专注、果决，复仇是其重要目标；同时也指出，她会对目标之外的事物流露感情，不能仅以杀手形象概括。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[{"title":"在路上","intro":"活下来的人走在复仇的路上。"}],"forms":[{"id":"char_158_milu","name":"守林人"}],"source":"https://prts.wiki/w/%E5%AE%88%E6%9E%97%E4%BA%BA"},{"id":"char_2025_shu","name":"黍","en":"Shu","kind":"operator","region":"yan","origin":"炎","faction":"炎-岁","profession":"重装","aliases":[],"title":"黍的农业研究与探亲留舰","summary":"黍是炎国农业天师和授业天师，在大荒城长期开展农业研究，已有多项成果，因探亲暂以访客身份留舰。她对年和夕的饮食、活动习惯提出要求，也为其他干员解答问题、听取烦恼。第一档案主要记录这些日常接触，没有在此展开农业项目的完整技术内容。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"谓我何求","intro":"“她为什么一直留在这儿呢？她到底在追寻什么呢？”"}],"forms":[{"id":"char_2025_shu","name":"黍"}],"source":"https://prts.wiki/w/%E9%BB%8D"},{"id":"char_4124_iana","name":"双月","en":"Iana","kind":"operator","region":"other","origin":"未知","faction":"彩虹小队","profession":"特种","aliases":[],"title":"双月的彩虹小队身份与装置运用","summary":"双月本名妮科，是彩虹小队成员，亲历克里斯达尔事件，事后登记为罗德岛合作人员。她使用能生成外形一致全息投影的装置，进行情报收集与战术欺骗。测评确认其战术素养和情报敏感度，但此前履历仍有空白。该小队没有与罗德岛签订长期合同，任务邀请受到相应限制。","focus":"仅采用联动档案和当前合作状态，不以外部作品经历补全未披露履历。","memories":[{"title":"探求明天","intro":"她已经猜到了答案，但她还是要找到盒子，将它打开。"}],"forms":[{"id":"char_4124_iana","name":"双月"}],"source":"https://prts.wiki/w/%E5%8F%8C%E6%9C%88"},{"id":"char_458_rfrost","name":"霜华","en":"Frost","kind":"operator","region":"other","origin":"未知","faction":"彩虹小队","profession":"特种","aliases":[],"title":"霜华的合作登记与野外专长","summary":"霜华本名蒂娜，是彩虹小队成员，在瞭望塔33号事件后登记为罗德岛合作人员。她擅长野外战斗，除枪械外，还以机械夹板布设障碍，为小队提供战术支援。队员对原有经历公开较少，罗德岛尊重合作方的信息保留；现有档案能够确认的主要是事件接触与实战专长。","focus":"本条依据联动后合作档案，不补写合作方未公开的原有经历。","memories":[{"title":"寻乡","intro":"在拒斥经验法则的地方，也许隐喻更能让人触及现实。"}],"forms":[{"id":"char_458_rfrost","name":"霜华"}],"source":"https://prts.wiki/w/%E9%9C%9C%E5%8D%8E"},{"id":"char_193_frostl","name":"霜叶","en":"Frostleaf","kind":"operator","region":"rhodes","origin":"哥伦比亚","faction":"罗德岛","profession":"近卫","aliases":[],"title":"霜叶的少年兵经历与佣兵转任","summary":"霜叶曾是哥伦比亚少年兵，所属部队覆灭后离开军旅，在佣兵生活中逐步与罗德岛建立合作并正式加入。她具有丰富战场经验和成熟技巧，列为优秀战力。日常中，她较少参与人群活动，喜欢在安静角落听音乐，所给记录未具体说明原部队覆灭的过程。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"识字本","intro":"“新生活”对于一名流浪雇佣兵来说，究竟是什么呢？"}],"forms":[{"id":"char_193_frostl","name":"霜叶"}],"source":"https://prts.wiki/w/%E9%9C%9C%E5%8F%B6"},{"id":"char_4177_brigid","name":"水灯心","en":"Brigid","kind":"operator","region":"victoria","origin":"维多利亚","faction":"塔拉","profession":"狙击","aliases":[],"title":"水灯心的游牧与预警传信工作","summary":"水灯心本名布莉吉，来自维多利亚南部的塔拉游牧部族，成年后离开部族独自活动。当地冲突期间，她持续从事游牧、天灾预警和信件传递，具有野外生存及长途行动经验。经苇草推荐，她与罗德岛合作，在接受矿石病治疗的同时，以狙击干员身份协助作战。","focus":"身份来源按本人及档案陈述记录，不将一支部族的生活方式代表全部塔拉。","memories":[{"title":"临行日","intro":"我知道，她只是做出了选择。"}],"forms":[{"id":"char_4177_brigid","name":"水灯心"}],"source":"https://prts.wiki/w/%E6%B0%B4%E7%81%AF%E5%BF%83"},{"id":"char_437_mizuki","name":"水月","en":"Mizuki","kind":"operator","region":"higashi","origin":"东国","faction":"东","profession":"特种","aliases":[],"title":"水月的接触留舰与文职工作","summary":"水月在多索雷斯与罗德岛干员接触，随行至本舰后，通过初步问询获准暂留，后来经调查评估长期留舰。他学习能力较好，能够协助部分文职工作。关于幼年经历，他自述东国海岸村庄遭逃兵摧毁，后获旅人救助；这一身世叙述应与罗德岛已经核实的任职情况分别处理。","focus":"幼年经历包含本人自述，本条不将全部细节视为已独立核实。","memories":[{"title":"第五类接触","intro":"事在人为，你是否已经准备好承担因你与他而起的所有责任与后果。"}],"forms":[{"id":"char_437_mizuki","name":"水月"}],"source":"https://prts.wiki/w/%E6%B0%B4%E6%9C%88"},{"id":"char_1043_leizi2","name":"司霆惊蛰","en":"Leizi the Thunderbringer","kind":"operator","region":"yan","origin":"炎","faction":"炎","profession":"近卫","aliases":[],"title":"惊蛰辞官后的雷法研修记录","summary":"麟青砚已辞去炎国大理寺少卿职务，回天师府研修雷法，游历途中暂居罗德岛并参加部分外勤。旧搜查协议已经终止，驻舰期间她规律训练、阅读，任务完成度较高。记录认为身份变化与其多年追查的案件有关，但没有展开完整经过，罗德岛也未进一步过问私人事项。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[],"forms":[{"id":"char_306_leizi","name":"惊蛰"},{"id":"char_1043_leizi2","name":"司霆惊蛰"}],"source":"https://prts.wiki/w/%E5%8F%B8%E9%9C%86%E6%83%8A%E8%9B%B0"},{"id":"char_263_skadi","name":"斯卡蒂","en":"Skadi","kind":"operator","region":"aegir","origin":"阿戈尔","faction":"深海猎人","profession":"近卫","aliases":[],"title":"斯卡蒂的赏金与单兵任务记录","summary":"斯卡蒂以赏金猎人身份受雇于罗德岛，在攻坚、歼灭及大型生物应对方面具有较强实力，现参加攻坚小队，也预备执行单兵任务。成为猎人前的履历在此缺失。早期观察记载她常独自行动、减少社交，使队友难以配合并产生传闻；阿米娅曾禁止相关传播，但未能完全消除。","focus":"本篇使用早期基础档案，不将干员间传闻视为对个人背景的正式说明。","memories":[{"title":"不见尽头的旅途","intro":"她一直以为，自己是最后的深海猎人。"}],"forms":[{"id":"char_263_skadi","name":"斯卡蒂"},{"id":"char_1012_skadi2","name":"浊心斯卡蒂"}],"source":"https://prts.wiki/w/%E6%96%AF%E5%8D%A1%E8%92%82"},{"id":"char_450_necras","name":"死芒","en":"Necrass","kind":"operator","region":"victoria","origin":"维多利亚","faction":"塔拉","profession":"术师","aliases":[],"title":"死芒的组织履历与有条件合作","summary":"死芒本名爱布拉娜·都柏林，曾任深池领袖，该组织在此阶段已不复存在。罗德岛经谨慎权衡，同意与她建立一定程度的合作，相关档案转入高权限资料库。输入还收录沃里克伯爵残缺日记中的早期评价，属于旁人记录，不能替代她本人各阶段的完整经历。","focus":"本条限定死芒阶段，合作条件与日记中的他人评价分别说明。","memories":[],"forms":[{"id":"char_450_necras","name":"死芒"}],"source":"https://prts.wiki/w/%E6%AD%BB%E8%8A%92"},{"id":"char_365_aprl","name":"四月","en":"April","kind":"operator","region":"rim","origin":"雷姆必拓","faction":"雷姆必拓","profession":"狙击","aliases":[],"title":"四月的失业经历与狙击培训","summary":"四月原是雷姆必拓猎人，感染矿石病后失业，辗转加入罗德岛。她未接受过专业军事训练，但过往狩猎经历使其较快适应狙击课程，现参加各类任务。第一档案记录，她日常性格外向，常携带随身听，关注生活品质与潮流，也会与其他干员交流相关话题。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"猎人的视线","intro":"他人是厌恶或喜欢，她最终选择不询问。"}],"forms":[{"id":"char_365_aprl","name":"四月"}],"source":"https://prts.wiki/w/%E5%9B%9B%E6%9C%88"},{"id":"char_440_pinecn","name":"松果","en":"Pinecone","kind":"operator","region":"columbia","origin":"哥伦比亚","faction":"哥伦比亚","profession":"狙击","aliases":[],"title":"松果的建筑经历与工程助手工作","summary":"松果来自哥伦比亚工人家庭，父母曾参加拓荒活动，后来在一座偏远小镇养育她。她从事建筑工作，卷入曼斯菲尔德事件后随山来到罗德岛求职。因具有相关劳动经验，她被安排为工程部部分干员提供助手服务。档案对童年居住环境有所记述，尚未列出所有工作项目。","focus":"依据已有家庭背景和岗位记录叙述，不扩写拓荒及监狱事件中的具体行动。","memories":[{"title":"展信好","intro":"工人总是怀着美好的愿景，无论是在移动城市里还是罗德岛上。"},{"title":"从头来过","intro":"我们回首来路，是为了知晓自己未来能做到什么。"}],"forms":[{"id":"char_440_pinecn","name":"松果"}],"source":"https://prts.wiki/w/%E6%9D%BE%E6%9E%9C"},{"id":"char_4199_makiri","name":"松桐","en":"Matsukiri","kind":"operator","region":"higashi","origin":"东国","faction":"东","profession":"先锋","aliases":[],"title":"松桐的情报业务与先锋任职","summary":"松桐本名森内彻，经营酒吧与关东煮摊，也是锻冶町周边情报交易的重要人物，熟悉东国信息流通。他主动联系罗德岛，提出情报和业务合作，并依本人意愿成为先锋。测试显示其冲锋、负重与短距爆发均达标准，虽然不喜肉搏，实际身体表现仍优于部分常规基准。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[{"title":"新茉莉酒馆","intro":"这样蛮不讲理任酸甜交织、回味中又带着绵密与苦涩的酒，真的能当作招牌吗？"}],"forms":[{"id":"char_4199_makiri","name":"松桐"}],"source":"https://prts.wiki/w/%E6%9D%BE%E6%A1%90"},{"id":"char_279_excu","name":"送葬人","en":"Executor","kind":"operator","region":"laterano","origin":"拉特兰","faction":"拉特兰","profession":"狙击","aliases":[],"title":"送葬人的公证所执行者任职","summary":"送葬人是拉特兰公证所专业执行者，通晓多种语言和法律体系，依合约参与罗德岛相关任务。他所代表的机构既督促公民履行法定义务，也提供权益维护，事务涉及遗产、监护和契约执行等。执行者被派往不同城邦，监督处理过程，确保相关事项实际落实。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"送葬人","intro":"他刚刚申请了一笔经费，用于购买一百个冰淇淋球。"},{"title":"敌人","intro":"他的头脑绝对理性，他的心灵真诚而坦荡。"}],"forms":[{"id":"char_279_excu","name":"送葬人"},{"id":"char_1032_excu2","name":"圣约送葬人"}],"source":"https://prts.wiki/w/%E9%80%81%E8%91%AC%E4%BA%BA"},{"id":"char_298_susuro","name":"苏苏洛","en":"Sussurro","kind":"operator","region":"rhodes","origin":"叙拉古","faction":"罗德岛","profession":"医疗","aliases":[],"title":"苏苏洛的医学教育与医疗任职","summary":"苏苏洛出生于叙拉古普通市民家庭，父母在当地公职机构工作。她选择医学专业时，主要考虑行业前景与就业，并非出于预先确立的宏大目标。毕业于帕勒莫市立医科学院后，她正式加入罗德岛，具备基础医疗知识，现承担总部后勤体系中的诊疗与救护工作。","focus":"求学动机采用本人履历中的说明，不用职业理想的强弱评价其专业水平。","memories":[{"title":"专业医师","intro":"苏苏洛经常因为外貌被人误解，但是她确实是一位专业医师。"}],"forms":[{"id":"char_298_susuro","name":"苏苏洛"}],"source":"https://prts.wiki/w/%E8%8B%8F%E8%8B%8F%E6%B4%9B"},{"id":"char_245_cello","name":"塑心","en":"Virtuosa","kind":"operator","region":"laterano","origin":"拉特兰","faction":"拉特兰","profession":"辅助","aliases":[],"title":"塑心的音乐履历与监管留舰","summary":"塑心本名阿尔图罗·吉亚洛，出身拉特兰，是活跃于泰拉的著名音乐家。受莱塔尼亚宫廷和拉特兰教皇厅委托，罗德岛与双方签约，允许她暂留本舰并提供干员服务，须由相应人员严格监管。现有输入主要确认艺术身份、留舰程序和约束，没有公开评议项目的全部内容。","focus":"本条依据受监管阶段记录，不能由留舰许可推定此前争议已经解决。","memories":[{"title":"天空与流云","intro":"见你所见，见我所见。"}],"forms":[{"id":"char_245_cello","name":"塑心"}],"source":"https://prts.wiki/w/%E5%A1%91%E5%BF%83"},{"id":"char_1047_halo2","name":"溯光星源","en":"Astgenne the Lightchaser","kind":"operator","region":"columbia","origin":"哥伦比亚","faction":"莱茵生命","profession":"辅助","aliases":[],"title":"星源的谢拉格观测站任职","summary":"星源原名埃琳娜·乌比卡，是莱茵生命能量科研究员，目前担任谢拉格观测站能量组长，也是当地天灾事件主要调查者之一。第一档案回溯其外派期间的生活，记载她有较多独处时间；相较此前持续的实验室工作，罗德岛时期的排期让她获得较长休整。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"谢拉格假期","intro":"“未知则令人感到更深邃的美。”"}],"forms":[{"id":"char_135_halo","name":"星源"},{"id":"char_1047_halo2","name":"溯光星源"}],"source":"https://prts.wiki/w/%E6%BA%AF%E5%85%89%E6%98%9F%E6%BA%90"},{"id":"char_366_acdrop","name":"酸糖","en":"Aciddrop","kind":"operator","region":"columbia","origin":"哥伦比亚","faction":"哥伦比亚","profession":"狙击","aliases":[],"title":"酸糖的街头活动与感染经过","summary":"酸糖来自哥伦比亚工人家庭，父母为卡车司机，经常不在家。她较早参加街头活动，练习滑板，多次在当地比赛中获奖，也与街头艺术人员交往。一次蓄意斗殴导致她接触源石粉尘并感染，随后到罗德岛求医。治疗检查推迟了骑行计划，但她仍持续关注原有兴趣与旅程。","focus":"感染经过按档案概述处理，不推断袭击者身份、完整动机或后续案件结果。","memories":[{"title":"一面墙","intro":"他们把土壤里自发生长出来的东西采摘、切碎、研磨、稀释，直到看不出一点原来的影子，然后用那玩意儿刷墙。"}],"forms":[{"id":"char_366_acdrop","name":"酸糖"}],"source":"https://prts.wiki/w/%E9%85%B8%E7%B3%96"},{"id":"char_415_flint","name":"燧石","en":"Flint","kind":"operator","region":"sargon","origin":"萨尔贡","faction":"萨尔贡","profession":"近卫","aliases":[],"title":"燧石的部族经验与近卫考核","summary":"燧石是萨尔贡部族战士，自年幼起累积格斗经验，擅长快速、精准的拳击。经精英干员推荐，她通过测试加入罗德岛近卫队伍，后来经常在训练室与人切磋。档案记录其适应过程中较强的挑战倾向，也说明本舰此前已有多种性格鲜明的战斗人员，相关行为并非孤立现象。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[{"title":"合格的战士","intro":"若拳头还不够大，就必须掌握其他解决问题的手段。"}],"forms":[{"id":"char_415_flint","name":"燧石"}],"source":"https://prts.wiki/w/%E7%87%A7%E7%9F%B3"},{"id":"char_4247_oxi","name":"塔露拉","en":"Talulah","kind":"operator","region":"ursus","origin":"乌萨斯","faction":"乌萨斯","profession":"近卫","aliases":[],"title":"塔露拉离队后的治疗登记","summary":"本阶段塔露拉的履历已包括整合运动的创立、发展与圣骏堡革命。她曾带队对抗迫害感染者的乌萨斯官方力量，组织随后扩大并成为革命的关键力量之一。革命结束后，她主动脱离整合运动，经陈推荐到罗德岛治疗；所给第一档案没有详述全部政局变化。","focus":"此为革命后入职时点；所给片段不足以重述革命过程和主动退队的原因。","memories":[],"forms":[{"id":"char_4247_oxi","name":"塔露拉"}],"source":"https://prts.wiki/w/%E5%A1%94%E9%9C%B2%E6%8B%89"},{"id":"char_4077_palico","name":"泰拉大陆调查团","en":"Terra Research Commission","kind":"operator","region":"rhodes","origin":"未知","faction":"罗德岛","profession":"狙击","aliases":[],"title":"调查团的成员分工与板车研发","summary":"泰拉大陆调查团由三只艾露猫组成，分别擅长生态研究、锻造和狩猎，现负责特殊外来生物应对。工匠猫与罗德岛工程部合作开发新型板车，使用当地生物材料加固结构并配置装置，随从猫负责多环境测试。团队保留调查团名称，正式编制则为艾露猫特别行动小组。","focus":"记录联动团队的具体分工，不将其故乡技术解释为泰拉一般工业标准。","memories":[],"forms":[{"id":"char_4077_palico","name":"泰拉大陆调查团"}],"source":"https://prts.wiki/w/%E6%B3%B0%E6%8B%89%E5%A4%A7%E9%99%86%E8%B0%83%E6%9F%A5%E5%9B%A2"},{"id":"char_151_myrtle","name":"桃金娘","en":"Myrtle","kind":"operator","region":"rhodes","origin":"未公开","faction":"罗德岛","profession":"先锋","aliases":[],"title":"桃金娘的自报履历与支援能力","summary":"桃金娘来自地下世界，是杜林族少女，要求将先前履历记为大将军。实际战斗记录显示，她能够鼓舞同伴、进行指挥，并提供一定治疗，可靠性得到认可。她对地上事物充满好奇，喜欢集体行动，也常主动接近人群。自称头衔与已经观察到的战术能力应分开理解。","focus":"大将军为本人要求登记的称呼，不能直接当作已核实的正式军衔。","memories":[{"title":"任务报告填写指南","intro":"你永远也搞不明白她在想些什么。"}],"forms":[{"id":"char_151_myrtle","name":"桃金娘"}],"source":"https://prts.wiki/w/%E6%A1%83%E9%87%91%E5%A8%98"},{"id":"char_4164_tecno","name":"特克诺","en":"Tecno","kind":"operator","region":"bolivar","origin":"玻利瓦尔","faction":"玻利瓦尔","profession":"术师","aliases":[],"title":"特克诺的治疗入职与街头艺术","summary":"特克诺来自多索雷斯街头艺术社区，在艺术馆袭击事件中接触大量源石粉尘，感染加重，经龙舌兰介绍求医。病情稳定后，她申请并通过培训，成为当地外勤。驻舰期间，她与同伴制作的喷绘引发调查，后来被病房负责人认出，按要求清理墙面后结束了这次事件。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"共舞","intro":"艺术在于调动情感……恐惧也算其中之一，对吧？"}],"forms":[{"id":"char_4164_tecno","name":"特克诺"}],"source":"https://prts.wiki/w/%E7%89%B9%E5%85%8B%E8%AF%BA"},{"id":"char_411_tomimi","name":"特米米","en":"Tomimi","kind":"operator","region":"sargon","origin":"萨尔贡","faction":"萨尔贡","profession":"术师","aliases":[],"title":"特米米的离乡与术师录用","summary":"特米米来自萨尔贡阿卡胡拉，曾试图阻止嘉维尔离开，失败后随其来到罗德岛。入职初期，她因对部族外生活了解有限而发生过常识错误，随后较快适应。测试者一度质疑其近身用杖方式是否符合术师要求，观察后认可其中的技艺运用，最终允许她继续采用自身方式训练。","focus":"按录用过程的分歧与结论分别叙述，不把少数术师的期待写成已成型流派。","memories":[{"title":"崭新生活","intro":"个人愉乐与倾情思慕，可否兼得？"}],"forms":[{"id":"char_411_tomimi","name":"特米米"}],"source":"https://prts.wiki/w/%E7%89%B9%E7%B1%B3%E7%B1%B3"},{"id":"char_2012_typhon","name":"提丰","en":"Typhon","kind":"operator","region":"sami","origin":"萨米","faction":"萨米","profession":"狙击","aliases":[],"title":"提丰的北地活动与猎人经验","summary":"提丰是活跃于萨米的萨卡兹猎人，熟悉当地自然环境、潜在威胁及相应应对方法。应麦哲伦邀请，她与罗德岛合作，协助萨米和无尽冰原地区事务。档案认为她不同于一般游荡者和部落猎人，她本人对这种特殊性有所认识，但输入没有提供可以完整说明其来源的材料。","focus":"本条采用已知合作与环境经验，不据特殊性补造未公开身世。","memories":[],"forms":[{"id":"char_2012_typhon","name":"提丰"}],"source":"https://prts.wiki/w/%E6%8F%90%E4%B8%B0"},{"id":"char_4056_titi","name":"缇缇","en":"Titi","kind":"operator","region":"sargon","origin":"萨尔贡","faction":"萨尔贡","profession":"医疗","aliases":[],"title":"缇缇的馆长身份与舰内交流","summary":"缇缇担任萨尔贡法尔贾万达巴德博物馆馆长，以外勤身份与罗德岛合作，并希望修复萨尔贡和米诺斯的关系。到本舰后，她主动参观各部门，以珍贵食谱交换菜谱，用文物修复材料协助处理工程零件，也与动力层工人交谈，很快建立了广泛的日常联系。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[],"forms":[{"id":"char_4056_titi","name":"缇缇"}],"source":"https://prts.wiki/w/%E7%BC%87%E7%BC%87"},{"id":"char_166_skfire","name":"天火","en":"Skyfire","kind":"operator","region":"victoria","origin":"维多利亚","faction":"维多利亚","profession":"术师","aliases":[],"title":"天火的研究资历与法术评估","summary":"天火拥有地质学和源石地质学双学位，属于狐尾研究会的王者之杖团体，任该团体驻罗德岛首席术师。她协助源石理论研究并参加歼灭等任务，能够凝聚高温火体并引导下落。评估认可其天赋，也说明她尚不能完全控制庞大力量，施术时周边火灾风险需要注意。","focus":"同时记录能力与控制限制，不将评估中的形容语言理解为无限威力。","memories":[{"title":"老同学","intro":"士别三日，当刮目相看。"}],"forms":[{"id":"char_166_skfire","name":"天火"}],"source":"https://prts.wiki/w/%E5%A4%A9%E7%81%AB"},{"id":"char_4213_skybx","name":"天空盒","en":"Skybox","kind":"operator","region":"columbia","origin":"哥伦比亚","faction":"哥伦比亚","profession":"狙击","aliases":[],"title":"天空盒的复职与跨机构合作","summary":"高登·谭农在螺旋桨天堂事件后，恢复该机构总长官身份，并升任哥伦比亚相关管理局探员总管。他以天空盒为代号与罗德岛合作，协助矿石病药物进入当地市场，同时开展天空科研。档案另有秘书工作准则等行政材料，能够说明机构运作的部分情况，但不是其完整个人传记。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[{"title":"红气球，蓝气球","intro":"天上飘的是什么东西？一只气球。那有什么稀奇？"}],"forms":[{"id":"char_4213_skybx","name":"天空盒"}],"source":"https://prts.wiki/w/%E5%A4%A9%E7%A9%BA%E7%9B%92"},{"id":"char_402_tuye","name":"图耶","en":"Tuye","kind":"operator","region":"sargon","origin":"萨尔贡","faction":"萨尔贡","profession":"医疗","aliases":[],"title":"图耶的运输后勤与医疗调任","summary":"图耶曾负责贸易公司的后勤研发和运输规划，沙暴事故中感染后到罗德岛治疗、工作。她原被考虑安排至工程部，但在一次医疗人手不足的紧急任务中表现突出。医疗人员认为，其器械知识与野外运输积累的救护经验足以胜任岗位，随后调入医疗部门。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"沙漠之虹","intro":"沙漠中没有比水更珍贵的宝藏。"}],"forms":[{"id":"char_402_tuye","name":"图耶"}],"source":"https://prts.wiki/w/%E5%9B%BE%E8%80%B6"},{"id":"char_112_siege","name":"推进之王","en":"Siege","kind":"operator","region":"victoria","origin":"维多利亚","faction":"格拉斯哥帮","profession":"先锋","aliases":[],"title":"推进之王的早期录用与队长岗位","summary":"维娜以推进之王为代号加入罗德岛，基础档案中大部分既往履历缺失，另有未证实的指控记录。她带领格拉斯哥帮，通过测试后担任先锋小队队长。早期同事曾低估其街头帮派背景，随后从体检和行动中确认队伍具有专业战斗技能。她在此时仅说明曾正常生活于伦蒂尼姆。","focus":"保留早期档案未明状态，不将后续公开身份倒写为当时所有人已知事实。","memories":[{"title":"幻日","intro":"总是把悲剧归咎于残酷的命运，是否也是一种懒惰？"}],"forms":[{"id":"char_112_siege","name":"推进之王"},{"id":"char_1019_siege2","name":"维娜·维多利亚"}],"source":"https://prts.wiki/w/%E6%8E%A8%E8%BF%9B%E4%B9%8B%E7%8E%8B"},{"id":"char_4119_wanqin","name":"万顷","en":"Wanqing","kind":"operator","region":"yan","origin":"炎","faction":"炎","profession":"先锋","aliases":[],"title":"万顷的育种研究与访学工作","summary":"万顷本名禾生，是炎国天师府学徒，担任农业天师，在大荒城多项育种试验中取得成果。经黍介绍，他来到罗德岛访学，兼任后勤。其专业背景使同僚对实际农事与研究产生兴趣，档案记录他面对相关提问的情况。输入主要涉及研究、推荐与交流任职，未展开全部教育经历。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[{"title":"问道","intro":"“精诚所至，金石为开”？这在科研领域到底作不作数啊？"}],"forms":[{"id":"char_4119_wanqin","name":"万顷"}],"source":"https://prts.wiki/w/%E4%B8%87%E9%A1%B7"},{"id":"char_2027_wang","name":"望","en":"Wang","kind":"operator","region":"yan","origin":"炎","faction":"炎-岁","profession":"特种","aliases":[],"title":"望的顾问经历与养病来访","summary":"望曾担任炎国军事顾问，现以无业棋手身份登记，是年、夕、令等人的兄长，也是重岳的弟弟。经重岳介绍，他来到罗德岛养病，偶尔为作战提供建议。第一档案记述百灶事件之后家族成员的驻舰情况，以及他出现在访客接待处的时间，未展开完整病情与旧任经历。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"终局","intro":"仍有人在等你……有许多人，都在等你。"}],"forms":[{"id":"char_2027_wang","name":"望"}],"source":"https://prts.wiki/w/%E6%9C%9B"},{"id":"char_275_breeze","name":"微风","en":"Breeze","kind":"operator","region":"victoria","origin":"维多利亚","faction":"维多利亚","profession":"医疗","aliases":[],"title":"微风的离家求学与医疗工作","summary":"微风本名格蕾丝，出自维多利亚一支旁系贵族家庭。因家族衰落与教条约束，她提出离乡求学，遭反对后独自出行。医疗进修期间，她接触罗德岛并主动求职，在药理学和临床理论方面表现良好，现参加战场救护。档案记录其游历后更关注现实生活及流离人员的医疗需求。","focus":"依据已有求学和任职过程叙述，不由离家行为推定她已完全断绝家庭关系。","memories":[{"title":"风暖寒林","intro":"卸下贵族的身份并不意味着逃避。"},{"title":"囚徒的幻梦","intro":"他们不满于当下，为走上另一条路而付诸一生，可到头来，没有一条路通往幸福。循环往复，光阴耗尽，唯余哀愁。"}],"forms":[{"id":"char_275_breeze","name":"微风"}],"source":"https://prts.wiki/w/%E5%BE%AE%E9%A3%8E"},{"id":"char_4098_vvana","name":"薇薇安娜","en":"Viviana","kind":"operator","region":"leithanien","origin":"莱塔尼亚","faction":"莱塔尼亚","profession":"近卫","aliases":[],"title":"薇薇安娜的骑士经历与合作","summary":"薇薇安娜出身莱塔尼亚霍赫贝格家族，是前卡西米尔人气竞技骑士。经耀骑士临光举荐，她登记为罗德岛合作干员，驻舰期间提供战术与外勤支援。她擅长光影源石技艺和剑术，能够灵活作战。现有履历同时列出家族背景、竞技经历与合作身份，不宜将其中一项替代其全部经历。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[{"title":"不写诗的诗人","intro":"诗人的眼如同时间，当她注目一片土地，土地的肌理便随之改变。"}],"forms":[{"id":"char_4098_vvana","name":"薇薇安娜"}],"source":"https://prts.wiki/w/%E8%96%87%E8%96%87%E5%AE%89%E5%A8%9C"},{"id":"char_4107_vrdant","name":"维荻","en":"Verdant","kind":"operator","region":"victoria","origin":"维多利亚","faction":"维多利亚","profession":"特种","aliases":[],"title":"维荻的植物学业与药物项目","summary":"维荻来自维多利亚农业小镇，曾就读植物学专业，感染后被迫中断学业，转为在野外采集植物的猎人。求医并签约后，他参加外勤，也进入药物开发项目进修。报到时，他对接待事务较冷淡，却积极研究盆栽并拜访疗养庭院，后来被要求重新填写真实入职材料。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"小草的呼喊","intro":"他在呼喊——不该被随意除去，也不该葬身火海。"}],"forms":[{"id":"char_4107_vrdant","name":"维荻"}],"source":"https://prts.wiki/w/%E7%BB%B4%E8%8D%BB"},{"id":"char_1019_siege2","name":"维娜·维多利亚","en":"Vina Victoria","kind":"operator","region":"victoria","origin":"维多利亚","faction":"维多利亚","profession":"近卫","aliases":[],"title":"维娜的战争任职与议会合作","summary":"维娜最初以格拉斯哥帮领袖身份登记，后来在伦蒂尼姆战争中作为典范军领袖与罗德岛协同行动。在这一后续阶段，她担任伦蒂尼姆议会议长，与罗德岛保持合作。双方已有医疗建设方面的联系，她也表示将在更多领域推进合作。档案未在该段具体列出所有政策及其实施结果。","focus":"采用议长阶段的明确职务，不将其与基础推进之王时期同时呈现为现状。","memories":[],"forms":[{"id":"char_112_siege","name":"推进之王"},{"id":"char_1019_siege2","name":"维娜·维多利亚"}],"source":"https://prts.wiki/w/%E7%BB%B4%E5%A8%9C%C2%B7%E7%BB%B4%E5%A4%9A%E5%88%A9%E4%BA%9A"},{"id":"char_1035_wisdel","name":"维什戴尔","en":"Wiš'adel","kind":"operator","region":"kazdel","origin":"卡兹戴尔","faction":"巴别塔","profession":"狙击","aliases":[],"title":"维什戴尔的更名与战略合作","summary":"萨卡兹雇佣兵领袖W在此阶段正式更名维什戴尔。伦蒂尼姆战争中，她与罗德岛特别行动队合作，多次阻止军事委员会行动，双方随后更新战略条款。工程部另为其新武器补登记，认为该装置具有主炮级巫术增幅功能；具体运用与性能仍依评估记录，不因名称相近与旧武器混同。","focus":"本条采用更名后的合作及装备记录，不将其提前套入早期W档案。","memories":[],"forms":[{"id":"char_113_cqbw","name":"W"},{"id":"char_1035_wisdel","name":"维什戴尔"}],"source":"https://prts.wiki/w/%E7%BB%B4%E4%BB%80%E6%88%B4%E5%B0%94"},{"id":"char_4226_veen","name":"维伊","en":"Вий","kind":"operator","region":"ursus","origin":"乌萨斯","faction":"乌萨斯","profession":"术师","aliases":[],"title":"维伊的独立兵团与合作接触","summary":"维伊原名斯乔帕·拉辛，是乌萨斯独立战术兵团谢钦的首领兼指挥官，也是自由民领袖。一一〇二年初，他带队离开军方管辖，圣骏堡事变后彻底独立，经办事处介绍与罗德岛接触。所给档案主要结合口述与走访说明自由民历史，尚未展开双方具体合作项目。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[],"forms":[{"id":"char_4226_veen","name":"维伊"}],"source":"https://prts.wiki/w/%E7%BB%B4%E4%BC%8A"},{"id":"char_261_sddrag","name":"苇草","en":"Reed","kind":"operator","region":"victoria","origin":"维多利亚","faction":"维多利亚","profession":"先锋","aliases":[],"title":"苇草的救援接收与技艺研究","summary":"苇草从维多利亚小丘郡战后废墟中被医疗干员救出，以矿石病患者身份留在罗德岛。非感染损伤康复后，她在测试中表现出较强战斗与技艺能力，但个人来历仍不明确。研究者认为施术引发的燃烧并非核心，而与生命组织活性变化有关；原理尚需继续研究，她仍处于留舰观察阶段。","focus":"按基础形态早期研究口吻叙述，不把实验判断扩大成已解决的全部机制。","memories":[{"title":"芦苇之心","intro":"当陷于黑暗之人见到光亮的边缘——"}],"forms":[{"id":"char_261_sddrag","name":"苇草"},{"id":"char_1020_reed2","name":"焰影苇草"}],"source":"https://prts.wiki/w/%E8%8B%87%E8%8D%89"},{"id":"char_400_weedy","name":"温蒂","en":"Weedy","kind":"operator","region":"rhodes","origin":"伊比利亚","faction":"罗德岛","profession":"特种","aliases":[],"title":"温蒂的生物工程与干员转任","summary":"温蒂出身伊比利亚科研家庭，是罗德岛创立初期即加入的生物工程研究者。长期调整和测试后，她完成适合自身的武器，并依本人意愿成为干员，提供远程支援。档案同时记录她对整洁要求较高，交流时会直接指出对方需要整理之处，因此日常活动与人际往来有一定限制。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[{"title":"同舟","intro":"没有选择前往远方，并不是因为害怕风雨。"},{"title":"盐漠上的海风","intro":"推开旧日的大门，她遇到一位沉溺于旧日的人。"}],"forms":[{"id":"char_400_weedy","name":"温蒂"}],"source":"https://prts.wiki/w/%E6%B8%A9%E8%92%82"},{"id":"char_4081_warmy","name":"温米","en":"Warmy","kind":"operator","region":"rim","origin":"雷姆必拓","faction":"雷姆必拓","profession":"术师","aliases":[],"title":"温米的求医陪护与基础学习","summary":"温米生于雷姆必拓矿业小镇，年纪尚小，已在烹饪和机械修理方面显示天分。暴行推荐她在监护人阿兰娜陪同下到罗德岛治疗，她同时参加施术基础课程。第一档案还记录小锅盖这一外号先由工程部传开的经过，没有继续说明她此前全部学习或家庭经历。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"未完的结局","intro":"记忆里那只宽厚又粗糙的手，她从未想过松开。"}],"forms":[{"id":"char_4081_warmy","name":"温米"}],"source":"https://prts.wiki/w/%E6%B8%A9%E7%B1%B3"},{"id":"char_4145_ulpia","name":"乌尔比安","en":"Ulpianus","kind":"operator","region":"aegir","origin":"阿戈尔","faction":"深海猎人","profession":"近卫","aliases":[],"title":"乌尔比安的深海职务与资料权限","summary":"乌尔比安是阿戈尔前技术院执政官，曾负责深海猎人计划，并担任相关军事团体作战指挥官之一，现为罗德岛海洋事务提供支持。其登陆时间和地点没有公开。经本人及相关人员确认，档案已移入高权限资料库，普通资料中仅保留职务与有限联络线索，不能据此复原全部行动。","focus":"明确公开信息与权限内资料的区别，不为缺失部分补写具体活动。","memories":[],"forms":[{"id":"char_4145_ulpia","name":"乌尔比安"}],"source":"https://prts.wiki/w/%E4%B9%8C%E5%B0%94%E6%AF%94%E5%AE%89"},{"id":"char_4224_turdus","name":"乌啾","en":"Укусик","kind":"operator","region":"ursus","origin":"乌萨斯","faction":"乌萨斯","profession":"医疗","aliases":[],"title":"乌啾的早年劳动与办事处任职","summary":"乌啾幼年失去父母，曾随其他儿童清扫圣骏堡布满源石的能源管道，后来参加地下组织无缚者同盟。经凛冬介绍，她加入当地罗德岛办事处，从事情报收集与急救。按照监护人烈夏要求，她定期前往总部治疗矿石病，并接受通识教育；档案将工作安排和未成年照护一并记录。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[{"title":"号外！号外！","intro":"即便是不识字之人，也能从读报者的表情中判断出消息的好坏。"}],"forms":[{"id":"char_4224_turdus","name":"乌啾"}],"source":"https://prts.wiki/w/%E4%B9%8C%E5%95%BE"},{"id":"char_455_nothin","name":"乌有","en":"Mr.Nothing","kind":"operator","region":"yan","origin":"炎","faction":"炎","profession":"特种","aliases":[],"title":"乌有的离乡求职与舰内活动","summary":"乌有来自炎国勾吴城，自幼习武，因得罪当地权势而离乡，途中遇到炎熔，经协商后前往罗德岛求职。他在舰内组织带炎国特色的占卜、推拿、健身等业余活动，也制作折扇出售。可露希尔曾就此长时间训话，随后让他协助部分舰内商业事务。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"落水人","intro":"他作揖告别这座城市的恩情，却躲不开缠在他身上的仇怨。"}],"forms":[{"id":"char_455_nothin","name":"乌有"}],"source":"https://prts.wiki/w/%E4%B9%8C%E6%9C%89"},{"id":"char_254_vodfox","name":"巫恋","en":"Shamare","kind":"operator","region":"siracusa","origin":"叙拉古","faction":"叙拉古","profession":"辅助","aliases":[],"title":"巫恋的调查收容与轻度任务","summary":"巫恋曾与叙拉古一处湖岛宅邸的异常事件相联系，当地流传诅咒与灵异说法。调查人员最终带回少女及部分受惊人员，确认相关问题源于她无法控制的源石技艺。罗德岛以感染者身份接收她，在治疗期间批准其参加部分轻度任务，目的包括学习控制自身能力。","focus":"将地方传闻与调查结论分层记录，不把怪谈当作对少女身份的正式定义。","memories":[{"title":"无字诅咒","intro":"她熟知恐惧，也清楚恐惧要如何消解，因此她翻开了书页。"}],"forms":[{"id":"char_254_vodfox","name":"巫恋"}],"source":"https://prts.wiki/w/%E5%B7%AB%E6%81%8B"},{"id":"char_2015_dusk","name":"夕","en":"Dusk","kind":"operator","region":"yan","origin":"炎","faction":"炎-岁","profession":"术师","aliases":[],"title":"夕的绘画专长与访客居住","summary":"夕是炎国画家，擅长传统绘画，经年的推动以访客身份来到罗德岛。她在本舰偏僻走道的墙上设置可进入的门，并居于其中，较少外出。她向人事人员坦言不想工作，也不消耗本舰物资。输入主要记述留舰安排和日常作风，未全面说明其能力原理与更早经历。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[{"title":"旦夕","intro":"他只有这一夜。"}],"forms":[{"id":"char_2015_dusk","name":"夕"}],"source":"https://prts.wiki/w/%E5%A4%95"},{"id":"char_336_folivo","name":"稀音","en":"Scene","kind":"operator","region":"sargon","origin":"萨尔贡","faction":"萨尔贡","profession":"辅助","aliases":[],"title":"稀音的摄影侦察与设备协作","summary":"稀音是摄影师，使用名为镜头的辅助设备和机器人小队勘察战场、传递图像，也支援野外考察。她的运动能力较低，执行工作时需要后勤协助。日常记录形容她几乎不说话，离开宿舍后较难联系，辅助设备发出的声音常成为同伴寻找其位置的线索。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"记录者","intro":"值得她坚持亲口说完的话，真的很少。"}],"forms":[{"id":"char_336_folivo","name":"稀音"}],"source":"https://prts.wiki/w/%E7%A8%80%E9%9F%B3"},{"id":"char_348_ceylon","name":"锡兰","en":"Ceylon","kind":"operator","region":"siesta","origin":"汐斯塔（独立城邦）","faction":"汐斯塔","profession":"医疗","aliases":[],"title":"锡兰的研究岗位与医疗支援","summary":"锡兰毕业于维多利亚国立大学源石研究专业，现为凯尔希研究室辅助研究员，并利用水系法术提供战场医疗支持。日常观察形容她态度较强势，但判断常能得到认可，出错时也愿意道歉。该段材料主要记录专业岗位和同事印象，没有完整展开她在汐斯塔及研究室内的全部经历。","focus":"将同事使用的日常称呼与正式专业身份区分，不以性格印象代替研究评价。","memories":[{"title":"真心的礼物","intro":"求索真知的道路比她想象的要更加艰难，但她也学会了从同路人那里获得勇气与支持。"},{"title":"留下的人","intro":"死亡并不只是带走了一个人的生命，它也会带走和这个人最亲密的人的一部分。"}],"forms":[{"id":"char_348_ceylon","name":"锡兰"}],"source":"https://prts.wiki/w/%E9%94%A1%E5%85%B0"},{"id":"char_4151_tinman","name":"锡人","en":"Tin Man","kind":"operator","region":"columbia","origin":"未公开","faction":"哥伦比亚","profession":"特种","aliases":[],"title":"锡人的侦探身份与临时对接","summary":"锡人是哥伦比亚侦探及梅兰德基金会高级特工，曾在特里蒙数次与罗德岛接触。双方正式合作后，他不是固定接洽人，仅在相关人员不便时临时代办。档案记述他干练敏锐，能以礼貌和亲和态度应对不同对象；其外观特殊，但日常职业表现与常见侦探形象较接近。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[{"title":"最后一案","intro":"追赶时代，或者被它甩进沙尘里摔个头破血流。"}],"forms":[{"id":"char_4151_tinman","name":"锡人"}],"source":"https://prts.wiki/w/%E9%94%A1%E4%BA%BA"},{"id":"char_423_blemsh","name":"瑕光","en":"Blemishine","kind":"operator","region":"kazimierz","origin":"卡西米尔","faction":"卡西米尔","profession":"重装","aliases":["玛莉娅·临光"],"title":"瑕光的骑士经历与工程兴趣","summary":"瑕光原名玛莉娅·临光，具有卡西米尔竞技经验，通过测试后按个人意愿与姐姐同任重装。她日常开朗，正式场合较稳重，与临光及鞭刃均有密切关系。驻舰期间，她频繁接触工匠和工程爱好者，多次申请参观学习，曾因长时间停留车间而影响其他安排。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"心甘情愿","intro":"或许理想的本质，在于相信与否。"}],"forms":[{"id":"char_423_blemsh","name":"瑕光"}],"source":"https://prts.wiki/w/%E7%91%95%E5%85%89"},{"id":"char_492_quercu","name":"夏栎","en":"Quercus","kind":"operator","region":"rhodes","origin":"维多利亚","faction":"罗德岛","profession":"辅助","aliases":[],"title":"夏栎的荒地巡医与情报职责","summary":"夏栎掌握维多利亚高多汀传统技艺，加入罗德岛前长期在南部荒地为聚落居民治病，现为当地情报人员。她的法术可治疗伤口、促进植物生长或形成荆棘，施术伴有传统仪式语言。日常记录也载明，她一般不会为干员恢复失养盆栽，而是建议按植物需要进行常规浇养。","focus":"分别记录可观察法术与传统表述，不将仪式语言本身认定为实际生效机制。","memories":[{"title":"终途","intro":"死者安息长眠，但死亡的阴霾不会轻易放过活着的人。"},{"title":"生命的萌芽","intro":"求生本就是一种贪婪，它可以被理解，但不能被纵容。"}],"forms":[{"id":"char_492_quercu","name":"夏栎"}],"source":"https://prts.wiki/w/%E5%A4%8F%E6%A0%8E"},{"id":"char_240_wyvern","name":"香草","en":"Vanilla","kind":"operator","region":"columbia","origin":"瓦伊凡","faction":"黑钢国际","profession":"先锋","aliases":[],"title":"香草的黑钢培训与交流派遣","summary":"香草是黑钢受训人员，加入时间不长，因认真努力被选入双方交流项目，派驻罗德岛学习。她凭较强抗打击能力承担先锋工作。与雷蛇、芙兰卡相处时，她常显拘谨，虽然身高高于两位前辈，经验仍较少。现有输入以培训、派遣和在舰表现为主，没有提供完整早期履历。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[{"title":"源石虫与啤酒花","intro":"人与自然的关系总是会有许多问题 ，可归根结底，一切都是人的问题。"}],"forms":[{"id":"char_240_wyvern","name":"香草"}],"source":"https://prts.wiki/w/%E9%A6%99%E8%8D%89"},{"id":"char_4214_cairn","name":"响石","en":"Cairn","kind":"operator","region":"columbia","origin":"哥伦比亚","faction":"哥伦比亚","profession":"重装","aliases":[],"title":"响石的旅行社经营与向导合作","summary":"响石原名费尔南·伯恩，在哥伦比亚经营一家独立旅行社，以能够到达多种地区闻名。除已故荣誉社员马丁·伯恩外，他是该社唯一成员。到罗德岛接受治疗后，他也签订合作协议，在多类外勤中担任向导；所给第一档案只提供禁区旅行评论的开端，未说明全部经营经历。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[],"forms":[{"id":"char_4214_cairn","name":"响石"}],"source":"https://prts.wiki/w/%E5%93%8D%E7%9F%B3"},{"id":"char_4122_grabds","name":"小满","en":"Grain Buds","kind":"operator","region":"yan","origin":"炎","faction":"炎","profession":"辅助","aliases":[],"title":"小满的牧兽经验与访客活动","summary":"小满来自炎国大荒城，自幼参与农业劳动，在照料牧兽方面具有经验，获得的多项农业荣誉经过核实。她随黍以访客身份暂住罗德岛，协助食堂研究菜谱、照顾植物，也帮助医疗人员安抚年幼患者。现有资料主要记录这些日常活动，未将其登记为某一部门的正式全职雇员。","focus":"明确访客身份与提供协助的差别，不把农业荣誉扩大为未记载的职务。","memories":[{"title":"旧梦重温","intro":"故事里的那片田野是真实存在的，小径、夕阳和乌云也是。"}],"forms":[{"id":"char_4122_grabds","name":"小满"}],"source":"https://prts.wiki/w/%E5%B0%8F%E6%BB%A1"},{"id":"char_497_ctable","name":"晓歌","en":"Cantabile","kind":"operator","region":"rhodes","origin":"玻利瓦尔","faction":"罗德岛","profession":"先锋","aliases":[],"title":"晓歌的获救治疗与正式录用","summary":"晓歌在玻利瓦尔难民区矿石病急性发作，由罗德岛当地办事处救助，并转送本舰继续治疗。半年后，她依本人意愿正式加入。部分同批病人因其气质而对她流落难民区感到疑惑，属于旁人的初见印象；履历能够确认的是接诊、后续治疗与录用，未由此说明其全部早年背景。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[{"title":"飞进窗的羽兽","intro":"羽兽衔来一粒米，放在晓歌面前，仰头看着她。"}],"forms":[{"id":"char_497_ctable","name":"晓歌"}],"source":"https://prts.wiki/w/%E6%99%93%E6%AD%8C"},{"id":"char_4051_akkord","name":"协律","en":"Akkord","kind":"operator","region":"leithanien","origin":"莱塔尼亚","faction":"莱塔尼亚","profession":"术师","aliases":[],"title":"协律的调谐工作与听觉评估","summary":"协律原为莱塔尼亚偏远小镇调谐师，暴雪引发的声场核心事故中感染，后到罗德岛治疗并支援音乐环境与作战。她会辨听个体周围频率，在私人笔记中建立标签，并据变化追加设备调试。医疗评估认为其方法高度依赖经验，暂未确认与调谐的直接关联，建议继续观察。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[],"forms":[{"id":"char_4051_akkord","name":"协律"}],"source":"https://prts.wiki/w/%E5%8D%8F%E5%BE%8B"},{"id":"char_1022_flwr2","name":"撷英调香师","en":"Perfumer the Distilled","kind":"operator","region":"rhodes","origin":"米诺斯","faction":"罗德岛","profession":"辅助","aliases":[],"title":"调香师的庭院交接与米诺斯外派","summary":"莱娜与博士和医疗部协商后，暂将疗养庭院交由波登可负责，主动申请外派米诺斯，担任雅赛努斯新办事处负责人，协助建立当地感染者医疗体系。此前她曾从花种和设计资料起步，规划庭院及芬芳治疗空间。该阶段的新职责较原岗位扩大，具体后续建设成果未在此详述。","focus":"按撷英形态的外派阶段记录，庭院交接属于暂时安排而非确认永久离职。","memories":[],"forms":[{"id":"char_181_flower","name":"调香师"},{"id":"char_1022_flwr2","name":"撷英调香师"}],"source":"https://prts.wiki/w/%E6%92%B7%E8%8B%B1%E8%B0%83%E9%A6%99%E5%B8%88"},{"id":"char_1041_angel2","name":"新约能天使","en":"Exusiai the New Covenant","kind":"operator","region":"lungmen","origin":"拉特兰","faction":"企鹅物流","profession":"特种","aliases":[],"title":"新约能天使的创业与合作登记","summary":"能天使在此阶段仍为拉特兰公民，为罗德岛执行秘密联络和武装押运。根据本人要求，人事部将合作身份更新为企鹅物流资深员工及苹果派物流老板。输入另有其学生时期的校务记录，内容属于过去的教育经历。新旧身份应按各自时点说明，不能把创业等同已结束所有原有合作。","focus":"本条采用新约阶段登记，保留早期教育材料与当前合作身份的时间区别。","memories":[],"forms":[{"id":"char_103_angel","name":"能天使"},{"id":"char_1041_angel2","name":"新约能天使"}],"source":"https://prts.wiki/w/%E6%96%B0%E7%BA%A6%E8%83%BD%E5%A4%A9%E4%BD%BF"},{"id":"char_4194_rmixer","name":"信仰搅拌机","en":"Sankta Miksaparato","kind":"operator","region":"laterano","origin":"拉特兰","faction":"拉特兰","profession":"重装","aliases":[],"title":"帕特里奇昂的铳骑任职记录","summary":"帕特里奇昂是拉特兰任职时间最长的铳骑，熟练使用各类铳械，经教皇厅与罗德岛友好协议，以信仰搅拌机为代号参加合作。所给日程记载，他清晨五时起床，独自花一小时穿好全套盔甲，拒绝挑选侍从。相关材料未继续展开此后完整日程或长期服役经过。","focus":"日程只提供清晨穿甲一项，不能据此推定他完整的生活制度或长期经历。","memories":[],"forms":[{"id":"char_4194_rmixer","name":"信仰搅拌机"}],"source":"https://prts.wiki/w/%E4%BF%A1%E4%BB%B0%E6%90%85%E6%8B%8C%E6%9C%BA"},{"id":"char_274_astesi","name":"星极","en":"Astesia","kind":"operator","region":"columbia","origin":"哥伦比亚","faction":"哥伦比亚","profession":"近卫","aliases":[],"title":"星极的文献顾问与治疗期间任职","summary":"星极出身具有星象传统的家庭，是哥伦比亚神秘学组织会员，经合作协议派驻莱茵生命，负责文献和双方交流。她本人促成了该协议，妹妹埃琳娜在莱茵任职是重要考虑因素。姐妹因共发性矿石病来到罗德岛，她在治疗期间通过测试成为干员，并运用特殊剑技参加行动。","focus":"占星咨询与正式顾问职责分别记录，不将神秘学建议写成已验证的预言。","memories":[{"title":"启明","intro":"点亮明日的，不止有星辰。"},{"title":"复耀","intro":"当沉默的星闪起光亮——"}],"forms":[{"id":"char_274_astesi","name":"星极"}],"source":"https://prts.wiki/w/%E6%98%9F%E6%9E%81"},{"id":"char_136_hsguma","name":"星熊","en":"Hoshiguma","kind":"operator","region":"lungmen","origin":"东国","faction":"龙门近卫局","profession":"重装","aliases":[],"title":"星熊的近卫局录用与重装任务","summary":"星熊出身东国，曾有数项指控记录。经魏彦吾交涉，龙门近卫局依其能力与表现破格吸纳，安排她处理高风险犯罪、要员保护及灾害救援。她后来以重装干员协助罗德岛，并提供现场执行和指挥支援。档案记录她衣着较随意、喜欢饮酒，这些日常习惯与专业职责分别呈现。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[{"title":"抉择过后","intro":"局外人当它是用脚轻轻一抹就可以模糊掉的粉笔线，亲自跨过去的人才知道，这虽不是天堑，却也已是险途。"}],"forms":[{"id":"char_136_hsguma","name":"星熊"},{"id":"char_1044_hsgma2","name":"斩业星熊"}],"source":"https://prts.wiki/w/%E6%98%9F%E7%86%8A"},{"id":"char_135_halo","name":"星源","en":"Astgenne","kind":"operator","region":"columbia","origin":"哥伦比亚","faction":"莱茵生命","profession":"术师","aliases":[],"title":"星源的外派申请与研究安排","summary":"星源是莱茵生命能量科研究员，曾因事故感染后与姐姐短住罗德岛，恢复工作后又因新的内部变故外派。她拥有电力和工程双学位，熟悉本舰工坊与后勤人员，较快适应新生活。到访后，她主动联系工匠并定制实验器材，记录显示仍在积极筹备研究。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"实验进行中","intro":"一点勇气，一点决断，再来一点长远的眼光，最后加入的是有关于底线的坚持，它们造就了埃琳娜。"}],"forms":[{"id":"char_135_halo","name":"星源"},{"id":"char_1047_halo2","name":"溯光星源"}],"source":"https://prts.wiki/w/%E6%98%9F%E6%BA%90"},{"id":"char_4170_hdbell","name":"行铃","en":"Herdbells","kind":"operator","region":"minos","origin":"米诺斯","faction":"米诺斯","profession":"特种","aliases":[],"title":"行铃的牧驮工作与养殖合作","summary":"行铃本名梅里塔，是米诺斯牧驮人，与驮兽一同和罗德岛建立合作。她负责经济动物养殖指导，驮兽提供运输服务。相关来信还记有她参加畜牧展演、仪式仪仗和武装运钞等活动。虽然能够承接多类工作，她与驮兽沟通仍有困难，不能据外界名声认定所有养殖问题均已解决。","focus":"活动事例采用来信的有限记录，不以多项兼职推定统一的正式职业编制。","memories":[],"forms":[{"id":"char_4170_hdbell","name":"行铃"}],"source":"https://prts.wiki/w/%E8%A1%8C%E9%93%83"},{"id":"char_4172_xingzh","name":"行箸","en":"Xingzhu","kind":"operator","region":"yan","origin":"炎","faction":"炎","profession":"辅助","aliases":[],"title":"行箸的历史研究与访客记录","summary":"行箸在炎国太史阁从事历史研究，也是畅销美食散记作者，经煌介绍以访客身份来到罗德岛。相关档案主要从接待准备展开，记述煌询问各地饮食、提交采购申请并关注信使动向。现有材料可以确认其学术与写作身份及来访关系，但没有完整公开其家庭或所有研究项目。","focus":"本条限定已有来访与职业记录，不由接待安排推断未明确的私人关系。","memories":[{"title":"回家","intro":"她一步步走向她梦想过无数次的场景。她的怯意来自期待，她的勇气也是。"}],"forms":[{"id":"char_4172_xingzh","name":"行箸"}],"source":"https://prts.wiki/w/%E8%A1%8C%E7%AE%B8"},{"id":"char_4105_almond","name":"杏仁","en":"Almond","kind":"operator","region":"columbia","origin":"哥伦比亚","faction":"黑钢国际","profession":"特种","aliases":[],"title":"杏仁的工程交流与技术沟通","summary":"杏仁原名罗拉，是黑钢机械工程和自动化专家，多次为行动提供技术支持。在新一轮交流项目中，她主动申请到罗德岛，任特别技术顾问，参加研发。她习惯在团队中公开讨论，表达迅速清楚，尤其重视经费与工程安全，能够解释原理、明确分工并推进协作。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"远航","intro":"她航行于黑夜，她不知道自己将被送往何方。"}],"forms":[{"id":"char_4105_almond","name":"杏仁"}],"source":"https://prts.wiki/w/%E6%9D%8F%E4%BB%81"},{"id":"char_491_humus","name":"休谟斯","en":"Humus","kind":"operator","region":"rhodes","origin":"哥伦比亚","faction":"罗德岛","profession":"近卫","aliases":[],"title":"休谟斯的废物处理与工程改造","summary":"休谟斯曾负责哥伦比亚拓荒地废弃物处理站，经当地办事处介绍来到罗德岛治疗，同时加入工程部并协助处理固体废弃物。初来时，他在宿舍存放大量旧物和零件，后通过自制伸缩收纳系统重新整理，没有丢弃原有物品，部分材料直接成为系统组件。档案记录了该次改造过程。","focus":"以已见工程实例说明经验，不把单次宿舍改造推广为全部技术能力。","memories":[{"title":"荒地巧匠","intro":"别小看他，他是个平凡的人，但有一颗非凡的心。"}],"forms":[{"id":"char_491_humus","name":"休谟斯"}],"source":"https://prts.wiki/w/%E4%BC%91%E8%B0%9F%E6%96%AF"},{"id":"char_436_whispr","name":"絮雨","en":"Whisperain","kind":"operator","region":"iberia","origin":"伊比利亚","faction":"伊比利亚","profession":"医疗","aliases":[],"title":"絮雨的巡游行医与短期同行","summary":"絮雨来自伊比利亚，曾在卡西米尔、萨米等地巡游，为遇见的伤者治疗，较少长期停留，也未指定明确旅程终点。她偶遇并救治一支罗德岛队伍，后因沙地车故障受困，获得本舰接应。随后她以随行医师身份临时加入医疗部，短期共同活动，双方接触属于相互救助后的合作。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[{"title":"雨落之前","intro":"虽然有无法治愈的病痛，但人们依然生活着。"}],"forms":[{"id":"char_436_whispr","name":"絮雨"}],"source":"https://prts.wiki/w/%E7%B5%AE%E9%9B%A8"},{"id":"char_4211_snhunt","name":"雪猎","en":"Snow Hunter","kind":"operator","region":"kjerag","origin":"谢拉格","faction":"谢拉格","profession":"狙击","aliases":[],"title":"雪猎的治疗任职与礼物误会","summary":"雪猎出自谢拉格山中猎户支系，熟悉狩猎和神像雕刻，捕猎感染后到罗德岛治疗，并自愿参加外勤。她曾赠医护一头角跳兽表示感谢，却造成过敏和照料问题。讨论后，动物被放归山野，她改赠肉干；人事部也据此认为原有新人融入方法仍需调整。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"射向群山的最后一箭","intro":"“纯善与信仰殊途同归。”"}],"forms":[{"id":"char_4211_snhunt","name":"雪猎"}],"source":"https://prts.wiki/w/%E9%9B%AA%E7%8C%8E"},{"id":"char_466_qanik","name":"雪绒","en":"Qanipalaat","kind":"operator","region":"sami","origin":"萨米","faction":"萨米","profession":"术师","aliases":[],"title":"雪绒的搜救经历与现代装备训练","summary":"雪绒曾在萨米从事野外搜救，为寻求更好的医疗条件离乡，现协助恶劣环境下的罗德岛外勤。初到舰上，他对门禁卡和现代法杖等设备不熟悉，发生过使用错误。之后他开始阅读说明、向前辈请教，逐渐掌握装备并参加任务。资料明确区分其野外经验与对外界生活的陌生。","focus":"设备学习困难不代表缺乏原有搜救能力，正文分别说明两类经验。","memories":[{"title":"风雪代为传达","intro":"重回怀抱，生养自然。"}],"forms":[{"id":"char_466_qanik","name":"雪绒"}],"source":"https://prts.wiki/w/%E9%9B%AA%E7%BB%92"},{"id":"char_383_snsant","name":"雪雉","en":"Snowsant","kind":"operator","region":"lungmen","origin":"龙门","faction":"炎-龙门","profession":"特种","aliases":[],"title":"雪雉的自学研究与返乡合作","summary":"雪雉出身龙门，靠自学和个人积蓄前往哥伦比亚，在高新技术开发区及私人研究机构从事科研。后来她回到龙门建设家乡，并与罗德岛签约。档案将其描述为长期努力的研究人员，相关履历可以确认跨地区的工作与返乡过程；输入并未完整列出其在各机构参与的所有项目。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[{"title":"数字问题","intro":"面对一个暂时太高的目标，她虽然着急，但还是踏踏实实地从一点一滴做起。"}],"forms":[{"id":"char_383_snsant","name":"雪雉"}],"source":"https://prts.wiki/w/%E9%9B%AA%E9%9B%89"},{"id":"char_4052_surfer","name":"寻澜","en":"Surfer","kind":"operator","region":"columbia","origin":"哥伦比亚","faction":"黑钢国际","profession":"先锋","aliases":[],"title":"寻澜的黑钢情报经历与外派申请","summary":"寻澜原名蒂拉，是黑钢先遣小组成员，凭敏锐感知和识别言外之意的能力从事情报工作，表现优秀。记录认为，她逐渐厌倦频繁运用这些特质，达维镇事件后申请成为罗德岛合作干员，有意远离核心业务。她现协助前期情报搜集，原能力与童年收养经历的联系仍属调查判断。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"顶峰之景","intro":"人的心中总会有无数纷繁之事，但她今天所求的只是最纯粹的风景。"}],"forms":[{"id":"char_4052_surfer","name":"寻澜"}],"source":"https://prts.wiki/w/%E5%AF%BB%E6%BE%9C"},{"id":"char_503_rang","name":"巡林者","en":"Rangers","kind":"operator","region":"rhodes","origin":"未公开","faction":"行动组A4","profession":"狙击","aliases":[],"title":"巡林者的弓术与A4行动组岗位","summary":"巡林者是罗德岛老员工，属于A4行动组，曾游历多个地方，现留舰服从任务调配。他年事已高，仍保有较好的敏捷性，是专业弓手。技艺记录说明，他较擅长主动突袭，会利用环境弥补自身颜色不利于隐蔽的问题。现有档案没有具体列出游历路线或更早时期的完整经历。","focus":"只采用已公开的岗位和技巧，不用年长形象补写未经记载的传奇。","memories":[],"forms":[{"id":"char_503_rang","name":"巡林者"}],"source":"https://prts.wiki/w/%E5%B7%A1%E6%9E%97%E8%80%85"},{"id":"char_198_blackd","name":"讯使","en":"Courier","kind":"operator","region":"kjerag","origin":"谢拉格","faction":"喀兰贸易","profession":"先锋","aliases":[],"title":"讯使的喀兰贸易派遣与识路经验","summary":"讯使出身谢拉格，是喀兰贸易成员，依据公司与罗德岛合作协议外派执行任务。他对地形环境的判断来自长期经验，幼时并不善于识路，曾在外出时被风雪困住，经银灰发现获救。档案将这一经历与后来的经验积累并列记述，未将其环境判断能力解释为先天即可具备。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[{"title":"希瓦艾什的影子","intro":"对讯使而言，忠诚并不只有护卫一种方式。"},{"title":"健步如飞","intro":"雪山上最矫健的依特拉啊，你准备好前往更开阔的天地了吗？"}],"forms":[{"id":"char_198_blackd","name":"讯使"}],"source":"https://prts.wiki/w/%E8%AE%AF%E4%BD%BF"},{"id":"char_173_slchan","name":"崖心","en":"Cliffheart","kind":"operator","region":"kjerag","origin":"谢拉格","faction":"谢拉格","profession":"特种","aliases":["恩希亚"],"title":"崖心的登山技能与外勤运用","summary":"崖心来自谢拉格，在罗德岛接受矿石病治疗并担任干员。她擅长攀岩和登山，能熟练使用工具，反应与耐力测试表现突出。档案说明，她将雪铲、冰凿等器具用于战场，能跨越一般人难以通行的地形；所给材料主要记述专业能力，没有展开完整家庭或政治背景。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"崖上之心","intro":"“上山容易下山难。”"},{"title":"新的高峰","intro":"崖心无时无刻不在思考，她能为哥哥姐姐做些什么，又能为谢拉格做些什么。"}],"forms":[{"id":"char_173_slchan","name":"崖心"}],"source":"https://prts.wiki/w/%E5%B4%96%E5%BF%83"},{"id":"char_345_folnic","name":"亚叶","en":"Folinic","kind":"operator","region":"rhodes","origin":"乌萨斯","faction":"罗德岛","profession":"医疗","aliases":[],"title":"亚叶的医疗学习与战地任务","summary":"亚叶在凯尔希直接关注下完成约两年的学习，取得医疗干员许可，并珍重保存特别制作的结业证明。经过半年的准备训练后，她正式参加战地救护。与普通岗位相比，她会寻找攻击敌人的机会，并携带专门配制的药剂。档案强调她学习细致，也记录了老师对各阶段成绩的持续询问。","focus":"训练、许可与实际战地岗位按阶段叙述，不将师承关系替代完整专业评估。","memories":[{"title":"明日之前","intro":"前进的方法多种多样，亚叶做出了选择。"}],"forms":[{"id":"char_345_folnic","name":"亚叶"}],"source":"https://prts.wiki/w/%E4%BA%9A%E5%8F%B6"},{"id":"char_131_flameb","name":"炎客","en":"Flamebringer","kind":"operator","region":"rhodes","origin":"卡兹戴尔","faction":"罗德岛","profession":"近卫","aliases":[],"title":"炎客的自报履历与作战能力","summary":"炎客自称萨卡兹流浪武士，提供的个人资料只有几名死于其手的人物姓名，其他履历缺失。相关名字与测试表现足以显示其刀术水平，但不能完整重建过往。他平时少言独居，多数同僚对其保持警惕；面对博士时则会明显表达情绪，具体前因仍未在输入中充分说明。","focus":"本条区分已见互动与未知前因，不由敌意推导双方全部历史。","memories":[],"forms":[{"id":"char_131_flameb","name":"炎客"}],"source":"https://prts.wiki/w/%E7%82%8E%E5%AE%A2"},{"id":"char_121_lava","name":"炎熔","en":"Lava","kind":"operator","region":"rhodes","origin":"维多利亚","faction":"行动预备组A1","profession":"术师","aliases":[],"title":"炎熔的家庭来路与训练申请","summary":"炎熔生于伦蒂尼姆普通家庭，是芙蓉的孪生妹妹，因矿石病来到罗德岛。她从小接触贫民及流浪儿童，了解其生活中的困难，更倾向通过直接实践提供帮助。认为投入努力救人值得做，她自愿加入罗德岛训练，现属行动预备组，相关材料记录的是早期学习阶段。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"姐妹","intro":"想不想要有个姐姐？"},{"title":"看护","intro":"到底是谁照顾谁？"}],"forms":[{"id":"char_121_lava","name":"炎熔"},{"id":"char_1011_lava2","name":"炎狱炎熔"}],"source":"https://prts.wiki/w/%E7%82%8E%E7%86%94"},{"id":"char_1011_lava2","name":"炎狱炎熔","en":"Lava the Purgatory","kind":"operator","region":"rhodes","origin":"维多利亚","faction":"罗德岛","profession":"术师","aliases":[],"title":"炎熔的多年训练与技艺研究","summary":"炎熔出生于伦蒂尼姆，是芙蓉的孪生妹妹，感染后在罗德岛生活多年。发现法术潜力后，教官为她安排系统训练，多名术师及精英干员提供过指导。此阶段她持续钻研技艺，不只关注破坏效果，也试图研究法术形式与本源，并通过实际任务了解疾病、战争及自身经历之间的联系。","focus":"采用炎狱阶段的多年训练记录，研究目标不等于相关问题已得到答案。","memories":[{"title":"我们都一样","intro":"友好的种子还会不会发芽？"}],"forms":[{"id":"char_121_lava","name":"炎熔"},{"id":"char_1011_lava2","name":"炎狱炎熔"}],"source":"https://prts.wiki/w/%E7%82%8E%E7%8B%B1%E7%82%8E%E7%86%94"},{"id":"char_337_utage","name":"宴","en":"Utage","kind":"operator","region":"higashi","origin":"东国","faction":"东","profession":"近卫","aliases":[],"title":"宴的游学感染与干员录用","summary":"宴原从东国到龙门游学，卷入感染者事件后患矿石病，依医师建议来到罗德岛。她在评审中显示出较好的战斗潜力，因此获准成为干员，而非最初考虑的非战斗人员。日常仍喜欢饮食、娱乐和时尚，执行任务时态度则显著不同；记录将其生活习惯与作战表现分别描述。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[{"title":"时髦把戏","intro":"宴不太高兴，但在事情结束之前，她是不会让你知道的。"},{"title":"鵺切的故事","intro":"你能相信她只是一位普通的东国女高中生而已吗？"}],"forms":[{"id":"char_337_utage","name":"宴"}],"source":"https://prts.wiki/w/%E5%AE%B4"},{"id":"char_1048_orchd2","name":"焰狐龙梓兰","en":"Violet Mizutsune Orchid","kind":"operator","region":"rhodes","origin":"哥伦比亚","faction":"行动预备组A6","profession":"狙击","aliases":[],"title":"梓兰的狙击转岗与杂志创办","summary":"梓兰继续担任A6队长，也从事人事工作，并创办舰内时尚杂志。她主动申请变更为狙击干员，在保留辅助能力的同时提高了进攻表现，执行任务时常提出建设性建议。所给第一档案以杂志采访开场，确认其专业视角与编辑成果，但未提供采访的完整内容。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[],"forms":[{"id":"char_278_orchid","name":"梓兰"},{"id":"char_1048_orchd2","name":"焰狐龙梓兰"}],"source":"https://prts.wiki/w/%E7%84%B0%E7%8B%90%E9%BE%99%E6%A2%93%E5%85%B0"},{"id":"char_420_flamtl","name":"焰尾","en":"Flametail","kind":"operator","region":"kazimierz","origin":"卡西米尔","faction":"红松骑士团","profession":"先锋","aliases":[],"title":"焰尾的灾后经历与红松领导工作","summary":"焰尾本名索娜，原是卡西米尔普通居民，家乡因天灾及当地贵族疏于保护而毁坏，亲属与旧生活受到重大损失。后来她成为感染者骑士团红松的实际领袖，在卡西米尔合作期间主动联系罗德岛求医。伙伴记有她谈及往事时停顿或落泪的情况，但灾后最初一段经历仍不明确。","focus":"明确灾后过程仍有空白，不以领袖的开朗表现认定过往损失已无影响。","memories":[{"title":"像火一样燃烧","intro":"她或许没有自觉，但她事实上做到了——像火一般燃烧。"}],"forms":[{"id":"char_420_flamtl","name":"焰尾"}],"source":"https://prts.wiki/w/%E7%84%B0%E5%B0%BE"},{"id":"char_1020_reed2","name":"焰影苇草","en":"Reed The Flame Shadow","kind":"operator","region":"victoria","origin":"维多利亚","faction":"塔拉","profession":"医疗","aliases":[],"title":"焰影苇草的撤离与救援行动","summary":"苇草曾在罗德岛维多利亚南部办事处提出撤离，后来重新建立联系。此时她以深池名义带领小股部队，主要救助遭暴力胁迫的塔拉人。为隐瞒身份，她曾申请新武器，工程部按旧装备推测设计；返舰后测试显示，新器材更适合其现阶段技艺，具体原因仍须结合后续记录理解。","focus":"本条采用重新联络后的活动阶段，不将不同深池人员的目标视为一致。","memories":[],"forms":[{"id":"char_261_sddrag","name":"苇草"},{"id":"char_1020_reed2","name":"焰影苇草"}],"source":"https://prts.wiki/w/%E7%84%B0%E5%BD%B1%E8%8B%87%E8%8D%89"},{"id":"char_464_cement","name":"洋灰","en":"Cement","kind":"operator","region":"rim","origin":"雷姆必拓","faction":"雷姆必拓","profession":"重装","aliases":[],"title":"洋灰的工程顾问与矿井避险","summary":"洋灰原名夏娜，是雷姆必拓工程小队负责人，熟悉钻探、掘进和浇筑，现作为非常驻顾问参加罗德岛任务。她具有敏锐嗅觉，曾据岩层异味组织工人避险并重浇安全结构。访舰时，她也表现出对花卉和调香的兴趣，但因工程排期紧张，很快返回雷姆必拓。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"矿井里的太阳","intro":"仅仅依靠专业能力在矿场上站稳脚跟是一件几乎不可能的事情，但是夏娜就想试上这么一次。"}],"forms":[{"id":"char_464_cement","name":"洋灰"}],"source":"https://prts.wiki/w/%E6%B4%8B%E7%81%B0"},{"id":"char_4202_haruka","name":"遥","en":"Haruka","kind":"operator","region":"higashi","origin":"东国","faction":"东","profession":"辅助","aliases":[],"title":"遥的艺人身份与本名登记","summary":"遥本名紫野遥，以羽生萌萌香为艺名在东国南院从事演艺工作。经星熊推荐，她与罗德岛签约，负责对东交流并按本人要求参加部分外勤。参观设施、了解合同后，她选择以本名作为代号，表示希望体验不使用艺名的生活；她仍继续为观众签名，也会以表演安抚就医儿童。","focus":"本名登记不等于终止演艺身份，正文保留她对两种生活方式的明确说明。","memories":[],"forms":[{"id":"char_4202_haruka","name":"遥"}],"source":"https://prts.wiki/w/%E9%81%A5"},{"id":"char_1014_nearl2","name":"耀骑士临光","en":"Nearl the Radiant Knight","kind":"operator","region":"kazimierz","origin":"卡西米尔","faction":"卡西米尔","profession":"近卫","aliases":[],"title":"耀骑士临光的夺冠与地区支援","summary":"临光重返卡西米尔，取得第二十四届骑士特别锦标赛决斗赛冠军后，留下处理后续事务。她以合作干员身份为当地罗德岛办事处提供战术支援，必要时赴其他地区协助。再次归来后，她更换武器，源石技艺也不再只用于治疗，在机动、掩护及歼灭行动中表现出较高水准。","focus":"本条采用再次夺冠后的合作记录，与早期重装干员阶段分别表述。","memories":[{"title":"起点","intro":"现实并非比赛，没有取得绝对胜利的那一天。 "}],"forms":[{"id":"char_148_nearl","name":"临光"},{"id":"char_1014_nearl2","name":"耀骑士临光"}],"source":"https://prts.wiki/w/%E8%80%80%E9%AA%91%E5%A3%AB%E4%B8%B4%E5%85%89"},{"id":"char_4013_kjera","name":"耶拉","en":"Kjera","kind":"operator","region":"kjerag","origin":"谢拉格","faction":"谢拉格","profession":"术师","aliases":[],"title":"耶拉的圣女代表与任务参与","summary":"耶拉以谢拉格圣女侍女长身份代表恩雅加入罗德岛，负责秘密来访的对接，并参加术师任务。日常记录指出，她外表年轻，部分观念却十分古老，也常照顾同行者。结合博士的谢拉格见闻，材料推测其身份不止公开职衔，但所给内容没有直接说明完整真实来历。","focus":"第一档案仅暗示身份另有背景，本条不将暗示扩大为未提供的完整真相。","memories":[{"title":"祂所关心的","intro":"你呀你，希瓦艾什这一家子呀，害苦了你！"}],"forms":[{"id":"char_4013_kjera","name":"耶拉"}],"source":"https://prts.wiki/w/%E8%80%B6%E6%8B%89"},{"id":"char_496_wildmn","name":"野鬃","en":"Wild Mane","kind":"operator","region":"kazimierz","origin":"卡西米尔","faction":"红松骑士团","profession":"先锋","aliases":[],"title":"野鬃的治疗安排与正义号改造","summary":"野鬃本名艾沃娜，是红松骑士团成员，特锦赛及相关事件后加入罗德岛，并接受矿石病治疗。刚到舰上时因伤未愈，暂未获安排工作。其间她主动推动正义骑士号升级，跟进系统及语音功能开发。设备完成后开始提供日常服务，她本人也表示愿意为感染者提供战斗方面的支持。","focus":"治疗休整与提供支援的意愿分别记录，不将未排班解释为已经失去任务资格。","memories":[{"title":"憧憬","intro":"哪一面是真实的他？"}],"forms":[{"id":"char_496_wildmn","name":"野鬃"}],"source":"https://prts.wiki/w/%E9%87%8E%E9%AC%83"},{"id":"char_476_blkngt","name":"夜半","en":"Blacknight","kind":"operator","region":"rim","origin":"雷姆必拓","faction":"雷姆必拓","profession":"先锋","aliases":[],"title":"夜半的驯兽经验与委派合作","summary":"夜半是雷姆必拓赏金猎人，擅长驯兽，曾因委托进入炎国，在尚蜀结识克洛丝。经当地官员介绍，她与罗德岛建立合作，参与炎国周边委派任务。档案同时说明长吻眠兽的习性和相关利用方式，能够辅助理解其驯兽工作，但现有输入没有完整提供她早年的所有委托经历。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[{"title":"荒地生灵","intro":"她不会时时都在，但需要她的时候，她一定会在。"},{"title":"赏金猎人转行后","intro":"自由的人从未停下，不过这一次她心里又多了些甜蜜的牵挂。"}],"forms":[{"id":"char_476_blkngt","name":"夜半"}],"source":"https://prts.wiki/w/%E5%A4%9C%E5%8D%8A"},{"id":"char_502_nblade","name":"夜刀","en":"Yato","kind":"operator","region":"rhodes","origin":"东国","faction":"行动组A4","profession":"先锋","aliases":[],"title":"夜刀的基础干员与组长职责","summary":"夜刀是罗德岛基础干员和行动组长，档案评价她忠诚、可靠，平日沉默，除面具外少有引人注意之处。她对较少受到关注并未表示不满，持续完成分配的任务。凯尔希以组织基石评价其工作，所给材料主要呈现早期任职状态，未展开她的过往经历和后续变化。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"授刀","intro":"要承下夜刀的刀可不容易。"}],"forms":[{"id":"char_502_nblade","name":"夜刀"},{"id":"char_1029_yato2","name":"麒麟R夜刀"}],"source":"https://prts.wiki/w/%E5%A4%9C%E5%88%80"},{"id":"char_164_nightm","name":"夜魔","en":"Nightmare","kind":"operator","region":"victoria","origin":"维多利亚","faction":"维多利亚","profession":"术师","aliases":[],"title":"夜魔的学习背景与特殊监护安排","summary":"夜魔登记姓名为葛罗莉亚，原在维多利亚高校学习医疗法术与心理干预，现于罗德岛相关调理机构任职，并适用由莱娜签字的特殊监护协议。早期诊疗交谈中，她曾明显不安并拒绝回答。花草与香薰有助于交流，在理解治疗目的与保密安排后，她逐渐能够配合访谈。","focus":"采用本人要求的称呼和已记录反应，不依据访谈困难推定未公开诊断。","memories":[],"forms":[{"id":"char_164_nightm","name":"夜魔"}],"source":"https://prts.wiki/w/%E5%A4%9C%E9%AD%94"},{"id":"char_141_nights","name":"夜烟","en":"Haze","kind":"operator","region":"victoria","origin":"维多利亚","faction":"维多利亚","profession":"术师","aliases":[],"title":"夜烟的越狱经历与法术运用","summary":"夜烟出身维多利亚，感染后曾被关入隔离区监狱，多次逃脱后获得自由，以化名辗转加入罗德岛。她能够运用独有黑雾法术，遮蔽视野、攻击目标或强化自身，使用方式较多。输入确认逃离与任职的基本顺序，但对被关押缘由、各次行动及加入前的全部经历没有详细交代。","focus":"本条不由监禁记录推定法律责任，也不补造各次逃离的具体过程。","memories":[{"title":"“猫猫”","intro":"“喵——” 在它们身边，她显得如此放松，惬意，心满意足。"},{"title":"女巫夜话","intro":"翻过炮火和逃亡，用癞皮鳞的叫声写下糖果色的梦，女巫的故事还没有结束呢。"}],"forms":[{"id":"char_141_nights","name":"夜烟"}],"source":"https://prts.wiki/w/%E5%A4%9C%E7%83%9F"},{"id":"char_179_cgbird","name":"夜莺","en":"Nightingale","kind":"operator","region":"kazdel","origin":"卡兹戴尔","faction":"使徒","profession":"医疗","aliases":[],"title":"夜莺的治疗技艺与法术防护","summary":"夜莺是萨卡兹和使徒成员，履历仍有缺失，在罗德岛治疗并提供急救及技艺支援。她不熟悉现代医学理论，笔试表现有限，但对人体构造有深入理解，治愈能力出色，也能建立抵御攻击法术的区域。凯尔希推测这些能力同源，所给记录尚不能证明该判断。","focus":"治愈与防护能力同源尚属推测，需要与已经记录的临床表现分别处理。","memories":[{"title":"蓝色羽毛与歌","intro":"一个看不见自身希望的人，依然希望能给他人带来希望。"}],"forms":[{"id":"char_179_cgbird","name":"夜莺"}],"source":"https://prts.wiki/w/%E5%A4%9C%E8%8E%BA"},{"id":"char_134_ifrit","name":"伊芙利特","en":"Ifrit","kind":"operator","region":"columbia","origin":"未公开","faction":"莱茵生命","profession":"术师","aliases":[],"title":"伊芙利特的转院治疗与监护","summary":"伊芙利特曾是莱茵生命医疗对象，转入罗德岛后仍为重度感染者，由赫默担任医生、监护及担保人。她具有较高源石适应性，使用为其定制的火焰释放设备。早期观察记有冲动、叛逆及较少考虑后果的行为，相关评估认为其心智表现较幼小。进入莱茵前的履历仍未完整公开。","focus":"将患者状态、监护与能力分别呈现，不因强大技艺忽略其年龄和照护需求。","memories":[{"title":"小队长","intro":"她觉得照顾自己的人瘦了，那人却说，是她长高了。"}],"forms":[{"id":"char_134_ifrit","name":"伊芙利特"}],"source":"https://prts.wiki/w/%E4%BC%8A%E8%8A%99%E5%88%A9%E7%89%B9"},{"id":"char_4087_ines","name":"伊内丝","en":"Ines","kind":"operator","region":"kazdel","origin":"卡兹戴尔","faction":"巴别塔","profession":"先锋","aliases":[],"title":"伊内丝的隐匿经历与重新合作","summary":"伊内丝曾为佣兵首领，短期参与卡兹戴尔内战，切尔诺伯格事件时借假死退出公众视野。伦蒂尼姆事件后，她重新与罗德岛接触，在阿斯卡纶担保下签订战略合作条款。失踪期间的经历未能查实，返舰后也不易被追踪，相关档案主要依据重新建立联系后的互动与活动。","focus":"失踪时段仍属未查实经历，不能据重新现身补写完整行动链。","memories":[],"forms":[{"id":"char_4087_ines","name":"伊内丝"}],"source":"https://prts.wiki/w/%E4%BC%8A%E5%86%85%E4%B8%9D"},{"id":"char_355_ethan","name":"伊桑","en":"Ethan","kind":"operator","region":"rhodes","origin":"未公开","faction":"罗德岛","profession":"特种","aliases":[],"title":"伊桑的组织脱离与特种任职","summary":"伊桑曾辗转多个地下感染者组织，后离开整合运动，经审查后进入罗德岛特种小队，擅长潜入和战术侦察。采访记录显示，他喜爱食物，也愿意与人交谈，但谈到过去队友时会用玩笑转移话题。其出生地仍不明确，材料没有补充各次组织转移的完整经过。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"他乡故旧","intro":"一件往事，一位老朋友，或者一段不值一提的经历。对于伊桑来说，过去的生活总让他耿耿于怀。"}],"forms":[{"id":"char_355_ethan","name":"伊桑"}],"source":"https://prts.wiki/w/%E4%BC%8A%E6%A1%91"},{"id":"char_4125_rdoc","name":"医生","en":"Doc","kind":"operator","region":"other","origin":"未知","faction":"彩虹小队","profession":"近卫","aliases":[],"title":"医生的医疗资历与临时合作","summary":"医生本名古斯塔夫，是彩虹小队成员，亲历克里斯达尔事件后登记为罗德岛合作人员。他接受过系统医疗训练，能在诊室与前线提供救护，并使用专门手枪远程注入急救药剂。其临床外知识也获得认可。资料说明，小队只与罗德岛暂时合作，不属于正式雇员，不宜过度安排任务。","focus":"明确暂时合作的人员边界，不用本地任职称谓替代其原有小队身份。","memories":[{"title":"模糊的面容","intro":"一股遗害至今的流毒，一场群体性的谵妄，一名原本与之无关的医生。"}],"forms":[{"id":"char_4125_rdoc","name":"医生"}],"source":"https://prts.wiki/w/%E5%8C%BB%E7%94%9F"},{"id":"char_472_pasngr","name":"异客","en":"Passenger","kind":"operator","region":"sargon","origin":"哥伦比亚","faction":"萨尔贡","profession":"术师","aliases":["艾利奥特"],"title":"异客的研究经历与工程部任职","summary":"异客少年时以优秀成绩提前毕业，获索恩教授提拔为研究助手，随项目进入萨尔贡后失去消息多年。后来他以伊巴特黑市成员身份接触罗德岛，脱离黑市后前来治疗，并在工程部行动。对其自制机械的分析显示，即使缺少先进材料，他仍独立建立了可运行的机械结构。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[],"forms":[{"id":"char_472_pasngr","name":"异客"}],"source":"https://prts.wiki/w/%E5%BC%82%E5%AE%A2"},{"id":"char_155_tiger","name":"因陀罗","en":"Indra","kind":"operator","region":"victoria","origin":"不明","faction":"格拉斯哥帮","profession":"近卫","aliases":[],"title":"因陀罗的战时行动与战后拳馆","summary":"因陀罗长期在街头生活，依靠体格和战斗直觉成为格拉斯哥帮武斗头目。战争期间，她跟随维娜参与典范军行动；战后返回诺伯特区经营拳馆。她还是罗德岛当地办事处联络人之一，参加实战指导，有时为维娜传递消息，继续维持与合作方的联系。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"干员间切磋指南","intro":"从街头混混到优秀干员，需要多几次深呼吸。"}],"forms":[{"id":"char_155_tiger","name":"因陀罗"}],"source":"https://prts.wiki/w/%E5%9B%A0%E9%99%80%E7%BD%97"},{"id":"char_172_svrash","name":"银灰","en":"SilverAsh","kind":"operator","region":"kjerag","origin":"谢拉格","faction":"喀兰贸易","profession":"近卫","aliases":["恩希欧迪斯"],"title":"银灰的早期贸易与战略支援职责","summary":"该早期档案中，银灰任希瓦艾什族长及喀兰贸易董事长，在贸易、外交和战术方面有经验，为罗德岛部分行动提供战略支持。他创办的公司成为谢拉格重要对外窗口，推动当地变化。罗德岛同时认为其具体目的与合作态度尚不明确，因此建议保持审慎，继续核实个人经历。","focus":"以早期董事长时点为范围，不提前加入后续辞任及所有政治计划。","memories":[{"title":"难猜的人","intro":"罕见同类，难逢敌手。"},{"title":"坚固的冰","intro":"永不融化，永不背弃。"}],"forms":[{"id":"char_172_svrash","name":"银灰"},{"id":"char_1045_svash2","name":"凛御银灰"}],"source":"https://prts.wiki/w/%E9%93%B6%E7%81%B0"},{"id":"char_1039_thorn2","name":"引星棘刺","en":"Thorns the Lodestar","kind":"operator","region":"iberia","origin":"伊比利亚","faction":"伊比利亚","profession":"特种","aliases":[],"title":"引星棘刺的船长身份与合作","summary":"棘刺从罗德岛前线干员转为宝宝摇篮号船长，该船兼做探索、科考、捕鳞与运输等业务。他继续与本舰合作，定期获得医疗和物资支持，并提供海洋事务便利及接触伊比利亚偏远聚落的渠道。档案另有船员对维修材料的请愿，记录的是航海阶段的具体管理和设备问题。","focus":"本条采用船长阶段资料，不将航海后身份提前到早期前线履历。","memories":[],"forms":[{"id":"char_293_thorns","name":"棘刺"},{"id":"char_1039_thorn2","name":"引星棘刺"}],"source":"https://prts.wiki/w/%E5%BC%95%E6%98%9F%E6%A3%98%E5%88%BA"},{"id":"char_4010_etlchi","name":"隐德来希","en":"Entelechia","kind":"operator","region":"rhodes","origin":"卡兹戴尔","faction":"罗德岛","profession":"近卫","aliases":[],"title":"隐德来希的情报履历与私人委托","summary":"隐德来希属于卡兹戴尔情报组织玫瑰河畔，曾向巴别塔提供信息。伦蒂尼姆战争期间，她主动联系罗德岛，后以访客身份留舰。档案特别注明双方不存在正式合约关系，合作全部按私人委托处理；所给权限记录仅有对话起始，不能据此确认其全部来意和后续行动。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[],"forms":[{"id":"char_4010_etlchi","name":"隐德来希"}],"source":"https://prts.wiki/w/%E9%9A%90%E5%BE%B7%E6%9D%A5%E5%B8%8C"},{"id":"char_498_inside","name":"隐现","en":"Insider","kind":"operator","region":"laterano","origin":"拉特兰","faction":"拉特兰","profession":"狙击","aliases":[],"title":"隐现的公证所任职与合作方式","summary":"隐现本名里凯莱，是拉特兰公证所执行者，比送葬人具有更长任职资历，依据协议以狙击干员身份协助罗德岛。他自述有民事纠纷处理经验，实际工作也显示出熟练程度。日常观察先认为他温和热心，后来更强调其圆滑和自保倾向；这些评价均未取代正式岗位与任务记录。","focus":"同僚比较属于观察意见，不能据此认定公证所所有执行者具有统一作风。","memories":[{"title":"机密任务","intro":"蛋一枚，砂糖三勺，酵母少许，面粉若干，枫糖两勺。"}],"forms":[{"id":"char_498_inside","name":"隐现"}],"source":"https://prts.wiki/w/%E9%9A%90%E7%8E%B0"},{"id":"char_143_ghost","name":"幽灵鲨","en":"Specter","kind":"operator","region":"aegir","origin":"阿戈尔","faction":"深海猎人","profession":"近卫","aliases":[],"title":"幽灵鲨的接收治疗与近卫任职","summary":"幽灵鲨被罗德岛接收时曾短暂清醒，接受正式医治前即出现严重精神状态不稳定，个人来历调查因而困难。她在破坏硬目标和对抗大型生物方面技巧较强，档案推测与过去作战经验有关。此阶段她担任近卫，日常与同僚接触较少，输入没有完整说明导致当前状态的全部经过。","focus":"本条限定早期近卫档案，不将该状态视为她在后续阶段始终不变。","memories":[{"title":"圣诞快乐！","intro":"一次珍贵的交换礼物的机会，承载一颗真诚的心。她能感受到吗？"},{"title":"我，即是“我”","intro":"一场期待许久却又过分短暂的重逢会面，有千言万语想要倾诉。她想要尽力传达。"}],"forms":[{"id":"char_143_ghost","name":"幽灵鲨"},{"id":"char_1023_ghost2","name":"归溟幽灵鲨"}],"source":"https://prts.wiki/w/%E5%B9%BD%E7%81%B5%E9%B2%A8"},{"id":"char_4185_amoris","name":"祐天寺若麦","en":"Yūtenji Nyamu","kind":"operator","region":"other","origin":"未知","faction":"Ave Mujica","profession":"近卫","aliases":[],"title":"祐天寺若麦的沟通与资料查阅","summary":"祐天寺若麦是乐队鼓手，驻留罗德岛时协助各类沟通事务，也常与澄闪为干员化妆。档案评价她性格率直、受到喜爱，工作之外会花较多时间在资料库了解罗德岛与泰拉。被问是否需要帮助时，她通常笑着拒绝，所给材料没有说明其具体查阅目标。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[],"forms":[{"id":"char_4185_amoris","name":"祐天寺若麦"}],"source":"https://prts.wiki/w/%E7%A5%90%E5%A4%A9%E5%AF%BA%E8%8B%A5%E9%BA%A6"},{"id":"char_2026_yu","name":"余","en":"Yu","kind":"operator","region":"yan","origin":"炎","faction":"炎-岁","profession":"重装","aliases":[],"title":"余的访客登记与烹饪协助","summary":"余是炎国厨师，具有丰富烹饪经验，通过审核后以访客身份驻留罗德岛，探访亲友并协助餐饮工作。登舰后，年为其整备厨房灶台，夕、黍、重岳和令随后聚餐。观察记录说明，多位亲属同时到场曾引起有关人员关注，但此段主要记载准备不同菜品及共同用餐的日常过程。","focus":"以访客和厨师职责为限，不从一次聚餐推定未公开的政治或家族计划。","memories":[{"title":"百年一日","intro":"百年老店的牌匾和楹联，和它的故事一样，都是一日复一日攒出来的。"}],"forms":[{"id":"char_2026_yu","name":"余"}],"source":"https://prts.wiki/w/%E4%BD%99"},{"id":"char_1015_aglna2","name":"予愿安洁莉娜","en":"Angelina the Mellow Wish","kind":"operator","region":"rhodes","origin":"叙拉古","faction":"罗德岛","profession":"特种","aliases":[],"title":"予愿安洁莉娜的信使与术师工作","summary":"安洁莉娜在此阶段已是罗德岛资深信使，足迹覆盖多数已知国家，并以资深术师身份支援行动。档案比较她入职前后表现，认为其源石技艺进步明显，得到多位法术干员注意。现有输入侧重职务与能力的发展，并未逐一列出各国行程、训练课程或每次外勤的具体经过。","focus":"本条采用资深阶段记录，不能据概括性游历履历补造各地事件。","memories":[],"forms":[{"id":"char_291_aglina","name":"安洁莉娜"},{"id":"char_1015_aglna2","name":"予愿安洁莉娜"}],"source":"https://prts.wiki/w/%E4%BA%88%E6%84%BF%E5%AE%89%E6%B4%81%E8%8E%89%E5%A8%9C"},{"id":"char_421_crow","name":"羽毛笔","en":"La Pluma","kind":"operator","region":"bolivar","origin":"玻利瓦尔","faction":"玻利瓦尔","profession":"近卫","aliases":[],"title":"羽毛笔的收养经历与战斗表现","summary":"羽毛笔父亲去世后由潘乔收养，随其辗转至多索雷斯，事件后与龙舌兰来到罗德岛。因背景特殊，组织经过会议审查才批准入职。她日常少主动说话，显得有些迷糊，战斗时却高度集中，服从指挥且通常能完成命令，与平时状态存在明显差异。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"坚韧的羽毛","intro":"女孩相信自己的愿望绝非虚妄，她亦将如羽兽一般搏击长空。"}],"forms":[{"id":"char_421_crow","name":"羽毛笔"}],"source":"https://prts.wiki/w/%E7%BE%BD%E6%AF%9B%E7%AC%94"},{"id":"char_109_fmout","name":"远山","en":"Gitano","kind":"operator","region":"sami","origin":"萨米","faction":"萨米","profession":"术师","aliases":[],"title":"远山的占卜活动与施术限制","summary":"远山来自萨米，从事神秘学活动，擅长塔罗和牌类技巧，没有向同事公开来到罗德岛前的个人经历。档案记载其占卜有较高成功率，也说明她无法直接占卜自己的未来，只能根据预兆准备。战斗中她可激发源石水晶球形成集中攻击，但释放力量后会受到抑制行动的反噬。","focus":"已知能力与限制一并保留，不将占卜表现扩展为可确定所有未来事件。","memories":[{"title":"占卜","intro":"给迷途之人一些无用指点。"}],"forms":[{"id":"char_109_fmout","name":"远山"}],"source":"https://prts.wiki/w/%E8%BF%9C%E5%B1%B1"},{"id":"char_430_fartth","name":"远牙","en":"Fartooth","kind":"operator","region":"kazimierz","origin":"卡西米尔","faction":"红松骑士团","profession":"狙击","aliases":[],"title":"远牙的特锦赛经历与骑士团合作","summary":"远牙本名查丝汀娜，凭特锦赛获得名气，现属感染者组建的红松骑士团。当地风波后，骑士团与罗德岛合作，她也来到本舰接受矿石病治疗并提供战斗支援。接触过程中，同僚多认为她少言、冷静和内敛；这些评价描述其日常表现，不替代竞技与合作经历的具体记录。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[{"title":"容身之所","intro":"闭上眼睛，家乡的风景，我说给你听。"}],"forms":[{"id":"char_430_fartth","name":"远牙"}],"source":"https://prts.wiki/w/%E8%BF%9C%E7%89%99"},{"id":"char_343_tknogi","name":"月禾","en":"Tsukinogi","kind":"operator","region":"higashi","origin":"东国","faction":"东","profession":"辅助","aliases":[],"title":"月禾的信使转职与侦察工作","summary":"月禾曾任东国天灾信使，凭敏锐感官判断细微环境变化，也适合发现隐蔽目标。信使之间跨国交流网络为她提供推荐，使缺少远方人脉的她获得罗德岛岗位。到访后，她重新适应环境并建立关系，继续从事天灾相关事务，档案建议安排侦察和匿踪方向任务。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"寻常夕阳","intro":"我记得离开东国的那天，临走之时，窗外也是这样的夕阳。"}],"forms":[{"id":"char_343_tknogi","name":"月禾"}],"source":"https://prts.wiki/w/%E6%9C%88%E7%A6%BE"},{"id":"char_283_midn","name":"月见夜","en":"Midnight","kind":"operator","region":"rhodes","origin":"东国","faction":"行动预备组A6","profession":"近卫","aliases":[],"title":"月见夜的旧职业与A6录用","summary":"月见夜曾在东国大型男公关俱乐部工作，取得较高营业成绩。作为患者进入罗德岛后，他依本人意愿接受并通过测试，被分配到预备行动组A6。档案记录其说话和举止较浮夸，也有令同伴困扰的行为，但较少造成实际混乱。此段未具体交代其患病经过和此前全部家庭关系。","focus":"旧职业采用事实说明，不以行业背景作道德判断，也不扩写未明家庭经历。","memories":[{"title":"一封家书","intro":"偶尔回一下头，或许不是坏事。"}],"forms":[{"id":"char_283_midn","name":"月见夜"}],"source":"https://prts.wiki/w/%E6%9C%88%E8%A7%81%E5%A4%9C"},{"id":"char_4219_yukari","name":"岳羽由加莉","en":"Yukari Takeba","kind":"operator","region":"other","origin":"未录入","faction":"S.E.E.S.","profession":"辅助","aliases":[],"title":"岳羽由加莉的校园适应记录","summary":"岳羽由加莉的出身尚未录入，客观履历为空，现有档案主要记述她在拉特兰校园的生活。入学后，她很快与班长交换联系方式，向高年级学生了解通学近路，也和小卖部工作人员熟悉起来；随后又参与弓箭社共同练习。相关内容可确认适应过程，尚不足以完整重建原有来历。","focus":"本条依据校园材料整理，不补写输入缺少的原世界背景和事件。","memories":[],"forms":[{"id":"char_4219_yukari","name":"岳羽由加莉"}],"source":"https://prts.wiki/w/%E5%B2%B3%E7%BE%BD%E7%94%B1%E5%8A%A0%E8%8E%89"},{"id":"char_4100_caper","name":"跃跃","en":"Caper","kind":"operator","region":"bolivar","origin":"玻利瓦尔","faction":"玻利瓦尔","profession":"狙击","aliases":[],"title":"跃跃的雇佣经历与舰内行为评估","summary":"跃跃曾在玻利瓦尔冲突地区接受短期雇佣，主动联系办事处并签订外勤合作协议。她喜爱挑战与恶作剧，往往不征求参与者同意，曾骗医疗机器更换语言模块，造成明显困扰。部分同伴认为她缺乏尊重，另一些人虽较宽容，也担忧她未认识到行为后果。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"快乐之地","intro":"跃跃要让多索雷斯人见识见识，什么才是真正的快乐。"}],"forms":[{"id":"char_4100_caper","name":"跃跃"}],"source":"https://prts.wiki/w/%E8%B7%83%E8%B7%83"},{"id":"char_4165_ctrail","name":"云迹","en":"Contrail","kind":"operator","region":"columbia","origin":"哥伦比亚","faction":"哥伦比亚","profession":"特种","aliases":[],"title":"云迹的飞行研究与工程协助","summary":"云迹是哥伦比亚飞行冒险家，曾为实验旅居各地，熟悉飞行动力装置开发和改良，因矿石病来到罗德岛并协助机动装置研发。她不擅长当众发言，一次会议后却提交了附实地照片的详细标识意见。另有干员目击她在甲板上空飞行，记录了其熟练程度及与平常不同的表现。","focus":"正式技术经历与日常观察分层记录，不以交际困难推定工作能力不足。","memories":[{"title":"迁徙前日","intro":"迁徙启程之前，一只羽兽需要得到什么？"}],"forms":[{"id":"char_4165_ctrail","name":"云迹"}],"source":"https://prts.wiki/w/%E4%BA%91%E8%BF%B9"},{"id":"char_219_meteo","name":"陨星","en":"Meteorite","kind":"operator","region":"rhodes","origin":"卡兹戴尔","faction":"罗德岛","profession":"狙击","aliases":[],"title":"陨星的佣兵经历与狙击任职","summary":"陨星曾是守林人组织成员，后来从事自由佣兵工作，其他履历未详。她现为罗德岛狙击干员，使用弩炮提供范围火力。档案将她描述为外表冷淡、言语直接，但实际关心他人，并持续注意萨卡兹相关新闻。现有材料确认职业和部分日常关注，未完整公开早期组织活动。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[{"title":"一星萤火","intro":"那是我们的语言，每个词汇都是怀想，都是希望。"}],"forms":[{"id":"char_219_meteo","name":"陨星"}],"source":"https://prts.wiki/w/%E9%99%A8%E6%98%9F"},{"id":"char_197_poca","name":"早露","en":"Роса","kind":"operator","region":"ursus","origin":"乌萨斯","faction":"乌萨斯学生自治团","profession":"狙击","aliases":[],"title":"早露的学生经历与岗位申请","summary":"早露在切尔诺伯格事变前是中学生和学生会长，之后加入罗德岛后勤部门，工作评价良好，再按本人申请转为前线狙击干员。她出身没落贵族家庭，较快融入舰内生活，日常待人有礼，工作和社交中都表现成熟，所给档案未具体重述事变期间的经历。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"昨天的明天","intro":"总有一天，她希望每个人都能像她那样，勇敢地说出那句话。"}],"forms":[{"id":"char_197_poca","name":"早露"}],"source":"https://prts.wiki/w/%E6%97%A9%E9%9C%B2"},{"id":"char_1044_hsgma2","name":"斩业星熊","en":"Hoshiguma the Breacher","kind":"operator","region":"lungmen","origin":"东国","faction":"龙门近卫局","profession":"重装","aliases":[],"title":"星熊接任督察组长后的合作","summary":"星熊完成东国之行后接任龙门近卫局特别督察组组长，经诗怀雅批准，以个人名义与罗德岛续签合作。她仍承担重装支援，新的衣装、刀与盾主要来自返乡取回的旧物，不完全由升职造成。经本人同意，部分东国早年经历被补入记录，基础档案的战斗经验年限也相应调整。","focus":"依据斩业阶段的岗位与补档情况叙述，不推定全部旧物与经历的具体来源。","memories":[],"forms":[{"id":"char_136_hsguma","name":"星熊"},{"id":"char_1044_hsgma2","name":"斩业星熊"}],"source":"https://prts.wiki/w/%E6%96%A9%E4%B8%9A%E6%98%9F%E7%86%8A"},{"id":"char_459_tachak","name":"战车","en":"Tachanka","kind":"operator","region":"other","origin":"未知","faction":"彩虹小队","profession":"近卫","aliases":[],"title":"战车的合作登记与阵地专长","summary":"战车本名亚历山大·塞纳维耶夫，是彩虹小队成员，瞭望塔33号事件后登记为罗德岛合作人员。他擅长阵地战，以机枪和特殊发射器提供主要火力，性格强韧、爽朗且冷静。与其他队员相同，他的个人记录仍有大量空白，原籍与此前经历不能仅由作战装备推定。","focus":"本条限定合作与能力记录，不将小队未公开背景补成确定史实。","memories":[{"title":"一如既往","intro":"站在这片熟悉又陌生的雪原中央，他始终没法像朋友忠告的那样“不去掺和得太深”。"}],"forms":[{"id":"char_459_tachak","name":"战车"}],"source":"https://prts.wiki/w/%E6%88%98%E8%BD%A6"},{"id":"char_499_kaitou","name":"折光","en":"Diamante","kind":"operator","region":"leithanien","origin":"莱塔尼亚","faction":"莱塔尼亚","profession":"术师","aliases":[],"title":"折光的鉴定师身份与盗窃记录","summary":"海因茨曾长期为莱塔尼亚贵族提供宝石鉴定，折光这一代号又见于多起盗窃预告。记录称盗窃者只以宝石为目标，多次按预告行动且未失手。来到罗德岛后，他继续使用该代号，直到同伴偶然查阅档案才将其与传闻联系；日常中，他通常有求必应，能提出特殊思路。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"被折射的星光","intro":"那些高塔上的家伙已经付出了代价。那之后呢？也许他会开一家宝石鉴定所。"}],"forms":[{"id":"char_499_kaitou","name":"折光"}],"source":"https://prts.wiki/w/%E6%8A%98%E5%85%89"},{"id":"char_4207_branch","name":"折桠","en":"Веточки","kind":"operator","region":"ursus","origin":"乌萨斯","faction":"乌萨斯","profession":"重装","aliases":[],"title":"折桠的矿区工作与感染者救助","summary":"折桠常用名别乔克，曾是乌萨斯远北中心矿区工人，负责清雪、取水、计时敲钟等工作，提醒井下人员避免滞留过久。她的日程还包括采集燃料和处理宿舍积雪。来到罗德岛后，她在治疗同时自愿接受标准强度战斗训练，现以外勤干员身份参加感染者救助。","focus":"以具体劳动日程和现有岗位为范围，不从有限片段补写整个矿区制度。","memories":[{"title":"止痛药","intro":"当她终于走出那片夜色，回头看去，那无法驱离的痛苦竟已是她唯一和最后的依凭。"}],"forms":[{"id":"char_4207_branch","name":"折桠"}],"source":"https://prts.wiki/w/%E6%8A%98%E6%A1%A0"},{"id":"char_195_glassb","name":"真理","en":"Истина","kind":"operator","region":"ursus","origin":"乌萨斯","faction":"乌萨斯学生自治团","profession":"辅助","aliases":[],"title":"真理的学生写作与辅助工作","summary":"真理曾在切尔诺伯格中学就读，多次向源石技艺杂志投稿，熟悉文学与社会学资料。通过罗德岛测试后，她以实习辅助干员参战，也负责信息和材料整理。她性格冷静、略内向，喜欢理论研究及服饰搭配；与学生自治团伙伴交往时，档案又记录到不同于日常的表达方式。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[{"title":"走吧，走吧","intro":"那座城的影子太长，她不得不加快脚步，免得被过去吞没。"},{"title":"再见以前","intro":"……就算真的到了告别的那天，我也会是守到最后的那个人。"}],"forms":[{"id":"char_195_glassb","name":"真理"}],"source":"https://prts.wiki/w/%E7%9C%9F%E7%90%86"},{"id":"char_4204_mantra","name":"真言","en":"Mantra","kind":"operator","region":"rhodes","origin":"萨尔贡","faction":"罗德岛-精英干员","profession":"术师","aliases":[],"title":"真言的通信支援与过度施术记录","summary":"真言受凯尔希邀请加入巴别塔，参与内战后成为罗德岛首批精英干员，长期领导特殊行动第三小队。她与通讯员配合，在通信困难或秘密行动中以技艺协调队伍。住院报告同时记载，过度施术造成脑部疲劳和肌肉异常萎缩，需观察神经风险并安排至少两个月复健。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"无处不在","intro":"嘘，仔细听。"}],"forms":[{"id":"char_4204_mantra","name":"真言"}],"source":"https://prts.wiki/w/%E7%9C%9F%E8%A8%80"},{"id":"char_4000_jnight","name":"正义骑士号","en":"\"Justice Knight\"","kind":"operator","region":"kazimierz","origin":"未公开","faction":"红松骑士团","profession":"狙击","aliases":[],"title":"正义骑士号的改造与服务授权","summary":"正义骑士号原为卡西米尔定制作业平台，经历多次改造，后由梅尔及可露希尔升级核心硬件、存储和语音系统。旧操作系统与数据已损坏，无法恢复。她原属红松骑士团，现获授权供罗德岛使用，除射击援护，也承担浇花、送餐和充电等服务，并经常主动与人员共同活动。","focus":"硬件更新不等于旧数据恢复，原队伍归属与罗德岛使用授权分别记录。","memories":[{"title":"正义号竭诚为您服务！","intro":"“您给正义号的服务打几分呢？”"}],"forms":[{"id":"char_4000_jnight","name":"正义骑士号"}],"source":"https://prts.wiki/w/%E6%AD%A3%E4%B9%89%E9%AA%91%E5%A3%AB%E5%8F%B7"},{"id":"char_4011_lessng","name":"止颂","en":"Lessing","kind":"operator","region":"leithanien","origin":"莱塔尼亚","faction":"莱塔尼亚","profession":"近卫","aliases":[],"title":"止颂的旁听经历与地区合作","summary":"止颂本名莱辛·梅耶尔，是莱塔尼亚路德维格大学旁听生，随黑键来到罗德岛。经充分沟通，他签订合作协议，协助当地行动。舰船停靠期间，他常在训练场独自练习或与人对战，不排斥围观。虽然自称战法普通，旁观者对其巨剑使用仍有疑问，相关评价不能替代完整作战履历。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[{"title":"共同建设乌提卡领","intro":"痛苦使他清醒，所以他将收割机放在一边，向着麦田挥起了自己的巨剑。"}],"forms":[{"id":"char_4011_lessng","name":"止颂"}],"source":"https://prts.wiki/w/%E6%AD%A2%E9%A2%82"},{"id":"char_4054_malist","name":"至简","en":"Minimalist","kind":"operator","region":"sargon","origin":"杜林","faction":"萨尔贡","profession":"术师","aliases":[],"title":"至简的工程任职与设计记录","summary":"至简是杜林族结构工程师和建筑设计师，因重度感染在罗德岛治疗，任职工程部并偶尔参加外勤。他经常提出室内改造意见，对洁净要求较高，也曾多次申请改宿舍。档案认可其简洁有效的设计，同时记录他擅改终端资料后的道歉，说明岗位表现与日常行为仍需分别评估。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"长夏未尽","intro":"“毕竟初来乍到，搞出一些对专业人士来说有点莫名其妙的问题也正常，对吧，斯第奇？”"}],"forms":[{"id":"char_4054_malist","name":"至简"}],"source":"https://prts.wiki/w/%E8%87%B3%E7%AE%80"},{"id":"char_2024_chyue","name":"重岳","en":"Chongyue","kind":"operator","region":"yan","origin":"炎","faction":"炎-岁","profession":"近卫","aliases":[],"title":"重岳的玉门任职与舰上教学","summary":"重岳此前担任玉门武术教官，卸任后为探望年、夕和令来到罗德岛，以访客身份驻留。他提供作战建议，但按凯尔希要求较少直接参加任务。日常训练规律，并曾临时教授武术，要求学员持续练习基本功。不同地区干员在课程中发现熟悉技法，但其完整技艺来源未在此说明。","focus":"学员对武学来源的猜测不当作事实，正文限于已知教学与合作职责。","memories":[{"title":"昔我往矣","intro":"他一直在这里。他真的属于这里吗？"}],"forms":[{"id":"char_2024_chyue","name":"重岳"}],"source":"https://prts.wiki/w/%E9%87%8D%E5%B2%B3"},{"id":"char_1040_blaze2","name":"烛煌","en":"Blaze the Igniting Spark","kind":"operator","region":"rhodes","origin":"炎","faction":"罗德岛-精英干员","profession":"术师","aliases":[],"title":"烛煌的双重职能与战术任务","summary":"烛煌本名顾烛煌，继续使用煌的代号，是罗德岛精英干员。她在此阶段兼任近卫与术师，法术破坏力和作用范围达到较高水平，参与攻坚、防守及突袭，承担部分任务中的战术核心职能。输入主要公开当前任职和能力范围，未完整列出相关变化发生的过程及各次行动。","focus":"本条采用异格阶段的双重职能，不由战力变化推断所有个人经历。","memories":[],"forms":[{"id":"char_017_huang","name":"煌"},{"id":"char_1040_blaze2","name":"烛煌"}],"source":"https://prts.wiki/w/%E7%83%9B%E7%85%8C"},{"id":"char_333_sidero","name":"铸铁","en":"Sideroca","kind":"operator","region":"minos","origin":"米诺斯","faction":"米诺斯","profession":"近卫","aliases":[],"title":"铸铁的佣兵经历与长期雇佣","summary":"铸铁来自米诺斯科林尼亚，成年后以独立佣兵身份离乡，擅长保护目标和押运货物。她在不同城邦工作，接触雅赛努斯与拉刻代蒙的生活，也开始了解米诺斯之外的地区。现与罗德岛签订长期合同，完成内部训练后参加多项任务，仍保有继续探索的计划。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"勤勉之人","intro":"为了应付铸铁，教官团想了个好法子。"}],"forms":[{"id":"char_333_sidero","name":"铸铁"}],"source":"https://prts.wiki/w/%E9%93%B8%E9%93%81"},{"id":"char_1012_skadi2","name":"浊心斯卡蒂","en":"Skadi the Corrupting Heart","kind":"operator","region":"aegir","origin":"阿戈尔","faction":"阿戈尔","profession":"辅助","aliases":[],"title":"浊心形态的生理观察记录","summary":"浊心斯卡蒂的资料并未提供通常的任职履历，而是记录观察者对持续细胞分化等现象的反应。研究人员认为现有生命科学框架难以解释相关状态，并担忧其发展可能影响既有社会与科学尺度。记录带有不确定性，也提到权限限制，尚不能据此整理完整机制或认定唯一发展结局。","focus":"本篇保留独立形态与观察记录的性质，不断言基础斯卡蒂必然出现相同状态。","memories":[],"forms":[{"id":"char_263_skadi","name":"斯卡蒂"},{"id":"char_1012_skadi2","name":"浊心斯卡蒂"}],"source":"https://prts.wiki/w/%E6%B5%8A%E5%BF%83%E6%96%AF%E5%8D%A1%E8%92%82"},{"id":"char_1024_hbisc2","name":"濯尘芙蓉","en":"Hibiscus the Purifier","kind":"operator","region":"rhodes","origin":"维多利亚","faction":"罗德岛","profession":"医疗","aliases":[],"title":"濯尘芙蓉的主治医师任职","summary":"经过系统理论学习和长期临床训练，芙蓉由实习医生转为正式医疗干员，并成为主治医师之一。她积累外勤经验，也研究健康管理和病后护理。档案同时记录待人方式的变化：过去较强硬的要求逐渐减少。相关材料说明她在能力与沟通上均有成长，但未列出所有培训及治疗个案。","focus":"本条限定正式主治阶段，与早期实习医生时期的职务分别说明。","memories":[{"title":"无名之花","intro":"预言中的恶魔来到了夕照区，但是带走了灾难。"}],"forms":[{"id":"char_120_hibisc","name":"芙蓉"},{"id":"char_1024_hbisc2","name":"濯尘芙蓉"}],"source":"https://prts.wiki/w/%E6%BF%AF%E5%B0%98%E8%8A%99%E8%93%89"},{"id":"char_4014_lunacu","name":"子月","en":"Lunacub","kind":"operator","region":"siracusa","origin":"叙拉古","faction":"叙拉古","profession":"狙击","aliases":[],"title":"子月的荒野向导与入职测试","summary":"子月在叙拉古荒野从事狩猎，经企鹅物流介绍进入罗德岛，担任当地野外向导并兼职狙击。她初次接触工作安排时反应有限，对福利则积极关注。虽然未受系统训练，她仍迅速完成测试，自述擅长为兽群解决问题；后勤记录也指出，她在探索仓库时需要遵守安保规则。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[{"title":"与人共舞","intro":"明白的事情她可以教给别人，有些不明白的事情却没人能教得了她。"}],"forms":[{"id":"char_4014_lunacu","name":"子月"}],"source":"https://prts.wiki/w/%E5%AD%90%E6%9C%88"},{"id":"char_278_orchid","name":"梓兰","en":"Orchid","kind":"operator","region":"rhodes","origin":"哥伦比亚","faction":"行动预备组A6","profession":"辅助","aliases":[],"title":"梓兰的编辑经历与A6队长工作","summary":"梓兰曾任哥伦比亚时尚杂志编辑，感染矿石病后进入罗德岛治疗，经本人同意通过测试，担任预备行动组A6队长。她负责小队统筹，并在任务中使用法术支援队员。日常材料强调其常识与管理经验，也记载她经常需要处理成员行为带来的问题，对普通生活仍有期待。","focus":"按早期队长岗位记录职责，不把日常照看他人的比喻当作正式编制。","memories":[{"title":"未完成","intro":"当最后一剪刀落下，她再后悔也没办法了。"},{"title":"A6成立的那一天","intro":"那天晚上，有某种切实存在的东西，真正将A6的几个人联系在了一起。"}],"forms":[{"id":"char_278_orchid","name":"梓兰"},{"id":"char_1048_orchd2","name":"焰狐龙梓兰"}],"source":"https://prts.wiki/w/%E6%A2%93%E5%85%B0"},{"id":"char_4121_zuole","name":"左乐","en":"Zuo Le","kind":"operator","region":"yan","origin":"炎","faction":"炎","profession":"近卫","aliases":[],"title":"左乐的秉烛人职务与驻舰工作","summary":"左乐隶属炎国处理巨兽问题的司岁台，担任秉烛人。为监督相关代理人，他暂驻罗德岛，定期返炎述职，并兼职参加外勤。其初步报告评估本舰常规武装及感染者事务，暂未发现利用岁兽代理人参与冲突的记录。报告结论具有当时调查范围，不能视为所有时期的永久判断。","focus":"调查报告应保留形成时点与观察范围，不将暂未发现等同永不发生。","memories":[],"forms":[{"id":"char_4121_zuole","name":"左乐"}],"source":"https://prts.wiki/w/%E5%B7%A6%E4%B9%90"},{"id":"char_286_cast3","name":"Castle-3","en":"Castle-3","kind":"operator","region":"rhodes","origin":"未公开","faction":"罗德岛","profession":"近卫","aliases":[],"title":"作业平台定制与日常记录","summary":"Castle-3是可露希尔定制的六轮作业平台，在罗德岛具有吉祥物式地位，方正外形给同伴留下可靠印象。档案记载，他接受并乐于继续强化，对预设喜好没有提出异议。机身标记有可能代表杀敌数，但记录仅以疑问提出，来源与含义尚未在所给材料中确认。","focus":"机身刻痕的含义仍是档案中的疑问，不能直接登记为确定战绩或历史。","memories":[{"title":"不朽","intro":"继续奔跑吧，Castle-3。 "}],"forms":[{"id":"char_286_cast3","name":"Castle-3"}],"source":"https://prts.wiki/w/Castle-3"},{"id":"char_4188_confes","name":"CONFESS-47","en":"CONFESS-47","kind":"operator","region":"laterano","origin":"未公开","faction":"拉特兰","profession":"先锋","aliases":[],"title":"CONFESS车的研制与驻舰服务","summary":"CONFESS-47是拉特兰设计的第一代自律告解车，由固定告解室改造，配备动力与可定制语音系统，能够响应移动告解需求。它作为教皇厅礼物，以干员身份定期驻留罗德岛，主要听取告解。到舰后不久即有大量人员使用，其中许多并非拉特兰人，后续访问者为此撰写报告。","focus":"使用人数与来源采用观察记录，不为不同访客统一推定宗教动机。","memories":[{"title":"不是盥洗室！","intro":"一个预料之外的客人，一次不合常规的告解，一条奇怪新规的诞生。"}],"forms":[{"id":"char_4188_confes","name":"CONFESS-47"}],"source":"https://prts.wiki/w/CONFESS-47"},{"id":"char_4093_frston","name":"Friston-3","en":"Friston-3","kind":"operator","region":"rhodes","origin":"未公开","faction":"罗德岛","profession":"重装","aliases":[],"title":"Friston-3的研发与作战应用","summary":"Friston-3是罗德岛智能作业平台团队成立后的首项成果，由可露希尔主持概念设计、组装及测试，依托PRTS更新代码和外部模块。该平台较轻便，性能全面稳定，作为重装参与任务，另配有新型防护设备。核心代码来源、编写思路等尚未向普通干员开放，不能据名称补全相关背景。","focus":"本条采用平台研发记录，不凭名称与其他同名相关人物直接等同。","memories":[],"forms":[{"id":"char_4093_frston","name":"Friston-3"}],"source":"https://prts.wiki/w/Friston-3"},{"id":"char_4227_gallus","name":"GALLUS²","en":"GALLUS²","kind":"operator","region":"rhodes","origin":"未公开","faction":"罗德岛","profession":"术师","aliases":[],"title":"石棺特殊生命与顾问任职","summary":"GALLUS²发现于泽尔格勒石棺核心，主体是由金属、玻璃和机械足构成的小屋，被确认为携带久远记忆的特殊生命。撤离后，它随凯尔希到罗德岛，担任历史、生物顾问及外勤。它经常讲述协助收集样本的往事，但对研究内容的进一步询问反应不耐，相关细节没有完全披露。","focus":"本条依据本阶段客观履历与档案资料一整理，未扩展至未提供的后续剧情。","memories":[],"forms":[{"id":"char_4227_gallus","name":"GALLUS²"}],"source":"https://prts.wiki/w/GALLUS%C2%B2"},{"id":"char_285_medic2","name":"Lancet-2","en":"Lancet-2","kind":"operator","region":"rhodes","origin":"未公开","faction":"罗德岛","profession":"医疗","aliases":[],"title":"Lancet平台的医疗改造与语音设定","summary":"Lancet-2是可露希尔定制改造的雷神六轮平台，设备强化了消毒及源石污染应对，以适应罗德岛的医疗需求。其圆形外观受到干员喜爱，日常语音较消极。相关记录说明，可露希尔设置了偏爱自身的条目，也增加自嘲词句频率，平台因此常对这些设定表达疑问。","focus":"将程序设定与人物化表达分别说明，不由语音表现推定未证实的生命属性。","memories":[{"title":"一个涂鸦","intro":"是最酷的机器人，也是最酷的朋友。"}],"forms":[{"id":"char_285_medic2","name":"Lancet-2"}],"source":"https://prts.wiki/w/Lancet-2"},{"id":"char_4198_christ","name":"Miss.Christine","en":"Miss.Christine","kind":"operator","region":"victoria","origin":"未知","faction":"维多利亚","profession":"术师","aliases":[],"title":"女士的自愿入职申请记录","summary":"Miss.Christine常出现于傀影身旁，现依自身意愿申请成为罗德岛干员，尚未分配具体职务。人事记录描述她递交带爪印申请的经过，以及同僚对原因的询问。关于她可能属于兽主的说法，在履历中仍属推测；当前能确认的是入职行为及与本舰的联系，其他身份细节未获充分说明。","focus":"兽主分类仍为推测，本条不将其作为已经完成核实的种族结论。","memories":[{"title":"很久很久以前","intro":"在这片大地上，曾流传着一个关于“黑猫”的传说。"}],"forms":[{"id":"char_4198_christ","name":"Miss.Christine"}],"source":"https://prts.wiki/w/Miss.Christine"},{"id":"char_4179_monstr","name":"Mon3tr","en":"Mon3tr","kind":"operator","region":"rhodes","origin":"罗德岛","faction":"罗德岛","profession":"医疗","aliases":[],"title":"Mon3tr的重建顾问与医疗工作","summary":"这一阶段的Mon3tr在凯尔希离去后参与罗德岛重建，继承其记忆，担任医疗、工程和外勤特别顾问。她参加医疗会议，主动救治伤员和协助手术，专业能力经部门评估认可。同伴也记录她参与训练和比赛，并认为她需要时间适应记忆及伤痛，未将其等同于凯尔希本人。","focus":"本条对应重建时期档案，不能与凯尔希早期在世篇章合并成同一时点。","memories":[],"forms":[{"id":"char_4179_monstr","name":"Mon3tr"}],"source":"https://prts.wiki/w/Mon3tr"},{"id":"char_4136_phonor","name":"PhonoR-0","en":"PhonoR-0","kind":"operator","region":"rhodes","origin":"未公开","faction":"罗德岛","profession":"辅助","aliases":[],"title":"PhonoR平台的巫术与辅助任务","summary":"PhonoR-0结合工业技术与女妖咒言法器，是罗德岛的辅助作业平台，可便利部署并支持行动。她也作为女妖们的使者与Logos相处，记录相关近况，准备带回河谷。离开伦蒂尼姆前，她参与收尾工作，日常则播放音乐，有时出现女声吟唱，并收到罗德岛合唱团邀请。","focus":"技术用途与传递消息的活动分别记录，不将基本性能评价当作全部作用。","memories":[{"title":"河水流向眼睛","intro":"在与过去相反的方向，河水流淌，她在观看。"}],"forms":[{"id":"char_4136_phonor","name":"PhonoR-0"}],"source":"https://prts.wiki/w/PhonoR-0"},{"id":"char_376_therex","name":"THRM-EX","en":"Thermal-EX","kind":"operator","region":"rhodes","origin":"未公开","faction":"罗德岛","profession":"特种","aliases":[],"title":"THRM-EX的改装与日常表现","summary":"THRM-EX是由梅尔与可露希尔共同定制的作业平台，梅尔主要负责武器和储能装置制作改进。它的外形具有攻击性，但日常主动问候并频繁赞美他人，周围成员对此有不同反应。档案还记录其特别赞赏梅尔改装工作的表现；相关热情属于互动记录，不宜直接据此判断全部偏好。","focus":"本条依据本阶段履历与档案资料整理，未将后续活动经历纳入叙述。","memories":[{"title":"炙热冲击！","intro":"没有最热，只有更热！Thermal-EX一直在变得更热更强的路上！"}],"forms":[{"id":"char_376_therex","name":"THRM-EX"}],"source":"https://prts.wiki/w/THRM-EX"},{"id":"char_4091_ulika","name":"U-Official","en":"U-Official","kind":"operator","region":"rhodes","origin":"未公开","faction":"罗德岛","profession":"辅助","aliases":[],"title":"主播U的传媒合作与背景保留","summary":"主播U曾在移动城市从事直播，经卡达介绍与罗德岛签约，提供直播、主持及传媒咨询服务。她与部分干员此前见过，经历似乎不愉快，当时也未使用现在的名字。本人强烈要求暂缓背景调查，罗德岛已接受；所给记录没有进一步确认旧身份或此前事件的完整细节。","focus":"按档案保留旧身份调查，本条不根据名字暗示补写其完整过往。","memories":[],"forms":[{"id":"char_4091_ulika","name":"U-Official"}],"source":"https://prts.wiki/w/U-Official"},{"id":"char_113_cqbw","name":"W","en":"W","kind":"operator","region":"kazdel","origin":"卡兹戴尔","faction":"巴别塔","profession":"狙击","aliases":[],"title":"W的佣兵与战略合作履历","summary":"W曾以萨卡兹佣兵身份参加卡兹戴尔内战，随后接受塔露拉邀请加入整合运动，在切尔诺伯格与罗德岛发生冲突。她后来单方面终止旧合作，经凯尔希交涉后与罗德岛签订战略条款。早期档案仍缺少部分行动履历，对其前后动机没有定论，并建议普通部门谨慎对待这名合作者。","focus":"沿该基础阶段的公开履历叙述，不用后续揭示代替当时尚未知晓的部分。","memories":[],"forms":[{"id":"char_113_cqbw","name":"W"},{"id":"char_1035_wisdel","name":"维什戴尔"}],"source":"https://prts.wiki/w/W"}];
window.NPC_INDEX = [{"id":"npc-frostnova","name":"霜星","region":"ursus","role":"整合运动雪怪小队队长","summary":"她从乌萨斯的苦难中与爱国者相遇，后来带着雪怪小队为感染者而战。龙门的交锋让她与罗德岛彼此理解，却未能使所有伤害及时停止。","groups":["main_6"],"source":"https://prts.wiki/w/%E9%9C%9C%E6%98%9F","focus":"资料时点以所列篇章为准；本条是主要人物的经历摘要，不是全部生平。","kind":"npc","title":"整合运动雪怪小队队长","origin":"以相关篇章为准","faction":"剧情人物","forms":[],"aliases":[],"memories":[]},{"id":"npc-patriot","name":"爱国者","region":"ursus","role":"整合运动中的前乌萨斯军人","summary":"博卓卡斯替背负萨卡兹与乌萨斯两段历史，也承受失去亲人的伤痛。他保护感染者，却并非始终认同整合运动的所有道路。","groups":["main_7","main_8"],"source":"https://prts.wiki/w/%E7%88%B1%E5%9B%BD%E8%80%85","focus":"资料时点以所列篇章为准；本条是主要人物的经历摘要，不是全部生平。","kind":"npc","title":"整合运动中的前乌萨斯军人","origin":"以相关篇章为准","faction":"剧情人物","forms":[],"aliases":[],"memories":[]},{"id":"npc-mephisto","name":"梅菲斯特","region":"ursus","role":"整合运动行动人员","summary":"童年的暴力与获救后的依恋，让他把安全寄托在少数人身上。与浮士德的关系使这条道路保留一份痛苦的私人尺度：他们曾经想要的生活，并不是后来成为的样子。","groups":["main_5","main_6","main_8"],"source":"https://prts.wiki/w/%E6%A2%85%E8%8F%B2%E6%96%AF%E7%89%B9","focus":"资料时点以所列篇章为准；本条是主要人物的经历摘要，不是全部生平。","kind":"npc","title":"整合运动行动人员","origin":"以相关篇章为准","faction":"剧情人物","forms":[],"aliases":[],"memories":[]},{"id":"npc-faust","name":"浮士德","region":"ursus","role":"整合运动狙击手","summary":"他擅长隐匿与射击，也始终牵挂梅菲斯特。对于组织的行动，他并非没有判断和迟疑。龙门的结局让保护变成一种艰难取舍：当共同生活的愿望已经走向破裂，仍有人希望给另一个人留下离开的机会。","groups":["main_5","main_6"],"source":"https://prts.wiki/w/%E6%B5%AE%E5%A3%AB%E5%BE%B7","focus":"资料时点以所列篇章为准；本条是主要人物的经历摘要，不是全部生平。","kind":"npc","title":"整合运动狙击手","origin":"以相关篇章为准","faction":"剧情人物","forms":[],"aliases":[],"memories":[]},{"id":"npc-alina","name":"阿丽娜","region":"ursus","role":"感染者队伍中的教师","summary":"她与塔露拉等感染者同行，承担着教学和日常照料。她的愿望不宏大，却让“大家怎样活下去”拥有了具体形状。","groups":["main_8"],"source":"https://prts.wiki/w/%E9%98%BF%E4%B8%BD%E5%A8%9C","focus":"资料时点以所列篇章为准；本条是主要人物的经历摘要，不是全部生平。","kind":"npc","title":"感染者队伍中的教师","origin":"以相关篇章为准","faction":"剧情人物","forms":[],"aliases":[],"memories":[]},{"id":"npc-koschei","name":"科西切","region":"ursus","role":"与黑蛇相关的乌萨斯贵族","summary":"他以政治经验与难以摆脱的影响，试图把他人的生命纳入自己的计划。塔露拉的经历因此包含一场对操纵的抵抗。","groups":["main_8"],"source":"https://prts.wiki/w/%E7%A7%91%E8%A5%BF%E5%88%87","focus":"资料时点以所列篇章为准；本条是主要人物的经历摘要，不是全部生平。","kind":"npc","title":"与黑蛇相关的乌萨斯贵族","origin":"以相关篇章为准","faction":"剧情人物","forms":[],"aliases":[],"memories":[]},{"id":"npc-nine","name":"九","region":"lungmen","role":"前龙门近卫局成员","summary":"她曾身处龙门的秩序之中，感染与经历使她走向另一条路。她与陈的联系，也让离开与留下形成了对照。","groups":["main_6","main_9"],"source":"https://prts.wiki/w/%E4%B9%9D","focus":"资料时点以所列篇章为准；本条是主要人物的经历摘要，不是全部生平。","kind":"npc","title":"前龙门近卫局成员","origin":"以相关篇章为准","faction":"剧情人物","forms":[],"aliases":[],"memories":[]},{"id":"npc-wei","name":"魏彦吾","region":"lungmen","role":"龙门的主要管理者","summary":"他以长久的政治经验维护龙门，也把许多决定藏在公开秩序之后。与陈、塔露拉和文月的关系，使城市治理不断遇到无法割裂的私人历史。","groups":["main_6","main_8"],"source":"https://prts.wiki/w/%E9%AD%8F%E5%BD%A6%E5%90%BE","focus":"资料时点以所列篇章为准；本条是主要人物的经历摘要，不是全部生平。","kind":"npc","title":"龙门的主要管理者","origin":"以相关篇章为准","faction":"剧情人物","forms":[],"aliases":[],"memories":[]},{"id":"npc-fumizuki","name":"文月","region":"lungmen","role":"魏彦吾的妻子","summary":"她与魏彦吾共享漫长生活，也关心陈的成长。让年轻人去更远的地方看看，是她给予陈的一种信任。","groups":["act12side","main_8"],"source":"https://prts.wiki/w/%E6%96%87%E6%9C%88","focus":"资料时点以所列篇章为准；本条是主要人物的经历摘要，不是全部生平。","kind":"npc","title":"魏彦吾的妻子","origin":"以相关篇章为准","faction":"剧情人物","forms":[],"aliases":[],"memories":[]},{"id":"npc-ratking","name":"鼠王","region":"lungmen","role":"龙门贫民区的重要人物","summary":"他熟悉龙门街巷中的关系与规则，也曾参与城市的建设。黑白之间的行动，让这座城市的秩序显得复杂而具体。","groups":["act5d0","main_6"],"source":"https://prts.wiki/w/%E9%BC%A0%E7%8E%8B","focus":"资料时点以所列篇章为准；本条是主要人物的经历摘要，不是全部生平。","kind":"npc","title":"龙门贫民区的重要人物","origin":"以相关篇章为准","faction":"剧情人物","forms":[],"aliases":[],"memories":[]},{"id":"npc-emperor","name":"大帝","region":"lungmen","role":"企鹅物流负责人","summary":"他以夸张姿态、音乐和出人意料的行动维持企鹅物流的日常。公司成员在他的安排与纵容中形成紧密关系。","groups":["act5d0"],"source":"https://prts.wiki/w/%E5%A4%A7%E5%B8%9D","focus":"资料时点以所列篇章为准；本条是主要人物的经历摘要，不是全部生平。","kind":"npc","title":"企鹅物流负责人","origin":"以相关篇章为准","faction":"剧情人物","forms":[],"aliases":[],"memories":[]},{"id":"npc-ace","name":"Ace","region":"rhodes","role":"罗德岛精英干员","summary":"他以经验和行动保护同伴，在博士获救后的撤离中承担危险。那份信任后来成为罗德岛记忆的一部分，也让撤离不再只是地图上的路线。","groups":["main_0","main_1"],"source":"https://prts.wiki/w/Ace","focus":"资料时点以所列篇章为准；本条是主要人物的经历摘要，不是全部生平。","kind":"npc","title":"罗德岛精英干员","origin":"以相关篇章为准","faction":"剧情人物","forms":[],"aliases":[],"memories":[]},{"id":"npc-scout","name":"Scout","region":"rhodes","role":"罗德岛精英干员","summary":"他参与切尔诺伯格的营救，清楚行动面临的风险，也知道旧日博士的分量。他的判断始终与队友的生存相连。","groups":["act4d0","act9d0"],"source":"https://prts.wiki/w/Scout","focus":"资料时点以所列篇章为准；本条是主要人物的经历摘要，不是全部生平。","kind":"npc","title":"罗德岛精英干员","origin":"以相关篇章为准","faction":"剧情人物","forms":[],"aliases":[],"memories":[]},{"id":"npc-outcast","name":"Outcast","region":"rhodes","role":"罗德岛精英干员","summary":"她在小丘郡的行动中与苇草等人的命运相遇，面对危险仍坚持保护同伴。她的从容来自长期经历，也让“精英”二字不只表示强大的战斗能力，而包含愿意为别人承担的责任。","groups":["main_9"],"source":"https://prts.wiki/w/Outcast","focus":"资料时点以所列篇章为准；本条是主要人物的经历摘要，不是全部生平。","kind":"npc","title":"罗德岛精英干员","origin":"以相关篇章为准","faction":"剧情人物","forms":[],"aliases":[],"memories":[]},{"id":"npc-misery","name":"Misery","region":"rhodes","role":"罗德岛精英干员","summary":"他以特殊的行动能力参与罗德岛的战地工作。相比完整的个人传记，现有故事更多通过任务呈现他的经验。","groups":["main_10","main_12"],"source":"https://prts.wiki/w/Misery","focus":"资料时点以所列篇章为准；本条是主要人物的经历摘要，不是全部生平。","kind":"npc","title":"罗德岛精英干员","origin":"以相关篇章为准","faction":"剧情人物","forms":[],"aliases":[],"memories":[]},{"id":"npc-theresa","name":"特蕾西娅","region":"kazdel","role":"巴别塔组织的领导者","summary":"她希望萨卡兹能够拥有不必依靠战争延续的生活，也因此让佣兵和流亡者接触到新的关系。她与博士、凯尔希及阿米娅的相遇，使这份愿望进入具体生命。巴别塔的悲剧留下事业，也留下无法轻易和解的选择。","groups":["act9d0","act33side"],"source":"https://prts.wiki/w/%E7%89%B9%E8%95%BE%E8%A5%BF%E5%A8%85","focus":"特蕾西娅本人与干员“魔王”不可直接合并。后者的档案涉及保留其记忆的程序，应区分历史人物与记忆记录。","kind":"npc","title":"巴别塔组织的领导者","origin":"以相关篇章为准","faction":"剧情人物","forms":[],"aliases":[],"memories":[]},{"id":"npc-theresis","name":"特雷西斯","region":"kazdel","role":"卡兹戴尔摄政王","summary":"他与特蕾西娅共享故土，也选择了不同的道路。伦蒂尼姆的战争使他的计划超出卡兹戴尔边界，把民族的创伤与更大规模的政治行动连在一起。他要争取的未来，以及他人要为之支付的代价，需要同时被看见。","groups":["act33side","main_10","main_12"],"source":"https://prts.wiki/w/%E7%89%B9%E9%9B%B7%E8%A5%BF%E6%96%AF","focus":"资料时点以所列篇章为准；本条是主要人物的经历摘要，不是全部生平。","kind":"npc","title":"卡兹戴尔摄政王","origin":"以相关篇章为准","faction":"剧情人物","forms":[],"aliases":[],"memories":[]},{"id":"npc-manfred","name":"曼弗雷德","region":"kazdel","role":"卡兹戴尔军事人员","summary":"他忠于特雷西斯，既参与指挥，也亲自出现在战场。作为执行者，他的职责与个人判断并非完全分离。","groups":["main_10","main_11"],"source":"https://prts.wiki/w/%E6%9B%BC%E5%BC%97%E9%9B%B7%E5%BE%B7","focus":"资料时点以所列篇章为准；本条是主要人物的经历摘要，不是全部生平。","kind":"npc","title":"卡兹戴尔军事人员","origin":"以相关篇章为准","faction":"剧情人物","forms":[],"aliases":[],"memories":[]},{"id":"npc-sanguinarch","name":"血魔大君","region":"kazdel","role":"萨卡兹王庭的血魔领袖","summary":"他把血统、力量与历史带进当下的冲突，对普通人的生命缺乏相同尺度的珍视。主线中的交锋让这种傲慢遭到挑战。","groups":["main_13"],"source":"https://prts.wiki/w/%E8%A1%80%E9%AD%94%E5%A4%A7%E5%90%9B","focus":"资料时点以所列篇章为准；本条是主要人物的经历摘要，不是全部生平。","kind":"npc","title":"萨卡兹王庭的血魔领袖","origin":"以相关篇章为准","faction":"剧情人物","forms":[],"aliases":[],"memories":[]},{"id":"npc-nachzehrer","name":"食腐者之王","region":"kazdel","role":"萨卡兹王庭成员","summary":"王庭的存在使萨卡兹政治不只有一条声音。对于这样的人物，应将言语、阵营与实际行动分别观察，避免只用称号概括。","groups":["main_11","main_14"],"source":"https://prts.wiki/w/%E9%A3%9F%E8%85%90%E8%80%85%E4%B9%8B%E7%8E%8B","focus":"资料时点以所列篇章为准；本条是主要人物的经历摘要，不是全部生平。","kind":"npc","title":"萨卡兹王庭成员","origin":"以相关篇章为准","faction":"剧情人物","forms":[],"aliases":[],"memories":[]},{"id":"npc-confessarius","name":"赦罪师","region":"kazdel","role":"赦罪师体系中的相关人物","summary":"闪灵和夜莺的经历，让这个称号具有沉重的私人意义。他所代表的研究与继承逻辑，把人的身体和意志视为可以安排的材料。她们离开的行动，则使保护与自主成为正面抵抗这套逻辑的道路。","groups":["main_13","main_14"],"source":"https://prts.wiki/w/%E8%B5%A6%E7%BD%AA%E5%B8%88","focus":"资料时点以所列篇章为准；本条是主要人物的经历摘要，不是全部生平。","kind":"npc","title":"赦罪师体系中的相关人物","origin":"以相关篇章为准","faction":"剧情人物","forms":[],"aliases":[],"memories":[]},{"id":"npc-roy","name":"罗伊","region":"kazimierz","role":"无胄盟青金位成员","summary":"他在商业力量与暴力之间工作，以轻松的表面掩住任务的危险。与骑士和其他执行者的关系说明，竞技场并非只有台上规则。那些无法公开呈现的命令，也深刻影响着比赛与人的生存。","groups":["act13side"],"source":"https://prts.wiki/w/%E7%BD%97%E4%BC%8A","focus":"资料时点以所列篇章为准；本条是主要人物的经历摘要，不是全部生平。","kind":"npc","title":"无胄盟青金位成员","origin":"以相关篇章为准","faction":"剧情人物","forms":[],"aliases":[],"memories":[]},{"id":"npc-monique","name":"莫妮克","region":"kazimierz","role":"无胄盟青金位成员","summary":"她与罗伊同属无胄盟的行动网络，擅长以精确而致命的方式处理目标。此处保留任务叙事的边界，不为档案未详述的私人生活补写结论。","groups":["act13side"],"source":"https://prts.wiki/w/%E8%8E%AB%E5%A6%AE%E5%85%8B","focus":"资料时点以所列篇章为准；本条是主要人物的经历摘要，不是全部生平。","kind":"npc","title":"无胄盟青金位成员","origin":"以相关篇章为准","faction":"剧情人物","forms":[],"aliases":[],"memories":[]},{"id":"npc-bloodknight","name":"血骑士","region":"kazimierz","role":"感染者竞技骑士","summary":"狄开俄波利斯成为感染者骑士无法绕开的名字。他的比赛承载个人意志，也被卷入制度与公众形象的运作。与耀骑士相遇时，战斗不只决定胜负，还使观众不得不看见感染者骑士所面对的处境。","groups":["act13side"],"source":"https://prts.wiki/w/%E8%A1%80%E9%AA%91%E5%A3%AB","focus":"资料时点以所列篇章为准；本条是主要人物的经历摘要，不是全部生平。","kind":"npc","title":"感染者竞技骑士","origin":"以相关篇章为准","faction":"剧情人物","forms":[],"aliases":[],"memories":[]},{"id":"npc-toland","name":"托兰","region":"kazimierz","role":"在大骑士领活动的赏金猎人","summary":"他以局外人的姿态参与大骑士领的故事，熟悉规则，也懂得规则之外的交易。与感染者骑士的接触，使合作与利用不再容易划清。","groups":["act13side"],"source":"https://prts.wiki/w/%E6%89%98%E5%85%B0","focus":"资料时点以所列篇章为准；本条是主要人物的经历摘要，不是全部生平。","kind":"npc","title":"在大骑士领活动的赏金猎人","origin":"以相关篇章为准","faction":"剧情人物","forms":[],"aliases":[],"memories":[]},{"id":"npc-ratatos","name":"菈塔托丝","region":"kjerag","role":"布朗陶家族家主","summary":"她经营布朗陶家族，也清楚银灰推动的变革将影响自己和谢拉格。她并非没有见识的守旧者，而是在局势中维护家族、重新判断合作条件的人。","groups":["act14side"],"source":"https://prts.wiki/w/%E8%8F%88%E5%A1%94%E6%89%98%E4%B8%9D","focus":"资料时点以所列篇章为准；本条是主要人物的经历摘要，不是全部生平。","kind":"npc","title":"布朗陶家族家主","origin":"以相关篇章为准","faction":"剧情人物","forms":[],"aliases":[],"memories":[]},{"id":"npc-sciurus","name":"休露丝","region":"kjerag","role":"布朗陶家族成员","summary":"围绕她的事件使政治不再只是家主间的谈判，还包括那些无法决定棋局、却要承受其结果的家人。","groups":["act14side"],"source":"https://prts.wiki/w/%E4%BC%91%E9%9C%B2%E4%B8%9D","focus":"资料时点以所列篇章为准；本条是主要人物的经历摘要，不是全部生平。","kind":"npc","title":"布朗陶家族成员","origin":"以相关篇章为准","faction":"剧情人物","forms":[],"aliases":[],"memories":[]},{"id":"npc-arctosz","name":"阿克托斯","region":"kjerag","role":"佩尔罗契家族家主","summary":"他依赖家族与传统建立自己的位置，也在谢拉格的变革中作出激烈回应。对于他的失败或局限，需要放回具体博弈，而不是把整个传统都缩成一个人的性格。","groups":["act14side"],"source":"https://prts.wiki/w/%E9%98%BF%E5%85%8B%E6%89%98%E6%96%AF","focus":"资料时点以所列篇章为准；本条是主要人物的经历摘要，不是全部生平。","kind":"npc","title":"佩尔罗契家族家主","origin":"以相关篇章为准","faction":"剧情人物","forms":[],"aliases":[],"memories":[]},{"id":"npc-kristen","name":"克丽斯腾","region":"columbia","role":"莱茵生命总辖","summary":"父母的往事与她对天空的执着相连，莱茵生命则成为推进探索的组织。她最终突破已知边界，也使同伴必须承担计划的后果。","groups":["act25side"],"source":"https://prts.wiki/w/%E5%85%8B%E4%B8%BD%E6%96%AF%E8%85%BE","focus":"资料时点以所列篇章为准；本条是主要人物的经历摘要，不是全部生平。","kind":"npc","title":"莱茵生命总辖","origin":"以相关篇章为准","faction":"剧情人物","forms":[],"aliases":[],"memories":[]},{"id":"npc-parvis","name":"帕尔维斯","region":"columbia","role":"莱茵生命研究人员","summary":"他以资深研究者的身份影响莱茵生命的工作，也参与那些让赫默与塞雷娅难以接受的实验。学识并没有自动生成对参与者的尊重。围绕他的冲突，使研究伦理从理念变成必须处理的实际责任。","groups":["act19side","act25side"],"source":"https://prts.wiki/w/%E5%B8%95%E5%B0%94%E7%BB%B4%E6%96%AF","focus":"资料时点以所列篇章为准；本条是主要人物的经历摘要，不是全部生平。","kind":"npc","title":"莱茵生命研究人员","origin":"以相关篇章为准","faction":"剧情人物","forms":[],"aliases":[],"memories":[]},{"id":"npc-friston","name":"弗里斯顿","region":"columbia","role":"保存者相关设施的守望者","summary":"在《孤星》的深处，博士与凯尔希面对一份来自遥远过去的记忆。弗里斯顿守望的设施与使命，使泰拉的来路突然显出更大的尺度。","groups":["act25side"],"source":"https://prts.wiki/w/%E5%BC%97%E9%87%8C%E6%96%AF%E9%A1%BF","focus":"资料时点以所列篇章为准；本条是主要人物的经历摘要，不是全部生平。","kind":"npc","title":"保存者相关设施的守望者","origin":"以相关篇章为准","faction":"剧情人物","forms":[],"aliases":[],"memories":[]},{"id":"npc-sicilia","name":"西西里夫人","region":"siracusa","role":"叙拉古家族体系的重要管理者","summary":"她站在叙拉古诸家族的关系之上，对新城和年轻人的尝试也保持自己的判断。她并非只存在于故事之外的权威，新的道路仍需与她代表的力量相处。","groups":["act21side"],"source":"https://prts.wiki/w/%E8%A5%BF%E8%A5%BF%E9%87%8C%E5%A4%AB%E4%BA%BA","focus":"资料时点以所列篇章为准；本条是主要人物的经历摘要，不是全部生平。","kind":"npc","title":"叙拉古家族体系的重要管理者","origin":"以相关篇章为准","faction":"剧情人物","forms":[],"aliases":[],"memories":[]},{"id":"npc-zaro","name":"扎罗","region":"siracusa","role":"参与叙拉古事务的狼主","summary":"他以近乎游戏的态度介入家族与城市的冲突，使人的努力不断遇到另一种力量尺度。拉普兰德与他的关系揭开新的方向。","groups":["act21side"],"source":"https://prts.wiki/w/%E6%89%8E%E7%BD%97","focus":"资料时点以所列篇章为准；本条是主要人物的经历摘要，不是全部生平。","kind":"npc","title":"参与叙拉古事务的狼主","origin":"以相关篇章为准","faction":"剧情人物","forms":[],"aliases":[],"memories":[]},{"id":"npc-bernardo","name":"贝纳尔多","region":"siracusa","role":"贝洛内家族家主","summary":"他既属于家族政治，也试着推动超出旧规则的计划。莱昂图索的未来与他的决定紧密相连。围绕他的故事，让父辈的控制、期待与牺牲纠缠在一起，无法只用成败解释。","groups":["act21side"],"source":"https://prts.wiki/w/%E8%B4%9D%E7%BA%B3%E5%B0%94%E5%A4%9A","focus":"资料时点以所列篇章为准；本条是主要人物的经历摘要，不是全部生平。","kind":"npc","title":"贝洛内家族家主","origin":"以相关篇章为准","faction":"剧情人物","forms":[],"aliases":[],"memories":[]},{"id":"npc-alberto","name":"阿尔贝托","region":"siracusa","role":"萨卢佐家族家主","summary":"他处理冲突的方式来自叙拉古长期的家族秩序，也用同样的尺度要求后辈。德克萨斯等人与旧日关系的碰撞，使这种规则的压迫变得具体。一个人怎样离开过去，往往要先面对过去仍在发号施令的人。","groups":["act21side"],"source":"https://prts.wiki/w/%E9%98%BF%E5%B0%94%E8%B4%9D%E6%89%98","focus":"资料时点以所列篇章为准；本条是主要人物的经历摘要，不是全部生平。","kind":"npc","title":"萨卢佐家族家主","origin":"以相关篇章为准","faction":"剧情人物","forms":[],"aliases":[],"memories":[]},{"id":"npc-kreide","name":"白垩","region":"leithanien","role":"莱塔尼亚感染者音乐人","summary":"他希望照顾亲人，也珍视演奏与相遇的时光。与黑键的友谊让音乐暂时脱离权力的用途，随后发生的剥夺则为两人的相遇留下无法补回的位置。","groups":["act18side"],"source":"https://prts.wiki/w/%E7%99%BD%E5%9E%A9","focus":"资料时点以所列篇章为准；本条是主要人物的经历摘要，不是全部生平。","kind":"npc","title":"莱塔尼亚感染者音乐人","origin":"以相关篇章为准","faction":"剧情人物","forms":[],"aliases":[],"memories":[]},{"id":"npc-witchking","name":"巫王","region":"leithanien","role":"莱塔尼亚的前统治者","summary":"他的统治把音乐、源石技艺与权力高度结合。名义上过去的时代，仍通过研究、记忆与追随者影响后来的人。","groups":["act18side","act29side"],"source":"https://prts.wiki/w/%E5%B7%AB%E7%8E%8B","focus":"资料时点以所列篇章为准；本条是主要人物的经历摘要，不是全部生平。","kind":"npc","title":"莱塔尼亚的前统治者","origin":"以相关篇章为准","faction":"剧情人物","forms":[],"aliases":[],"memories":[]},{"id":"npc-twins","name":"双子女皇","region":"leithanien","role":"莱塔尼亚两位统治者的合称","summary":"推翻巫王之后，双子女皇成为莱塔尼亚政治与艺术秩序的重要中心。赞歌可以庆贺时代变化，个人仍可能被旧日遗产与新权力卷入。","groups":["act29side"],"source":"https://prts.wiki/w/%E5%8F%8C%E5%AD%90%E5%A5%B3%E7%9A%87","focus":"资料时点以所列篇章为准；本条是主要人物的经历摘要，不是全部生平。","kind":"npc","title":"莱塔尼亚两位统治者的合称","origin":"以相关篇章为准","faction":"剧情人物","forms":[],"aliases":[],"memories":[]},{"id":"npc-andoain","name":"安多恩","region":"laterano","role":"寻路者的带领者","summary":"他在圣城之外见过苦难，开始追问为何拉特兰的庇护不能分享给更多人。对往事的不同理解，使他与昔日伙伴再次相遇。","groups":["act16side"],"source":"https://prts.wiki/w/%E5%AE%89%E5%A4%9A%E6%81%A9","focus":"资料时点以所列篇章为准；本条是主要人物的经历摘要，不是全部生平。","kind":"npc","title":"寻路者的带领者","origin":"以相关篇章为准","faction":"剧情人物","forms":[],"aliases":[],"memories":[]},{"id":"npc-cecilia","name":"塞茜莉亚","region":"laterano","role":"身世涉及两族关系的儿童","summary":"她的身世使萨科塔与萨卡兹的边界成为眼前的问题。对于她，首先需要的并非替圣城回答所有历史，而是告别母亲、得到照顾并继续长大。艾泽尔握住她的手，为抽象争论打开了一条具体道路。","groups":["act16side"],"source":"https://prts.wiki/w/%E5%A1%9E%E8%8C%9C%E8%8E%89%E4%BA%9A","focus":"资料时点以所列篇章为准；本条是主要人物的经历摘要，不是全部生平。","kind":"npc","title":"身世涉及两族关系的儿童","origin":"以相关篇章为准","faction":"剧情人物","forms":[],"aliases":[],"memories":[]},{"id":"npc-pope","name":"伊万杰利斯塔十一世","region":"laterano","role":"拉特兰教宗","summary":"与安多恩的相遇，将信仰、共同体与未来的问题推到台前。稳固的权威并不意味着已经拥有所有答案，守护也需要承认边界之外的人。","groups":["act16side"],"source":"https://prts.wiki/w/%E4%BC%8A%E4%B8%87%E6%9D%B0%E5%88%A9%E6%96%AF%E5%A1%94%E5%8D%81%E4%B8%80%E4%B8%96","focus":"资料时点以所列篇章为准；本条是主要人物的经历摘要，不是全部生平。","kind":"npc","title":"拉特兰教宗","origin":"以相关篇章为准","faction":"剧情人物","forms":[],"aliases":[],"memories":[]},{"id":"npc-dario","name":"达里奥","region":"iberia","role":"伊比利亚审判官","summary":"他以严厉训练艾丽妮，也深知海岸威胁的重量。面对深海与黄金时代的遗留，他仍将职责落实为行动。","groups":["act18d3","act17side"],"source":"https://prts.wiki/w/%E8%BE%BE%E9%87%8C%E5%A5%A5","focus":"资料时点以所列篇章为准；本条是主要人物的经历摘要，不是全部生平。","kind":"npc","title":"伊比利亚审判官","origin":"以相关篇章为准","faction":"剧情人物","forms":[],"aliases":[],"memories":[]},{"id":"npc-alfonso","name":"阿方索","region":"iberia","role":"愚人号舰长","summary":"他与愚人号及伊比利亚黄金时代相连，长期守望使荣誉与执念难以分开。深海猎人的到来迫使旧日力量面对当下威胁。读他的故事，也是在读一个时代如何被记住，又如何仍需接受现实。","groups":["act17side"],"source":"https://prts.wiki/w/%E9%98%BF%E6%96%B9%E7%B4%A2","focus":"资料时点以所列篇章为准；本条是主要人物的经历摘要，不是全部生平。","kind":"npc","title":"愚人号舰长","origin":"以相关篇章为准","faction":"剧情人物","forms":[],"aliases":[],"memories":[]},{"id":"npc-garcia","name":"加西亚","region":"iberia","role":"愚人号相关人员","summary":"加西亚与阿方索共同留在愚人号的故事里，旧日职责与漫长守望塑造了彼此关系。曾经的生活无法原样恢复，仍有人试着维护其意义。","groups":["act17side"],"source":"https://prts.wiki/w/%E5%8A%A0%E8%A5%BF%E4%BA%9A","focus":"资料时点以所列篇章为准；本条是主要人物的经历摘要，不是全部生平。","kind":"npc","title":"愚人号相关人员","origin":"以相关篇章为准","faction":"剧情人物","forms":[],"aliases":[],"memories":[]},{"id":"npc-quintus","name":"昆图斯","region":"iberia","role":"深海教会相关人员","summary":"作为深海教会相关人物，他用不同于审判庭的语言回应海岸居民的恐惧。承诺与侵蚀交织，使人们需要判断所谓救赎将把自己带向何处。《覆潮之下》中的冲突把这些选择置于具体危机中。","groups":["act18d3"],"source":"https://prts.wiki/w/%E6%98%86%E5%9B%BE%E6%96%AF","focus":"资料时点以所列篇章为准；本条是主要人物的经历摘要，不是全部生平。","kind":"npc","title":"深海教会相关人员","origin":"以相关篇章为准","faction":"剧情人物","forms":[],"aliases":[],"memories":[]},{"id":"npc-tiago","name":"蒂亚戈","region":"iberia","role":"格兰法洛居民","summary":"他与乔迪的成长、当地人的日常以及灯塔记忆相连。面对重新靠近的海洋，过去的知识与现在的生活一起受到考验。他让伊比利亚故事保留一个普通家庭和社区的尺度。","groups":["act17side"],"source":"https://prts.wiki/w/%E8%92%82%E4%BA%9A%E6%88%88","focus":"资料时点以所列篇章为准；本条是主要人物的经历摘要，不是全部生平。","kind":"npc","title":"格兰法洛居民","origin":"以相关篇章为准","faction":"剧情人物","forms":[],"aliases":[],"memories":[]},{"id":"npc-herman","name":"赫尔曼","region":"siesta","role":"汐斯塔管理者","summary":"他在节庆繁荣与火山威胁之间管理汐斯塔，也面对女儿锡兰对家乡的关切。城市的未来并非只是一项技术安排，还涉及居民如何继续生活。与锡兰的关系，让这种职责同时拥有家庭的重量。","groups":["act3d0"],"source":"https://prts.wiki/w/%E8%B5%AB%E5%B0%94%E6%9B%BC","focus":"资料时点以所列篇章为准；本条是主要人物的经历摘要，不是全部生平。","kind":"npc","title":"汐斯塔管理者","origin":"以相关篇章为准","faction":"剧情人物","forms":[],"aliases":[],"memories":[]},{"id":"npc-candela","name":"坎黛拉","region":"bolivar","role":"多索雷斯市长","summary":"她熟悉利益与政治，试图让一座旅游城市在冲突之中持续运转。繁荣是她的成果，也包含明确取舍。陈的到访提供了另一种观看，使城市的务实治理与它无法遮蔽的战争背景同时显现。","groups":["act12side"],"source":"https://prts.wiki/w/%E5%9D%8E%E9%BB%9B%E6%8B%89","focus":"资料时点以所列篇章为准；本条是主要人物的经历摘要，不是全部生平。","kind":"npc","title":"多索雷斯市长","origin":"以相关篇章为准","faction":"剧情人物","forms":[],"aliases":[],"memories":[]},{"id":"npc-ernesto","name":"埃内斯托","region":"bolivar","role":"潘乔之子","summary":"他与父亲潘乔的关系，把多索雷斯的危机带回个人生活。继承故土的记忆，并不意味着必须重复上一代的行动。他需要判断自己愿意承担什么，也需要从他人的期待中走出自己的方向。","groups":["act12side"],"source":"https://prts.wiki/w/%E5%9F%83%E5%86%85%E6%96%AF%E6%89%98","focus":"资料时点以所列篇章为准；本条是主要人物的经历摘要，不是全部生平。","kind":"npc","title":"潘乔之子","origin":"以相关篇章为准","faction":"剧情人物","forms":[],"aliases":[],"memories":[]},{"id":"npc-pancho","name":"潘乔","region":"bolivar","role":"玻利瓦尔相关军事人员","summary":"他无法把玻利瓦尔的历史与个人选择分开，对多索雷斯的繁华抱有强烈判断。他采取的行动使城市的平静破裂，也把埃内斯托卷入其中。","groups":["act12side"],"source":"https://prts.wiki/w/%E6%BD%98%E4%B9%94","focus":"资料时点以所列篇章为准；本条是主要人物的经历摘要，不是全部生平。","kind":"npc","title":"玻利瓦尔相关军事人员","origin":"以相关篇章为准","faction":"剧情人物","forms":[],"aliases":[],"memories":[]},{"id":"npc-du","name":"杜遥夜","region":"yan","role":"行裕物流的经营者","summary":"她的行动与镖局、家族和地方关系相连。旧怨与新局使她必须判断合作、信任与自身责任。《将进酒》因此不仅有古老存在的棋局，也有普通人为了守住生活而作出的决定。","groups":["act15side"],"source":"https://prts.wiki/w/%E6%9D%9C%E9%81%A5%E5%A4%9C","focus":"资料时点以所列篇章为准；本条是主要人物的经历摘要，不是全部生平。","kind":"npc","title":"行裕物流的经营者","origin":"以相关篇章为准","faction":"剧情人物","forms":[],"aliases":[],"memories":[]},{"id":"npc-liang","name":"梁洵","region":"yan","role":"尚蜀知府","summary":"他带着炎的制度与职责参与地方事务，也必须面对巨兽相关事件中的特殊情况。规则无法脱离具体的人而运作。围绕尚蜀的故事，使他的判断不断在政治、地方关系与民生之间落地。","groups":["act15side"],"source":"https://prts.wiki/w/%E6%A2%81%E6%B4%B5","focus":"资料时点以所列篇章为准；本条是主要人物的经历摘要，不是全部生平。","kind":"npc","title":"尚蜀知府","origin":"以相关篇章为准","faction":"剧情人物","forms":[],"aliases":[],"memories":[]},{"id":"npc-ning","name":"宁辞秋","region":"yan","role":"参与地方事务的炎国官员","summary":"她作为炎的官员参与尚蜀等相关事务，既理解制度要求，也需要在复杂关系中判断现实。与梁洵等人的往来，为宏大的政治背景增加了日常尺度。","groups":["act15side"],"source":"https://prts.wiki/w/%E5%AE%81%E8%BE%9E%E7%A7%8B","focus":"资料时点以所列篇章为准；本条是主要人物的经历摘要，不是全部生平。","kind":"npc","title":"参与地方事务的炎国官员","origin":"以相关篇章为准","faction":"剧情人物","forms":[],"aliases":[],"memories":[]},{"id":"npc-taihe","name":"太合","region":"yan","role":"炎国肃政院副监察御史","summary":"他参与围绕岁的监察事务，也与左乐等后来者的工作相连。处理古老存在，并不只是确认力量是否受控，还涉及人在其间怎样生活。","groups":["main_6","act15side","act23side"],"source":"https://prts.wiki/w/%E5%A4%AA%E5%90%88","focus":"资料时点以所列篇章为准；本条是主要人物的经历摘要，不是全部生平。","kind":"npc","title":"炎国肃政院副监察御史","origin":"以相关篇章为准","faction":"剧情人物","forms":[],"aliases":[],"memories":[]},{"id":"npc-sponsor","name":"老商人","region":"yan","role":"《怀黍离》中的年迈商人","summary":"《怀黍离》中的年迈商人把经营的经验带入对共赢的追问。他不能走遍所有地方，却将未完成的问题交给拥有更多时间的人。","groups":["act31side"],"source":"https://prts.wiki/w/%E8%80%81%E5%95%86%E4%BA%BA","focus":"资料时点以所列篇章为准；本条是主要人物的经历摘要，不是全部生平。","kind":"npc","title":"《怀黍离》中的年迈商人","origin":"以相关篇章为准","faction":"剧情人物","forms":[],"aliases":[],"memories":[]},{"id":"npc-dukewellington","name":"威灵顿公爵","region":"victoria","role":"维多利亚公爵","summary":"他与深池等力量的关系，使塔拉问题、地方战争与维多利亚大局相互连接。对于被卷入其中的普通人，这些布局最终以撤离、伤亡和失去家园的方式出现。","groups":["main_9","act22side"],"source":"https://prts.wiki/w/%E5%A8%81%E7%81%B5%E9%A1%BF%E5%85%AC%E7%88%B5","focus":"资料时点以所列篇章为准；本条是主要人物的经历摘要，不是全部生平。","kind":"npc","title":"维多利亚公爵","origin":"以相关篇章为准","faction":"剧情人物","forms":[],"aliases":[],"memories":[]},{"id":"npc-mandragora","name":"蔓德拉","region":"victoria","role":"深池行动人员","summary":"她以激烈方式参与深池行动，所背负的地域与身份处境使她的愤怒有其来路。她给别人造成的伤害也不能因此消失。","groups":["main_9"],"source":"https://prts.wiki/w/%E6%9B%BC%E5%BE%B7%E6%8B%89","focus":"资料时点以所列篇章为准；本条是主要人物的经历摘要，不是全部生平。","kind":"npc","title":"深池行动人员","origin":"以相关篇章为准","faction":"剧情人物","forms":[],"aliases":[],"memories":[]},{"id":"npc-lastknight","name":"最后的骑士","region":"iberia","role":"深海相关分支叙事人物","summary":"他以骑士之名出现在深海相关叙事中，执念与身份经历变化。关于他的故事包含集成战略的分支语境，因此本条只作主题入口，不将每一条结局合并为唯一历史，也不把他与其他称号相近的人混为一谈。","groups":[],"source":"https://prts.wiki/w/%E6%9C%80%E5%90%8E%E7%9A%84%E9%AA%91%E5%A3%AB","focus":"此人物的材料较分散，部分出现于特殊行动或分支叙事；未将不同分支合并为连续生平。","kind":"npc","title":"深海相关分支叙事人物","origin":"以相关篇章为准","faction":"剧情人物","forms":[],"aliases":[],"memories":[]},{"id":"npc-cannott","name":"坎诺特","region":"sami","role":"跨地区活动的商人","summary":"他穿行于不同地区与探索故事，携带货物，也带来对世界的独特观察。一个商人的出现，往往意味着道路仍有人行走、资源仍在交换。","groups":[],"source":"https://prts.wiki/w/%E5%9D%8E%E8%AF%BA%E7%89%B9","focus":"此人物的材料较分散，部分出现于特殊行动或分支叙事；未将不同分支合并为连续生平。","kind":"npc","title":"跨地区活动的商人","origin":"以相关篇章为准","faction":"剧情人物","forms":[],"aliases":[],"memories":[]},{"id":"npc-sharp","name":"锋刃","region":"rhodes","role":"罗德岛精英干员","summary":"他以作战经验和明确的保护职责参与行动。《风雪过境》中，他在谢拉格的博弈之外提供具体保障，也与锏相遇。","groups":["act14side","act30side"],"source":"https://prts.wiki/w/Sharp","focus":"资料时点以所列篇章为准；本条是主要人物的经历摘要，不是全部生平。","kind":"npc","title":"罗德岛精英干员","origin":"以相关篇章为准","faction":"剧情人物","forms":[],"aliases":[],"memories":[]},{"id":"npc-stormeye","name":"风暴眼","region":"rhodes","role":"罗德岛精英干员","summary":"他通过罗德岛的支援与特殊行动系统进入读者视野。现有叙事并未为他提供与主角等量的个人传记。","groups":[],"source":"https://prts.wiki/w/Stormeye","focus":"此人物的材料较分散，部分出现于特殊行动或分支叙事；未将不同分支合并为连续生平。","kind":"npc","title":"罗德岛精英干员","origin":"以相关篇章为准","faction":"剧情人物","forms":[],"aliases":[],"memories":[]},{"id":"npc-touch","name":"触痕","region":"rhodes","role":"罗德岛精英干员","summary":"她作为罗德岛精英支援力量出现。相较于部分拥有独立活动的干员，她的个人故事仍较分散。","groups":[],"source":"https://prts.wiki/w/Touch","focus":"此人物的材料较分散，部分出现于特殊行动或分支叙事；未将不同分支合并为连续生平。","kind":"npc","title":"罗德岛精英干员","origin":"以相关篇章为准","faction":"剧情人物","forms":[],"aliases":[],"memories":[]},{"id":"npc-tulip","name":"郁金香","region":"rhodes","role":"罗德岛特殊支援干员","summary":"她在特殊作战和支援叙事中呈现自己的能力，与罗德岛保持明确联系。本条按现有正式称呼建立索引；个人过去未充分展开的部分不作猜测，也不把玩法表现直接当成完整人物性格。","groups":[],"source":"https://prts.wiki/w/%E9%83%81%E9%87%91%E9%A6%99","focus":"此人物的材料较分散，部分出现于特殊行动或分支叙事；未将不同分支合并为连续生平。","kind":"npc","title":"罗德岛特殊支援干员","origin":"以相关篇章为准","faction":"剧情人物","forms":[],"aliases":[],"memories":[]},{"id":"npc-doctor","name":"博士","region":"rhodes","role":"罗德岛指挥者与源石研究的旧时代参与者","summary":"博士在巴别塔时期参与战争，后因特蕾西娅抹去记忆而重新开始。切城获救之后，指挥、研究与对过去的追问逐渐交汇。","groups":["act33side","main_8","act25side","main_14","main_15","main_17"],"source":"https://prts.wiki/w/%E5%8D%9A%E5%A3%AB","focus":"按本条所列主线与回忆整理，旧时代身份和未公开年代保留边界。","kind":"npc","origin":"尚未完整公开","faction":"跨时代剧情","en":"Doctor","title":"罗德岛指挥者与源石研究的旧时代参与者","aliases":["预言家","巴别塔的恶灵"],"forms":[],"memories":[]},{"id":"npc-priestess","name":"普瑞赛斯","region":"rhodes","role":"旧时代源石计划的研究者","summary":"她曾与博士共同参与源石计划，后与源石中的信息海洋相连。苏醒后对当代泰拉的控制，与罗德岛守护现有生命的选择发生直接冲突。","groups":["act33side","act25side","main_15","main_17"],"source":"https://prts.wiki/w/%E6%99%AE%E7%91%9E%E8%B5%9B%E6%96%AF","focus":"按本条所列主线与回忆整理，旧时代身份和未公开年代保留边界。","kind":"npc","origin":"尚未完整公开","faction":"跨时代剧情","en":"Priestess","title":"旧时代源石计划的研究者","aliases":[],"forms":[],"memories":[]}];
